INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37031, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "「招く」は、自ら進んで引き起こすわけではないが、結果として悪い状態や出来事を発生させることを意味します。通常、望ましくない結果に用いられます。", "primary_collocate": null, "pronunciation": "まねく", "ipa": "maneku", "syllable_count": 3, "sentences": [{"text": "悪気はなかったが、私の言葉が相手の怒りを招いてしまった。", "target_word": "招いて", "complexity_tier": "T3", "furigana": "悪気[わるぎ]はなかったが、私[わたし]の言葉[ことば]が相手[あいて]の怒[いか]りを招[まね]いてしまった。", "sentence_source": "generated"}, {"text": "善意の行動が、思わぬ誤解を招くこともある。", "target_word": "招く", "complexity_tier": "T3", "furigana": "善意[ぜんい]の行動[こうどう]が、思[おも]わぬ誤解[ごかい]を招[まね]くこともある。", "sentence_source": "generated"}, {"text": "彼を助けたつもりが、かえって混乱を招いた。", "target_word": "招いた", "complexity_tier": "T3", "furigana": "彼[かれ]を助[たす]けたつもりが、かえって混乱[こんらん]を招[まね]いた。", "sentence_source": "generated"}, {"text": "急いだことが、結果として大きなミスを招いた。", "target_word": "招いた", "complexity_tier": "T3", "furigana": "急[いそ]いだことが、結果[けっか]として大[おお]きなミスを招[まね]いた。", "sentence_source": "generated"}, {"text": "安い部品を使ったことが、のちの故障を招いた。", "target_word": "招いた", "complexity_tier": "T3", "furigana": "安[やす]い部品[ぶひん]を使[つか]ったことが、のちの故障[こしょう]を招[まね]いた。", "sentence_source": "generated"}, {"text": "そのつもりはなくても、冷たい返事は不信を招く。", "target_word": "招く", "complexity_tier": "T3", "furigana": "そのつもりはなくても、冷[つめ]たい返事[へんじ]は不信[ふしん]を招[まね]く。", "sentence_source": "generated"}, {"text": "長い説明が、聞く人の退屈を招いてしまった。", "target_word": "招いて", "complexity_tier": "T3", "furigana": "長[なが]い説明[せつめい]が、聞[き]く人[ひと]の退屈[たいくつ]を招[まね]いてしまった。", "sentence_source": "generated"}, {"text": "事故を招かないよう、注意して運転する。", "target_word": "招かない", "complexity_tier": "T3", "furigana": "事故[じこ]を招[まね]かないよう、注意[ちゅうい]して運転[うんてん]する。", "sentence_source": "generated"}, {"text": "彼の沈黙は、周りの不安を招いた。", "target_word": "招いた", "complexity_tier": "T3", "furigana": "彼[かれ]の沈黙[ちんもく]は、周[まわ]りの不安[ふあん]を招[まね]いた。", "sentence_source": "generated"}, {"text": "規則を変えたことが、思わぬ反発を招いた。", "target_word": "招いた", "complexity_tier": "T3", "furigana": "規則[きそく]を変[か]えたことが、思[おも]わぬ反発[はんぱつ]を招[まね]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "招く", "label": "終止形"}, {"form": "招いた", "label": "過去形"}, {"form": "招いて", "label": "て形"}, {"form": "招かない", "label": "否定形"}, {"form": "招き", "label": "連用形"}], "register": "中立", "sense_fingerprint": "意図せず結果として悪い事態を生じさせる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6ccf0ee-587d-4100-bacc-1b9c2c21e01c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37031, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "招いて", "is_correct": true, "explanation": "「怒りを〜しまった」に続き、意図せず結果を生じさせた意味で文に合う。"}, {"text": "食べて", "is_correct": false, "explanation": "怒りは食べられないので、「怒りを食べてしまった」は意味が通らない。"}, {"text": "眠って", "is_correct": false, "explanation": "怒りが眠るという意味にはならず、文脈に合わない。"}, {"text": "泳いで", "is_correct": false, "explanation": "怒りは泳がないので、「怒りを泳いでしまった」は成り立たない。"}], "explanations": {"招いて": "「怒りを〜しまった」に続き、意図せず結果を生じさせた意味で文に合う。", "食べて": "怒りは食べられないので、「怒りを食べてしまった」は意味が通らない。", "眠って": "怒りが眠るという意味にはならず、文脈に合わない。", "泳いで": "怒りは泳がないので、「怒りを泳いでしまった」は成り立たない。"}, "sentence_index": 0, "correct_answer": "招いて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大きな段ボールを招いて、倉庫へ移した。", "explanation": "ここは〈移す〉の意味。物を動かす場合は移すを使い、招くは人を迎える意味で使うので、段ボールには合わない。"}, {"text": "彼女の説明が、議論を正しい結論へ招いた。", "explanation": "ここは〈導く〉の意味。良い方向へ進める場合は導くを使い、望ましくない結果には招くを使う。"}, {"text": "店員が、床に落ちた伝票を招いて拾った。", "explanation": "ここは〈拾う〉の意味。床の紙を取り上げる動作は拾うを使い、招くは人を呼ぶときに使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37031, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "招いて", "is_correct": true, "explanation": "「退屈を〜しまった」に続き、説明が意図せず退屈を生じさせた意味で文に合う。"}, {"text": "歌って", "is_correct": false, "explanation": "退屈は歌わないので、「退屈を歌ってしまった」は意味が通らない。"}, {"text": "煮て", "is_correct": false, "explanation": "退屈は煮られないので、「退屈を煮てしまった」は成り立たない。"}, {"text": "踊って", "is_correct": false, "explanation": "退屈は踊らないので、「退屈を踊ってしまった」は文脈に合わない。"}], "explanations": {"招いて": "「退屈を〜しまった」に続き、説明が意図せず退屈を生じさせた意味で文に合う。", "歌って": "退屈は歌わないので、「退屈を歌ってしまった」は意味が通らない。", "煮て": "退屈は煮られないので、「退屈を煮てしまった」は成り立たない。", "踊って": "退屈は踊らないので、「退屈を踊ってしまった」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "招いて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市は、寄付を広く招くことにした。", "explanation": "ここは〈集める〉の意味。寄付のように物や金を集める場合、招くは使わない。"}, {"text": "店は、慣れないアルバイトを招くことにした。", "explanation": "ここは〈雇う〉の意味。人を仕事として採用する場合、招くは使わない。"}, {"text": "倒れた人を見て、救急車を招いた。", "explanation": "ここは〈呼ぶ〉の意味。救急車を来させる場合は呼ぶを使い、招くは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37031, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その一言が、周りの誤解で招くこともある。", "corrected_sentence": "その一言が、周りの誤解を招くこともある。", "error_description": "「招く」は目的語に「を」を取る。「で」は手段を表すので誤り。正しくは「誤解を招く」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "招く", "is_correct": true, "explanation": "終止形で、「〜こともある」の前に置いて一般的な可能性を述べる形。"}, {"text": "招けば", "is_correct": false, "explanation": "仮定形なので「ことがある」に続かず、文が成り立たない。"}, {"text": "招いて", "is_correct": false, "explanation": "て形なので文を言い切れず、「〜こともある」に続かない。"}, {"text": "招こう", "is_correct": false, "explanation": "意志形なので「ことがある」に続かず、文が成り立たない。"}], "correct_form": "招く", "base_form": "招く", "form_label": "終止形", "sentence_index": 1, "explanations": {"招く": "終止形で、「〜こともある」の前に置いて一般的な可能性を述べる形。", "招けば": "仮定形なので「ことがある」に続かず、文が成り立たない。", "招いて": "て形なので文を言い切れず、「〜こともある」に続かない。", "招こう": "意志形なので「ことがある」に続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37031, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "油断せず運転して、事故に招かないようにする。", "corrected_sentence": "油断せず運転して、事故を招かないようにする。", "error_description": "「招く」は目的語に「を」を取る。「に」は誤りで、正しくは「事故を」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "招かない", "is_correct": true, "explanation": "否定形で、「〜ないよう」に続けて事故を避ける意味を表す形。"}, {"text": "招き", "is_correct": false, "explanation": "連用形の「招き」は「〜よう」に続かず、「事故を招きよう」は文が成り立たない。"}, {"text": "招けば", "is_correct": false, "explanation": "仮定形の「招けば」は条件を表すので、「〜よう」の目的を示す文には合わない。"}, {"text": "招かれた", "is_correct": false, "explanation": "受け身の過去形で、事故が招かれる意味になり、注意して運転する文に合わない。"}], "correct_form": "招かない", "base_form": "招く", "form_label": "否定形", "sentence_index": 7, "explanations": {"招かない": "否定形で、「〜ないよう」に続けて事故を避ける意味を表す形。", "招き": "連用形の「招き」は「〜よう」に続かず、「事故を招きよう」は文が成り立たない。", "招けば": "仮定形の「招けば」は条件を表すので、「〜よう」の目的を示す文には合わない。", "招かれた": "受け身の過去形で、事故が招かれる意味になり、注意して運転する文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37032, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「見られた」の主語（現れた対象）を示す。「鈍化が見られた」で、鈍化が確認されたことを表す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「見られた」は受け身なので「を」は取れない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を示すが、「見られた」を修飾する名詞がなく文が成り立たない"}, {"text": "へ", "is_correct": false, "explanation": "向かう先を示すが、「鈍化へ見られた」では方向の意味が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「見られた」の主語（現れた対象）を示す。「鈍化が見られた」で、鈍化が確認されたことを表す。", "を": "目的語を示すが、「見られた」は受け身なので「を」は取れない。", "の": "連体修飾を示すが、「見られた」を修飾する名詞がなく文が成り立たない", "へ": "向かう先を示すが、「鈍化へ見られた」では方向の意味が成り立たない。"}, "error_tags": {"を": "object", "の": "possessive", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37032, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「進歩が鈍化している」の主語（鈍化する主体）を示す。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「進歩から鈍化している」では意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、ここには比べる対象がない。"}, {"text": "に", "is_correct": false, "explanation": "対象を示すが、「進歩に鈍化している」では対象との関係が成り立たない"}], "correct_answer": "が", "explanations": {"が": "「進歩が鈍化している」の主語（鈍化する主体）を示す。", "から": "起点を示すが、「進歩から鈍化している」では意味が通らない。", "より": "比較を示すが、ここには比べる対象がない。", "に": "対象を示すが、「進歩に鈍化している」では対象との関係が成り立たない"}, "error_tags": {"から": "source", "より": "comparison", "に": "target"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37032, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の動きや変化が遅くなること。", "primary_collocate": null, "pronunciation": "どんか", "ipa": "doŋka", "syllable_count": 3, "sentences": [{"text": "年をとると、体の動きの鈍化を感じることが多くなる。", "target_word": "鈍化", "complexity_tier": "T3", "furigana": "年[とし]をとると、体[からだ]の動[うご]きの鈍化[どんか]を感[かん]じることが多[おお]くなる。", "sentence_source": "generated"}, {"text": "寒さのせいで、虫の活動の鈍化が見られた。", "target_word": "鈍化", "complexity_tier": "T3", "furigana": "寒[さむ]さのせいで、虫[むし]の活動[かつどう]の鈍化[どんか]が見[み]られた。", "sentence_source": "generated"}, {"text": "睡眠不足が続くと、頭の働きの鈍化につながる。", "target_word": "鈍化", "complexity_tier": "T3", "furigana": "睡眠不足[すいみんぶそく]が続[つづ]くと、頭[あたま]の働[はたら]きの鈍化[どんか]につながる。", "sentence_source": "generated"}, {"text": "変化の鈍化が目立ち、新しい発見は少なくなった。", "target_word": "鈍化", "complexity_tier": "T3", "furigana": "変化[へんか]の鈍化[どんか]が目立[めだ]ち、新[あたら]しい発見[はっけん]は少[すく]なくなった。", "sentence_source": "generated"}, {"text": "低い気温は、植物の成長の鈍化を引き起こす。", "target_word": "鈍化", "complexity_tier": "T3", "furigana": "低[ひく]い気温[きおん]は、植物[しょくぶつ]の成長[せいちょう]の鈍化[どんか]を引[ひ]き起[お]こす。", "sentence_source": "generated"}, {"text": "反応の鈍化を防ぐために、毎日軽い運動をしている。", "target_word": "鈍化", "complexity_tier": "T3", "furigana": "反応[はんのう]の鈍化[どんか]を防[ふせ]ぐために、毎日[まいにち]軽[かる]い運動[うんどう]をしている。", "sentence_source": "generated"}, {"text": "会社の変化が鈍化したのは、新しい考えが出なくなったからだ。", "target_word": "鈍化", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の変化[へんか]が鈍化[どんか]したのは、新[あたら]しい考[かんが]えが出[で]なくなったからだ。", "sentence_source": "generated"}, {"text": "研究の進歩が鈍化している原因を調べる。", "target_word": "鈍化", "complexity_tier": "T3", "furigana": "研究[けんきゅう]の進歩[しんぽ]が鈍化[どんか]している原因[げんいん]を調[しら]べる。", "sentence_source": "generated"}, {"text": "薬の影響で、神経の働きが鈍化することがある。", "target_word": "鈍化", "complexity_tier": "T3", "furigana": "薬[くすり]の影響[えいきょう]で、神経[しんけい]の働[はたら]きが鈍化[どんか]することがある。", "sentence_source": "generated"}, {"text": "筋肉の動きが鈍化したので、医者に相談した。", "target_word": "鈍化", "complexity_tier": "T3", "furigana": "筋肉[きんにく]の動[うご]きが鈍化[どんか]したので、医者[いしゃ]に相談[そうだん]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鈍化する", "label": "終止形"}, {"form": "鈍化した", "label": "過去形"}, {"form": "鈍化している", "label": "継続形"}, {"form": "鈍化しない", "label": "否定形"}, {"form": "鈍化して", "label": "て形"}], "register": "書き言葉（やや硬い・常体）", "sense_fingerprint": "動き・変化・働きがにぶくなり、進み方が遅くなること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78c67344-a01c-4ca8-a260-da533eb0cbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37032, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鈍化", "is_correct": true, "explanation": "動きや変化が遅くなる意味で、「体の動きの〜を感じる」に入る。"}, {"text": "規則", "is_correct": false, "explanation": "決まりごとの意味で、体の動きを感じるという文には入らない。"}, {"text": "予約", "is_correct": false, "explanation": "前もって取っておくことで、体の動きの感覚を表す文には合わない。"}, {"text": "発表", "is_correct": false, "explanation": "人前で示すことで、体の感覚を述べる文には入らない。"}], "explanations": {"鈍化": "動きや変化が遅くなる意味で、「体の動きの〜を感じる」に入る。", "規則": "決まりごとの意味で、体の動きを感じるという文には入らない。", "予約": "前もって取っておくことで、体の動きの感覚を表す文には合わない。", "発表": "人前で示すことで、体の感覚を述べる文には入らない。"}, "sentence_index": 0, "correct_answer": "鈍化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は人の気持ちに対して鈍化しているので、よく空気を読み違える。", "explanation": "ここは〈鈍感〉の意味。人の感じ取る力の弱さは鈍感で、鈍化は進み方が遅くなることを指すので合わない。"}, {"text": "この商品は品質の鈍化が続き、客が次第に離れていった。", "explanation": "ここは〈低下〉の意味。鈍化は動きや変化が遅くなることで、品質の質的な落ち込みには使わない。"}, {"text": "地元の商店街は鈍化が進み、店が次々と閉まった。", "explanation": "ここは〈衰退〉の意味。鈍化は勢いや速さが弱まることで、町全体がさびれていく場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37032, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鈍化", "is_correct": true, "explanation": "会社の変化の速さが遅くなったことを表し、「〜したのは」に合う。"}, {"text": "発注", "is_correct": false, "explanation": "注文を出すことで、変化の速さの文には入らない。"}, {"text": "採用", "is_correct": false, "explanation": "人や方法を取り入れる意味で、変化の速さは表さない。"}, {"text": "配布", "is_correct": false, "explanation": "広く配ることで、変化の速さを述べる文には合わない。"}], "explanations": {"鈍化": "会社の変化の速さが遅くなったことを表し、「〜したのは」に合う。", "発注": "注文を出すことで、変化の速さの文には入らない。", "採用": "人や方法を取り入れる意味で、変化の速さは表さない。", "配布": "広く配ることで、変化の速さを述べる文には合わない。"}, "sentence_index": 6, "correct_answer": "鈍化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大雨で、文化祭の鈍化が発表された。", "explanation": "ここは〈中止〉の意味。鈍化は勢いや速さが弱まることで、行事を取りやめる意味には使わない。"}, {"text": "古い電池は容量の鈍化が進み、すぐに切れるようになった。", "explanation": "ここは〈劣化〉の意味。鈍化は速さや変化の遅れで、性能が質的に悪くなる場合には使わない。"}, {"text": "先生は授業の内容を鈍化させて、生徒を眠らせた。", "explanation": "ここは〈単調〉の意味。鈍化は勢いや速さが弱まることで、内容の面白みが乏しいことには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37032, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冬になると、虫の動きの鈍化を目立つようになる。", "corrected_sentence": "冬になると、虫の動きの鈍化が目立つようになる。", "error_description": "「目立つ」は「〜が目立つ」と主語に「が」を取る。「鈍化を」は誤りで、正しくは「鈍化が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37032, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "物価の上昇が鈍化ので、家計の負担は少し軽くなった。", "corrected_sentence": "物価の上昇が鈍化したので、家計の負担は少し軽くなった。", "error_description": "「鈍化」はサ変名詞なので、「した」で文を続ける必要がある。「鈍化ので」は形が不完全で、正しくは「鈍化したので」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37033, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「鈍化が」で、人口の増え方が弱まったという状態の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「鈍化を問題になっている」では文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を示すが、「鈍化の、」では文がつながらない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「問題へ」では意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「鈍化が」で、人口の増え方が弱まったという状態の主語を示す。", "を": "目的語を示すが、「鈍化を問題になっている」では文が成り立たない。", "の": "連体修飾を示すが、「鈍化の、」では文がつながらない。", "へ": "方向を示すが、「問題へ」では意味が通らない。"}, "error_tags": {"を": "object", "の": "possessive", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37033, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「鈍化が」で、鈍化が起きた主体を示す"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を示すが、「鈍化の」で終わり文が成り立たない"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「鈍化へ、仕事を減らした」では意味が通らない"}, {"text": "と", "is_correct": false, "explanation": "並列を示すが、「鈍化と、仕事を減らした」では文がつながらない"}], "correct_answer": "が", "explanations": {"が": "「鈍化が」で、鈍化が起きた主体を示す", "の": "連体修飾を示すが、「鈍化の」で終わり文が成り立たない", "へ": "方向を示すが、「鈍化へ、仕事を減らした」では意味が通らない", "と": "並列を示すが、「鈍化と、仕事を減らした」では文がつながらない"}, "error_tags": {"の": "possessive", "へ": "direction", "と": "coordination"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37033, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の勢いや速さが弱まって、遅くなること。", "primary_collocate": null, "pronunciation": "どんか", "ipa": "doŋka", "syllable_count": 3, "sentences": [{"text": "景気の鈍化が続き、店の売り上げも減ってきた。", "target_word": "鈍化", "complexity_tier": "T3", "furigana": "景気[けいき]の鈍化[どんか]が続[つづ]き、店[みせ]の売[う]り上[あ]げも減[へ]ってきた。", "sentence_source": "generated"}, {"text": "人口の増え方の鈍化が、国の大きな問題になっている。", "target_word": "鈍化", "complexity_tier": "T3", "furigana": "人口[じんこう]の増[ふ]え方[かた]の鈍化[どんか]が、国[くに]の大[おお]きな問題[もんだい]になっている。", "sentence_source": "generated"}, {"text": "世界経済の成長の鈍化を心配する声が高まっている。", "target_word": "鈍化", "complexity_tier": "T3", "furigana": "世界[せかい]経済[けいざい]の成長[せいちょう]の鈍化[どんか]を心配[しんぱい]する声[こえ]が高[たか]まっている。", "sentence_source": "generated"}, {"text": "台風の進む速さの鈍化で、到着が予定より遅れた。", "target_word": "鈍化", "complexity_tier": "T3", "furigana": "台風[たいふう]の進[すす]む速[はや]さの鈍化[どんか]で、到着[とうちゃく]が予定[よてい]より遅[おく]れた。", "sentence_source": "generated"}, {"text": "輸出の伸びが鈍化したため、会社は計画を見直した。", "target_word": "鈍化", "complexity_tier": "T3", "furigana": "輸出[ゆしゅつ]の伸[の]びが鈍化[どんか]したため、会社[かいしゃ]は計画[けいかく]を見直[みなお]した。", "sentence_source": "generated"}, {"text": "物価の上昇の鈍化は、買い物をする人にはうれしい知らせだ。", "target_word": "鈍化", "complexity_tier": "T3", "furigana": "物価[ぶっか]の上昇[じょうしょう]の鈍化[どんか]は、買[か]い物[もの]をする人[ひと]にはうれしい知[し]らせだ。", "sentence_source": "generated"}, {"text": "工場の生産の勢いの鈍化に気づいた社長は、機械を新しくした。", "target_word": "鈍化", "complexity_tier": "T3", "furigana": "工場[こうじょう]の生産[せいさん]の勢[いきお]いの鈍化[どんか]に気[き]づいた社長[しゃちょう]は、機械[きかい]を新[あたら]しくした。", "sentence_source": "generated"}, {"text": "住宅の売れ行きの鈍化が、建設会社の仕事を減らした。", "target_word": "鈍化", "complexity_tier": "T3", "furigana": "住宅[じゅうたく]の売[う]れ行[ゆ]きの鈍化[どんか]が、建設会社[けんせつがいしゃ]の仕事[しごと]を減[へ]らした。", "sentence_source": "generated"}, {"text": "雨の勢いが鈍化するのを待って、試合が再開された。", "target_word": "鈍化", "complexity_tier": "T3", "furigana": "雨[あめ]の勢[いきお]いが鈍化[どんか]するのを待[ま]って、試合[しあい]が再開[さいかい]された。", "sentence_source": "generated"}, {"text": "投資の勢いが鈍化しているため、株価も上がりにくい。", "target_word": "鈍化", "complexity_tier": "T3", "furigana": "投資[とうし]の勢[いきお]いが鈍化[どんか]しているため、株価[かぶか]も上[あ]がりにくい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鈍化する", "label": "終止形"}, {"form": "鈍化した", "label": "過去形"}, {"form": "鈍化している", "label": "継続形"}, {"form": "鈍化しない", "label": "否定形"}, {"form": "鈍化して", "label": "て形"}], "register": "書き言葉（やや硬い・常体）", "sense_fingerprint": "景気・成長・伸びなどの勢いや速さが弱まり、ゆるやかになること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78c67344-a01c-4ca8-a260-da533eb0cbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37033, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鈍化", "is_correct": true, "explanation": "景気の勢いが弱まることを表し、「景気の〜が続く」に入る。"}, {"text": "礼儀", "is_correct": false, "explanation": "人への振る舞いのことで、景気の動きを表す文には合わない。"}, {"text": "宿題", "is_correct": false, "explanation": "課された勉強や作業のことで、景気の話には入らない。"}, {"text": "迷路", "is_correct": false, "explanation": "道が入り組んだ場所のことで、景気の文には合わない。"}], "explanations": {"鈍化": "景気の勢いが弱まることを表し、「景気の〜が続く」に入る。", "礼儀": "人への振る舞いのことで、景気の動きを表す文には合わない。", "宿題": "課された勉強や作業のことで、景気の話には入らない。", "迷路": "道が入り組んだ場所のことで、景気の文には合わない。"}, "sentence_index": 0, "correct_answer": "鈍化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "株価の鈍化で、投資家は大きな損失を出した。", "explanation": "ここは〈下落〉の意味。鈍化は勢いが弱まることで、値段が大きく下がる意味にはならない。"}, {"text": "輸出の鈍化で工場が次々と増築された。", "explanation": "ここは〈拡大〉の意味。鈍化は伸びが弱まることで、設備が広がる意味では使わない。"}, {"text": "雇用の鈍化が改善し、若者の仕事が増えた。", "explanation": "ここは〈回復〉の意味。鈍化は勢いや伸びが弱まることで、雇用が立ち直って増える意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37033, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鈍化", "is_correct": true, "explanation": "生産の勢いが弱まったことを表し、「勢いの〜に気づいた」に入る。"}, {"text": "見出し", "is_correct": false, "explanation": "記事の題のことで、生産の勢いを表す文には入らない。"}, {"text": "慣習", "is_correct": false, "explanation": "昔からの習わしのことで、生産の勢いには合わない。"}, {"text": "寝具", "is_correct": false, "explanation": "寝るときに使う物のことで、勢いの文には入らない。"}], "explanations": {"鈍化": "生産の勢いが弱まったことを表し、「勢いの〜に気づいた」に入る。", "見出し": "記事の題のことで、生産の勢いを表す文には入らない。", "慣習": "昔からの習わしのことで、生産の勢いには合わない。", "寝具": "寝るときに使う物のことで、勢いの文には入らない。"}, "sentence_index": 6, "correct_answer": "鈍化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "円相場が一晩で鈍化し、輸入品の値段が跳ね上がった。", "explanation": "ここは〈急落〉の意味。鈍化は少しずつ勢いが弱まることで、一晩で大きく動く変化には使わない。"}, {"text": "大雨のため、試合の鈍化を審判が伝えた。", "explanation": "ここは〈中断〉の意味。鈍化は勢いが弱まることで、途中で打ち切る意味には使わない。"}, {"text": "社長は売れ行きの変化に対して鈍化しており、在庫が増えたことに気づかなかった。", "explanation": "ここは〈鈍感〉の意味。人の感じ取る力の弱さは鈍感で、鈍化は速さの変化を表すので、社長の性格には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37033, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "景気の鈍化を続き、人々の財布の紐は固くなった。", "corrected_sentence": "景気の鈍化が続き、人々の財布の紐は固くなった。", "error_description": "「続く」は主語に「が」を取る自動詞。「鈍化を続き」は誤りで、正しくは「鈍化が続き」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37033, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "住宅の売れ行きの鈍化ため、建築の仕事は減ってきた。", "corrected_sentence": "住宅の売れ行きの鈍化のため、建築の仕事は減ってきた。", "error_description": "「のため」の「の」が抜けている。名詞の「鈍化」に続けるには「鈍化のため」が必要で、「鈍化ため」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37034, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「定期の練習」で、定期が練習を修飾する働きの「の」。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「定期が練習を重ねて」では文の主語が合わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「定期を練習」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「定期へ練習」では意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「定期の練習」で、定期が練習を修飾する働きの「の」。", "が": "主語を示すが、「定期が練習を重ねて」では文の主語が合わない。", "を": "目的語を示すが、「定期を練習」では文が成り立たない。", "へ": "方向を示すが、「定期へ練習」では意味が通らない。"}, "error_tags": {"が": "subject", "を": "object", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
