INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37034, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何度も同じように行うこと。", "primary_collocate": null, "pronunciation": "ていき", "ipa": "teːki", "syllable_count": 3, "sentences": [{"text": "祖父とは、定期の電話で近況を話している。", "target_word": "定期", "complexity_tier": "T3", "furigana": "祖父[そふ]とは、定期[ていき]の電話[でんわ]で近況[きんきょう]を話[はな]している。", "sentence_source": "generated"}, {"text": "部員たちは、定期の練習を重ねて腕をみがく。", "target_word": "定期", "complexity_tier": "T3", "furigana": "部員[ぶいん]たちは、定期[ていき]の練習[れんしゅう]を重[かさ]ねて腕[うで]をみがく。", "sentence_source": "generated"}, {"text": "母は定期の掃除を欠かさないので、家はいつもきれいだ。", "target_word": "定期", "complexity_tier": "T3", "furigana": "母[はは]は定期[ていき]の掃除[そうじ]を欠[か]かさないので、家[いえ]はいつもきれいだ。", "sentence_source": "generated"}, {"text": "この仕事では、上司への定期の報告が決まりになっている。", "target_word": "定期", "complexity_tier": "T3", "furigana": "この仕事[しごと]では、上司[じょうし]への定期[ていき]の報告[ほうこく]が決[き]まりになっている。", "sentence_source": "generated"}, {"text": "町内会では、定期の集まりを開いて近所の問題を話し合う。", "target_word": "定期", "complexity_tier": "T3", "furigana": "町内会[ちょうないかい]では、定期[ていき]の集[あつ]まりを開[ひら]いて近所[きんじょ]の問題[もんだい]を話[はな]し合[あ]う。", "sentence_source": "generated"}, {"text": "週末の定期の買い物で、一週間分の食料をそろえる。", "target_word": "定期", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]の定期[ていき]の買[か]い物[もの]で、一週間分[いっしゅうかんぶん]の食料[しょくりょう]をそろえる。", "sentence_source": "generated"}, {"text": "友人たちとの定期の食事会は、もう五年も続いている。", "target_word": "定期", "complexity_tier": "T3", "furigana": "友人[ゆうじん]たちとの定期[ていき]の食事会[しょくじかい]は、もう五年[ごねん]も続[つづ]いている。", "sentence_source": "generated"}, {"text": "犬の定期の散歩のおかげで、私も毎日運動できる。", "target_word": "定期", "complexity_tier": "T3", "furigana": "犬[いぬ]の定期[ていき]の散歩[さんぽ]のおかげで、私[わたし]も毎日[まいにち]運動[うんどう]できる。", "sentence_source": "generated"}, {"text": "定期の勉強会を続けた結果、みんなの成績が上がった。", "target_word": "定期", "complexity_tier": "T3", "furigana": "定期[ていき]の勉強会[べんきょうかい]を続[つづ]けた結果[けっか]、みんなの成績[せいせき]が上[あ]がった。", "sentence_source": "generated"}, {"text": "弟は定期の手入れを続けたので、自転車は十年たっても新品のようだ。", "target_word": "定期", "complexity_tier": "T3", "furigana": "弟[おとうと]は定期[ていき]の手[て]入[い]れを続[つづ]けたので、自転車[じてんしゃ]は十年[じゅうねん]たっても新品[しんぴん]のようだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "定期", "label": "基本形"}], "register": "中立（常体）", "sense_fingerprint": "練習・報告・集まりなどを、同じ形で何度も続けて行うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: みがく (Zipf 1.93)']::text[], '78c67344-a01c-4ca8-a260-da533eb0cbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37034, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "定期", "is_correct": true, "explanation": "同じ形で何度も続けて行う意味で、「〜の電話」として電話が続いていることを表す。"}, {"text": "祝日", "is_correct": false, "explanation": "休日のことで、電話の種類を表す語としては合わない。"}, {"text": "湿度", "is_correct": false, "explanation": "空気の湿り具合のことで、電話の修飾には合わない。"}, {"text": "絵画", "is_correct": false, "explanation": "描かれた作品のことで、電話の種類には入らない。"}], "explanations": {"定期": "同じ形で何度も続けて行う意味で、「〜の電話」として電話が続いていることを表す。", "祝日": "休日のことで、電話の種類を表す語としては合わない。", "湿度": "空気の湿り具合のことで、電話の修飾には合わない。", "絵画": "描かれた作品のことで、電話の種類には入らない。"}, "sentence_index": 0, "correct_answer": "定期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は定期の掃除を、汚れたときに随時行う。", "explanation": "ここは〈不定期〉の意味。定期は決まった間隔で同じように続けることで、汚れたときに必要に応じて行う掃除には合わない。"}, {"text": "祖父とは、定期の電話をたまにしかかけない。", "explanation": "ここは〈不定期〉の意味。定期は一定の間隔で続くことで、たまにしか起きないことには使わない。"}, {"text": "一度きりの旅行の定期の計画を立てた。", "explanation": "ここは〈単発〉の意味。定期は同じ形で何度も続けることで、一度きりの計画には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37034, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "定期", "is_correct": true, "explanation": "繰り返し行うことを表し、食事会が続いている意味に合う。"}, {"text": "天井", "is_correct": false, "explanation": "建物の上の面のことで、食事会の種類を表す語としては入らない。"}, {"text": "乾燥", "is_correct": false, "explanation": "水分がなくなる様子のことで、食事会には合わない。"}, {"text": "辞書", "is_correct": false, "explanation": "言葉を調べる本のことで、食事会の修飾には使わない。"}], "explanations": {"定期": "繰り返し行うことを表し、食事会が続いている意味に合う。", "天井": "建物の上の面のことで、食事会の種類を表す語としては入らない。", "乾燥": "水分がなくなる様子のことで、食事会には合わない。", "辞書": "言葉を調べる本のことで、食事会の修飾には使わない。"}, "sentence_index": 6, "correct_answer": "定期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は、定期の料理を一度だけ作った。", "explanation": "ここは〈単発〉の意味。定期は同じことを繰り返すことで、一度だけの行いには使わない。"}, {"text": "地震が定期に一度だけ起きて、建物が大きく揺れた。", "explanation": "ここは〈単発〉の意味。定期は同じことを繰り返すことで、一度だけの出来事には使わない。"}, {"text": "祖父の家には、世界に一つしかない定期の人形がある。", "explanation": "ここは〈唯一〉の意味。定期は同じことを繰り返すことで、一つしかないものには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37034, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は定期を掃除をしている。", "corrected_sentence": "母は定期の掃除をしている。", "error_description": "「定期の掃除」の「の」を「を」に変えると、定期が目的語になってしまい文が成り立たない。正しくは「定期の」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37034, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姉は定期が英会話教室に通い、英語が上達した。", "corrected_sentence": "姉は定期の英会話教室に通い、英語が上達した。", "error_description": "「定期の英会話教室」の「の」が必要。「定期が」は定期を主語にしてしまい、文の意味が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37036, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "足りないのは攪拌なので、主語を示す『が』が正しい。"}, {"text": "を", "is_correct": false, "explanation": "『足りない』は目的語『を』をとらないので文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "『に足りない』は文として不自然で、攪拌と結びつかない。"}, {"text": "と", "is_correct": false, "explanation": "『攪拌と足りなくて』は『と』で文が成り立たず、主語も示せない。"}], "correct_answer": "が", "explanations": {"が": "足りないのは攪拌なので、主語を示す『が』が正しい。", "を": "『足りない』は目的語『を』をとらないので文が成り立たない。", "に": "『に足りない』は文として不自然で、攪拌と結びつかない。", "と": "『攪拌と足りなくて』は『と』で文が成り立たず、主語も示せない。"}, "error_tags": {"を": "対象", "に": "方向・相手", "と": "共同・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37036, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『やめる』は『攪拌を』と目的語『を』をとるので正しい。"}, {"text": "が", "is_correct": false, "explanation": "『攪拌がやめた』は『やめる』の目的語の形として不自然。"}, {"text": "に", "is_correct": false, "explanation": "『攪拌にやめた』は文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段の『で』は『やめた』の対象にならない。"}], "correct_answer": "を", "explanations": {"を": "『やめる』は『攪拌を』と目的語『を』をとるので正しい。", "が": "『攪拌がやめた』は『やめる』の目的語の形として不自然。", "に": "『攪拌にやめた』は文として成り立たない。", "で": "手段の『で』は『やめた』の対象にならない。"}, "error_tags": {"が": "主語", "に": "方向・相手", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37036, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "かきまぜること。ぐるぐるまわして、まぜあわせること。", "primary_collocate": null, "pronunciation": "かくはん", "ipa": "kakɯhaɴ", "syllable_count": 4, "sentences": [{"text": "鍋の中身が焦げないように、ゆっくり攪拌する。", "target_word": "攪拌", "complexity_tier": "T3", "furigana": "鍋[なべ]の中身[なかみ]が焦[こ]げないように、ゆっくり攪拌[かくはん]する。", "sentence_source": "generated"}, {"text": "絵の具は攪拌が足りなくて、色にむらが出た。", "target_word": "攪拌", "complexity_tier": "T3", "furigana": "絵[え]の具[ぐ]は攪拌[かくはん]が足[た]りなくて、色[いろ]にむらが出[で]た。", "sentence_source": "generated"}, {"text": "長く攪拌したので、卵と砂糖がよく混ざった。", "target_word": "攪拌", "complexity_tier": "T3", "furigana": "長[なが]く攪拌[かくはん]したので、卵[たまご]と砂糖[さとう]がよく混[ま]ざった。", "sentence_source": "generated"}, {"text": "沈んだ粉は、攪拌すれば再び水に広がる。", "target_word": "攪拌", "complexity_tier": "T3", "furigana": "沈[しず]んだ粉[こな]は、攪拌[かくはん]すれば再[ふたた]び水[みず]に広[ひろ]がる。", "sentence_source": "generated"}, {"text": "機械が自動で攪拌してくれるから、手間がかからない。", "target_word": "攪拌", "complexity_tier": "T3", "furigana": "機械[きかい]が自動[じどう]で攪拌[かくはん]してくれるから、手間[てま]がかからない。", "sentence_source": "generated"}, {"text": "攪拌の速さを変えると、できあがりの食感も変わる。", "target_word": "攪拌", "complexity_tier": "T3", "furigana": "攪拌[かくはん]の速[はや]さを変[か]えると、できあがりの食感[しょっかん]も変[か]わる。", "sentence_source": "generated"}, {"text": "父は大きなスプーンで、バケツの泥水を攪拌した。", "target_word": "攪拌", "complexity_tier": "T3", "furigana": "父[ちち]は大[おお]きなスプーンで、バケツの泥水[どろみず]を攪拌[かくはん]した。", "sentence_source": "generated"}, {"text": "攪拌をやめた途端、渦はゆっくり消えていった。", "target_word": "攪拌", "complexity_tier": "T3", "furigana": "攪拌[かくはん]をやめた途端[とたん]、渦[うず]はゆっくり消[き]えていった。", "sentence_source": "generated"}, {"text": "洗濯機は水を攪拌して、服の汚れを落とす。", "target_word": "攪拌", "complexity_tier": "T3", "furigana": "洗濯機[せんたくき]は水[みず]を攪拌[かくはん]して、服[ふく]の汚[よご]れを落[お]とす。", "sentence_source": "generated"}, {"text": "攪拌が終わるまで、ふたを開けてはいけない。", "target_word": "攪拌", "complexity_tier": "T3", "furigana": "攪拌[かくはん]が終[お]わるまで、ふたを開[あ]けてはいけない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "攪拌する", "label": "サ変動詞 終止形"}, {"form": "攪拌した", "label": "過去形"}, {"form": "攪拌して", "label": "て形"}, {"form": "攪拌される", "label": "受身形"}], "register": "標準的な普通体", "sense_fingerprint": "ぐるぐる回して中身をかき混ぜる動作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc4c99e5-c08d-4486-b1ed-5a1851877780') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37036, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "攪拌", "is_correct": true, "explanation": "鍋の中身をぐるぐるかき混ぜる動作を表し、焦げないようにゆっくり混ぜる文脈に合う。"}, {"text": "点火", "is_correct": false, "explanation": "火をつける意味で、中身を混ぜる文脈に合わない。"}, {"text": "換気", "is_correct": false, "explanation": "空気を入れ替える意味で、鍋の中身には使わない。"}, {"text": "計量", "is_correct": false, "explanation": "分量をはかる意味で、混ぜる動作を表さない。"}], "explanations": {"攪拌": "鍋の中身をぐるぐるかき混ぜる動作を表し、焦げないようにゆっくり混ぜる文脈に合う。", "点火": "火をつける意味で、中身を混ぜる文脈に合わない。", "換気": "空気を入れ替える意味で、鍋の中身には使わない。", "計量": "分量をはかる意味で、混ぜる動作を表さない。"}, "sentence_index": 0, "correct_answer": "攪拌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "散らかった書類を攪拌して、机の上を片付けた。", "explanation": "ここは〈整理する〉の意味。攪拌は液体や粉末をかき混ぜる語なので、紙の束には使わない。"}, {"text": "新しいデータを攪拌して、傾向をつかんだ。", "explanation": "ここは〈分析する〉の意味。攪拌は物理的にかき混ぜる動作で、データを調べる文脈には合わない。"}, {"text": "忙しい朝、時間を攪拌して、なんとか出勤した。", "explanation": "ここは〈やりくりする〉の意味。攪拌は物質に使う語で、時間を操作する意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37036, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "攪拌", "is_correct": true, "explanation": "スプーンで泥水をかき混ぜる動作を表し、文脈に合う。"}, {"text": "点灯", "is_correct": false, "explanation": "明かりをつける意味で、泥水を混ぜる文脈に合わない。"}, {"text": "施錠", "is_correct": false, "explanation": "鍵をかける意味で、泥水には使わない。"}, {"text": "乾杯", "is_correct": false, "explanation": "杯を合わせる意味で、泥水を混ぜる動作の文脈に合わない。"}], "explanations": {"攪拌": "スプーンで泥水をかき混ぜる動作を表し、文脈に合う。", "点灯": "明かりをつける意味で、泥水を混ぜる文脈に合わない。", "施錠": "鍵をかける意味で、泥水には使わない。", "乾杯": "杯を合わせる意味で、泥水を混ぜる動作の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "攪拌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古い機械が攪拌して、窓の鍵を開けた。", "explanation": "ここは〈開ける〉の意味。攪拌は中身をかき混ぜる動作で、鍵を開ける意味はない。"}, {"text": "泣いている子どもの気持ちを攪拌して、落ち着かせた。", "explanation": "ここは〈なだめる〉の意味。攪拌は液体や粉をかき混ぜる語で、人の気持ちには使わない。"}, {"text": "夏休みの宿題を攪拌して、一日で終わらせた。", "explanation": "ここは〈まとめてこなす〉の意味。攪拌は物理的にかき混ぜる語で、課題には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37036, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ハンドミキサーで卵白を攪拌に、ふわふわに泡立てた。", "corrected_sentence": "ハンドミキサーで卵白を攪拌して、ふわふわに泡立てた。", "error_description": "攪拌に→攪拌して。動作を続けて次の動作につなぐには『て形』が必要で、『に』では文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37036, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母は木べらで、鍋のスープに攪拌して、味を均一にした。", "corrected_sentence": "母は木べらで、鍋のスープを攪拌して、味を均一にした。", "error_description": "スープに→スープを。攪拌する動作の対象は「を」で示す。「に」では対象を表せない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37037, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "不十分なのは攪拌なので、主語を示す『が』が正しい。"}, {"text": "を", "is_correct": false, "explanation": "『不十分』は目的語『を』をとらないので文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "『に不十分』は文として不自然で、攪拌と結びつかない。"}, {"text": "と", "is_correct": false, "explanation": "『攪拌と不十分だと』は『と』で文が成り立たず、主語も示せない。"}], "correct_answer": "が", "explanations": {"が": "不十分なのは攪拌なので、主語を示す『が』が正しい。", "を": "『不十分』は目的語『を』をとらないので文が成り立たない。", "に": "『に不十分』は文として不自然で、攪拌と結びつかない。", "と": "『攪拌と不十分だと』は『と』で文が成り立たず、主語も示せない。"}, "error_tags": {"を": "対象", "に": "方向・相手", "と": "共同・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
