INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37037, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "液体や粉末などを、かき混ぜて均一にすること。", "primary_collocate": null, "pronunciation": "かくはん", "ipa": "kakɯhaɴ", "syllable_count": 4, "sentences": [{"text": "粉末を水に入れて、均一になるまで攪拌する。", "target_word": "攪拌", "complexity_tier": "T3", "furigana": "粉末[ふんまつ]を水[みず]に入[い]れて、均一[きんいつ]になるまで攪拌[かくはん]する。", "sentence_source": "generated"}, {"text": "薬品は攪拌が不十分だと、濃さにばらつきが出る。", "target_word": "攪拌", "complexity_tier": "T3", "furigana": "薬品[やくひん]は攪拌[かくはん]が不十分[ふじゅうぶん]だと、濃[こ]さにばらつきが出[で]る。", "sentence_source": "generated"}, {"text": "実験では、溶液を十分攪拌してから温度を測った。", "target_word": "攪拌", "complexity_tier": "T3", "furigana": "実験[じっけん]では、溶液[ようえき]を十分[じゅうぶん]攪拌[かくはん]してから温度[おんど]を測[はか]った。", "sentence_source": "generated"}, {"text": "塗料は缶の底に沈むので、使う前に攪拌が必要だ。", "target_word": "攪拌", "complexity_tier": "T3", "furigana": "塗料[とりょう]は缶[かん]の底[そこ]に沈[しず]むので、使[つか]う前[まえ]に攪拌[かくはん]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "工場では大きなタンクで、原料を攪拌している。", "target_word": "攪拌", "complexity_tier": "T3", "furigana": "工場[こうじょう]では大[おお]きなタンクで、原料[げんりょう]を攪拌[かくはん]している。", "sentence_source": "generated"}, {"text": "攪拌後の液体は、どこをすくっても同じ濃さだった。", "target_word": "攪拌", "complexity_tier": "T3", "furigana": "攪拌後[かくはんご]の液体[えきたい]は、どこをすくっても同[おな]じ濃[こ]さだった。", "sentence_source": "generated"}, {"text": "小麦粉のだまを防ぐには、牛乳を少しずつ入れて攪拌する。", "target_word": "攪拌", "complexity_tier": "T3", "furigana": "小麦粉[こむぎこ]のだまを防[ふせ]ぐには、牛乳[ぎゅうにゅう]を少[すこ]しずつ入[い]れて攪拌[かくはん]する。", "sentence_source": "generated"}, {"text": "装置の攪拌が止まったため、粉と液が分離してしまった。", "target_word": "攪拌", "complexity_tier": "T3", "furigana": "装置[そうち]の攪拌[かくはん]が止[と]まったため、粉[こな]と液[えき]が分離[ぶんり]してしまった。", "sentence_source": "generated"}, {"text": "肥料を水に溶かし、よく攪拌してから畑にまいた。", "target_word": "攪拌", "complexity_tier": "T3", "furigana": "肥料[ひりょう]を水[みず]に溶[と]かし、よく攪拌[かくはん]してから畑[はたけ]にまいた。", "sentence_source": "generated"}, {"text": "攪拌の時間を五分から十分に延ばして、溶け残りをなくした。", "target_word": "攪拌", "complexity_tier": "T3", "furigana": "攪拌[かくはん]の時間[じかん]を五分[ごふん]から十分[じゅっぷん]に延[の]ばして、溶[と]け残[のこ]りをなくした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "攪拌する", "label": "サ変動詞 終止形"}, {"form": "攪拌した", "label": "過去形"}, {"form": "攪拌して", "label": "て形"}, {"form": "攪拌される", "label": "受身形"}], "register": "標準的な普通体", "sense_fingerprint": "液体や粉末を混ぜて濃さをそろえる作業", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc4c99e5-c08d-4486-b1ed-5a1851877780') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37037, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "攪拌", "is_correct": true, "explanation": "粉末を水に入れて均一にするまでかき混ぜる動作を表し、文脈に合う。"}, {"text": "解錠", "is_correct": false, "explanation": "鍵を開ける意味で、粉末と水を混ぜる文脈に合わない。"}, {"text": "点検", "is_correct": false, "explanation": "状態を調べる意味で、混ぜて均一にする動作を表さない。"}, {"text": "洗濯", "is_correct": false, "explanation": "衣類などを洗う意味で、粉末を水に混ぜる文脈に合わない。"}], "explanations": {"攪拌": "粉末を水に入れて均一にするまでかき混ぜる動作を表し、文脈に合う。", "解錠": "鍵を開ける意味で、粉末と水を混ぜる文脈に合わない。", "点検": "状態を調べる意味で、混ぜて均一にする動作を表さない。", "洗濯": "衣類などを洗う意味で、粉末を水に混ぜる文脈に合わない。"}, "sentence_index": 0, "correct_answer": "攪拌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "読み終えた本を攪拌して、もう一度読み直した。", "explanation": "ここは〈読み直す〉の意味。攪拌は液体や粉をかき混ぜる語で、本には使わない。"}, {"text": "砂糖はすぐに攪拌して消えた。", "explanation": "ここは〈溶ける〉の意味。攪拌は人や機械がかき混ぜる動作で、砂糖が自然に溶ける現象には使わない。"}, {"text": "予定を攪拌して、週末をあけた。", "explanation": "ここは〈組み替える〉の意味。攪拌は物質をかき混ぜる語で、予定には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37037, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "攪拌", "is_correct": true, "explanation": "牛乳を少しずつ入れてかき混ぜ、だまを防ぐ動作を表す。"}, {"text": "冷凍", "is_correct": false, "explanation": "凍らせる意味で、混ぜる文脈に合わない。"}, {"text": "点呼", "is_correct": false, "explanation": "人を呼んで数える意味で、材料には使わない。"}, {"text": "施工", "is_correct": false, "explanation": "工事を行う意味で、料理の動作には合わない。"}], "explanations": {"攪拌": "牛乳を少しずつ入れてかき混ぜ、だまを防ぐ動作を表す。", "冷凍": "凍らせる意味で、混ぜる文脈に合わない。", "点呼": "人を呼んで数える意味で、材料には使わない。", "施工": "工事を行う意味で、料理の動作には合わない。"}, "sentence_index": 6, "correct_answer": "攪拌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窓を攪拌して、汚れを落とした。", "explanation": "ここは〈拭く〉の意味。攪拌は液体や粉をかき混ぜる語なので、窓には使わない。"}, {"text": "敵の動きを攪拌するため、わざと偽の情報を流した。", "explanation": "ここは〈撹乱する〉の意味。攪拌は液体や粉をかき混ぜる語で、相手の動きを乱す意味はない。"}, {"text": "会議の時間を攪拌した。", "explanation": "ここは〈延長する〉の意味。攪拌は混ぜる動作で、時間の長さを変える意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37037, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "機械の攪拌を不十分だと、濃さにばらつきが出る。", "corrected_sentence": "機械の攪拌が不十分だと、濃さにばらつきが出る。", "error_description": "攪拌が不十分→攪拌を不十分。『不十分だ』は主語に『が』を取るので、攪拌には『が』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37037, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その機械は、粉と水を攪拌ている。", "corrected_sentence": "その機械は、粉と水を攪拌している。", "error_description": "攪拌している→攪拌ている。サ変動詞『する』の連用形『し』が抜けている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37038, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「使う」の目的語（使うもの）を示す「を」が正しく、「酸素を使って」で文が成り立ちます。"}, {"text": "が", "is_correct": false, "explanation": "「酸素が使って呼吸している」だと酸素が主語になり、「使って」の形と合わず不自然です。"}, {"text": "と", "is_correct": false, "explanation": "「酸素と使う」の形は目的語を表さず、文が成り立ちません。"}, {"text": "の", "is_correct": false, "explanation": "「酸素の使って」は名詞を結ぶだけで、動詞「使う」の目的語にならず成り立ちません。"}], "correct_answer": "を", "explanations": {"を": "「使う」の目的語（使うもの）を示す「を」が正しく、「酸素を使って」で文が成り立ちます。", "が": "「酸素が使って呼吸している」だと酸素が主語になり、「使って」の形と合わず不自然です。", "と": "「酸素と使う」の形は目的語を表さず、文が成り立ちません。", "の": "「酸素の使って」は名詞を結ぶだけで、動詞「使う」の目的語にならず成り立ちません。"}, "error_tags": {"を": "目的語", "が": "主語", "と": "並列・共同", "の": "所属・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37038, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「なくなる」の主語（なくなるもの）を示す「が」が正しく、「酸素がなくなると」で文が成り立ちます。"}, {"text": "を", "is_correct": false, "explanation": "「なくなる」は目的語を取らない自動詞なので、「酸素を なくなる」は成り立ちません。"}, {"text": "に", "is_correct": false, "explanation": "「酸素に なくなる」は不自然で、「なくなる」の主語として機能しません。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表しますが、「なくなる」の動作の向かう先にはならないので合いません。"}], "correct_answer": "が", "explanations": {"が": "「なくなる」の主語（なくなるもの）を示す「が」が正しく、「酸素がなくなると」で文が成り立ちます。", "を": "「なくなる」は目的語を取らない自動詞なので、「酸素を なくなる」は成り立ちません。", "に": "「酸素に なくなる」は不自然で、「なくなる」の主語として機能しません。", "へ": "「へ」は方向を表しますが、「なくなる」の動作の向かう先にはならないので合いません。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "対象", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37038, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "空気の中にあって、生き物が生きていくために必要な気体です。", "primary_collocate": null, "pronunciation": "さんそ", "ipa": "sanso", "syllable_count": 3, "sentences": [{"text": "山の上は空気がうすく、酸素が足りなくなりやすい。", "target_word": "酸素", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]は空気[くうき]がうすく、酸素[さんそ]が足[た]りなくなりやすい。", "sentence_source": "generated"}, {"text": "魚は水にとけた酸素を使って呼吸している。", "target_word": "酸素", "complexity_tier": "T3", "furigana": "魚[さかな]は水[みず]にとけた酸素[さんそ]を使[つか]って呼吸[こきゅう]している。", "sentence_source": "generated"}, {"text": "木が多い公園には、酸素がたくさんあると言われる。", "target_word": "酸素", "complexity_tier": "T3", "furigana": "木[き]が多[おお]い公園[こうえん]には、酸素[さんそ]がたくさんあると言[い]われる。", "sentence_source": "generated"}, {"text": "部屋の窓を閉めきると、酸素が減って頭がぼんやりする。", "target_word": "酸素", "complexity_tier": "T3", "furigana": "部屋[へや]の窓[まど]を閉[し]めきると、酸素[さんそ]が減[へ]って頭[あたま]がぼんやりする。", "sentence_source": "generated"}, {"text": "水の中の酸素が少なくなって、池の魚が弱ってしまった。", "target_word": "酸素", "complexity_tier": "T3", "furigana": "水[みず]の中[なか]の酸素[さんそ]が少[すく]なくなって、池[いけ]の魚[さかな]が弱[よわ]ってしまった。", "sentence_source": "generated"}, {"text": "病気の祖母は、鼻につけた管から酸素を吸っている。", "target_word": "酸素", "complexity_tier": "T3", "furigana": "病気[びょうき]の祖母[そぼ]は、鼻[はな]につけた管[くだ]から酸素[さんそ]を吸[す]っている。", "sentence_source": "generated"}, {"text": "深く息をすると、体に酸素が入って元気になる。", "target_word": "酸素", "complexity_tier": "T3", "furigana": "深[ふか]く息[いき]をすると、体[からだ]に酸素[さんそ]が入[はい]って元気[げんき]になる。", "sentence_source": "generated"}, {"text": "火は酸素がなくなると消えてしまう。", "target_word": "酸素", "complexity_tier": "T3", "furigana": "火[ひ]は酸素[さんそ]がなくなると消[き]えてしまう。", "sentence_source": "generated"}, {"text": "登山者は高い山に登るとき、酸素のボンベを持っていく。", "target_word": "酸素", "complexity_tier": "T3", "furigana": "登山者[とざんしゃ]は高[たか]い山[やま]に登[のぼ]るとき、酸素[さんそ]のボンベを持[も]っていく。", "sentence_source": "generated"}, {"text": "植物は光を受けて、酸素を空気中に出している。", "target_word": "酸素", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]は光[ひかり]を受[う]けて、酸素[さんそ]を空気中[くうきちゅう]に出[だ]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "酸素", "label": "基本形"}], "register": "中立（常体）", "sense_fingerprint": "息をするときに体に取り入れる、生き物に必要な空気中の気体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78c67344-a01c-4ca8-a260-da533eb0cbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37038, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "窒素", "is_correct": false, "explanation": "「空気がうすい」ときに足りなくなるのは酸素です。窒素は空気の約8割を占め、標高が上がっても割合は変わらないので、この文脈に合いません。"}, {"text": "酸素", "is_correct": true, "explanation": "空気がうすくなると取り込める酸素が減るため、「酸素が足りなくなりやすい」と文が成り立ちます。"}, {"text": "二酸化炭素", "is_correct": false, "explanation": "空気中の割合は約0.04%しかなく、山の上で不足して問題になる気体ではないので合いません。"}, {"text": "水素", "is_correct": false, "explanation": "水素は空気中にほとんど含まれないため、「空気がうすいために不足する」という話には合いません。"}], "explanations": {"窒素": "「空気がうすい」ときに足りなくなるのは酸素です。窒素は空気の約8割を占め、標高が上がっても割合は変わらないので、この文脈に合いません。", "酸素": "空気がうすくなると取り込める酸素が減るため、「酸素が足りなくなりやすい」と文が成り立ちます。", "二酸化炭素": "空気中の割合は約0.04%しかなく、山の上で不足して問題になる気体ではないので合いません。", "水素": "水素は空気中にほとんど含まれないため、「空気がうすいために不足する」という話には合いません。"}, "sentence_index": 0, "correct_answer": "酸素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨上がりの森は、酸素が澄んでいて気持ちがいい。", "explanation": "ここは〈空気〉の使い方です。空気は「澄んでいる」と言えますが、酸素は気体の成分名で、澄んだり濁ったりという見た目の状態を表す語ではないので合いません。"}, {"text": "池の酸素が濁って、魚が見えなくなった。", "explanation": "ここは〈水〉の使い方です。水は濁りますが、酸素は無色の気体なので「濁る」とは言えず、この文には合いません。"}, {"text": "火事の現場から酸素がもくもくと立ち上った。", "explanation": "ここは〈煙〉の使い方です。煙は見えるので「もくもくと立ち上る」と言えますが、酸素は無色で目に見えないので合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37038, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アルゴン", "is_correct": false, "explanation": "アルゴンは空気中にわずかに含まれる不活性の気体で、体に取り込んでも元気にする働きはありません。"}, {"text": "一酸化炭素", "is_correct": false, "explanation": "一酸化炭素は体に入ると酸素の運搬を妨げるので、元気になるどころか害になります。"}, {"text": "酸素", "is_correct": true, "explanation": "深く息をして体に取り込み、元気になるのは呼吸で取り込む酸素です。"}, {"text": "メタン", "is_correct": false, "explanation": "メタンは天然ガスの主成分で、体の中で元気にする働きはないので合いません。"}], "explanations": {"アルゴン": "アルゴンは空気中にわずかに含まれる不活性の気体で、体に取り込んでも元気にする働きはありません。", "一酸化炭素": "一酸化炭素は体に入ると酸素の運搬を妨げるので、元気になるどころか害になります。", "酸素": "深く息をして体に取り込み、元気になるのは呼吸で取り込む酸素です。", "メタン": "メタンは天然ガスの主成分で、体の中で元気にする働きはないので合いません。"}, "sentence_index": 6, "correct_answer": "酸素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "台所に焼き魚の酸素がこもった。", "explanation": "ここは〈匂い〉の使い方です。匂いは部屋にこもりますが、酸素は無臭の気体なので、匂いの元として言うことはできません。"}, {"text": "体育館の中で、大きな酸素が響いた。", "explanation": "ここは〈声〉の使い方です。声は体育館の中で響きますが、酸素は音を出さないので「響く」とは言えません。"}, {"text": "このケーキは酸素が甘くて、子どもに人気だ。", "explanation": "ここは〈味〉の使い方です。ケーキは甘いと言えますが、酸素には味がないので「甘い」とは言いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37038, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ダイバーは、背中のタンクに入った酸素で吸って水中で息をする。", "corrected_sentence": "ダイバーは、背中のタンクに入った酸素を吸って水中で息をする。", "error_description": "「で」が誤りで、正しくは「を」です。「吸う」は吸う対象を「を」で示すため、「酸素で吸う」は不自然になります。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37038, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "患者の呼吸を助けるため、鼻から酸素を食べる。", "corrected_sentence": "患者の呼吸を助けるため、鼻から酸素を送り込む。", "error_description": "「食べる」が誤りで、正しくは「送り込む」です。気体の酸素は食べるものではなく、体へ送り込む対象なので、「食べる」は不自然になります。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37039, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「酸素は〜元素である」と話題を示す「は」が正しく、文の主題になります。"}, {"text": "を", "is_correct": false, "explanation": "「表される」は受け身で、「酸素を 表される」の形では酸素が目的語にならず、文が成り立ちません。"}, {"text": "に", "is_correct": false, "explanation": "「酸素に 表される」は不自然で、「表される」の主語にも対象にもなりません。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表しますが、「表される」の向かう先として使うのは不自然です。"}], "correct_answer": "は", "explanations": {"は": "「酸素は〜元素である」と話題を示す「は」が正しく、文の主題になります。", "を": "「表される」は受け身で、「酸素を 表される」の形では酸素が目的語にならず、文が成り立ちません。", "に": "「酸素に 表される」は不自然で、「表される」の主語にも対象にもなりません。", "へ": "「へ」は方向を表しますが、「表される」の向かう先として使うのは不自然です。"}, "error_tags": {"は": "主題", "を": "目的語", "に": "対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37039, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「大気中の酸素は、〜増えてきた」と話題を示す「は」が正しく、酸素が増えた主体になります。"}, {"text": "から", "is_correct": false, "explanation": "「酸素から増えた」は起点を表しますが、酸素を話題にする文の主題としては不自然です。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比べる対象が必要ですが、この文には比較する相手がなく成り立ちません。"}, {"text": "で", "is_correct": false, "explanation": "「酸素で増えてきた」では手段・場所の「で」が「増えてきた」の主体にならず、文が成り立ちません。"}], "correct_answer": "は", "explanations": {"は": "「大気中の酸素は、〜増えてきた」と話題を示す「は」が正しく、酸素が増えた主体になります。", "から": "「酸素から増えた」は起点を表しますが、酸素を話題にする文の主題としては不自然です。", "より": "「より」は比べる対象が必要ですが、この文には比較する相手がなく成り立ちません。", "で": "「酸素で増えてきた」では手段・場所の「で」が「増えてきた」の主体にならず、文が成り立ちません。"}, "error_tags": {"は": "主題", "から": "起点", "より": "比較", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37039, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "空気中に約21%含まれる無色・無臭の気体で、生物の呼吸や燃焼を支える元素。化学記号はO。", "primary_collocate": null, "pronunciation": "さんそ", "ipa": "sanso", "syllable_count": 3, "sentences": [{"text": "空気の約五分の一は酸素で、残りの大部分は窒素だ。", "target_word": "酸素", "complexity_tier": "T3", "furigana": "空気[くうき]の約[やく]五分[ごふん]の一[いち]は酸素[さんそ]で、残[のこ]りの大部分[だいぶぶん]は窒素[ちっそ]だ。", "sentence_source": "generated"}, {"text": "酸素は化学記号Oで表される元素である。", "target_word": "酸素", "complexity_tier": "T3", "furigana": "酸素[さんそ]は化学[かがく]記号[きごう]Oで表[あらわ]される元素[げんそ]である。", "sentence_source": "generated"}, {"text": "物が燃えるには、酸素と熱と燃えるものが必要である。", "target_word": "酸素", "complexity_tier": "T3", "furigana": "物[もの]が燃[も]えるには、酸素[さんそ]と熱[ねつ]と燃[も]えるものが必要[ひつよう]である。", "sentence_source": "generated"}, {"text": "水は水素と酸素が結びついてできている。", "target_word": "酸素", "complexity_tier": "T3", "furigana": "水[みず]は水素[すいそ]と酸素[さんそ]が結[むす]びついてできている。", "sentence_source": "generated"}, {"text": "酸素は色もにおいもない気体で、目には見えない。", "target_word": "酸素", "complexity_tier": "T3", "furigana": "酸素[さんそ]は色[いろ]もにおいもない気体[きたい]で、目[め]には見[み]えない。", "sentence_source": "generated"}, {"text": "鉄がさびるのは、空気中の酸素と反応するからだ。", "target_word": "酸素", "complexity_tier": "T3", "furigana": "鉄[てつ]がさびるのは、空気中[くうきちゅう]の酸素[さんそ]と反応[はんのう]するからだ。", "sentence_source": "generated"}, {"text": "細胞は酸素を使って、食べ物からエネルギーを取り出す。", "target_word": "酸素", "complexity_tier": "T3", "furigana": "細胞[さいぼう]は酸素[さんそ]を使[つか]って、食[た]べ物[もの]からエネルギーを取[と]り出[だ]す。", "sentence_source": "generated"}, {"text": "大気中の酸素は、植物が光合成を行うことで増えてきた。", "target_word": "酸素", "complexity_tier": "T3", "furigana": "大気中[たいきちゅう]の酸素[さんそ]は、植物[しょくぶつ]が光合成[こうごうせい]を行[おこな]うことで増[ふ]えてきた。", "sentence_source": "generated"}, {"text": "液体にした酸素は、ロケットの燃料を燃やすために使われる。", "target_word": "酸素", "complexity_tier": "T3", "furigana": "液体[えきたい]にした酸素[さんそ]は、ロケットの燃料[ねんりょう]を燃[も]やすために使[つか]われる。", "sentence_source": "generated"}, {"text": "地殻の中で最も多い元素は酸素で、重さで約半分を占める。", "target_word": "酸素", "complexity_tier": "T3", "furigana": "地殻[ちかく]の中[なか]で最[もっと]も多[おお]い元素[げんそ]は酸素[さんそ]で、重[おも]さで約[やく]半分[はんぶん]を占[し]める。", "sentence_source": "generated"}], "morphological_forms": [{"form": "酸素", "label": "基本形"}], "register": "科学的な説明文（常体）", "sense_fingerprint": "化学記号Oで表される元素で、呼吸・燃焼・さびなどの反応に関わる気体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T3: contains vocabulary far above tier T3: さびる (Zipf 1.07)']::text[], '78c67344-a01c-4ca8-a260-da533eb0cbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37039, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "二酸化炭素", "is_correct": false, "explanation": "空気中の割合は約0.04%で、約五分の一を占めるという文の内容には合いません。"}, {"text": "ヘリウム", "is_correct": false, "explanation": "ヘリウムは空気中にごくわずかしかなく、五分の一を占める気体ではありません。"}, {"text": "酸素", "is_correct": true, "explanation": "空気の約五分の一（約20%）を占める気体で、残りの大部分が窒素という文の内容と合います。"}, {"text": "アルゴン", "is_correct": false, "explanation": "アルゴンは空気の約1%で、五分の一ではないので合いません。"}], "explanations": {"二酸化炭素": "空気中の割合は約0.04%で、約五分の一を占めるという文の内容には合いません。", "ヘリウム": "ヘリウムは空気中にごくわずかしかなく、五分の一を占める気体ではありません。", "酸素": "空気の約五分の一（約20%）を占める気体で、残りの大部分が窒素という文の内容と合います。", "アルゴン": "アルゴンは空気の約1%で、五分の一ではないので合いません。"}, "sentence_index": 0, "correct_answer": "酸素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この液体は酸素なので、金属が少しずつ溶ける。", "explanation": "ここは〈酸性〉の意味です。酸素は気体の元素名で、液体の性質を表す語としては使いません。「酸性」が正しい語です。"}, {"text": "窓の酸素は、雨が降るとさびる。", "explanation": "ここは〈鉄〉の使い方です。さびるのは鉄などの金属で、酸素は鉄をさびさせる働きをするものの、自分がさびることはありません。"}, {"text": "酸素は空気と混ざると、火をつけると激しく燃える。", "explanation": "ここは〈水素〉の使い方です。水素は燃える気体ですが、酸素は物を燃やす働きをするだけで、自分が燃えることはありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37039, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水素", "is_correct": false, "explanation": "細胞が呼吸で使うのは酸素で、水素はエネルギーを取り出す反応には使われません。"}, {"text": "オゾン", "is_correct": false, "explanation": "オゾンは酸素の仲間ですが、細胞の呼吸には使われず、体には有害です。"}, {"text": "酸素", "is_correct": true, "explanation": "細胞が食べ物からエネルギーを取り出すときに使う気体は酸素です。"}, {"text": "メタン", "is_correct": false, "explanation": "メタンは天然ガスの主成分で、細胞の呼吸には使われないので合いません。"}], "explanations": {"水素": "細胞が呼吸で使うのは酸素で、水素はエネルギーを取り出す反応には使われません。", "オゾン": "オゾンは酸素の仲間ですが、細胞の呼吸には使われず、体には有害です。", "酸素": "細胞が食べ物からエネルギーを取り出すときに使う気体は酸素です。", "メタン": "メタンは天然ガスの主成分で、細胞の呼吸には使われないので合いません。"}, "sentence_index": 6, "correct_answer": "酸素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜明けの酸素が、部屋をやさしく照らした。", "explanation": "ここは〈光〉の使い方です。光は部屋を照らしますが、酸素は無色の気体で光を出さないので、照らすことはできません。"}, {"text": "昨日は夕方から酸素が降り出した。", "explanation": "ここは〈雨〉の使い方です。雨は降りますが、酸素は気体なので降ることはなく、この言い方は合いません。"}, {"text": "庭の酸素がやさしく香っていた。", "explanation": "ここは〈花〉の使い方です。花は香りますが、酸素は無臭なので香ることはありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37039, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "火を消すには、酸素に供給を断つのが有効だ。", "corrected_sentence": "火を消すには、酸素の供給を断つのが有効だ。", "error_description": "「に」が誤りで、正しくは「の」です。「酸素の供給」は名詞同士を「の」でつなぐ形で、「酸素に供給」は成り立たないため不自然です。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37039, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "潜水の前に、タンクの酸素をしっかり飲んだ。", "corrected_sentence": "潜水の前に、タンクの酸素をしっかり確かめた。", "error_description": "「飲んだ」が誤りで、正しくは「確かめた」です。気体の酸素は飲むものではなく、残量などを確かめる対象なので、「飲む」は不自然になります。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37040, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「建物の内部は、外より涼しい」と比べる話題を示す「は」が正しく、文の主題になります。"}, {"text": "を", "is_correct": false, "explanation": "「涼しい」は状態を表す形容詞で目的語を取らないので、「内部を涼しい」は成り立ちません。"}, {"text": "に", "is_correct": false, "explanation": "「内部に 外より涼しい」は主語と述語が結びつかず、不自然です。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表しますが、「涼しい」の主語にはならないので合いません。"}], "correct_answer": "は", "explanations": {"は": "「建物の内部は、外より涼しい」と比べる話題を示す「は」が正しく、文の主題になります。", "を": "「涼しい」は状態を表す形容詞で目的語を取らないので、「内部を涼しい」は成り立ちません。", "に": "「内部に 外より涼しい」は主語と述語が結びつかず、不自然です。", "へ": "「へ」は方向を表しますが、「涼しい」の主語にはならないので合いません。"}, "error_tags": {"は": "主題", "を": "目的語", "に": "場所・状態", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外部", "is_correct": true, "explanation": "「内部」は物のうちがわの部分を表すので、その反対のそとがわの部分を表す「外部」が対義語になります。"}, {"text": "昼間", "is_correct": false, "explanation": "「昼間」は時を表す語で、「内部」の対義語にはなりません。"}, {"text": "地上", "is_correct": false, "explanation": "「地上」は地面の上の場所を指し、物のうちがわの部分の反対語にはなりません。"}, {"text": "周囲", "is_correct": false, "explanation": "「周囲」はまわりの範囲を指す語で、「内部」の対義語として辞書には並びません。"}], "correct_answer": "外部", "explanations": {"外部": "「内部」は物のうちがわの部分を表すので、その反対のそとがわの部分を表す「外部」が対義語になります。", "昼間": "「昼間」は時を表す語で、「内部」の対義語にはなりません。", "地上": "「地上」は地面の上の場所を指し、物のうちがわの部分の反対語にはなりません。", "周囲": "「周囲」はまわりの範囲を指す語で、「内部」の対義語として辞書には並びません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37040, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「地球の内部は、〜熱いと言われている」と話題を示す「は」が正しく、文の主題になります。"}, {"text": "と", "is_correct": false, "explanation": "「地球の内部と、とても熱い」と並列になると、「言われています」の文として成り立ちません。"}, {"text": "の", "is_correct": false, "explanation": "「地球の内部の、とても熱い」と続けると名詞の修飾になり、文が成り立ちません。"}, {"text": "を", "is_correct": false, "explanation": "「言われる」は「AをBと言う」の受け身なので、目的語の「を」は残らず、文が成り立ちません。"}], "correct_answer": "は", "explanations": {"は": "「地球の内部は、〜熱いと言われている」と話題を示す「は」が正しく、文の主題になります。", "と": "「地球の内部と、とても熱い」と並列になると、「言われています」の文として成り立ちません。", "の": "「地球の内部の、とても熱い」と続けると名詞の修飾になり、文が成り立ちません。", "を": "「言われる」は「AをBと言う」の受け身なので、目的語の「を」は残らず、文が成り立ちません。"}, "error_tags": {"は": "主題", "と": "並列", "の": "修飾", "を": "目的語"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外部", "is_correct": true, "explanation": "「内部」は物のうちがわの部分を表すので、その反対のそとがわの部分を表す「外部」が対義語になります。"}, {"text": "海面", "is_correct": false, "explanation": "「海面」は海の水面を指し、物のうちがわの部分の反対語にはなりません。"}, {"text": "空中", "is_correct": false, "explanation": "「空中」は空の中の場所を指し、「内部」の対義語として辞書には並びません。"}, {"text": "路上", "is_correct": false, "explanation": "「路上」は道の上の場所を指し、物のうちがわの部分の反対語にはなりません。"}], "correct_answer": "外部", "explanations": {"外部": "「内部」は物のうちがわの部分を表すので、その反対のそとがわの部分を表す「外部」が対義語になります。", "海面": "「海面」は海の水面を指し、物のうちがわの部分の反対語にはなりません。", "空中": "「空中」は空の中の場所を指し、「内部」の対義語として辞書には並びません。", "路上": "「路上」は道の上の場所を指し、物のうちがわの部分の反対語にはなりません。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37040, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "もののうちがわの部分。", "primary_collocate": null, "pronunciation": "ないぶ", "ipa": "naibɯ", "syllable_count": 3, "sentences": [{"text": "この箱の内部は、赤い紙が貼ってあります。", "target_word": "内部", "complexity_tier": "T3", "furigana": "この箱[はこ]の内部[ないぶ]は、赤[あか]い紙[かみ]が貼[は]ってあります。", "sentence_source": "generated"}, {"text": "建物の内部は外より涼しいです。", "target_word": "内部", "complexity_tier": "T3", "furigana": "建物[たてもの]の内部[ないぶ]は外[そと]より涼[すず]しいです。", "sentence_source": "generated"}, {"text": "時計の内部には小さな部品がたくさんあります。", "target_word": "内部", "complexity_tier": "T3", "furigana": "時計[とけい]の内部[ないぶ]には小[ちい]さな部品[ぶひん]がたくさんあります。", "sentence_source": "generated"}, {"text": "工事のため、ビルの内部には入れません。", "target_word": "内部", "complexity_tier": "T3", "furigana": "工事[こうじ]のため、ビルの内部[ないぶ]には入[はい]れません。", "sentence_source": "generated"}, {"text": "外から見ると新しいですが、車の内部はとても古いです。", "target_word": "内部", "complexity_tier": "T3", "furigana": "外[そと]から見[み]ると新[あたら]しいですが、車[くるま]の内部[ないぶ]はとても古[ふる]いです。", "sentence_source": "generated"}, {"text": "洞窟の内部は暗いので、ライトが必要です。", "target_word": "内部", "complexity_tier": "T3", "furigana": "洞窟[どうくつ]の内部[ないぶ]は暗[くら]いので、ライトが必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "汚れていたので、冷蔵庫の内部を掃除しました。", "target_word": "内部", "complexity_tier": "T3", "furigana": "汚[よご]れていたので、冷蔵庫[れいぞうこ]の内部[ないぶ]を掃除[そうじ]しました。", "sentence_source": "generated"}, {"text": "地球の内部は、とても熱いと言われています。", "target_word": "内部", "complexity_tier": "T3", "furigana": "地球[ちきゅう]の内部[ないぶ]は、とても熱[あつ]いと言[い]われています。", "sentence_source": "generated"}, {"text": "機械の内部に水が入って、動かなくなりました。", "target_word": "内部", "complexity_tier": "T3", "furigana": "機械[きかい]の内部[ないぶ]に水[みず]が入[はい]って、動[うご]かなくなりました。", "sentence_source": "generated"}, {"text": "大きな果物でも、内部が傷んでいることがあります。", "target_word": "内部", "complexity_tier": "T3", "furigana": "大[おお]きな果物[くだもの]でも、内部[ないぶ]が傷[いた]んでいることがあります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "内部", "label": "基本形"}, {"form": "内部の", "label": "連体形"}], "register": "丁寧語", "sense_fingerprint": "ものや建物の外側に対する、うちがわの部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78c67344-a01c-4ca8-a260-da533eb0cbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37040, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "形", "is_correct": false, "explanation": "「形」は箱の外から見た姿を表すので、赤い紙が中に貼ってあるという内容とはつながりません。"}, {"text": "内部", "is_correct": true, "explanation": "赤い紙が貼ってあるのは箱の内側なので、「この箱の内部」が文の内容と合います。"}, {"text": "重さ", "is_correct": false, "explanation": "「重さ」は箱の重さを表すので、紙が貼ってある場所を示す文には合いません。"}, {"text": "色", "is_correct": false, "explanation": "「色」は箱の色を表すので、紙が貼ってある場所を示すことはできません。"}], "explanations": {"形": "「形」は箱の外から見た姿を表すので、赤い紙が中に貼ってあるという内容とはつながりません。", "内部": "赤い紙が貼ってあるのは箱の内側なので、「この箱の内部」が文の内容と合います。", "重さ": "「重さ」は箱の重さを表すので、紙が貼ってある場所を示す文には合いません。", "色": "「色」は箱の色を表すので、紙が貼ってある場所を示すことはできません。"}, "sentence_index": 0, "correct_answer": "内部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "志望していた会社から、ついに内部をもらいました。", "explanation": "ここは〈内定〉の意味です。内定は会社から採用が決まることで、「内定をもらう」と言います。「内部」は物の内側の部分なので、もらうものとしては使いません。"}, {"text": "カプセルの内部を、水と一緒に飲みました。", "explanation": "ここは〈中身〉の使い方です。中身は粉や液体など飲めるものを指しますが、内部は物の内側の部分を表すので、飲むものとは言えません。"}, {"text": "このブランドの靴は内部が高いですけれど、丈夫です。", "explanation": "ここは〈値段〉の使い方です。値段は高い・安いと評価しますが、内部は場所を表す語なので、高い・安いとは言えません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37040, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "値段", "is_correct": false, "explanation": "値段は掃除の対象にならず、「冷蔵庫の値段を掃除しました」は成り立ちません。"}, {"text": "音", "is_correct": false, "explanation": "冷蔵庫の音は掃除の対象にならないので、この文には合いません。"}, {"text": "内部", "is_correct": true, "explanation": "汚れた冷蔵庫の中を掃除するという文の内容と、「冷蔵庫の内部」が合います。"}, {"text": "温度", "is_correct": false, "explanation": "温度は掃除の対象ではなく、冷蔵庫の中を掃除するという文脈とは合いません。"}], "explanations": {"値段": "値段は掃除の対象にならず、「冷蔵庫の値段を掃除しました」は成り立ちません。", "音": "冷蔵庫の音は掃除の対象にならないので、この文には合いません。", "内部": "汚れた冷蔵庫の中を掃除するという文の内容と、「冷蔵庫の内部」が合います。", "温度": "温度は掃除の対象ではなく、冷蔵庫の中を掃除するという文脈とは合いません。"}, "sentence_index": 6, "correct_answer": "内部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の内部が、言葉の端々から伝わってきました。", "explanation": "ここは〈気持ち〉の意味です。気持ちは相手に伝わりますが、内部は場所や構造を表す語で、感情の伝わり方には使いません。"}, {"text": "明日は一日中、内部がいいそうです。", "explanation": "ここは〈天気〉の意味です。天気は晴れや雨など空模様の良し悪しを言いますが、内部は天気の状態を表しません。"}, {"text": "このスープは内部が濃くて、少ししょっぱいです。", "explanation": "ここは〈味〉の意味です。味は濃い・薄いと言いますが、内部は味の濃さを表さないので、この文では使えません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37040, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "許可がないと、工場の内部を入ることはできません。", "corrected_sentence": "許可がないと、工場の内部に入ることはできません。", "error_description": "「を」が誤りで、正しくは「に」です。「入る」は移動先を「に」で示すので、「内部を入る」は不自然になります。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37040, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "エンジンの内部を注文して、油漏れを見つけました。", "corrected_sentence": "エンジンの内部を点検して、油漏れを見つけました。", "error_description": "「注文して」が誤りで、正しくは「点検して」です。「内部」は注文の対象にならず、油漏れを見つける動作と合う「点検する」が必要です。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
