INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37042, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "五十という数字をあらわすことばです。", "primary_collocate": null, "pronunciation": "ごじゅう", "ipa": "ɡodʑɯː", "syllable_count": 3, "sentences": [{"text": "「50」は5の10倍です。", "target_word": "50", "complexity_tier": "T3", "furigana": "「50」は5の10倍[ばい]です。", "sentence_source": "generated"}, {"text": "30と20を足すと「50」になります。", "target_word": "50", "complexity_tier": "T3", "furigana": "30と20を足[た]すと「50」になります。", "sentence_source": "generated"}, {"text": "100の半分は「50」です。", "target_word": "50", "complexity_tier": "T3", "furigana": "100の半分[はんぶん]は「50」です。", "sentence_source": "generated"}, {"text": "「50」から10を引くと、40になります。", "target_word": "50", "complexity_tier": "T3", "furigana": "「50」から10を引[ひ]くと、40になります。", "sentence_source": "generated"}, {"text": "先生は黒板に大きく「50」と書きました。", "target_word": "50", "complexity_tier": "T3", "furigana": "先生[せんせい]は黒板[こくばん]に大[おお]きく「50」と書[か]きました。", "sentence_source": "generated"}, {"text": "数字の「50」は、ゼロが一つあります。", "target_word": "50", "complexity_tier": "T3", "furigana": "数字[すうじ]の「50」は、ゼロが一[ひと]つあります。", "sentence_source": "generated"}, {"text": "10が5つ集まると「50」です。", "target_word": "50", "complexity_tier": "T3", "furigana": "10が5[いつ]つ集[あつ]まると「50」です。", "sentence_source": "generated"}, {"text": "「50」の次の数は51です。", "target_word": "50", "complexity_tier": "T3", "furigana": "「50」の次[つぎ]の数[かず]は51です。", "sentence_source": "generated"}, {"text": "25を二倍にすると「50」になります。", "target_word": "50", "complexity_tier": "T3", "furigana": "25を二倍[にばい]にすると「50」になります。", "sentence_source": "generated"}, {"text": "1から「50」まで声に出して数えました。", "target_word": "50", "complexity_tier": "T3", "furigana": "1から「50」まで声[こえ]に出[だ]して数[かぞ]えました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "50", "label": "基本形"}], "register": "丁寧語", "sense_fingerprint": "数字の五十そのもの。計算や数え方で使う数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78c67344-a01c-4ca8-a260-da533eb0cbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37042, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "500", "is_correct": false, "explanation": "「500」は5の100倍で、5の10倍ではないので合いません。"}, {"text": "50", "is_correct": true, "explanation": "5の10倍は五十で、「50」にあたるので文の内容と合います。"}, {"text": "15", "is_correct": false, "explanation": "「15」は5の3倍で、5の10倍にはならないので合いません。"}, {"text": "25", "is_correct": false, "explanation": "「25」は5の5倍で、5の10倍ではないので合いません。"}], "explanations": {"500": "「500」は5の100倍で、5の10倍ではないので合いません。", "50": "5の10倍は五十で、「50」にあたるので文の内容と合います。", "15": "「15」は5の3倍で、5の10倍にはならないので合いません。", "25": "「25」は5の5倍で、5の10倍ではないので合いません。"}, "sentence_index": 0, "correct_answer": "50"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この言葉は50音あって、とても長いです。", "explanation": "ここは〈五音〉の意味です。五十音は仮名の表を指す語で、単語の音の数は「五音」のように言います。五十音を音数として使うことはありません。"}, {"text": "彼は五十中八九、遅刻するでしょう。", "explanation": "ここは〈十〉の意味です。「十中八九」は十のうち八か九、つまりほとんどという成句で、「十」を「五十」に変えると成句として通じません。"}, {"text": "勝率は50割でした。", "explanation": "ここは〈五割〉の意味です。割は十分の一を表す単位で、50％は「五割」と言います。「50割」は500％の意味になるので、勝率には使えません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37042, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "60", "is_correct": false, "explanation": "「10が6つ集まると」は60になり、5つ集まると50という文の内容と合いません。"}, {"text": "50", "is_correct": true, "explanation": "10が5つ集まると50になるので、文の内容と合います。"}, {"text": "55", "is_correct": false, "explanation": "「55」は10の倍数ではなく、10が5つ集まった数にはなりません。"}, {"text": "510", "is_correct": false, "explanation": "「510」は10が51個分の数で、10が5つ集まった数ではありません。"}], "explanations": {"60": "「10が6つ集まると」は60になり、5つ集まると50という文の内容と合いません。", "50": "10が5つ集まると50になるので、文の内容と合います。", "55": "「55」は10の倍数ではなく、10が5つ集まった数にはなりません。", "510": "「510」は10が51個分の数で、10が5つ集まった数ではありません。"}, "sentence_index": 6, "correct_answer": "50"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その教会の屋根には、大きな50字架が飾られています。", "explanation": "ここは〈十字架〉の意味です。十字架は十の字の形をした物を指す語で、「50字架」という言い方はありません。"}, {"text": "春の庭は五十花繚乱です。", "explanation": "ここは〈百〉の意味です。「百花繚乱」は色とりどりの花が咲き乱れる様子を表す成句で、「百」を「五十」に変えると成句になりません。"}, {"text": "駅前の50字路で、友達と待ち合わせました。", "explanation": "ここは〈十字路〉の意味です。十字路は道が交差する場所を指す語で、「50字路」という言い方はありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37042, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "50本の生徒が、校庭に集まりました。", "corrected_sentence": "50人の生徒が、校庭に集まりました。", "error_description": "「本」が誤りで、正しくは「人」です。生徒は「人」で数えるので、「本」の数え方は合いません。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37042, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "50に大きい数だけを選びました。", "corrected_sentence": "50より大きい数だけを選びました。", "error_description": "「に」が誤りで、正しくは「より」です。比べる基準を示す「より」が必要で、「に」は「大きい」と結びつかず不自然です。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
