INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37043, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "数字の50を表す。数量や順番などを示すのに使う。", "primary_collocate": null, "pronunciation": "ごじゅう", "ipa": "ɡodʑɯː", "syllable_count": 3, "sentences": [{"text": "出席番号は「50」です。", "target_word": "50", "complexity_tier": "T3", "furigana": "出席番号[しゅっせきばんごう]は「50」です。", "sentence_source": "generated"}, {"text": "参加者は全部で「50」でした。", "target_word": "50", "complexity_tier": "T3", "furigana": "参加者[さんかしゃ]は全部[ぜんぶ]で「50」でした。", "sentence_source": "generated"}, {"text": "私の順位は「50」で、百人中の真ん中でした。", "target_word": "50", "complexity_tier": "T3", "furigana": "私[わたし]の順位[じゅんい]は「50」で、百人中[ひゃくにんちゅう]の真[ま]ん中[なか]でした。", "sentence_source": "generated"}, {"text": "部屋の番号は「50」で、廊下の奥にあります。", "target_word": "50", "complexity_tier": "T3", "furigana": "部屋[へや]の番号[ばんごう]は「50」で、廊下[ろうか]の奥[おく]にあります。", "sentence_source": "generated"}, {"text": "乗るバスは「50」ですか、15ですか。", "target_word": "50", "complexity_tier": "T3", "furigana": "乗[の]るバスは「50」ですか、15ですか。", "sentence_source": "generated"}, {"text": "走った人の数は49ではなく「50」でした。", "target_word": "50", "complexity_tier": "T3", "furigana": "走[はし]った人[ひと]の数[かず]は49ではなく「50」でした。", "sentence_source": "generated"}, {"text": "売れた本は、先月が40で、今月が「50」でした。", "target_word": "50", "complexity_tier": "T3", "furigana": "売[う]れた本[ほん]は、先月[せんげつ]が40で、今月[こんげつ]が「50」でした。", "sentence_source": "generated"}, {"text": "席の数は「50」で、ほとんど満席です。", "target_word": "50", "complexity_tier": "T3", "furigana": "席[せき]の数[かず]は「50」で、ほとんど満席[まんせき]です。", "sentence_source": "generated"}, {"text": "彼のゼッケンは「50」なので、すぐ分かります。", "target_word": "50", "complexity_tier": "T3", "furigana": "彼[かれ]のゼッケンは「50」なので、すぐ分[わ]かります。", "sentence_source": "generated"}, {"text": "一回目の点数は30で、二回目は「50」でした。", "target_word": "50", "complexity_tier": "T3", "furigana": "一回目[いっかいめ]の点数[てんすう]は30で、二回目[にかいめ]は「50」でした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "50", "label": "基本形"}], "register": "丁寧語", "sense_fingerprint": "数量や順番、番号を示す50", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78c67344-a01c-4ca8-a260-da533eb0cbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37043, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "50", "is_correct": true, "explanation": "出席番号として文中に示された数字で、これが正解。"}, {"text": "40", "is_correct": false, "explanation": "40は別の数字で、この文に示された番号ではない。"}, {"text": "15", "is_correct": false, "explanation": "15は文中の番号ではない数字で、ここには当てはまらない。"}, {"text": "49", "is_correct": false, "explanation": "49は50の一つ前の数で、文中の番号とは異なる。"}], "explanations": {"50": "出席番号として文中に示された数字で、これが正解。", "40": "40は別の数字で、この文に示された番号ではない。", "15": "15は文中の番号ではない数字で、ここには当てはまらない。", "49": "49は50の一つ前の数で、文中の番号とは異なる。"}, "sentence_index": 0, "correct_answer": "50"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この表は50音順に並んでいる。", "explanation": "ここは〈五十音〉という別の語。数字の50では音の順は表せないので合わない。"}, {"text": "50円玉を一枚拾った。", "explanation": "ここは〈50円玉〉という硬貨の語。数字の50そのものは硬貨を指せないので合わない。"}, {"text": "50メートル走で一位になった。", "explanation": "ここは〈50メートル走〉という競技名の一部。数字の50の意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37043, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "50", "is_correct": true, "explanation": "売れた本の今月の数として文中に示された数字で、これが正解。"}, {"text": "60", "is_correct": false, "explanation": "60は別の数字で、ここで示された数ではない。"}, {"text": "45", "is_correct": false, "explanation": "45は文中の数ではなく、今月の数と一致しない。"}, {"text": "100", "is_correct": false, "explanation": "100は百のことで、ここで示された数ではない。"}], "explanations": {"50": "売れた本の今月の数として文中に示された数字で、これが正解。", "60": "60は別の数字で、ここで示された数ではない。", "45": "45は文中の数ではなく、今月の数と一致しない。", "100": "100は百のことで、ここで示された数ではない。"}, "sentence_index": 6, "correct_answer": "50"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "50年代の映画が好きで、よく見ます。", "explanation": "ここは〈50年代〉（1950年代）という年代の語。数字の50だけでは年代は指せない。"}, {"text": "50代の上司に相談した。", "explanation": "ここは〈50代〉という年齢層の語。数字の50そのものは年齢層を指せない。"}, {"text": "ファイルを50音順に並べ直した。", "explanation": "ここは〈五十音〉という別の語。数字の50では音の順は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37043, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "50番の席を座ります。", "corrected_sentence": "50番の席に座ります。", "error_description": "「座る」は場所を表す「に」を取るが、ここでは「を」になっている。誤りは「50番の席」に付く助詞。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37043, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会場には50人を来ました。", "corrected_sentence": "会場には50人が来ました。", "error_description": "「来る」の主語には「が」を使うが、ここでは「を」になっている。誤りは「50人」に付く助詞。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
