INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37044, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「60キロ前後で」の「で」は後の〈安定しています〉へつなぐ接続の用法で、文中に入る。"}, {"text": "と", "is_correct": false, "explanation": "引用・並列の「と」で、〈安定しています〉とはつながらない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」だが、〈安定しています〉の文に目的語は要らないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は名詞を修飾するもので、述語の前には置けない。"}], "correct_answer": "で", "explanations": {"で": "「60キロ前後で」の「で」は後の〈安定しています〉へつなぐ接続の用法で、文中に入る。", "と": "引用・並列の「と」で、〈安定しています〉とはつながらない。", "を": "目的語の「を」だが、〈安定しています〉の文に目的語は要らないので合わない。", "の": "連体修飾の「の」は名詞を修飾するもので、述語の前には置けない。"}, "error_tags": {"と": "並列・引用", "を": "目的語", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37044, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「前後」は、ある数字の近くという意味です。", "primary_collocate": null, "pronunciation": "ぜんご", "ipa": "dzeŋɡo", "syllable_count": 3, "sentences": [{"text": "父は50歳前後に見えます。", "target_word": "前後", "complexity_tier": "T3", "furigana": "父[ちち]は50歳[さい]前後[ぜんご]に見[み]えます。", "sentence_source": "generated"}, {"text": "この店のラーメンは、800円前後です。", "target_word": "前後", "complexity_tier": "T3", "furigana": "この店[みせ]のラーメンは、800円[えん]前後[ぜんご]です。", "sentence_source": "generated"}, {"text": "参加者は、20人前後だと思います。", "target_word": "前後", "complexity_tier": "T3", "furigana": "参加者[さんかしゃ]は、20人[にん]前後[ぜんご]だと思[おも]います。", "sentence_source": "generated"}, {"text": "彼女の身長は、160センチ前後です。", "target_word": "前後", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の身長[しんちょう]は、160センチ前後[ぜんご]です。", "sentence_source": "generated"}, {"text": "今日の気温は、25度前後でしょう。", "target_word": "前後", "complexity_tier": "T3", "furigana": "今日[きょう]の気温[きおん]は、25度[ど]前後[ぜんご]でしょう。", "sentence_source": "generated"}, {"text": "会社の新入社員は、毎年30人前後です。", "target_word": "前後", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の新入社員[しんにゅうしゃいん]は、毎年[まいとし]30人[にん]前後[ぜんご]です。", "sentence_source": "generated"}, {"text": "この靴は、5000円前後で買えます。", "target_word": "前後", "complexity_tier": "T3", "furigana": "この靴[くつ]は、5000円[えん]前後[ぜんご]で買[か]えます。", "sentence_source": "generated"}, {"text": "体重は、60キロ前後で安定しています。", "target_word": "前後", "complexity_tier": "T3", "furigana": "体重[たいじゅう]は、60キロ前後[ぜんご]で安定[あんてい]しています。", "sentence_source": "generated"}, {"text": "家から駅までは、1キロ前後です。", "target_word": "前後", "complexity_tier": "T3", "furigana": "家[いえ]から駅[えき]までは、1キロ前後[ぜんご]です。", "sentence_source": "generated"}, {"text": "家賃は、月に7万円前後です。", "target_word": "前後", "complexity_tier": "T3", "furigana": "家賃[やちん]は、月[つき]に7万円[まんえん]前後[ぜんご]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "前後", "label": "基本形"}, {"form": "前後の", "label": "連体形"}], "register": "丁寧語", "sense_fingerprint": "年齢・金額・人数などの数字のあたりを示す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78c67344-a01c-4ca8-a260-da533eb0cbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37044, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前後", "is_correct": true, "explanation": "「50歳前後」のように、年齢のおよその範囲を示すので正解。"}, {"text": "直前", "is_correct": false, "explanation": "直前はある時点のすぐ前を指し、年齢のおよその範囲には合わない。"}, {"text": "最中", "is_correct": false, "explanation": "最中はその行為が続いている間の意味で、年齢の目安には使えない。"}, {"text": "以内", "is_correct": false, "explanation": "以内は上限を示すので、〈およその年齢〉の意味と合わない。"}], "explanations": {"前後": "「50歳前後」のように、年齢のおよその範囲を示すので正解。", "直前": "直前はある時点のすぐ前を指し、年齢のおよその範囲には合わない。", "最中": "最中はその行為が続いている間の意味で、年齢の目安には使えない。", "以内": "以内は上限を示すので、〈およその年齢〉の意味と合わない。"}, "sentence_index": 0, "correct_answer": "前後"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は昨日の飲み会で、前後不覚になるまで飲んだ。", "explanation": "ここは〈前後不覚〉（意識がない状態）という別の語。数量の目安の意味では合わない。"}, {"text": "電車はちょうど7時前後に出た。", "explanation": "ここは〈ちょうど〉（正確な時刻）の意味。「前後」は目安なので、「ちょうど」と組むと合わない。"}, {"text": "彼女の身長は、160センチ前後と言い切れるほど正確だ。", "explanation": "ここは〈正確〉の意味。前後は大まかな範囲なので、正確さを表す文脈と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37044, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前後", "is_correct": true, "explanation": "「5000円前後」のように、金額のおよその目安を示すので正解。"}, {"text": "直後", "is_correct": false, "explanation": "直後はその時点のすぐ後を指し、金額の目安には合わない。"}, {"text": "以前", "is_correct": false, "explanation": "以前は〈前〉の時間を示し、金額の目安には使えない。"}, {"text": "以後", "is_correct": false, "explanation": "以後はそれから先を示す意味で、金額の目安に合わない。"}], "explanations": {"前後": "「5000円前後」のように、金額のおよその目安を示すので正解。", "直後": "直後はその時点のすぐ後を指し、金額の目安には合わない。", "以前": "以前は〈前〉の時間を示し、金額の目安には使えない。", "以後": "以後はそれから先を示す意味で、金額の目安に合わない。"}, "sentence_index": 6, "correct_answer": "前後"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電車に乗る前に、前後を見回して安全を確かめた。", "explanation": "ここは〈前後〉が前と後ろの方向を指す別の語義。数量の目安の意味では合わない。"}, {"text": "家賃は、月に7万円前後ぴったりです。", "explanation": "ここは〈ぴったり〉（正確な額）の意味。前後は目安で、正確な額とは合わない。"}, {"text": "家賃は、7万円前後の下限として、それより安くはならない。", "explanation": "ここは〈下限〉（それ以上）の意味。前後は目安で、下限を表す文脈と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37044, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は30歳前後を男性です。", "corrected_sentence": "彼は30歳前後の男性です。", "error_description": "「前後」が修飾する名詞には「の」を使うが、ここでは「を」になっている。誤りは「前後」に付く助詞。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37044, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明日は午前5時前後で出発します。", "corrected_sentence": "明日は午前5時前後に出発します。", "error_description": "「出発する」は時点を示す「に」を取るが、ここでは「で」になっている。誤りは「前後」に付く助詞。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37045, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "時点を示す「に」で、「7時前後に」として後の〈家を出ます〉へつながる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」だが、時刻に付けると〈家を出る〉の主語として不自然。"}, {"text": "と", "is_correct": false, "explanation": "共同・引用の「と」で、時刻に付けて〈家を出る〉と結ぶのは合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」で、時点を表す文脈には合わない。"}], "correct_answer": "に", "explanations": {"に": "時点を示す「に」で、「7時前後に」として後の〈家を出ます〉へつながる。", "が": "主語を示す「が」だが、時刻に付けると〈家を出る〉の主語として不自然。", "と": "共同・引用の「と」で、時刻に付けて〈家を出る〉と結ぶのは合わない。", "へ": "方向を示す「へ」で、時点を表す文脈には合わない。"}, "error_tags": {"が": "主語", "と": "共同・引用", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37045, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "引用の「と」で、「発表されました」の内容を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」だが、受け身の〈発表されました〉の文には合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」で、内容を引用する文脈とは合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」で、発表の内容を導くことはできない。"}], "correct_answer": "と", "explanations": {"と": "引用の「と」で、「発表されました」の内容を示す。", "を": "目的語の「を」だが、受け身の〈発表されました〉の文には合わない。", "から": "起点の「から」で、内容を引用する文脈とは合わない。", "の": "連体修飾の「の」で、発表の内容を導くことはできない。"}, "error_tags": {"を": "目的語", "から": "起点", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37045, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「前後」は、数量や時間のおよその範囲を表し、基準となる値の前後を含むことを示します。", "primary_collocate": null, "pronunciation": "ぜんご", "ipa": "dzeŋɡo", "syllable_count": 3, "sentences": [{"text": "会議は、午後3時前後に終わります。", "target_word": "前後", "complexity_tier": "T3", "furigana": "会議[かいぎ]は、午後[ごご]3時[じ]前後[ぜんご]に終[お]わります。", "sentence_source": "generated"}, {"text": "毎朝、7時前後に家を出ます。", "target_word": "前後", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、7時[じ]前後[ぜんご]に家[いえ]を出[で]ます。", "sentence_source": "generated"}, {"text": "荷物は、明日の正午前後に届く予定です。", "target_word": "前後", "complexity_tier": "T3", "furigana": "荷物[にもつ]は、明日[あした]の正午[しょうご]前後[ぜんご]に届[とど]く予定[よてい]です。", "sentence_source": "generated"}, {"text": "試合は、2時間前後で終わるでしょう。", "target_word": "前後", "complexity_tier": "T3", "furigana": "試合[しあい]は、2時間[じかん]前後[ぜんご]で終[お]わるでしょう。", "sentence_source": "generated"}, {"text": "桜は、毎年4月10日前後に咲きます。", "target_word": "前後", "complexity_tier": "T3", "furigana": "桜[さくら]は、毎年[まいとし]4月[がつ]10日[か]前後[ぜんご]に咲[さ]きます。", "sentence_source": "generated"}, {"text": "渋滞のため、到着は9時前後になりそうです。", "target_word": "前後", "complexity_tier": "T3", "furigana": "渋滞[じゅうたい]のため、到着[とうちゃく]は9時[じ]前後[ぜんご]になりそうです。", "sentence_source": "generated"}, {"text": "作るのに、30分前後かかります。", "target_word": "前後", "complexity_tier": "T3", "furigana": "作[つく]るのに、30分[ぷん]前後[ぜんご]かかります。", "sentence_source": "generated"}, {"text": "来場者は、1000人前後と発表されました。", "target_word": "前後", "complexity_tier": "T3", "furigana": "来場者[らいじょうしゃ]は、1000人[にん]前後[ぜんご]と発表[はっぴょう]されました。", "sentence_source": "generated"}, {"text": "週末は、夜10時前後に寝ています。", "target_word": "前後", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]は、夜[よる]10時[じ]前後[ぜんご]に寝[ね]ています。", "sentence_source": "generated"}, {"text": "雨は、夕方5時前後にやむでしょう。", "target_word": "前後", "complexity_tier": "T3", "furigana": "雨[あめ]は、夕方[ゆうがた]5時[じ]前後[ぜんご]にやむでしょう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "前後", "label": "基本形"}, {"form": "前後に", "label": "時間を示す形"}], "register": "丁寧語", "sense_fingerprint": "時刻や所要時間、数量の基準値の少し前から少し後までのおよその範囲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78c67344-a01c-4ca8-a260-da533eb0cbef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37045, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前後", "is_correct": true, "explanation": "「午後3時前後」のように、時刻のおよその範囲を示すので正解。"}, {"text": "最中", "is_correct": false, "explanation": "最中はその時間の真っ只中を指し、およその時刻の範囲とは合わない。"}, {"text": "途中", "is_correct": false, "explanation": "途中は進行の過程の中を指し、時刻の目安にはならない。"}, {"text": "直前", "is_correct": false, "explanation": "直前はある時点の少し前を指し、およその範囲は示せない。"}], "explanations": {"前後": "「午後3時前後」のように、時刻のおよその範囲を示すので正解。", "最中": "最中はその時間の真っ只中を指し、およその時刻の範囲とは合わない。", "途中": "途中は進行の過程の中を指し、時刻の目安にはならない。", "直前": "直前はある時点の少し前を指し、およその範囲は示せない。"}, "sentence_index": 0, "correct_answer": "前後"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "宝くじの前後賞に当たった。", "explanation": "ここは〈前後賞〉（宝くじの賞の名前）という別の語。目安の意味では合わない。"}, {"text": "試合は、ぴったり2時間前後で終わるでしょう。", "explanation": "ここは〈ぴったり〉（正確な時間）の意味。前後は目安なので、「ぴったり」と組むと合わない。"}, {"text": "試合は、二時間前後と正確に決まっていて、一秒も違わない。", "explanation": "ここは〈正確〉の意味。前後は大まかな範囲なので、一秒単位の正確さとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37045, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前後", "is_correct": true, "explanation": "「30分前後」のように、所要時間のおよその範囲を示すので正解。"}, {"text": "直後", "is_correct": false, "explanation": "直後はある時点の少し後を指し、所要時間の範囲には合わない。"}, {"text": "以降", "is_correct": false, "explanation": "以降はそれより先の時間を示し、範囲の目安には合わない。"}, {"text": "途中", "is_correct": false, "explanation": "途中は進行中の意味で、かかる時間の目安にはならない。"}], "explanations": {"前後": "「30分前後」のように、所要時間のおよその範囲を示すので正解。", "直後": "直後はある時点の少し後を指し、所要時間の範囲には合わない。", "以降": "以降はそれより先の時間を示し、範囲の目安には合わない。", "途中": "途中は進行中の意味で、かかる時間の目安にはならない。"}, "sentence_index": 6, "correct_answer": "前後"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電車の前後の車両は、夕方でも空いている。", "explanation": "ここは〈前後〉が前と後ろの位置を指す別の語義。時刻の目安の意味では合わない。"}, {"text": "雨は夕方5時前後ちょうどにやむでしょう。", "explanation": "ここは〈ちょうど〉（正確な時刻）の意味。前後は目安なので、「ちょうど」と組むと合わない。"}, {"text": "締切は夕方5時前後と決まっていて、それを過ぎてはならない。", "explanation": "ここは〈厳守の期限〉の意味。前後は目安で、厳守される期限とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37045, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "バスは朝8時前後を出発します。", "corrected_sentence": "バスは朝8時前後に出発します。", "error_description": "「出発する」は時点を示す「に」を取るが、ここでは「を」になっている。誤りは「前後」に付く助詞。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37045, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "次の電車は、朝7時前後で着きます。", "corrected_sentence": "次の電車は、朝7時前後に着きます。", "error_description": "「着く」は時点を示す「に」を取るが、ここでは「で」になっている。誤りは「前後」に付く助詞。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fd84768-ec85-41ae-b891-6004f756aff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37046, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「部屋を見守る」の対象を示す助詞で、モニタリングに直接つく。"}, {"text": "が", "is_correct": false, "explanation": "「部屋がモニタリングしている」だと部屋が見守る主体になり、文の意味が合わない。"}, {"text": "に", "is_correct": false, "explanation": "「部屋にモニタリングする」は位置の意味になり、対象を示す文として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「部屋へモニタリングする」は方向の意味になり、見守る対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「部屋を見守る」の対象を示す助詞で、モニタリングに直接つく。", "が": "「部屋がモニタリングしている」だと部屋が見守る主体になり、文の意味が合わない。", "に": "「部屋にモニタリングする」は位置の意味になり、対象を示す文として不自然。", "へ": "「部屋へモニタリングする」は方向の意味になり、見守る対象を表せない。"}, "error_tags": {"が": "主語", "に": "位置", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37046, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「家の様子を見守る」の対象を示し、モニタリングに直接つく助詞。"}, {"text": "と", "is_correct": false, "explanation": "「様子とモニタリングできる」は並べる意味になり、対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「様子よりモニタリングできる」は比較の意味になり、文の意味が合わない。"}, {"text": "で", "is_correct": false, "explanation": "「様子でモニタリングできる」は手段の意味にならず、見守る対象が示せない。"}], "correct_answer": "を", "explanations": {"を": "「家の様子を見守る」の対象を示し、モニタリングに直接つく助詞。", "と": "「様子とモニタリングできる」は並べる意味になり、対象を示せない。", "より": "「様子よりモニタリングできる」は比較の意味になり、文の意味が合わない。", "で": "「様子でモニタリングできる」は手段の意味にならず、見守る対象が示せない。"}, "error_tags": {"と": "並列", "より": "比較", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37046, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かをずっと見て、様子を確かめることです。", "primary_collocate": null, "pronunciation": "もにたりんぐ", "ipa": "monitaɾiŋɡɯ", "syllable_count": 6, "sentences": [{"text": "看護師は一晩中、患者の様子をモニタリングしました。", "target_word": "モニタリング", "complexity_tier": "T3", "furigana": "看護師[かんごし]は一晩中[ひとばんじゅう]、患者[かんじゃ]の様子[ようす]をモニタリングしました。", "sentence_source": "generated"}, {"text": "赤ちゃんが泣いたらすぐわかるように、カメラで部屋をモニタリングしている。", "target_word": "モニタリング", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんが泣[な]いたらすぐわかるように、カメラで部屋[へや]をモニタリングしている。", "sentence_source": "generated"}, {"text": "工場では機械の音をモニタリングして、故障を早く見つけます。", "target_word": "モニタリング", "complexity_tier": "T3", "furigana": "工場[こうじょう]では機械[きかい]の音[おと]をモニタリングして、故障[こしょう]を早[はや]く見[み]つけます。", "sentence_source": "generated"}, {"text": "山の天気は変わりやすいので、雨雲の動きをモニタリングしてください。", "target_word": "モニタリング", "complexity_tier": "T3", "furigana": "山[やま]の天気[てんき]は変[か]わりやすいので、雨雲[あまぐも]の動[うご]きをモニタリングしてください。", "sentence_source": "generated"}, {"text": "親は子どものネット利用を、ときどきモニタリングしている。", "target_word": "モニタリング", "complexity_tier": "T3", "furigana": "親[おや]は子[こ]どものネット利用[りよう]を、ときどきモニタリングしている。", "sentence_source": "generated"}, {"text": "川の水位をモニタリングしていたので、大雨でも早く避難できた。", "target_word": "モニタリング", "complexity_tier": "T3", "furigana": "川[かわ]の水位[すいい]をモニタリングしていたので、大雨[おおあめ]でも早[はや]く避難[ひなん]できた。", "sentence_source": "generated"}, {"text": "モニタリングを続けたおかげで、小さな異常にもすぐ気づいた。", "target_word": "モニタリング", "complexity_tier": "T3", "furigana": "モニタリングを続[つづ]けたおかげで、小[ちい]さな異常[いじょう]にもすぐ気[き]づいた。", "sentence_source": "generated"}, {"text": "犬の散歩中も、スマホで家の様子をモニタリングできる。", "target_word": "モニタリング", "complexity_tier": "T3", "furigana": "犬[いぬ]の散歩中[さんぽちゅう]も、スマホで家[いえ]の様子[ようす]をモニタリングできる。", "sentence_source": "generated"}, {"text": "医者は薬を飲んだあとの体調を、数日間モニタリングするつもりだ。", "target_word": "モニタリング", "complexity_tier": "T3", "furigana": "医者[いしゃ]は薬[くすり]を飲[の]んだあとの体調[たいちょう]を、数日間[すうじつかん]モニタリングするつもりだ。", "sentence_source": "generated"}, {"text": "店に人がいない時間も、防犯カメラで店内をモニタリングしている。", "target_word": "モニタリング", "complexity_tier": "T3", "furigana": "店[みせ]に人[ひと]がいない時間[じかん]も、防犯[ぼうはん]カメラで店内[てんない]をモニタリングしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "モニタリング", "label": "基本形"}, {"form": "モニタリングする", "label": "サ変動詞"}, {"form": "モニタリングして", "label": "て形"}], "register": "neutral", "sense_fingerprint": "様子が変わらないかをずっと見守って確かめること(見守り・監視)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23b6f44e-98bc-47ea-8709-e20223619fec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37046, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "モニタリング", "is_correct": true, "explanation": "「患者の様子を一晩中見守って確かめる」意味になり、この文の流れに合う。"}, {"text": "注文", "is_correct": false, "explanation": "様子を注文するという言い方はなく、見守る文脈に合わない。"}, {"text": "返却", "is_correct": false, "explanation": "様子は返せるものではないので、返却とは結びつかない。"}, {"text": "修正", "is_correct": false, "explanation": "様子を修正すると状態を直す意味になり、見守って確かめる文と合わない。"}], "explanations": {"モニタリング": "「患者の様子を一晩中見守って確かめる」意味になり、この文の流れに合う。", "注文": "様子を注文するという言い方はなく、見守る文脈に合わない。", "返却": "様子は返せるものではないので、返却とは結びつかない。", "修正": "様子を修正すると状態を直す意味になり、見守って確かめる文と合わない。"}, "sentence_index": 0, "correct_answer": "モニタリング"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しいモニタリングを買ったので、映画を大画面で楽しめる。", "explanation": "ここは〈モニター〉(映像を映す機器)の意味。モニタリングは様子を見守る行為で、機器は指さない。"}, {"text": "試験の答案を一度だけモニタリングして、すぐ返した。", "explanation": "ここは〈点検〉(一度確かめる)の意味。モニタリングは長く見守り続けることなので、一回の確認には合わない。"}, {"text": "英語の原稿をモニタリングして、日本語に直した。", "explanation": "ここは〈翻訳〉の意味。モニタリングは様子を見守ることで、言語を置き換える作業は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37046, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "モニタリング", "is_correct": true, "explanation": "「続けて様子を見守ったおかげで異常に気づいた」という流れに合う。"}, {"text": "出品", "is_correct": false, "explanation": "出品は商品を売りに出す行為で、異常に気づく流れとつながらない。"}, {"text": "包装", "is_correct": false, "explanation": "包装を続けても異常に気づくという流れにはならない。"}, {"text": "翻訳", "is_correct": false, "explanation": "翻訳を続けて異常に気づく流れは不自然で、見守る行為とは違う。"}], "explanations": {"モニタリング": "「続けて様子を見守ったおかげで異常に気づいた」という流れに合う。", "出品": "出品は商品を売りに出す行為で、異常に気づく流れとつながらない。", "包装": "包装を続けても異常に気づくという流れにはならない。", "翻訳": "翻訳を続けて異常に気づく流れは不自然で、見守る行為とは違う。"}, "sentence_index": 6, "correct_answer": "モニタリング"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新商品のモニタリングを三十人にお願いして、感想を集めた。", "explanation": "ここは〈モニター〉(試しに使ってもらう人)の意味。モニタリングは見守る行為で、人を指さない。"}, {"text": "この絵の作者を三か月モニタリングして、本物と判定した。", "explanation": "ここは〈鑑定〉(真偽や価値を判断する)の意味。モニタリングは状態の変化を見守ることで、判定はしない。"}, {"text": "テレビで新商品をモニタリングして、人気を広げた。", "explanation": "ここは〈宣伝〉(広く知らせる)の意味。モニタリングは見守る行為で、広めることは指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37046, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜中は、赤ちゃんの呼吸にモニタリングしている。", "corrected_sentence": "夜中は、赤ちゃんの呼吸をモニタリングしている。", "error_description": "「モニタリングする」の対象は「を」で示す。「に」は誤りで、モニタリングに直接つく助詞は「を」になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37046, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しいサービスの利用状況は、毎月モニタリングられている。", "corrected_sentence": "新しいサービスの利用状況は、毎月モニタリングされている。", "error_description": "「モニタリングする」の受身形は「モニタリングされている」。「られている」は誤った受身の語形になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37047, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「モニタリングによってデータを集める」という手段を示し、モニタリングの直後につく。"}, {"text": "に", "is_correct": false, "explanation": "「モニタリングにデータを集める」は位置の意味になり、手段として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「モニタリングへデータを集める」は方向の意味で、データの集め方を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「モニタリングとデータを集める」は並べる意味になり、手段の文として不自然。"}], "correct_answer": "で", "explanations": {"で": "「モニタリングによってデータを集める」という手段を示し、モニタリングの直後につく。", "に": "「モニタリングにデータを集める」は位置の意味になり、手段として成り立たない。", "へ": "「モニタリングへデータを集める」は方向の意味で、データの集め方を表せない。", "と": "「モニタリングとデータを集める」は並べる意味になり、手段の文として不自然。"}, "error_tags": {"に": "位置", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37047, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「心拍を観察して記録する」の対象を示し、モニタリングに直接つく助詞。"}, {"text": "が", "is_correct": false, "explanation": "「心拍がモニタリングした記録」は心拍が観察する主体になり、文の意味が合わない。"}, {"text": "より", "is_correct": false, "explanation": "「心拍よりモニタリングした」は比較の意味になり、対象を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「心拍にモニタリングした」は対象を示せず、動詞の続き方が崩れる。"}], "correct_answer": "を", "explanations": {"を": "「心拍を観察して記録する」の対象を示し、モニタリングに直接つく助詞。", "が": "「心拍がモニタリングした記録」は心拍が観察する主体になり、文の意味が合わない。", "より": "「心拍よりモニタリングした」は比較の意味になり、対象を示せない。", "に": "「心拍にモニタリングした」は対象を示せず、動詞の続き方が崩れる。"}, "error_tags": {"が": "主語", "より": "比較", "に": "位置"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37047, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事の状態や変化を、継続的に観察して記録すること。", "primary_collocate": null, "pronunciation": "もにたりんぐ", "ipa": "monitaɾiŋɡɯ", "syllable_count": 6, "sentences": [{"text": "研究者は毎日、湖の水温をモニタリングして記録している。", "target_word": "モニタリング", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は毎日[まいにち]、湖[みずうみ]の水温[すいおん]をモニタリングして記録[きろく]している。", "sentence_source": "generated"}, {"text": "長期のモニタリングでデータを集めると、気候の変化が見えてくる。", "target_word": "モニタリング", "complexity_tier": "T3", "furigana": "長期[ちょうき]のモニタリングでデータを集[あつ]めると、気候[きこう]の変化[へんか]が見[み]えてくる。", "sentence_source": "generated"}, {"text": "森の鳥の数を十年間モニタリングし、数の変化をグラフにした。", "target_word": "モニタリング", "complexity_tier": "T3", "furigana": "森[もり]の鳥[とり]の数[かず]を十年間[じゅうねんかん]モニタリングし、数[かず]の変化[へんか]をグラフにした。", "sentence_source": "generated"}, {"text": "大気の汚れは、専門の機械で二十四時間モニタリングされている。", "target_word": "モニタリング", "complexity_tier": "T3", "furigana": "大気[たいき]の汚[よご]れは、専門[せんもん]の機械[きかい]で二十四時間[にじゅうよじかん]モニタリングされている。", "sentence_source": "generated"}, {"text": "血圧を毎朝モニタリングしてノートに書いておくと、診察のときに役立つ。", "target_word": "モニタリング", "complexity_tier": "T3", "furigana": "血圧[けつあつ]を毎朝[まいあさ]モニタリングしてノートに書[か]いておくと、診察[しんさつ]のときに役立[やくだ]つ。", "sentence_source": "generated"}, {"text": "海の温度のモニタリングは、地球温暖化の研究に欠かせない。", "target_word": "モニタリング", "complexity_tier": "T3", "furigana": "海[うみ]の温度[おんど]のモニタリングは、地球温暖化[ちきゅうおんだんか]の研究[けんきゅう]に欠[か]かせない。", "sentence_source": "generated"}, {"text": "市は川の水質をモニタリングし、結果を毎月ホームページで発表する。", "target_word": "モニタリング", "complexity_tier": "T3", "furigana": "市[し]は川[かわ]の水質[すいしつ]をモニタリングし、結果[けっか]を毎月[まいつき]ホームページで発表[はっぴょう]する。", "sentence_source": "generated"}, {"text": "患者の心拍をモニタリングした記録は、医者が見直した。", "target_word": "モニタリング", "complexity_tier": "T3", "furigana": "患者[かんじゃ]の心拍[しんぱく]をモニタリングした記録[きろく]は、医者[いしゃ]が見直[みなお]した。", "sentence_source": "generated"}, {"text": "このモニタリングの目的は、工事のあとで地面が動かないか確かめることだ。", "target_word": "モニタリング", "complexity_tier": "T3", "furigana": "このモニタリングの目的[もくてき]は、工事[こうじ]のあとで地面[じめん]が動[うご]かないか確[たし]かめることだ。", "sentence_source": "generated"}, {"text": "火山の小さな揺れを継続的にモニタリングし、変化を記録している。", "target_word": "モニタリング", "complexity_tier": "T3", "furigana": "火山[かざん]の小[ちい]さな揺[ゆ]れを継続的[けいぞくてき]にモニタリングし、変化[へんか]を記録[きろく]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "モニタリング", "label": "基本形"}, {"form": "モニタリングする", "label": "サ変動詞"}, {"form": "モニタリングされる", "label": "受身形"}], "register": "formal", "sense_fingerprint": "状態の変化を長く観察してデータとして記録し続ける調査・測定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23b6f44e-98bc-47ea-8709-e20223619fec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37047, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "モニタリング", "is_correct": true, "explanation": "「湖の水温を継続的に観察して記録する」意味になり、この文に合う。"}, {"text": "注文", "is_correct": false, "explanation": "水温は注文できるものではないので、記録する文と合わない。"}, {"text": "返却", "is_correct": false, "explanation": "水温を返すという動作は成り立たない。"}, {"text": "販売", "is_correct": false, "explanation": "水温は売買の対象にならず、記録する流れと合わない。"}], "explanations": {"モニタリング": "「湖の水温を継続的に観察して記録する」意味になり、この文に合う。", "注文": "水温は注文できるものではないので、記録する文と合わない。", "返却": "水温を返すという動作は成り立たない。", "販売": "水温は売買の対象にならず、記録する流れと合わない。"}, "sentence_index": 0, "correct_answer": "モニタリング"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この新しいモニタリングは画面が大きくて、映画がきれいに映る。", "explanation": "ここは〈モニター〉(映像を映す機器)の意味。モニタリングは観察と記録の行為で、機器は指さない。"}, {"text": "この骨董品をモニタリングして、本物と判定した。", "explanation": "ここは〈鑑定〉(真偽や価値を判断する)の意味。モニタリングは状態を観察して記録することで、判定はしない。"}, {"text": "新商品を街頭でモニタリングして、人気を広めた。", "explanation": "ここは〈宣伝〉(広く知らせる)の意味。モニタリングは観察と記録の行為で、広めることは指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37047, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "モニタリング", "is_correct": true, "explanation": "「川の水質を継続して観察し、結果を発表する」流れに合う。"}, {"text": "出品", "is_correct": false, "explanation": "水質を商品として出品する意味になり、結果の発表とつながらない。"}, {"text": "包装", "is_correct": false, "explanation": "水質は包装できないので、この文では成り立たない。"}, {"text": "翻訳", "is_correct": false, "explanation": "水質を翻訳するという意味は成り立たず、観察と発表の流れと合わない。"}], "explanations": {"モニタリング": "「川の水質を継続して観察し、結果を発表する」流れに合う。", "出品": "水質を商品として出品する意味になり、結果の発表とつながらない。", "包装": "水質は包装できないので、この文では成り立たない。", "翻訳": "水質を翻訳するという意味は成り立たず、観察と発表の流れと合わない。"}, "sentence_index": 6, "correct_answer": "モニタリング"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しいお菓子のモニタリングを、学生に頼んで感想を書いてもらった。", "explanation": "ここは〈モニター〉(試してもらう人)の意味。モニタリングは観察と記録の行為で、人を指さない。"}, {"text": "新しい機械を一度だけモニタリングして、すぐ出荷した。", "explanation": "ここは〈点検〉(一度確かめる)の意味。モニタリングは継続的に観察して記録することなので、一回の確認には合わない。"}, {"text": "英語の論文をモニタリングして、日本語に直した。", "explanation": "ここは〈翻訳〉の意味。モニタリングは状態を観察して記録することで、言語を置き換える作業は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37047, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "県は海の水質をモニタリングれ、結果を毎年公表する。", "corrected_sentence": "県は海の水質をモニタリングし、結果を毎年公表する。", "error_description": "サ変動詞「する」の連用形は「し」。「れ」は誤りで、「モニタリング」に直接つく形は「し」になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37047, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山の雪崩の危険は、毎日モニタリングれている。", "corrected_sentence": "山の雪崩の危険は、毎日モニタリングされている。", "error_description": "受身の「モニタリングされている」が正しい。「さ」を欠くと受身の形が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37048, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「わからない」は「〜がわかる」の形をとるので、病原の後は「が」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「わからない」は目的語に「を」を取らないので、ここでは使えない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示すので、「わからない」の主語には付かない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、病原を状態の主語にはできない。"}], "correct_answer": "が", "explanations": {"が": "「わからない」は「〜がわかる」の形をとるので、病原の後は「が」が正しい。", "を": "「わからない」は目的語に「を」を取らないので、ここでは使えない。", "に": "「に」は相手や場所を示すので、「わからない」の主語には付かない。", "で": "「で」は手段や場所を示すので、病原を状態の主語にはできない。"}, "error_tags": {"を": "目的語", "に": "相手・方向", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37048, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「知らない」は知る対象に「を」を取るので、病原を直接つなぐ。"}, {"text": "に", "is_correct": false, "explanation": "「知らない」に「に」は付かないので、ここでは使えない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すので、知る対象の目的語にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、知らないの対象を表すことはできない。"}], "correct_answer": "を", "explanations": {"を": "「知らない」は知る対象に「を」を取るので、病原を直接つなぐ。", "に": "「知らない」に「に」は付かないので、ここでは使えない。", "で": "「で」は場所や手段を示すので、知る対象の目的語にはならない。", "から": "「から」は起点を示すので、知らないの対象を表すことはできない。"}, "error_tags": {"に": "相手・方向", "で": "場所・手段", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37048, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "びょうきのもとになるばいきんのこと。", "primary_collocate": null, "pronunciation": "びょうげん", "ipa": "bʲoːɡeɴ", "syllable_count": 4, "sentences": [{"text": "医者は、この病気の病原を調べるために血液を取りました。", "target_word": "病原", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、この病気[びょうき]の病原[びょうげん]を調[しら]べるために血液[けつえき]を取[と]りました。", "sentence_source": "generated"}, {"text": "病原がわからないので、治療を始められません。", "target_word": "病原", "complexity_tier": "T3", "furigana": "病原[びょうげん]がわからないので、治療[ちりょう]を始[はじ]められません。", "sentence_source": "generated"}, {"text": "食中毒の病原は、冷蔵庫に入れ忘れた肉で増えた細菌でした。", "target_word": "病原", "complexity_tier": "T3", "furigana": "食中毒[しょくちゅうどく]の病原[びょうげん]は、冷蔵庫[れいぞうこ]に入れ忘れた肉[にく]で増えた細菌[さいきん]でした。", "sentence_source": "generated"}, {"text": "手をよく洗えば、病原が体に入るのを防げます。", "target_word": "病原", "complexity_tier": "T3", "furigana": "手[て]をよく洗[あら]えば、病原[びょうげん]が体[からだ]に入[はい]るのを防[ふせ]げます。", "sentence_source": "generated"}, {"text": "先生は、病原を見つけるために毎日研究しています。", "target_word": "病原", "complexity_tier": "T3", "furigana": "先生[せんせい]は、病原[びょうげん]を見[み]つけるために毎日[まいにち]研究[けんきゅう]しています。", "sentence_source": "generated"}, {"text": "病原を取りのぞいたので、町の人はようやく安心しました。", "target_word": "病原", "complexity_tier": "T3", "furigana": "病原[びょうげん]を取[と]りのぞいたので、町[まち]の人[ひと]はようやく安心[あんしん]しました。", "sentence_source": "generated"}, {"text": "この池の水から病原が見つかったと、検査でわかりました。", "target_word": "病原", "complexity_tier": "T3", "furigana": "この池[いけ]の水[みず]から病原[びょうげん]が見つかったと、検査[けんさ]でわかりました。", "sentence_source": "generated"}, {"text": "病原を知らないまま薬を飲むのは危険です。", "target_word": "病原", "complexity_tier": "T3", "furigana": "病原[びょうげん]を知[し]らないまま薬[くすり]を飲[の]むのは危険[きけん]です。", "sentence_source": "generated"}, {"text": "病原がどこから来たのか、まだはっきりしていません。", "target_word": "病原", "complexity_tier": "T3", "furigana": "病原[びょうげん]がどこから来[き]たのか、まだはっきりしていません。", "sentence_source": "generated"}, {"text": "病原を突き止めた医者は、すぐに町の人に知らせました。", "target_word": "病原", "complexity_tier": "T3", "furigana": "病原[びょうげん]を突[つ]き止[と]めた医者[いしゃ]は、すぐに町[まち]の人[ひと]に知[し]らせました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "病原", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "病気を起こすもとになるばいきん", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bb45688-8400-4456-9927-11fbe9b516ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37048, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "病原", "is_correct": true, "explanation": "ここは病気を起こすもとになる細菌やウイルスを指す。血液で突き止める対象として合う。"}, {"text": "治療法", "is_correct": false, "explanation": "治療法は病気を治す方法で、血液を取って調べる対象としては合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は血液を取って調べる対象としては不自然で、この病気の調べ物にはならない。"}, {"text": "副作用", "is_correct": false, "explanation": "副作用は薬の影響で出る害のことで、この病気そのものを調べる場面には合わない。"}], "explanations": {"病原": "ここは病気を起こすもとになる細菌やウイルスを指す。血液で突き止める対象として合う。", "治療法": "治療法は病気を治す方法で、血液を取って調べる対象としては合わない。", "天気": "天気は血液を取って調べる対象としては不自然で、この病気の調べ物にはならない。", "副作用": "副作用は薬の影響で出る害のことで、この病気そのものを調べる場面には合わない。"}, "sentence_index": 0, "correct_answer": "病原"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の寝不足が、頭痛の病原になったのかもしれません。", "explanation": "ここは〈原因〉の意味。病原は病気を起こす微生物なので、寝不足のような出来事には使わない。〈原因〉と混同した誤り。"}, {"text": "検査の結果、彼女の病原は肺炎と判明し、入院することになりました。", "explanation": "ここは〈病名〉の意味。肺炎は病名で、病原は病気を起こす微生物なので、病名の代わりに病原を使うのは誤り。"}, {"text": "熱やせきは、風邪の病原としてよく現れます。", "explanation": "ここは〈症状〉の意味。熱やせきは体に現れる症状で、微生物である病原ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37048, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病原", "is_correct": true, "explanation": "ここは水から見つかる微生物を指し、検査で見つかったものとして合う。"}, {"text": "体温", "is_correct": false, "explanation": "体温は人の体の熱の度合いで、池の水から見つかるものではない。"}, {"text": "注射", "is_correct": false, "explanation": "注射は体に薬を入れる行為で、池の水から見つかる対象ではない。"}, {"text": "手術", "is_correct": false, "explanation": "手術は体を切って治療する医療行為で、水から見つかるものとしては合わない。"}], "explanations": {"病原": "ここは水から見つかる微生物を指し、検査で見つかったものとして合う。", "体温": "体温は人の体の熱の度合いで、池の水から見つかるものではない。", "注射": "注射は体に薬を入れる行為で、池の水から見つかる対象ではない。", "手術": "手術は体を切って治療する医療行為で、水から見つかるものとしては合わない。"}, "sentence_index": 6, "correct_answer": "病原"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "熱が出たので、朝一番で病原に行きました。", "explanation": "ここは〈病院〉の意味。行く先は施設の病院で、微生物の病原は行き先にならない。"}, {"text": "倒れた人のために、すぐに病原を呼びました。", "explanation": "ここは〈救急車〉の意味。呼ぶのは救急車で、病原は呼べるものではない。"}, {"text": "入院中の祖母は、病原で一日中寝ています。", "explanation": "ここは〈病室〉の意味。寝る場所を指す語で、病原は微生物なので場所にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37048, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "病原を体を守るために、まめに手を洗いましょう。", "corrected_sentence": "病原から体を守るために、まめに手を洗いましょう。", "error_description": "病原に付く助詞の誤り。害を与えるものから守るときは「から」を使う。「を」では病原を守る対象のように読まれ、不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37048, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "病原に正体を突き止めたので、治療薬が作られました。", "corrected_sentence": "病原の正体を突き止めたので、治療薬が作られました。", "error_description": "助詞の誤り。「病原の正体」と名詞をつなぐ「の」が正しい。「に」では病原を場所や相手と読んでしまい、意味が通らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37049, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「観察しました」は観察する対象に「を」を取るので、病原を直接つなぐ。"}, {"text": "が", "is_correct": false, "explanation": "「が」にすると病原が主語になり、観察する対象としての文にならない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示し、観察の対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、観察する対象は表せない。"}], "correct_answer": "を", "explanations": {"を": "「観察しました」は観察する対象に「を」を取るので、病原を直接つなぐ。", "が": "「が」にすると病原が主語になり、観察する対象としての文にならない。", "に": "「に」は相手や場所を示し、観察の対象にはならない。", "へ": "「へ」は方向を示すので、観察する対象は表せない。"}, "error_tags": {"が": "主語", "に": "相手・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
