INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37049, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "病気や害を引き起こす細菌やウイルスなどの微生物。", "primary_collocate": null, "pronunciation": "びょうげん", "ipa": "bʲoːɡeɴ", "syllable_count": 4, "sentences": [{"text": "この病気の病原は、目に見えないほど小さな微生物です。", "target_word": "病原", "complexity_tier": "T3", "furigana": "この病気[びょうき]の病原[びょうげん]は、目[め]に見[み]えないほど小[ちい]さな微生物[びせいぶつ]です。", "sentence_source": "generated"}, {"text": "研究者は、顕微鏡で病原を観察しました。", "target_word": "病原", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、顕微鏡[けんびきょう]で病原[びょうげん]を観察[かんさつ]しました。", "sentence_source": "generated"}, {"text": "インフルエンザの病原はウイルスです。", "target_word": "病原", "complexity_tier": "T3", "furigana": "インフルエンザの病原[びょうげん]はウイルスです。", "sentence_source": "generated"}, {"text": "病原が増える前に、早く薬を飲んでください。", "target_word": "病原", "complexity_tier": "T3", "furigana": "病原[びょうげん]が増[ふ]える前[まえ]に、早[はや]く薬[くすり]を飲[の]んでください。", "sentence_source": "generated"}, {"text": "新しい感染症の病原が、検査で明らかになりました。", "target_word": "病原", "complexity_tier": "T3", "furigana": "新[あたら]しい感染症[かんせんしょう]の病原[びょうげん]が、検査[けんさ]で明[あき]らかになりました。", "sentence_source": "generated"}, {"text": "病原は水や空気を通して広がることがあります。", "target_word": "病原", "complexity_tier": "T3", "furigana": "病原[びょうげん]は水[みず]や空気[くうき]を通[とお]して広[ひろ]がることがあります。", "sentence_source": "generated"}, {"text": "病原を特定するために、病院は患者の検体を集めました。", "target_word": "病原", "complexity_tier": "T3", "furigana": "病原[びょうげん]を特定[とくてい]するために、病院[びょういん]は患者[かんじゃ]の検体[けんたい]を集[あつ]めました。", "sentence_source": "generated"}, {"text": "この細菌は、動物にも人にも病気を起こす病原です。", "target_word": "病原", "complexity_tier": "T3", "furigana": "この細菌[さいきん]は、動物[どうぶつ]にも人[ひと]にも病気[びょうき]を起[お]こす病原[びょうげん]です。", "sentence_source": "generated"}, {"text": "病原の種類によって、使う薬は変わります。", "target_word": "病原", "complexity_tier": "T3", "furigana": "病原[びょうげん]の種類[しゅるい]によって、使[つか]う薬[くすり]は変[か]わります。", "sentence_source": "generated"}, {"text": "病原が変異したため、前のワクチンは効きにくくなりました。", "target_word": "病原", "complexity_tier": "T3", "furigana": "病原[びょうげん]が変異[へんい]したため、前[まえ]のワクチンは効[き]きにくくなりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "病原", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "病気を起こす細菌やウイルスなどの微生物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bb45688-8400-4456-9927-11fbe9b516ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37049, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "病原", "is_correct": true, "explanation": "ここは病気を起こす微生物を指し、説明文の主語として合う。"}, {"text": "症状", "is_correct": false, "explanation": "症状は病気で体に現れる変化で、微生物だとは説明できない。"}, {"text": "治療薬", "is_correct": false, "explanation": "治療薬は病気を治す薬で、目に見えない微生物そのものとは言えない。"}, {"text": "注射", "is_correct": false, "explanation": "注射は薬を体に入れる行為で、目に見えない微生物とは結びつかない。"}], "explanations": {"病原": "ここは病気を起こす微生物を指し、説明文の主語として合う。", "症状": "症状は病気で体に現れる変化で、微生物だとは説明できない。", "治療薬": "治療薬は病気を治す薬で、目に見えない微生物そのものとは言えない。", "注射": "注射は薬を体に入れる行為で、目に見えない微生物とは結びつかない。"}, "sentence_index": 0, "correct_answer": "病原"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父の病原は、薬を飲んでから少しずつよくなっています。", "explanation": "ここは〈病状〉の意味。病状は病気の様子を指し、微生物の病原は回復したりよくなったりしない。"}, {"text": "昨日の暑さが、頭痛の病原になったのかもしれません。", "explanation": "ここは〈原因〉の意味。暑さのような出来事は原因にはなっても、病原とは呼ばない。"}, {"text": "インフルエンザは、毎年流行する病原です。", "explanation": "ここは〈感染症〉の意味。インフルエンザは病気の名前で、病気を起こすウイルスが病原なので、病気そのものを病原とは呼ばない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37049, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病原", "is_correct": true, "explanation": "ここは特定される対象の微生物を指し、検体を集める目的として合う。"}, {"text": "体温", "is_correct": false, "explanation": "体温は人の体の熱の度合いで、検体を集めて特定する対象ではない。"}, {"text": "手術", "is_correct": false, "explanation": "手術は治療の行為で、検体を集めて特定する対象にはならない。"}, {"text": "入院", "is_correct": false, "explanation": "入院は患者が病院に泊まることで、特定する対象にはならない。"}], "explanations": {"病原": "ここは特定される対象の微生物を指し、検体を集める目的として合う。", "体温": "体温は人の体の熱の度合いで、検体を集めて特定する対象ではない。", "手術": "手術は治療の行為で、検体を集めて特定する対象にはならない。", "入院": "入院は患者が病院に泊まることで、特定する対象にはならない。"}, "sentence_index": 6, "correct_answer": "病原"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "入院した祖母は、三階の病原にいます。", "explanation": "ここは〈病棟〉の意味。入院患者がいる場所を指す語で、微生物の病原はいる場所としては合わない。"}, {"text": "風邪薬をもらうため、近くの病原に寄りました。", "explanation": "ここは〈薬局〉の意味。薬をもらう店を指す語で、微生物の病原は寄る場所にならない。"}, {"text": "熱を測るため、病原を脇に挟みました。", "explanation": "ここは〈体温計〉の意味。脇に挟んで熱を測る道具を指すので、微生物の病原は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37049, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "病原を広がるのを防ぐため、手を洗いましょう。", "corrected_sentence": "病原が広がるのを防ぐため、手を洗いましょう。", "error_description": "助詞の誤り。「広がる」は主語（〜が）をとる自動詞なので、病原には「が」を使う。「を」は他動詞の目的語に使うため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37049, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ワクチンは、病原を対抗する力を体の中に作ります。", "corrected_sentence": "ワクチンは、病原に対抗する力を体の中に作ります。", "error_description": "助詞の誤り。「対抗する」は相手に「に」を使う。「を」にすると病原を目的語として扱うことになり、不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37050, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「抜く」の対象を示す「を」。「雑草を抜く」の意味になる。"}, {"text": "が", "is_correct": false, "explanation": "「雑草が」だと雑草が主語になり、抜く動作の対象にならないので誤り。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や相手を表すので、抜く対象は示せない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表すので、抜く対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「抜く」の対象を示す「を」。「雑草を抜く」の意味になる。", "が": "「雑草が」だと雑草が主語になり、抜く動作の対象にならないので誤り。", "に": "「に」は方向や相手を表すので、抜く対象は示せない。", "で": "「で」は手段や場所を表すので、抜く対象にはならない。"}, "error_tags": {"が": "主語", "に": "方向・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37050, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「取る」の対象を示す「を」。「雑草を取る」の意味になる。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を表すので、取る対象は示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、取る対象にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すので、取る対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「取る」の対象を示す「を」。「雑草を取る」の意味になる。", "と": "「と」は並列や引用を表すので、取る対象は示せない。", "へ": "「へ」は方向を表すので、取る対象にはならない。", "より": "「より」は比較を表すので、取る対象にはならない。"}, "error_tags": {"と": "並列・引用", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37050, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "道ばたや畑に自然に生える、役に立たないと思われる草。", "primary_collocate": null, "pronunciation": "ざっそう", "ipa": "dzasːoː", "syllable_count": 4, "sentences": [{"text": "道ばたに雑草が生えている。", "target_word": "雑草", "complexity_tier": "T3", "furigana": "道[みち]ばたに雑草[ざっそう]が生[は]えている。", "sentence_source": "generated"}, {"text": "庭の雑草を抜くのに、一時間もかかった。", "target_word": "雑草", "complexity_tier": "T3", "furigana": "庭[にわ]の雑草[ざっそう]を抜[ぬ]くのに、一時間[いちじかん]もかかった。", "sentence_source": "generated"}, {"text": "雨のあと、雑草が一気に伸びた。", "target_word": "雑草", "complexity_tier": "T3", "furigana": "雨[あめ]のあと、雑草[ざっそう]が一気[いっき]に伸[の]びた。", "sentence_source": "generated"}, {"text": "線路のわきは、雑草でいっぱいだ。", "target_word": "雑草", "complexity_tier": "T3", "furigana": "線路[せんろ]のわきは、雑草[ざっそう]でいっぱいだ。", "sentence_source": "generated"}, {"text": "空き地には、背の高い雑草が茂っている。", "target_word": "雑草", "complexity_tier": "T3", "furigana": "空[あ]き地[ち]には、背[せ]の高[たか]い雑草[ざっそう]が茂[しげ]っている。", "sentence_source": "generated"}, {"text": "雑草でも、小さな花を咲かせることがある。", "target_word": "雑草", "complexity_tier": "T3", "furigana": "雑草[ざっそう]でも、小[ちい]さな花[はな]を咲[さ]かせることがある。", "sentence_source": "generated"}, {"text": "夏休みの間に、家の前の雑草が増えた。", "target_word": "雑草", "complexity_tier": "T3", "furigana": "夏休[なつやす]みの間[あいだ]に、家[いえ]の前[まえ]の雑草[ざっそう]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "祖父は毎朝、畑の雑草を取っている。", "target_word": "雑草", "complexity_tier": "T3", "furigana": "祖父[そふ]は毎朝[まいあさ]、畑[はたけ]の雑草[ざっそう]を取[と]っている。", "sentence_source": "generated"}, {"text": "踏まれても立ち上がる雑草の強さに感心した。", "target_word": "雑草", "complexity_tier": "T3", "furigana": "踏[ふ]まれても立[た]ち上[あ]がる雑草[ざっそう]の強[つよ]さに感心[かんしん]した。", "sentence_source": "generated"}, {"text": "使っていない駐車場は、雑草だらけになってしまった。", "target_word": "雑草", "complexity_tier": "T3", "furigana": "使[つか]っていない駐車場[ちゅうしゃじょう]は、雑草[ざっそう]だらけになってしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "雑草", "label": "基本形"}, {"form": "雑草が", "label": "が格"}, {"form": "雑草を", "label": "を格"}], "register": "中立", "sense_fingerprint": "道ばたや畑に自然に生える役に立たない草", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6ccf0ee-587d-4100-bacc-1b9c2c21e01c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37050, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雑草", "is_correct": true, "explanation": "道ばたに自然に生える草を指すので、「道ばたに〜が生えている」に合う。"}, {"text": "石", "is_correct": false, "explanation": "石は生えるものではないので、「生えている」とは合わない。"}, {"text": "電柱", "is_correct": false, "explanation": "電柱は立てられるもので、道ばたに生えることはない。"}, {"text": "看板", "is_correct": false, "explanation": "看板は設置するもので、生えることはないので文が成り立たない。"}], "explanations": {"雑草": "道ばたに自然に生える草を指すので、「道ばたに〜が生えている」に合う。", "石": "石は生えるものではないので、「生えている」とは合わない。", "電柱": "電柱は立てられるもので、道ばたに生えることはない。", "看板": "看板は設置するもので、生えることはないので文が成り立たない。"}, "sentence_index": 0, "correct_answer": "雑草"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春になると、山菜として雑草を摘みに行く。", "explanation": "ここは〈野草〉の意味。食べられる草は役に立つものとして扱われ、雑草とは呼ばないので合わない。"}, {"text": "植木市で、苗木として雑草を売っていた。", "explanation": "ここは〈園芸品〉の意味。植木市で売るのは育てた園芸品で、雑草は売り物にはならないので合わない。"}, {"text": "盆栽として、雑草の苗を一本ずつ植え替えた。", "explanation": "ここは〈観賞植物〉の意味。手をかけて育てる植物を指すので、人が植えない雑草の苗には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37050, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雑草", "is_correct": true, "explanation": "家の前に生えて増える草を指すので、「家の前の〜が増えた」に合う。"}, {"text": "岩", "is_correct": false, "explanation": "岩は夏休みの間に数が増えるものではないので、「増えた」と合わない。"}, {"text": "鏡", "is_correct": false, "explanation": "鏡が家の前で増えるという状況は、文として不自然。"}, {"text": "窓", "is_correct": false, "explanation": "窓は家の一部で、家の前に増える対象としては不自然。"}], "explanations": {"雑草": "家の前に生えて増える草を指すので、「家の前の〜が増えた」に合う。", "岩": "岩は夏休みの間に数が増えるものではないので、「増えた」と合わない。", "鏡": "鏡が家の前で増えるという状況は、文として不自然。", "窓": "窓は家の一部で、家の前に増える対象としては不自然。"}, "sentence_index": 6, "correct_answer": "雑草"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "秋になって、畑の雑草を収穫して市場に出した。", "explanation": "ここは〈作物〉の意味。雑草は人が植えず、収穫の対象にもならないので「収穫する」とは合わない。"}, {"text": "ゴルフ場の芝の代わりに、雑草を一面に張って整えた。", "explanation": "ここは〈芝生〉の意味。芝生は張って整える草だが、雑草は人が張る対象ではないので合わない。"}, {"text": "お中元に、雑草の詰め合わせを贈った。", "explanation": "ここは〈贈答品〉の意味。贈答品は人が選んで用意する品物で、雑草は贈り物にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37050, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭の雑草に、一時間かけて抜いた。", "corrected_sentence": "庭の雑草を、一時間かけて抜いた。", "error_description": "正しくは「雑草を」。「抜く」は目的語に「を」を取るので、「雑草に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37050, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏休みの間に、庭の雑草を増えた。", "corrected_sentence": "夏休みの間に、庭の雑草が増えた。", "error_description": "正しくは「雑草が」。「増える」は主語を取る自動詞なので、対象を示す「を」は使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37051, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「はびこる」の主語になる雑草を示す。"}, {"text": "を", "is_correct": false, "explanation": "「はびこる」は目的語を取らないので、「雑草をはびこって」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すので、「雑草ではびこって」は主語を示せず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表すので、「雑草とはびこって」は主語として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「はびこる」の主語になる雑草を示す。", "を": "「はびこる」は目的語を取らないので、「雑草をはびこって」は成り立たない。", "で": "「で」は場所や手段を表すので、「雑草ではびこって」は主語を示せず不自然。", "と": "「と」は並列や相手を表すので、「雑草とはびこって」は主語として成り立たない。"}, "error_tags": {"を": "目的語", "で": "場所", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37051, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「放っておく」の目的語になる雑草を示す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示すが、「放っておく」は目的語を「を」で取るので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、「雑草から放っておくと」は目的語にならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すので、「雑草より放っておくと」は比べる意味になり文に合わない。"}], "correct_answer": "を", "explanations": {"を": "「放っておく」の目的語になる雑草を示す。", "に": "「に」は相手や場所を示すが、「放っておく」は目的語を「を」で取るので合わない。", "から": "「から」は起点を表すので、「雑草から放っておくと」は目的語にならない。", "より": "「より」は比較を表すので、「雑草より放っておくと」は比べる意味になり文に合わない。"}, "error_tags": {"に": "相手", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37051, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が育てているわけではないのに、自然に生えてくる草。農作物の育ちを邪魔することが多い。", "primary_collocate": null, "pronunciation": "ざっそう", "ipa": "dzasːoː", "syllable_count": 4, "sentences": [{"text": "雑草は作物の栄養を奪うので、早めに抜く。", "target_word": "雑草", "complexity_tier": "T3", "furigana": "雑草[ざっそう]は作物[さくもつ]の栄養[えいよう]を奪[うば]うので、早[はや]めに抜[ぬ]く。", "sentence_source": "generated"}, {"text": "雑草がはびこって、野菜の育ちが悪い。", "target_word": "雑草", "complexity_tier": "T3", "furigana": "雑草[ざっそう]がはびこって、野菜[やさい]の育[そだ]ちが悪[わる]い。", "sentence_source": "generated"}, {"text": "農家にとって、雑草は大きな悩みの種だ。", "target_word": "雑草", "complexity_tier": "T3", "furigana": "農家[のうか]にとって、雑草[ざっそう]は大[おお]きな悩[なや]みの種[たね]だ。", "sentence_source": "generated"}, {"text": "畑に植えた覚えがないのに、雑草が勝手に生えてくる。", "target_word": "雑草", "complexity_tier": "T3", "furigana": "畑[はたけ]に植[う]えた覚[おぼ]えがないのに、雑草[ざっそう]が勝手[かって]に生[は]えてくる。", "sentence_source": "generated"}, {"text": "田んぼの雑草を防ぐため、水の深さを調整する。", "target_word": "雑草", "complexity_tier": "T3", "furigana": "田[た]んぼの雑草[ざっそう]を防[ふせ]ぐため、水[みず]の深[ふか]さを調整[ちょうせい]する。", "sentence_source": "generated"}, {"text": "雑草に日光をさえぎられて、苗が育たなかった。", "target_word": "雑草", "complexity_tier": "T3", "furigana": "雑草[ざっそう]に日光[にっこう]をさえぎられて、苗[なえ]が育[そだ]たなかった。", "sentence_source": "generated"}, {"text": "肥料をやると、作物だけでなく雑草も元気になる。", "target_word": "雑草", "complexity_tier": "T3", "furigana": "肥料[ひりょう]をやると、作物[さくもつ]だけでなく雑草[ざっそう]も元気[げんき]になる。", "sentence_source": "generated"}, {"text": "雑草を放っておくと、畑がすぐに荒れてしまう。", "target_word": "雑草", "complexity_tier": "T3", "furigana": "雑草[ざっそう]を放[ほう]っておくと、畑[はたけ]がすぐに荒[あ]れてしまう。", "sentence_source": "generated"}, {"text": "収穫量を守るために、農家は雑草の管理を欠かさない。", "target_word": "雑草", "complexity_tier": "T3", "furigana": "収穫量[しゅうかくりょう]を守[まも]るために、農家[のうか]は雑草[ざっそう]の管理[かんり]を欠[か]かさない。", "sentence_source": "generated"}, {"text": "種をまいていないのに、春になると雑草が芽を出す。", "target_word": "雑草", "complexity_tier": "T3", "furigana": "種[たね]をまいていないのに、春[はる]になると雑草[ざっそう]が芽[め]を出[だ]す。", "sentence_source": "generated"}], "morphological_forms": [{"form": "雑草", "label": "基本形"}, {"form": "雑草が", "label": "が格"}, {"form": "雑草に", "label": "に格"}], "register": "中立", "sense_fingerprint": "育てていないのに生え、作物の邪魔になる草", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6ccf0ee-587d-4100-bacc-1b9c2c21e01c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37051, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雑草", "is_correct": true, "explanation": "作物の栄養を奪い、早めに抜かれる草を指すので文に合う。"}, {"text": "農機具", "is_correct": false, "explanation": "農機具は栄養を奪う存在でも抜く対象でもないので、「農機具は作物の栄養を奪う」は成り立たない。"}, {"text": "倉庫", "is_correct": false, "explanation": "倉庫は作物の栄養を奪わず、抜かれる対象にもならないので文に合わない。"}, {"text": "苗箱", "is_correct": false, "explanation": "苗箱は苗を入れる道具で、作物の栄養を奪う存在ではないので合わない。"}], "explanations": {"雑草": "作物の栄養を奪い、早めに抜かれる草を指すので文に合う。", "農機具": "農機具は栄養を奪う存在でも抜く対象でもないので、「農機具は作物の栄養を奪う」は成り立たない。", "倉庫": "倉庫は作物の栄養を奪わず、抜かれる対象にもならないので文に合わない。", "苗箱": "苗箱は苗を入れる道具で、作物の栄養を奪う存在ではないので合わない。"}, "sentence_index": 0, "correct_answer": "雑草"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "花壇に雑草を植えて、毎年楽しむ。", "explanation": "ここは〈草花〉の意味。草花は植えて楽しむが、雑草は人が植えるものではないので合わない。"}, {"text": "庭に雑草を張り、子どもが転がって遊べるようにした。", "explanation": "ここは〈芝〉の意味。芝は人が張るものだが、雑草は人が張る草ではないので合わない。"}, {"text": "雑草を一列に植えて、畑に並べた。", "explanation": "ここは〈苗〉の意味。苗は植えるものだが、雑草は人が植えるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37051, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雑草", "is_correct": true, "explanation": "作物と並べて、肥料で元気になる植物として雑草が入るので文に合う。"}, {"text": "納屋", "is_correct": false, "explanation": "納屋は植物ではないので、元気になるという文の意味に合わない。"}, {"text": "農薬", "is_correct": false, "explanation": "農薬は作物を害虫から守る薬で、元気になる主体ではないので合わない。"}, {"text": "草刈り機", "is_correct": false, "explanation": "草刈り機は機械なので、植物のように元気になるとは言えない。"}], "explanations": {"雑草": "作物と並べて、肥料で元気になる植物として雑草が入るので文に合う。", "納屋": "納屋は植物ではないので、元気になるという文の意味に合わない。", "農薬": "農薬は作物を害虫から守る薬で、元気になる主体ではないので合わない。", "草刈り機": "草刈り機は機械なので、植物のように元気になるとは言えない。"}, "sentence_index": 6, "correct_answer": "雑草"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "畑では雑草を育てて、収穫を待つ。", "explanation": "ここは〈作物〉の意味。作物は育てて収穫するが、雑草は育てて収穫するものではないので合わない。"}, {"text": "雑草をまいて、芽が出るのを待つ。", "explanation": "ここは〈種〉の意味。種はまいて芽を出させるが、雑草は人がまくものではないので合わない。"}, {"text": "畑で雑草を収穫して、家族に配った。", "explanation": "ここは〈野菜〉の意味。収穫するのは野菜で、雑草は収穫の対象にならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37051, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "畑に雑草を生えると、作物の育ちが悪くなる。", "corrected_sentence": "畑に雑草が生えると、作物の育ちが悪くなる。", "error_description": "「生える」は自動詞なので主語に「が」を取る。「を」は誤りで、正しくは「雑草が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37051, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雑草に抜いて、畑を耕す。", "corrected_sentence": "雑草を抜いて、畑を耕す。", "error_description": "「抜く」は目的語に「を」を取る。「雑草に」は誤りで、正しくは「雑草を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37052, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "ここは種子を起点として芽が出る流れを示すので、「から」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「出る」は目的語をとらないので、「を」は付かない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示すので、芽が出る起点としては文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、芽が出る起点としては合わない。"}], "correct_answer": "から", "explanations": {"から": "ここは種子を起点として芽が出る流れを示すので、「から」が正しい。", "を": "「出る」は目的語をとらないので、「を」は付かない。", "より": "「より」は比較の基準を示すので、芽が出る起点としては文が成り立たない。", "へ": "「へ」は方向を示すので、芽が出る起点としては合わない。"}, "error_tags": {"を": "目的語", "より": "比較", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37052, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37052, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "植物の赤ちゃんになるもの。", "primary_collocate": null, "pronunciation": "しゅし", "ipa": "ɕɯɕi", "syllable_count": 2, "sentences": [{"text": "この植物の種子は、風に乗って遠くまで飛びます。", "target_word": "種子", "complexity_tier": "T3", "furigana": "この植物[しょくぶつ]の種子[しゅし]は、風[かぜ]に乗[の]って遠[とお]くまで飛[と]びます。", "sentence_source": "generated"}, {"text": "種子から小さな芽が出て、やがて花が咲きました。", "target_word": "種子", "complexity_tier": "T3", "furigana": "種子[しゅし]から小[ちい]さな芽[め]が出[で]て、やがて花[はな]が咲[さ]きました。", "sentence_source": "generated"}, {"text": "秋になると、木は地面に種子を落とします。", "target_word": "種子", "complexity_tier": "T3", "furigana": "秋[あき]になると、木[き]は地面[じめん]に種子[しゅし]を落[お]とします。", "sentence_source": "generated"}, {"text": "鳥が実を食べて、種子をほかの場所に運びます。", "target_word": "種子", "complexity_tier": "T3", "furigana": "鳥[とり]が実[み]を食[た]べて、種子[しゅし]をほかの場所[ばしょ]に運[はこ]びます。", "sentence_source": "generated"}, {"text": "種子は水と温度がそろうと、芽を出します。", "target_word": "種子", "complexity_tier": "T3", "furigana": "種子[しゅし]は水[みず]と温度[おんど]がそろうと、芽[め]を出[だ]します。", "sentence_source": "generated"}, {"text": "リンゴの種子は、実の真ん中に入っています。", "target_word": "種子", "complexity_tier": "T3", "furigana": "リンゴの種子[しゅし]は、実[み]の真[ま]ん中[なか]に入[はい]っています。", "sentence_source": "generated"}, {"text": "理科の授業で、いろいろな種子を観察しました。", "target_word": "種子", "complexity_tier": "T3", "furigana": "理科[りか]の授業[じゅぎょう]で、いろいろな種子[しゅし]を観察[かんさつ]しました。", "sentence_source": "generated"}, {"text": "乾いた種子は、土の中でじっと春を待っています。", "target_word": "種子", "complexity_tier": "T3", "furigana": "乾[かわ]いた種子[しゅし]は、土[つち]の中[なか]でじっと春[はる]を待[ま]っています。", "sentence_source": "generated"}, {"text": "種子が地面に落ちなかったので、新しい木は育ちませんでした。", "target_word": "種子", "complexity_tier": "T3", "furigana": "種子[しゅし]が地面[じめん]に落[お]ちなかったので、新[あたら]しい木[き]は育[そだ]ちませんでした。", "sentence_source": "generated"}, {"text": "母は、花が終わったあとの種子を紙の袋に集めました。", "target_word": "種子", "complexity_tier": "T3", "furigana": "母[はは]は、花[はな]が終[お]わったあとの種子[しゅし]を紙[かみ]の袋[ふくろ]に集[あつ]めました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "種子", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "芽を出して新しい植物になる、植物の命のもと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bb45688-8400-4456-9927-11fbe9b516ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37052, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "種子", "is_correct": true, "explanation": "ここは植物の赤ちゃんになる粒を指し、風に乗って遠くへ飛ぶものとして合う。"}, {"text": "根", "is_correct": false, "explanation": "根は地中で水や養分を吸う部分で、風に乗って飛ぶものではない。"}, {"text": "芽", "is_correct": false, "explanation": "芽は種子から出る新しい葉や茎で、飛んで遠くへ移る対象ではない。"}, {"text": "茎", "is_correct": false, "explanation": "茎は植物を支える部分で、風に乗って遠くまで飛ぶことはない。"}], "explanations": {"種子": "ここは植物の赤ちゃんになる粒を指し、風に乗って遠くへ飛ぶものとして合う。", "根": "根は地中で水や養分を吸う部分で、風に乗って飛ぶものではない。", "芽": "芽は種子から出る新しい葉や茎で、飛んで遠くへ移る対象ではない。", "茎": "茎は植物を支える部分で、風に乗って遠くまで飛ぶことはない。"}, "sentence_index": 0, "correct_answer": "種子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この種子は果汁がたっぷりで、夏にみずみずしく食べられます。", "explanation": "ここは〈果実〉の意味。果汁が多くみずみずしい部分は果実で、乾いた種子には合わない。"}, {"text": "この庭では、春になると種子がきれいに咲きます。", "explanation": "ここは〈花〉の意味。咲くのは花で、種子は咲かない。〈花〉と取り違えた誤り。"}, {"text": "この木は、深い種子を張って強く育ちます。", "explanation": "ここは〈根〉の意味。地中に張るのは根で、種子は地中に広がらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37052, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "種子", "is_correct": true, "explanation": "ここは授業で観察される植物の粒を指し、観察の対象として合う。"}, {"text": "施肥", "is_correct": false, "explanation": "施肥は肥料をやる作業で、観察する対象としては合わない。"}, {"text": "雑巾", "is_correct": false, "explanation": "雑巾は理科の授業で観察する対象ではなく、文として合わない。"}, {"text": "予定", "is_correct": false, "explanation": "予定は観察する対象ではないので、理科の授業で見るものとして合わない。"}], "explanations": {"種子": "ここは授業で観察される植物の粒を指し、観察の対象として合う。", "施肥": "施肥は肥料をやる作業で、観察する対象としては合わない。", "雑巾": "雑巾は理科の授業で観察する対象ではなく、文として合わない。", "予定": "予定は観察する対象ではないので、理科の授業で見るものとして合わない。"}, "sentence_index": 6, "correct_answer": "種子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "次の種子は、百メートル走です。", "explanation": "ここは〈種目〉の意味。競技の種類を指す語で、植物の粒の種子とは別。"}, {"text": "ガスの種子が消えないように、つけっぱなしにします。", "explanation": "ここは〈種火〉の意味。ガス器具の小さな火を指す語で、種子（植物の粒）とは別なので誤り。"}, {"text": "この国には、様々な種子の人々が暮らしています。", "explanation": "ここは〈人種〉の意味。人の集団を指す語で、植物の粒の種子では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37052, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "種子にまくとき、深すぎないように気をつけます。", "corrected_sentence": "種子をまくとき、深すぎないように気をつけます。", "error_description": "助詞の誤り。「まく」は何をまくかを「を」で示すので、「種子を」が正しい。「種子に」では種子を場所のように読んでしまい、まく対象が抜けてしまう。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37052, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小さな種子を風で遠くへ運ばれます。", "corrected_sentence": "小さな種子が風で遠くへ運ばれます。", "error_description": "助詞の誤り。「運ばれる」は受け身で、運ばれるものは「が」で示す。「を」を使うと能動の目的語のように読まれ、不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37053, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「売る」は売るもの（種子）に「を」を付けるので、ここでは正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」にすると種子が主語になり、売っている店の文として不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示すので、売るものの後には付かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、売る対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「売る」は売るもの（種子）に「を」を付けるので、ここでは正しい。", "が": "「が」にすると種子が主語になり、売っている店の文として不自然。", "に": "「に」は相手や場所を示すので、売るものの後には付かない。", "へ": "「へ」は方向を示すので、売る対象を表せない。"}, "error_tags": {"の": "修飾", "に": "相手・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37053, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「小さすぎて」の主語は種子なので、種子の後には「が」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の目的語に付くので、状態を表す「小さすぎる」の主語にはならない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示し、小さすぎるの主語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、種子の状態を説明できない。"}], "correct_answer": "が", "explanations": {"が": "「小さすぎて」の主語は種子なので、種子の後には「が」が正しい。", "を": "「を」は動作の目的語に付くので、状態を表す「小さすぎる」の主語にはならない。", "に": "「に」は相手や場所を示し、小さすぎるの主語にはならない。", "で": "「で」は手段や場所を示すので、種子の状態を説明できない。"}, "error_tags": {"を": "目的語", "に": "相手・方向", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37053, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "植物が育つもとになる小さな粒。", "primary_collocate": null, "pronunciation": "しゅし", "ipa": "ɕɯɕi", "syllable_count": 2, "sentences": [{"text": "農家の人は、春に野菜の種子を畑にまきます。", "target_word": "種子", "complexity_tier": "T3", "furigana": "農家[のうか]の人[ひと]は、春[はる]に野菜[やさい]の種子[しゅし]を畑[はたけ]にまきます。", "sentence_source": "generated"}, {"text": "この店では、花の種子を一袋百円で売っています。", "target_word": "種子", "complexity_tier": "T3", "furigana": "この店[みせ]では、花[はな]の種子[しゅし]を一袋[ひとふくろ]百円[ひゃくえん]で売[う]っています。", "sentence_source": "generated"}, {"text": "種子を植える前に、土を柔らかくしておきます。", "target_word": "種子", "complexity_tier": "T3", "furigana": "種子[しゅし]を植[う]える前[まえ]に、土[つち]を柔[やわ]らかくしておきます。", "sentence_source": "generated"}, {"text": "古い種子は芽が出にくいので、新しいものを買いました。", "target_word": "種子", "complexity_tier": "T3", "furigana": "古[ふる]い種子[しゅし]は芽[め]が出[で]にくいので、新[あたら]しいものを買[か]いました。", "sentence_source": "generated"}, {"text": "小さな種子でも、水をやれば大きく育ちます。", "target_word": "種子", "complexity_tier": "T3", "furigana": "小[ちい]さな種子[しゅし]でも、水[みず]をやれば大[おお]きく育[そだ]ちます。", "sentence_source": "generated"}, {"text": "種子を保管するときは、湿気を避けることが大切です。", "target_word": "種子", "complexity_tier": "T3", "furigana": "種子[しゅし]を保管[ほかん]するときは、湿気[しっけ]を避[さ]けることが大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "ひまわりの種子は、黒くて平たい形をしています。", "target_word": "種子", "complexity_tier": "T3", "furigana": "ひまわりの種子[しゅし]は、黒[くろ]くて平[ひら]たい形[かたち]をしています。", "sentence_source": "generated"}, {"text": "種子が小さすぎて、指でつまむのに苦労しました。", "target_word": "種子", "complexity_tier": "T3", "furigana": "種子[しゅし]が小[ちい]さすぎて、指[ゆび]でつまむのに苦労[くろう]しました。", "sentence_source": "generated"}, {"text": "学校の花壇に、みんなで朝顔の種子をまきました。", "target_word": "種子", "complexity_tier": "T3", "furigana": "学校[がっこう]の花壇[かだん]に、みんなで朝顔[あさがお]の種子[しゅし]をまきました。", "sentence_source": "generated"}, {"text": "倉庫には、来年用の種子がたくさんしまってあります。", "target_word": "種子", "complexity_tier": "T3", "furigana": "倉庫[そうこ]には、来年用[らいねんよう]の種子[しゅし]がたくさんしまってあります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "種子", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "まいたり植えたりして植物を育てるための小さな粒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bb45688-8400-4456-9927-11fbe9b516ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37053, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "種子", "is_correct": true, "explanation": "ここは畑にまく植物の粒を指し、まく対象として合う。"}, {"text": "苗", "is_correct": false, "explanation": "苗は育った植物を植え付けるもので、まくものではない。"}, {"text": "害虫", "is_correct": false, "explanation": "害虫は作物を食べる虫で、畑にまく対象にはならない。"}, {"text": "雑草", "is_correct": false, "explanation": "雑草は勝手に生える草で、まく対象とは言えない。"}], "explanations": {"種子": "ここは畑にまく植物の粒を指し、まく対象として合う。", "苗": "苗は育った植物を植え付けるもので、まくものではない。", "害虫": "害虫は作物を食べる虫で、畑にまく対象にはならない。", "雑草": "雑草は勝手に生える草で、まく対象とは言えない。"}, "sentence_index": 0, "correct_answer": "種子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この種子は葉が四枚になったので、畑に植え替えます。", "explanation": "ここは〈苗〉の意味。葉が出て育った植物を指すので、まだ芽も出ていない種子には合わない。"}, {"text": "チューリップの種子は、土の中で何年も大きくなります。", "explanation": "ここは〈球根〉の意味。土の中で養分をためて大きくなるのは球根で、種子には合わない。"}, {"text": "切った枝を土にさして増やす方法を、種子といいます。", "explanation": "ここは〈挿し木〉の意味。枝を土にさして増やす方法を指すので、種子という語では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37053, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "種子", "is_correct": true, "explanation": "ここはひまわりの粒を主語にし、黒くて平たい形と結びつく。"}, {"text": "水分", "is_correct": false, "explanation": "水分は中に含む水のことで、黒くて平たい形とは説明できない。"}, {"text": "茎", "is_correct": false, "explanation": "茎は細長い支えの部分で、黒くて平たい形とは合わない。"}, {"text": "養分", "is_correct": false, "explanation": "養分は栄養の成分で、形を説明する主語としては不自然。"}], "explanations": {"種子": "ここはひまわりの粒を主語にし、黒くて平たい形と結びつく。", "水分": "水分は中に含む水のことで、黒くて平たい形とは説明できない。", "茎": "茎は細長い支えの部分で、黒くて平たい形とは合わない。", "養分": "養分は栄養の成分で、形を説明する主語としては不自然。"}, "sentence_index": 6, "correct_answer": "種子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この森には、珍しい種子の動物が住んでいます。", "explanation": "ここは〈種族〉の意味。動物の集まりを指す語で、植物の粒の種子では表せない。"}, {"text": "次の種子は、五十メートル走です。", "explanation": "ここは〈種目〉の意味。競技の種類を指す語で、植物の粒の種子とは別。"}, {"text": "ガスの種子が消えないように、弱火で保ちます。", "explanation": "ここは〈種火〉の意味。ガス器具の小さな火を指す語で、種子（植物の粒）とは別なので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37053, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "種子がまいたあと、土を軽く押さえます。", "corrected_sentence": "種子をまいたあと、土を軽く押さえます。", "error_description": "助詞の誤り。「まく」は他動詞なので、まくもの（種子）には「を」を使う。「が」だと種子が自分でまいたように読めてしまい、不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37053, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "種子を飲んで、庭にまきました。", "corrected_sentence": "種子を買って、庭にまきました。", "error_description": "動詞の誤り。「種子を買う」が正しい。「飲む」は飲み物に使う動詞で、種子を飲むとは言わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
