INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37054, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "夢や願いなどを、本当に実際のものにすること。", "primary_collocate": null, "pronunciation": "じつげん", "ipa": "d͡ʑit͡sɯɡeɴ", "syllable_count": 4, "sentences": [{"text": "子どものころの夢が、三十年後にようやく実現した。", "target_word": "実現", "complexity_tier": "T3", "furigana": "子[こ]どものころの夢[ゆめ]が、三十年後[さんじゅうねんご]にようやく実現[じつげん]した。", "sentence_source": "generated"}, {"text": "彼女は歌手になる夢を実現し、全国でコンサートを開いている。", "target_word": "実現", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は歌手[かしゅ]になる夢[ゆめ]を実現[じつげん]し、全国[ぜんこく]でコンサートを開[ひら]いている。", "sentence_source": "generated"}, {"text": "宇宙旅行が実現する日を、多くの人が待っている。", "target_word": "実現", "complexity_tier": "T3", "furigana": "宇宙旅行[うちゅうりょこう]が実現[じつげん]する日[ひ]を、多[おお]くの人[ひと]が待[ま]っている。", "sentence_source": "generated"}, {"text": "理想の暮らしを実現するには、お金だけでなく時間も必要だ。", "target_word": "実現", "complexity_tier": "T3", "furigana": "理想[りそう]の暮[く]らしを実現[じつげん]するには、お金[かね]だけでなく時間[じかん]も必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "長年の願いが実現して、祖母は涙を流して喜んだ。", "target_word": "実現", "complexity_tier": "T3", "furigana": "長年[ながねん]の願[ねが]いが実現[じつげん]して、祖母[そぼ]は涙[なみだ]を流[なが]して喜[よろこ]んだ。", "sentence_source": "generated"}, {"text": "空を飛ぶという昔の夢は、飛行機によって実現した。", "target_word": "実現", "complexity_tier": "T3", "furigana": "空[そら]を飛[と]ぶという昔[むかし]の夢[ゆめ]は、飛行機[ひこうき]によって実現[じつげん]した。", "sentence_source": "generated"}, {"text": "彼は努力を重ねて、自分の店を持つ目標を実現させた。", "target_word": "実現", "complexity_tier": "T3", "furigana": "彼[かれ]は努力[どりょく]を重[かさ]ねて、自分[じぶん]の店[みせ]を持[も]つ目標[もくひょう]を実現[じつげん]させた。", "sentence_source": "generated"}, {"text": "夢を見るだけでは何も実現しないので、行動することが大切だ。", "target_word": "実現", "complexity_tier": "T3", "furigana": "夢[ゆめ]を見[み]るだけでは何[なに]も実現[じつげん]しないので、行動[こうどう]することが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "仲間の支えがあったからこそ、長年の夢だったヨーロッパ旅行を実現できた。", "target_word": "実現", "complexity_tier": "T3", "furigana": "仲間[なかま]の支[ささ]えがあったからこそ、長年[ながねん]の夢[ゆめ]だったヨーロッパ旅行[りょこう]を実現[じつげん]できた。", "sentence_source": "generated"}, {"text": "二人の約束が実現するまでに、十年かかった。", "target_word": "実現", "complexity_tier": "T3", "furigana": "二人[ふたり]の約束[やくそく]が実現[じつげん]するまでに、十年[じゅうねん]かかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実現する", "label": "辞書形"}, {"form": "実現した", "label": "過去形"}, {"form": "実現しない", "label": "否定形"}, {"form": "実現できる", "label": "可能形"}, {"form": "実現させる", "label": "使役形"}], "register": "標準", "sense_fingerprint": "夢や願いなどが現実のものになる、または現実のものにすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: 長年の夢 (Zipf 2.36)']::text[], 'c171a401-7adc-4cc9-9573-2a4e0f6702de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37054, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実現", "is_correct": true, "explanation": "「夢が〜ようやく実現した」で、夢が現実のものになる意味に合う。"}, {"text": "遅刻", "is_correct": false, "explanation": "遅刻は時刻に遅れること。「夢が遅刻した」では意味が成り立たない。"}, {"text": "欠席", "is_correct": false, "explanation": "欠席は授業や会合に出ないこと。夢を主語にすると文が通らない。"}, {"text": "失業", "is_correct": false, "explanation": "失業は仕事を失うこと。夢が主語の文には当てはまらない。"}], "explanations": {"実現": "「夢が〜ようやく実現した」で、夢が現実のものになる意味に合う。", "遅刻": "遅刻は時刻に遅れること。「夢が遅刻した」では意味が成り立たない。", "欠席": "欠席は授業や会合に出ないこと。夢を主語にすると文が通らない。", "失業": "失業は仕事を失うこと。夢が主語の文には当てはまらない。"}, "sentence_index": 0, "correct_answer": "実現"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天文台の観測で、新しい星を実現した。", "explanation": "ここは〈発見〉の意味。実現は夢や計画が現実になることで、星を見つける場面には合わない。"}, {"text": "天気予報は、明日の雨を実現した。", "explanation": "ここは〈予想〉の意味。予想は先のことを推し量ることで、夢が現実になる意味の実現とは合わない。"}, {"text": "彼の英語は、短い期間で実現した。", "explanation": "ここは〈上達〉の意味。上達は腕前が上がることで、計画を形にする実現とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37054, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実現", "is_correct": true, "explanation": "「目標を実現させた」で、目標を現実のものにする意味が入る。"}, {"text": "病気", "is_correct": false, "explanation": "病気は体の不調のこと。「目標を病気させた」では意味が成り立たない。"}, {"text": "宴会", "is_correct": false, "explanation": "宴会は飲食の集まり。目標の対象として文が通らない。"}, {"text": "通勤", "is_correct": false, "explanation": "通勤は職場へ行き来すること。「目標を通勤させた」では意味が通らない。"}], "explanations": {"実現": "「目標を実現させた」で、目標を現実のものにする意味が入る。", "病気": "病気は体の不調のこと。「目標を病気させた」では意味が成り立たない。", "宴会": "宴会は飲食の集まり。目標の対象として文が通らない。", "通勤": "通勤は職場へ行き来すること。「目標を通勤させた」では意味が通らない。"}, "sentence_index": 6, "correct_answer": "実現"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の話の意味を、ようやく実現した。", "explanation": "ここは〈理解〉の意味。理解は内容を把握することで、計画を形にする実現とは違う。"}, {"text": "机の上の書類を、すぐに実現した。", "explanation": "ここは〈整理〉の意味。整理は物を片づけて順序よく並べることで、計画を形にする実現とは違う。"}, {"text": "旅先で、日本の良さを実現した。", "explanation": "ここは〈実感〉の意味。実感は実際に感じ取ることで、夢や願いを現実のものにする意味とは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37054, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小さい頃の夢が、ついに実現させて、今は店を開いている。", "corrected_sentence": "小さい頃の夢が、ついに実現して、今は店を開いている。", "error_description": "「夢が」が主語の文では、実現は自動詞として「実現して」を使う。「させて」は行わせる人が必要なため、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37054, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ずっと願っていた留学が実現に、家族は喜んでくれた。", "corrected_sentence": "ずっと願っていた留学が実現して、家族は喜んでくれた。", "error_description": "「実現」の後に「に」を続けると文が切れない。前の出来事から後の文へつなぐには「実現して」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37055, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「公約に掲げた」の対象は実現なので、目的語を示す「を」が入る。"}, {"text": "が", "is_correct": false, "explanation": "「が」では掲げる対象がなくなり、「公約に掲げた」の目的語が欠けてしまう。"}, {"text": "に", "is_correct": false, "explanation": "「公約に」にすでに「に」があり、続けて「実現に」と置くと二重になって成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示す。実現の後ろに置くと「掲げた」の対象が示せない。"}], "correct_answer": "を", "explanations": {"を": "「公約に掲げた」の対象は実現なので、目的語を示す「を」が入る。", "が": "「が」では掲げる対象がなくなり、「公約に掲げた」の目的語が欠けてしまう。", "に": "「公約に」にすでに「に」があり、続けて「実現に」と置くと二重になって成り立たない。", "で": "「で」は場所や手段を示す。実現の後ろに置くと「掲げた」の対象が示せない。"}, "error_tags": {"を": "目的語", "が": "主語", "に": "方向・相手", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37055, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37055, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "計画や考えを、実際の行動や形として現すこと。", "primary_collocate": null, "pronunciation": "じつげん", "ipa": "d͡ʑit͡sɯɡeɴ", "syllable_count": 4, "sentences": [{"text": "また、限られた環境で効率的に生産を行う「資源管理」の観点からも、持続可能な食料供給の実現において重要な役割を果たしています。", "target_word": "実現", "complexity_tier": "T3", "furigana": "また、限[かぎ]られた環境[かんきょう]で効率的[こうりつてき]に生産[せいさん]を行[おこな]う「資源管理[しげんかんり]」の観点[かんてん]からも、持続可能[じぞくかのう]な食料供給[しょくりょうきょうきゅう]の実現[じつげん]において重要[じゅうよう]な役割[やくわり]を果[は]たしています。", "sentence_source": "mined"}, {"text": "市長は、子どもが安心して遊べる公園の実現を公約に掲げた。", "target_word": "実現", "complexity_tier": "T3", "furigana": "市長[しちょう]は、子[こ]どもが安心[あんしん]して遊[あそ]べる公園[こうえん]の実現[じつげん]を公約[こうやく]に掲[かか]げた。", "sentence_source": "generated"}, {"text": "資金が足りなかったため、この計画の実現は来年に延期された。", "target_word": "実現", "complexity_tier": "T3", "furigana": "資金[しきん]が足[た]りなかったため、この計画[けいかく]の実現[じつげん]は来年[らいねん]に延期[えんき]された。", "sentence_source": "generated"}, {"text": "長い議論の末、ようやく新しい図書館の建設が実現した。", "target_word": "実現", "complexity_tier": "T3", "furigana": "長[なが]い議論[ぎろん]の末[すえ]、ようやく新[あたら]しい図書館[としょかん]の建設[けんせつ]が実現[じつげん]した。", "sentence_source": "generated"}, {"text": "彼は留学の計画を実現するために、毎晩アルバイトをして貯金している。", "target_word": "実現", "complexity_tier": "T3", "furigana": "彼[かれ]は留学[りゅうがく]の計画[けいかく]を実現[じつげん]するために、毎晩[まいばん]アルバイトをして貯金[ちょきん]している。", "sentence_source": "generated"}, {"text": "社員の提案がそのまま実現するとは、誰も思っていなかった。", "target_word": "実現", "complexity_tier": "T3", "furigana": "社員[しゃいん]の提案[ていあん]がそのまま実現[じつげん]するとは、誰[だれ]も思[おも]っていなかった。", "sentence_source": "generated"}, {"text": "実現が難しい案でも、まず意見を出し合うことが大切だ。", "target_word": "実現", "complexity_tier": "T3", "furigana": "実現[じつげん]が難[むずか]しい案[あん]でも、まず意見[いけん]を出[だ]し合[あ]うことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "住民の願いを実現させるため、町内会が署名を集めた。", "target_word": "実現", "complexity_tier": "T3", "furigana": "住民[じゅうみん]の願[ねが]いを実現[じつげん]させるため、町内会[ちょうないかい]が署名[しょめい]を集[あつ]めた。", "sentence_source": "generated"}, {"text": "この橋の建設が実現すれば、島と町の行き来がずっと楽になる。", "target_word": "実現", "complexity_tier": "T3", "furigana": "この橋[はし]の建設[けんせつ]が実現[じつげん]すれば、島[しま]と町[まち]の行[い]き来[き]がずっと楽[らく]になる。", "sentence_source": "generated"}, {"text": "理想は立派だが、予算がなければ実現できない。", "target_word": "実現", "complexity_tier": "T3", "furigana": "理想[りそう]は立派[りっぱ]だが、予算[よさん]がなければ実現[じつげん]できない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実現する", "label": "辞書形"}, {"form": "実現した", "label": "過去形"}, {"form": "実現しない", "label": "否定形"}, {"form": "実現できる", "label": "可能形"}, {"form": "実現される", "label": "受身形"}], "register": "標準", "sense_fingerprint": "計画・案・提案などを実行して実際の形にすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: 出し合う (Zipf 1.9)']::text[], 'c171a401-7adc-4cc9-9573-2a4e0f6702de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37055, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実現", "is_correct": true, "explanation": "「食料供給の実現において」と続き、計画や考えを形にする意味で文に合う。"}, {"text": "解散", "is_correct": false, "explanation": "解散は組織や集まりを解いて散らすこと。食料供給の文脈では意味が通らない。"}, {"text": "削除", "is_correct": false, "explanation": "削除は文字やデータを消すこと。食料供給の役割を述べる文には入らない。"}, {"text": "失業", "is_correct": false, "explanation": "失業は仕事を失うこと。「食料供給の失業において」では文が成り立たない。"}], "explanations": {"実現": "「食料供給の実現において」と続き、計画や考えを形にする意味で文に合う。", "解散": "解散は組織や集まりを解いて散らすこと。食料供給の文脈では意味が通らない。", "削除": "削除は文字やデータを消すこと。食料供給の役割を述べる文には入らない。", "失業": "失業は仕事を失うこと。「食料供給の失業において」では文が成り立たない。"}, "sentence_index": 0, "correct_answer": "実現"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "霧の中から、大きな船が実現した。", "explanation": "ここは〈出現〉の意味。実現は計画や願いを形にすることで、船が現れる場面には合わない。"}, {"text": "彼女は言葉にできない思いを、踊りで実現した。", "explanation": "ここは〈表現〉の意味。実現は計画を形にすることで、気持ちを外に示す場面には使わない。"}, {"text": "長く続いた対立を、話し合いで実現した。", "explanation": "ここは〈解決〉の意味。実現は計画や願いを形にすることで、対立を収める場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37055, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実現", "is_correct": true, "explanation": "「実現が難しい案」で、計画を形にする意味が文の主題として通る。"}, {"text": "遅刻", "is_correct": false, "explanation": "遅刻は決まった時刻に遅れること。「遅刻が難しい案」では意味が成り立たない。"}, {"text": "病気", "is_correct": false, "explanation": "病気は体の不調のこと。「病気が難しい案」と言っても文が通らない。"}, {"text": "宴会", "is_correct": false, "explanation": "宴会は人が集まって飲食する会。計画の難しさを表す主語には合わない。"}], "explanations": {"実現": "「実現が難しい案」で、計画を形にする意味が文の主題として通る。", "遅刻": "遅刻は決まった時刻に遅れること。「遅刻が難しい案」では意味が成り立たない。", "病気": "病気は体の不調のこと。「病気が難しい案」と言っても文が通らない。", "宴会": "宴会は人が集まって飲食する会。計画の難しさを表す主語には合わない。"}, "sentence_index": 6, "correct_answer": "実現"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅先で、日本の良さをしみじみ実現した。", "explanation": "ここは〈実感〉の意味。実感は実際に感じ取ることで、計画を形にする実現とは別の意味。"}, {"text": "昔の出来事を、映像で実現して見せた。", "explanation": "ここは〈再現〉の意味。再現は過去の場面を改めて示すことで、計画を形にする意味の実現とは合わない。"}, {"text": "チームは、ふだんの実力を実現した。", "explanation": "ここは〈発揮〉の意味。発揮は持っている力を表に出すことで、計画を形にする実現とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37055, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市の新しい地下鉄の計画は、予算の問題で実現で延期された。", "corrected_sentence": "市の新しい地下鉄の計画は、予算の問題で実現が延期された。", "error_description": "誤りは「実現で」。延期されるのは実現そのものなので、主語を表す「が」が正しい。「で」は場所や手段を表すため不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37055, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大学の寮の建設計画が、ついに実現なかった。", "corrected_sentence": "大学の寮の建設計画が、ついに実現しなかった。", "error_description": "「実現」は「する」の付く動詞。否定は「実現しなかった」が正しく、「実現なかった」は形が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
