INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37056, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "茶色い色のことです。", "primary_collocate": null, "pronunciation": "かっしょく", "ipa": "kaɕɕokɯ", "syllable_count": 4, "sentences": [{"text": "秋になると、木の葉は褐色に変わります。", "target_word": "褐色", "complexity_tier": "T3", "furigana": "秋[あき]になると、木[き]の葉[は]は褐色[かっしょく]に変[か]わります。", "sentence_source": "generated"}, {"text": "彼女は夏の海で、肌が褐色に焼けていました。", "target_word": "褐色", "complexity_tier": "T3", "furigana": "彼女は夏[なつ]の海[うみ]で、肌[はだ]が褐色[かっしょく]に焼[や]けていました。", "sentence_source": "generated"}, {"text": "このコーヒーは、きれいな褐色をしています。", "target_word": "褐色", "complexity_tier": "T3", "furigana": "このコーヒーは、きれいな褐色[かっしょく]をしています。", "sentence_source": "generated"}, {"text": "褐色の犬が、庭で走りまわっていました。", "target_word": "褐色", "complexity_tier": "T3", "furigana": "褐色[かっしょく]の犬[いぬ]が、庭[にわ]で走[はし]りまわっていました。", "sentence_source": "generated"}, {"text": "古い紙は、時間がたつと褐色になります。", "target_word": "褐色", "complexity_tier": "T3", "furigana": "古[ふる]い紙[かみ]は、時間[じかん]がたつと褐色[かっしょく]になります。", "sentence_source": "generated"}, {"text": "土が乾くと、畑は褐色に見えます。", "target_word": "褐色", "complexity_tier": "T3", "furigana": "土[つち]が乾[かわ]くと、畑[はたけ]は褐色[かっしょく]に見[み]えます。", "sentence_source": "generated"}, {"text": "パンを焼きすぎて、表面が濃い褐色になりました。", "target_word": "褐色", "complexity_tier": "T3", "furigana": "パンを焼[や]きすぎて、表面[ひょうめん]が濃[こ]い褐色[かっしょく]になりました。", "sentence_source": "generated"}, {"text": "褐色のかばんは、どんな服にも合います。", "target_word": "褐色", "complexity_tier": "T3", "furigana": "褐色[かっしょく]のかばんは、どんな服[ふく]にも合[あ]います。", "sentence_source": "generated"}, {"text": "雨で川の水が濁り、褐色の水が流れていました。", "target_word": "褐色", "complexity_tier": "T3", "furigana": "雨[あめ]で川[かわ]の水[みず]が濁[にご]り、褐色[かっしょく]の水[みず]が流[なが]れていました。", "sentence_source": "generated"}, {"text": "リンゴを切って放っておくと、切り口が褐色に変わります。", "target_word": "褐色", "complexity_tier": "T3", "furigana": "リンゴを切[き]って放[ほう]っておくと、切[き]り口[くち]が褐色[かっしょく]に変[か]わります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "褐色", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "茶色という色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bb45688-8400-4456-9927-11fbe9b516ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37056, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "褐色", "is_correct": true, "explanation": "木の葉の色を表す語で、「褐色に変わる」と自然に続く。"}, {"text": "樹液", "is_correct": false, "explanation": "木の内側を流れる液体で色の名前ではないため、「樹液に変わる」は成り立たない。"}, {"text": "年輪", "is_correct": false, "explanation": "木の断面に見える同心円の模様で、色を表さないので「年輪に変わる」とは続かない。"}, {"text": "花粉", "is_correct": false, "explanation": "植物が飛ばす粉で、木の葉が変わる先としては意味が通らない。"}], "explanations": {"褐色": "木の葉の色を表す語で、「褐色に変わる」と自然に続く。", "樹液": "木の内側を流れる液体で色の名前ではないため、「樹液に変わる」は成り立たない。", "年輪": "木の断面に見える同心円の模様で、色を表さないので「年輪に変わる」とは続かない。", "花粉": "植物が飛ばす粉で、木の葉が変わる先としては意味が通らない。"}, "sentence_index": 0, "correct_answer": "褐色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このスープは、褐色の味がする。", "explanation": "ここは〈甘い〉のような味覚の語が入る場面。褐色は色の名前なので、味は表せない。"}, {"text": "このコーヒーは、褐色の香りが強い。", "explanation": "ここは〈香ばしい〉のような香りの語が入る場面。褐色は色を表すので、香りの強さは表せない。"}, {"text": "電話の向こうで、褐色の声がした。", "explanation": "ここは〈低い〉〈大きな〉のような声の様子を表す語が入る場面。褐色は色名なので、声の様子は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37056, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "褐色", "is_correct": true, "explanation": "焼けた表面の色を表す語で、「濃い褐色になる」と自然に続く。"}, {"text": "酵母", "is_correct": false, "explanation": "パン生地を発酵させる微生物で色の名前ではないため、「濃い酵母になる」は成り立たない。"}, {"text": "小麦粉", "is_correct": false, "explanation": "パンの材料で、焼き色の結果としては意味が通らない。"}, {"text": "生地", "is_correct": false, "explanation": "焼く前の材料の塊で、焼けた表面の状態を表せないので合わない。"}], "explanations": {"褐色": "焼けた表面の色を表す語で、「濃い褐色になる」と自然に続く。", "酵母": "パン生地を発酵させる微生物で色の名前ではないため、「濃い酵母になる」は成り立たない。", "小麦粉": "パンの材料で、焼き色の結果としては意味が通らない。", "生地": "焼く前の材料の塊で、焼けた表面の状態を表せないので合わない。"}, "sentence_index": 6, "correct_answer": "褐色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電車が、褐色の音を立てた。", "explanation": "ここは〈きしむ〉〈大きな〉のような音の様子を表す語が入る場面。褐色は色名なので、音は表せない。"}, {"text": "ざらざらした表面は、褐色の感触だった。", "explanation": "ここは〈ざらざら〉のような手触りの語が入る場面。褐色は色名で、触った感じは表せない。"}, {"text": "来月は、予定がほとんど褐色だ。", "explanation": "ここは〈びっしり〉のような予定の詰まり具合を表す語が入る場面。褐色は色名なので、予定の混み具合は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37056, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "秋になると、山の木々は褐色で変わります。", "corrected_sentence": "秋になると、山の木々は褐色に変わります。", "error_description": "変化の結果を表す「に」を「で」にした誤り。「褐色に変わる」の「に」が正しく、「で」では手段や場所の意味になって合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37056, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "切ったあとの断面が褐色に変えます。", "corrected_sentence": "切ったあとの断面が褐色に変わります。", "error_description": "自動詞「変わる」を他動詞「変える」にした誤り。断面が自分で色を変えるので、自動詞の「変わる」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
