INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37057, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "茶色い色を表す言葉。焦げ茶色や濃い茶色など、さまざまな濃さがある。", "primary_collocate": null, "pronunciation": "かっしょく", "ipa": "kaɕɕokɯ", "syllable_count": 4, "sentences": [{"text": "褐色には、薄いものから焦げ茶のように濃いものまであります。", "target_word": "褐色", "complexity_tier": "T3", "furigana": "褐色[かっしょく]には、薄[うす]いものから焦[こ]げ茶[ちゃ]のように濃[こ]いものまであります。", "sentence_source": "generated"}, {"text": "画家は、絵の具を混ぜて深い褐色を作りました。", "target_word": "褐色", "complexity_tier": "T3", "furigana": "画家[がか]は、絵[え]の具[ぐ]を混[ま]ぜて深[ふか]い褐色[かっしょく]を作[つく]りました。", "sentence_source": "generated"}, {"text": "この革の靴は、年月がたって濃い褐色になりました。", "target_word": "褐色", "complexity_tier": "T3", "furigana": "この革[かわ]の靴[くつ]は、年月[としつき]がたって濃[こ]い褐色[かっしょく]になりました。", "sentence_source": "generated"}, {"text": "日に焼けた肌は、健康的な褐色に見えます。", "target_word": "褐色", "complexity_tier": "T3", "furigana": "日[ひ]に焼[や]けた肌[はだ]は、健康的[けんこうてき]な褐色[かっしょく]に見[み]えます。", "sentence_source": "generated"}, {"text": "家具は、落ち着いた褐色にそろえてあります。", "target_word": "褐色", "complexity_tier": "T3", "furigana": "家具[かぐ]は、落[お]ち着[つ]いた褐色[かっしょく]にそろえてあります。", "sentence_source": "generated"}, {"text": "壁を明るい褐色にぬると、部屋が暖かい感じになります。", "target_word": "褐色", "complexity_tier": "T3", "furigana": "壁[かべ]を明[あか]るい褐色[かっしょく]にぬると、部屋[へや]が暖[あたた]かい感[かん]じになります。", "sentence_source": "generated"}, {"text": "熟した木の実は、つやのある褐色をしています。", "target_word": "褐色", "complexity_tier": "T3", "furigana": "熟[じゅく]した木[き]の実[み]は、つやのある褐色[かっしょく]をしています。", "sentence_source": "generated"}, {"text": "彼は、褐色の目でじっとこちらを見ました。", "target_word": "褐色", "complexity_tier": "T3", "furigana": "彼[かれ]は、褐色[かっしょく]の目[め]でじっとこちらを見[み]ました。", "sentence_source": "generated"}, {"text": "チョコレートの色は、黒に近い褐色です。", "target_word": "褐色", "complexity_tier": "T3", "furigana": "チョコレートの色[いろ]は、黒[くろ]に近[ちか]い褐色[かっしょく]です。", "sentence_source": "generated"}, {"text": "夕方の光で、山全体がやわらかい褐色に染まりました。", "target_word": "褐色", "complexity_tier": "T3", "furigana": "夕方[ゆうがた]の光[ひかり]で、山全体[やまぜんたい]がやわらかい褐色[かっしょく]に染[そ]まりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "褐色", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "薄い茶色から焦げ茶色まで、濃さに幅のある茶色系の色名", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bb45688-8400-4456-9927-11fbe9b516ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37057, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "褐色", "is_correct": true, "explanation": "薄いものから濃いものまで幅のある色名で、主語として文が成り立つ。"}, {"text": "時計", "is_correct": false, "explanation": "時刻を示す道具で、濃淡の幅を持たないので「時計には濃いものまである」は成り立たない。"}, {"text": "手紙", "is_correct": false, "explanation": "文書のことで、色の濃さという性質には当てはまらない。"}, {"text": "郵便", "is_correct": false, "explanation": "郵送のしくみを指し、濃淡の幅は持たないので合わない。"}], "explanations": {"褐色": "薄いものから濃いものまで幅のある色名で、主語として文が成り立つ。", "時計": "時刻を示す道具で、濃淡の幅を持たないので「時計には濃いものまである」は成り立たない。", "手紙": "文書のことで、色の濃さという性質には当てはまらない。", "郵便": "郵送のしくみを指し、濃淡の幅は持たないので合わない。"}, "sentence_index": 0, "correct_answer": "褐色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このお茶は、褐色の味がする。", "explanation": "ここは〈苦い〉〈香ばしい〉のような味覚の語が入る場面。褐色は色名で、味は表せない。"}, {"text": "ざらざらした表面は、褐色の手触りだった。", "explanation": "ここは〈ざらざら〉のような手触りの語が入る場面。褐色は色名なので、触った感じは表せない。"}, {"text": "電話の向こうで、褐色の声がした。", "explanation": "ここは〈低い〉〈大きな〉のような声の様子を表す語が入る場面。褐色は色名なので、声の様子は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37057, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "褐色", "is_correct": true, "explanation": "色の様子を表す語で、「つやのある褐色をしている」と自然に続く。"}, {"text": "香り", "is_correct": false, "explanation": "香りを表す語で、「つやのある香りをしている」では見た目の様子にならない。"}, {"text": "硬さ", "is_correct": false, "explanation": "手ざわりや性質を表す語で、つやのある見た目には当てはまらない。"}, {"text": "甘味", "is_correct": false, "explanation": "味覚を表す語で、つやのある見た目には合わない。"}], "explanations": {"褐色": "色の様子を表す語で、「つやのある褐色をしている」と自然に続く。", "香り": "香りを表す語で、「つやのある香りをしている」では見た目の様子にならない。", "硬さ": "手ざわりや性質を表す語で、つやのある見た目には当てはまらない。", "甘味": "味覚を表す語で、つやのある見た目には合わない。"}, "sentence_index": 6, "correct_answer": "褐色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電車が、大きな褐色の音を立てた。", "explanation": "ここは〈大きな〉〈きしむ〉のような音の語が入る場面。褐色は色の名前なので、音は表せない。"}, {"text": "この紅茶は、褐色の香りがふわりと広がる。", "explanation": "ここは〈香ばしい〉のような香りの語が入る場面。褐色は色を表すので、香りは表せない。"}, {"text": "兄は、褐色の性格でよく笑う。", "explanation": "ここは〈明るい〉〈陽気〉のような性格の語が入る場面。褐色は色名なので、人の性格は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37057, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ドアを褐色へ塗りました。", "corrected_sentence": "ドアを褐色に塗りました。", "error_description": "「に」を「へ」にした誤り。色を塗った結果は「に」で表すので、方向の「へ」は合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37057, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "少年は、褐色な目でじっとこちらを見つめました。", "corrected_sentence": "少年は、褐色の目でじっとこちらを見つめました。", "error_description": "名詞の「褐色」に「な」を付けた誤り。色を表す名詞は「褐色の」と「の」で続けるのが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37058, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「本格の日本庭園」と、本格が後ろの庭園を修飾する形になる。"}, {"text": "が", "is_correct": false, "explanation": "「本格が日本庭園を作る」では本格が作る主体になり、文の主語として意味が合わない。"}, {"text": "に", "is_correct": false, "explanation": "「本格に日本庭園を作る」は成り立たず、相手や結果を示す文脈にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、本格を修飾する位置には入らない。"}], "correct_answer": "の", "explanations": {"の": "「本格の日本庭園」と、本格が後ろの庭園を修飾する形になる。", "が": "「本格が日本庭園を作る」では本格が作る主体になり、文の主語として意味が合わない。", "に": "「本格に日本庭園を作る」は成り立たず、相手や結果を示す文脈にならない。", "へ": "方向を示す「へ」は、本格を修飾する位置には入らない。"}, "error_tags": {"が": "主格", "に": "相手・結果", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37058, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「本格を売りにする」で、本格が売り物（目的語）になる。"}, {"text": "が", "is_correct": false, "explanation": "「本格が売りにしている」では、本格を売る主体のように読めて文が合わない。"}, {"text": "に", "is_correct": false, "explanation": "「本格に売りにする」は売り物の対象を示せず、成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、「本格から売りにする」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「本格を売りにする」で、本格が売り物（目的語）になる。", "が": "「本格が売りにしている」では、本格を売る主体のように読めて文が合わない。", "に": "「本格に売りにする」は売り物の対象を示せず、成り立たない。", "から": "「から」は起点を示すので、「本格から売りにする」は意味が通らない。"}, "error_tags": {"が": "主格", "に": "相手・結果", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37058, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "本当にそのものらしい、という感じのこと。", "primary_collocate": null, "pronunciation": "ほんかく", "ipa": "hoŋkaku", "syllable_count": 4, "sentences": [{"text": "この店のカレーはインドから来た料理人が作る本格の味で、毎日行列ができる。", "target_word": "本格", "complexity_tier": "T3", "furigana": "この店[みせ]のカレーはインドから来[き]た料理人[りょうりにん]が作[つく]る本格[ほんかく]の味[あじ]で、毎日[まいにち]行列[ぎょうれつ]ができる。", "sentence_source": "generated"}, {"text": "祖父は本格の日本庭園を作るために、石を遠くから運んできた。", "target_word": "本格", "complexity_tier": "T3", "furigana": "祖父[そふ]は本格[ほんかく]の日本庭園[にほんていえん]を作[つく]るために、石[いし]を遠[とお]くから運[はこ]んできた。", "sentence_source": "generated"}, {"text": "本格を求める客が多いので、この店は安い材料を使わない。", "target_word": "本格", "complexity_tier": "T3", "furigana": "本格[ほんかく]を求[もと]める客[きゃく]が多[おお]いので、この店[みせ]は安[やす]い材料[ざいりょう]を使[つか]わない。", "sentence_source": "generated"}, {"text": "このピザは窯で焼く本格のイタリア料理なので、生地の香りが違う。", "target_word": "本格", "complexity_tier": "T4", "furigana": "このピザは窯[かま]で焼[や]く本格[ほんかく]のイタリア料理[りょうり]なので、生地[きじ]の香[かお]りが違[ちが]う。", "sentence_source": "generated"}, {"text": "本格にこだわる父は、インスタントのコーヒーを一度も飲まない。", "target_word": "本格", "complexity_tier": "T3", "furigana": "本格[ほんかく]にこだわる父[ちち]は、インスタントのコーヒーを一度[いちど]も飲[の]まない。", "sentence_source": "generated"}, {"text": "家庭で作る料理でも、だしをていねいにとれば本格の味に近づく。", "target_word": "本格", "complexity_tier": "T3", "furigana": "家庭[かてい]で作[つく]る料理[りょうり]でも、だしをていねいにとれば本格[ほんかく]の味[あじ]に近[ちか]づく。", "sentence_source": "generated"}, {"text": "安いお菓子だと思ったが、食べてみると本格のフランス菓子だった。", "target_word": "本格", "complexity_tier": "T3", "furigana": "安[やす]いお菓子[かし]だと思[おも]ったが、食[た]べてみると本格[ほんかく]のフランス菓子[がし]だった。", "sentence_source": "generated"}, {"text": "本格を売りにしているラーメン屋は、スープを三日かけて作っている。", "target_word": "本格", "complexity_tier": "T3", "furigana": "本格[ほんかく]を売[う]りにしているラーメン屋[や]は、スープを三日[みっか]かけて作[つく]っている。", "sentence_source": "generated"}, {"text": "観光客向けの店ではなく、地元の人が通う本格の寿司屋に行きたい。", "target_word": "本格", "complexity_tier": "T4", "furigana": "観光客[かんこうきゃく]向[む]けの店[みせ]ではなく、地元[じもと]の人[ひと]が通[かよ]う本格[ほんかく]の寿司屋[すしや]に行[い]きたい。", "sentence_source": "generated"}, {"text": "兄は本格の中華料理を習うために、中国まで留学した。", "target_word": "本格", "complexity_tier": "T3", "furigana": "兄[あに]は本格[ほんかく]の中華料理[ちゅうかりょうり]を習[なら]うために、中国[ちゅうごく]まで留学[りゅうがく]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "本格", "label": "基本形"}, {"form": "本格的", "label": "派生形"}], "register": "neutral", "sense_fingerprint": "本物そのものらしい正統な味や作りであること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bb45688-8400-4456-9927-11fbe9b516ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37058, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本格", "is_correct": true, "explanation": "本物らしい正統な作りを表し、「本格の味」と自然に続く。"}, {"text": "特売", "is_correct": false, "explanation": "安く売る催しを指すので、料理の味の性質を表せず「特売の味」は不自然。"}, {"text": "新築", "is_correct": false, "explanation": "建物を新しく建てることで、味とは結びつかない。"}, {"text": "残業", "is_correct": false, "explanation": "勤務時間を延ばすことで、料理の味とは関係がない。"}], "explanations": {"本格": "本物らしい正統な作りを表し、「本格の味」と自然に続く。", "特売": "安く売る催しを指すので、料理の味の性質を表せず「特売の味」は不自然。", "新築": "建物を新しく建てることで、味とは結びつかない。", "残業": "勤務時間を延ばすことで、料理の味とは関係がない。"}, "sentence_index": 0, "correct_answer": "本格"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は本格で試合に勝つつもりだ。", "explanation": "ここは〈本気〉（真剣さ）の意味。本格は味や作りが本物らしいことで、人の意気込みには使わない。"}, {"text": "公園の本格で、子どもが遊んでいる。", "explanation": "ここは〈公園〉の意味。本格は本物らしい様子を表す語なので、遊び場所は指さない。"}, {"text": "朝の本格の時間に、ゆっくり読書をした。", "explanation": "ここは〈静かな〉のように時間の様子を表す語が入る場面。本格は作りの正統さを表すので、時間の様子には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37058, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本格", "is_correct": true, "explanation": "正統な作りの菓子だと示し、「本格のフランス菓子」と続く。"}, {"text": "包装", "is_correct": false, "explanation": "菓子を包む容器や見た目を指し、菓子の本物らしさとは結びつかない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "保存に使う家電で、菓子の種類を表さないので「冷蔵庫のフランス菓子」は不自然。"}, {"text": "容器", "is_correct": false, "explanation": "入れ物を指すため、菓子の本格さは表せない。"}], "explanations": {"本格": "正統な作りの菓子だと示し、「本格のフランス菓子」と続く。", "包装": "菓子を包む容器や見た目を指し、菓子の本物らしさとは結びつかない。", "冷蔵庫": "保存に使う家電で、菓子の種類を表さないので「冷蔵庫のフランス菓子」は不自然。", "容器": "入れ物を指すため、菓子の本格さは表せない。"}, "sentence_index": 6, "correct_answer": "本格"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は本格の気持ちを正直に話してくれた。", "explanation": "ここは〈本音〉（隠さない本当の気持ち）の意味。本格は味や作りが本物らしいことで、気持ちの率直さは表さない。"}, {"text": "今日は本格が良くて、洗濯日和だ。", "explanation": "ここは〈天気〉の意味。本格は作りや様式の正統さで、空模様は表せない。"}, {"text": "健康診断で、本格が三キロも増えた。", "explanation": "ここは〈体重〉の意味。本格は量ではなく作りの正統さを指すので、重さの増減には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37058, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店の料理は、本格で味を求めて材料にこだわっている。", "corrected_sentence": "この店の料理は、本格の味を求めて材料にこだわっている。", "error_description": "「本格の味」の「の」を「で」にした誤り。本格は味や作りを修飾するので、名詞に続く「の」が正しく、「で」では意味が通らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37058, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は本格的の和食を作るために、器を集めている。", "corrected_sentence": "父は本格的な和食を作るために、器を集めている。", "error_description": "「本格的な」の「な」を「の」にした誤り。形容動詞は「な」で名詞を修飾するので、「の」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
