INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37059, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37059, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "物事が本物らしく、しっかりとした様子であること。また、そのさま。", "primary_collocate": null, "pronunciation": "ほんかく", "ipa": "hoŋkaku", "syllable_count": 4, "sentences": [{"text": "準備は終わったので、来週からいよいよ本格の練習が始まる。", "target_word": "本格", "complexity_tier": "T3", "furigana": "準備[じゅんび]は終[お]わったので、来週[らいしゅう]からいよいよ本格[ほんかく]の練習[れんしゅう]が始[はじ]まる。", "sentence_source": "generated"}, {"text": "今年は雪が少なかったが、二月になって本格の冬が来た。", "target_word": "本格", "complexity_tier": "T3", "furigana": "今年[ことし]は雪[ゆき]が少[すく]なかったが、二月[にがつ]になって本格[ほんかく]の冬[ふゆ]が来[き]た。", "sentence_source": "generated"}, {"text": "本格の工事は来月からで、今月は準備だけだ。", "target_word": "本格", "complexity_tier": "T3", "furigana": "本格[ほんかく]の工事[こうじ]は来月[らいげつ]からで、今月[こんげつ]は準備[じゅんび]だけだ。", "sentence_source": "generated"}, {"text": "本格の梅雨が来る前に、傘を新しく買っておこう。", "target_word": "本格", "complexity_tier": "T3", "furigana": "本格[ほんかく]の梅雨[つゆ]が来[く]る前[まえ]に、傘[かさ]を新[あたら]しく買[か]っておこう。", "sentence_source": "generated"}, {"text": "兄は趣味でピアノを始めたが、今は先生について本格の練習をしている。", "target_word": "本格", "complexity_tier": "T3", "furigana": "兄[あに]は趣味[しゅみ]でピアノを始[はじ]めたが、今[いま]は先生[せんせい]について本格[ほんかく]の練習[れんしゅう]をしている。", "sentence_source": "generated"}, {"text": "遊びのつもりだったのに、本格のゲームを作り始めたら止まらなくなった。", "target_word": "本格", "complexity_tier": "T3", "furigana": "遊[あそ]びのつもりだったのに、本格[ほんかく]のゲームを作[つく]り始[はじ]めたら止[と]まらなくなった。", "sentence_source": "generated"}, {"text": "登山は初めてだから、本格の装備をそろえる前にまず低い山を歩いてみる。", "target_word": "本格", "complexity_tier": "T4", "furigana": "登山[とざん]は初[はじ]めてだから、本格[ほんかく]の装備[そうび]をそろえる前[まえ]にまず低[ひく]い山[やま]を歩[ある]いてみる。", "sentence_source": "generated"}, {"text": "子どもの水泳教室から、大会を目指す本格のコースに移った。", "target_word": "本格", "complexity_tier": "T3", "furigana": "子[こ]どもの水泳教室[すいえいきょうしつ]から、大会[たいかい]を目指[めざ]す本格[ほんかく]のコースに移[うつ]った。", "sentence_source": "generated"}, {"text": "会社は今年から、海外での本格の販売を始める。", "target_word": "本格", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は今年[ことし]から、海外[かいがい]での本格[ほんかく]の販売[はんばい]を始[はじ]める。", "sentence_source": "generated"}, {"text": "今年の夏は本格の暑さが来るそうだ。", "target_word": "本格", "complexity_tier": "T3", "furigana": "今年[ことし]の夏[なつ]は本格[ほんかく]の暑[あつ]さが来[く]るそうだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "本格", "label": "基本形"}, {"form": "本格的", "label": "派生形"}], "register": "一般", "sense_fingerprint": "物事が遊びや仮の段階を終え、しっかり本式になっている様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bb45688-8400-4456-9927-11fbe9b516ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37059, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本格", "is_correct": true, "explanation": "本式に入った段階を表し、「本格の練習」と自然に続く。"}, {"text": "眠気", "is_correct": false, "explanation": "体の状態を表す語で、練習の対象にはならないので「眠気の練習」は成り立たない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "空の景色を表す語で、練習の対象にはならないので「夕焼けの練習」は成り立たない。"}, {"text": "落とし物", "is_correct": false, "explanation": "紛失物を指すので、練習の段階を表す語としては意味が通らない。"}], "explanations": {"本格": "本式に入った段階を表し、「本格の練習」と自然に続く。", "眠気": "体の状態を表す語で、練習の対象にはならないので「眠気の練習」は成り立たない。", "夕焼け": "空の景色を表す語で、練習の対象にはならないので「夕焼けの練習」は成り立たない。", "落とし物": "紛失物を指すので、練習の段階を表す語としては意味が通らない。"}, "sentence_index": 0, "correct_answer": "本格"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "宿題の本格を三つ残したままだ。", "explanation": "ここは〈宿題〉（課題）の意味。本格は物事の本物らしさを表す語で、宿題のように数えるものは指さない。"}, {"text": "本格が鳴ったので、急いで電話に出た。", "explanation": "ここは〈着信〉（電話の鳴動）の意味。本格は様子を表す語なので、音を立てる物は指さない。"}, {"text": "空いた皿を、本格の場所へ置いた。", "explanation": "ここは〈置き場所〉の意味。本格は様子を表す語で、場所は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37059, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本格", "is_correct": true, "explanation": "本式の装備を表し、「本格の装備」と続く。"}, {"text": "寝坊", "is_correct": false, "explanation": "寝過ごすことで、装備の種類にはならない。"}, {"text": "天井", "is_correct": false, "explanation": "部屋の上の面を指し、装備とは関係がない。"}, {"text": "締め切り", "is_correct": false, "explanation": "提出期限を指すので、装備の種類を表せない。"}], "explanations": {"本格": "本式の装備を表し、「本格の装備」と続く。", "寝坊": "寝過ごすことで、装備の種類にはならない。", "天井": "部屋の上の面を指し、装備とは関係がない。", "締め切り": "提出期限を指すので、装備の種類を表せない。"}, "sentence_index": 6, "correct_answer": "本格"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "うっかり、本格の寝言をつぶやいてしまった。", "explanation": "ここは〈寝言〉（寝ている間の言葉）の意味。本格は本式の段階を表すので、寝言の状態とは結びつかない。"}, {"text": "授業中に、本格の鼻水をかんでしまった。", "explanation": "ここは〈鼻水〉（鼻から出る液）の意味。本格は本物らしい様子を表す語なので、体の液体は指さない。"}, {"text": "空腹で、本格の腹の虫が鳴いた。", "explanation": "ここは〈腹の虫〉（空腹の音）の意味。本格は本式の段階を表すので、体から出る音には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37059, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新学期からいよいよ本格へ練習が始まる。", "corrected_sentence": "新学期からいよいよ本格の練習が始まる。", "error_description": "「本格の練習」の「の」を「へ」にした誤り。本格は練習を修飾するので「の」が必要で、「へ」は方向を表すため合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37059, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来月から本格な練習が始まった。", "corrected_sentence": "来月から本格的な練習が始まった。", "error_description": "「本格」に「的」を補い忘れた誤り。名詞の「本格」を「本格的な」の形で修飾するのが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37060, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「姿勢を改善する」で対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「姿勢に改善する」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「姿勢へ改善する」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「姿勢と改善する」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「姿勢を改善する」で対象を示す。", "に": "「姿勢に改善する」は成り立たない。", "へ": "「姿勢へ改善する」は成り立たない。", "と": "「姿勢と改善する」は成り立たない。"}, "error_tags": {"に": "target_marker", "へ": "direction", "と": "companion"}, "sentence_index": 3}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悪化", "is_correct": true, "explanation": "状態が悪くなる意味で、改善の反対。"}, {"text": "向上", "is_correct": false, "explanation": "良くなる意味で、反対ではない。"}, {"text": "改良", "is_correct": false, "explanation": "良く直す意味で、類義語。"}, {"text": "上達", "is_correct": false, "explanation": "うまくなる意味で、反対ではない。"}], "correct_answer": "悪化", "explanations": {"悪化": "状態が悪くなる意味で、改善の反対。", "向上": "良くなる意味で、反対ではない。", "改良": "良く直す意味で、類義語。", "上達": "うまくなる意味で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37060, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "より", "options": [{"text": "より", "is_correct": true, "explanation": "「前より」で比べる基準を示す。"}, {"text": "を", "is_correct": false, "explanation": "「前をずっと改善された」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「前でずっと改善された」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「前へずっと改善された」は成り立たない。"}], "correct_answer": "より", "explanations": {"より": "「前より」で比べる基準を示す。", "を": "「前をずっと改善された」は成り立たない。", "で": "「前でずっと改善された」は成り立たない。", "へ": "「前へずっと改善された」は成り立たない。"}, "error_tags": {"を": "object_marker", "で": "means", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "改悪", "is_correct": true, "explanation": "悪く変えることで、改善の反対。"}, {"text": "進歩", "is_correct": false, "explanation": "進んで良くなる意味で、反対ではない。"}, {"text": "修理", "is_correct": false, "explanation": "壊れた物を直す意味で、反対ではない。"}, {"text": "回復", "is_correct": false, "explanation": "良い状態に戻る意味で、反対ではない。"}], "correct_answer": "改悪", "explanations": {"改悪": "悪く変えることで、改善の反対。", "進歩": "進んで良くなる意味で、反対ではない。", "修理": "壊れた物を直す意味で、反対ではない。", "回復": "良い状態に戻る意味で、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37060, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "わるいところを、もっとよくする。", "primary_collocate": null, "pronunciation": "かいぜん", "ipa": "kaizeɴ", "syllable_count": 4, "sentences": [{"text": "悪い点を改善する。", "target_word": "改善", "complexity_tier": "T1", "furigana": "悪[わる]い点[てん]を改善[かいぜん]する。", "sentence_source": "generated"}, {"text": "食生活を改善しましょう。", "target_word": "改善", "complexity_tier": "T2", "furigana": "食生活[しょくせいかつ]を改善[かいぜん]しましょう。", "sentence_source": "generated"}, {"text": "成績は少し改善しました。", "target_word": "改善", "complexity_tier": "T2", "furigana": "成績[せいせき]は少[すこ]し改善[かいぜん]しました。", "sentence_source": "generated"}, {"text": "姿勢を改善するために、毎日体操をしている。", "target_word": "改善", "complexity_tier": "T3", "furigana": "姿勢[しせい]を改善[かいぜん]するために、毎日[まいにち]体操[たいそう]をしている。", "sentence_source": "generated"}, {"text": "悪いところを見つけて改善して、またやってみた。", "target_word": "改善", "complexity_tier": "T3", "furigana": "悪[わる]いところを見[み]つけて改善[かいぜん]して、またやってみた。", "sentence_source": "generated"}, {"text": "間違いを指摘されて、やり方を改善した。", "target_word": "改善", "complexity_tier": "T4", "furigana": "間違[まちが]いを指摘[してき]されて、やり方[かた]を改善[かいぜん]した。", "sentence_source": "generated"}, {"text": "改善が必要な点を、先にリストにしておこう。", "target_word": "改善", "complexity_tier": "T4", "furigana": "改善[かいぜん]が必要[ひつよう]な点[てん]を、先[さき]にリストにしておこう。", "sentence_source": "generated"}, {"text": "店の接客は、前よりずっと改善された。", "target_word": "改善", "complexity_tier": "T4", "furigana": "店[みせ]の接客[せっきゃく]は、前[まえ]よりずっと改善[かいぜん]された。", "sentence_source": "generated"}, {"text": "問題を放っておかずに、できるところから改善を始めることが大切だ。", "target_word": "改善", "complexity_tier": "T5", "furigana": "問題[もんだい]を放[ほう]っておかずに、できるところから改善[かいぜん]を始[はじ]めることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "改善の方法を、みんなで考えた。", "target_word": "改善", "complexity_tier": "T3", "furigana": "改善[かいぜん]の方法[ほうほう]を、みんなで考[かんが]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "改善する", "label": "活用"}, {"form": "改善した", "label": "活用"}, {"form": "改善される", "label": "活用"}, {"form": "改善策", "label": "派生"}, {"form": "改善点", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 悪い点をよりよくすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3446334-3278-4fc4-9bdd-c73ba1cb63db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37060, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "改善", "is_correct": true, "explanation": "「かいぜん」で、聞いた語と一致する。"}, {"text": "完全", "is_correct": false, "explanation": "「かんぜん」で、「い」が「ん」に変わる一拍違い。"}, {"text": "最善", "is_correct": false, "explanation": "「さいぜん」で、「か」が「さ」に変わる一拍違い。"}, {"text": "回線", "is_correct": false, "explanation": "「かいせん」で、「ぜ」が「せ」に変わる一拍違い。"}, {"text": "改憲", "is_correct": false, "explanation": "「かいけん」で、「ぜ」が「け」に変わる一拍違い。"}], "explanations": {"改善": "「かいぜん」で、聞いた語と一致する。", "完全": "「かんぜん」で、「い」が「ん」に変わる一拍違い。", "最善": "「さいぜん」で、「か」が「さ」に変わる一拍違い。", "回線": "「かいせん」で、「ぜ」が「せ」に変わる一拍違い。", "改憲": "「かいけん」で、「ぜ」が「け」に変わる一拍違い。"}, "sentence_index": null, "correct_answer": "改善"}, "level_3": {"options": [{"text": "改善", "is_correct": true, "explanation": "悪い点をよくする意味で合う。"}, {"text": "出発", "is_correct": false, "explanation": "形は合うが、悪い点を「出発」では意味が合わない。"}, {"text": "旅行", "is_correct": false, "explanation": "形は合うが、悪い点を「旅行」では意味が合わない。"}, {"text": "結婚", "is_correct": false, "explanation": "形は合うが、悪い点を「結婚」では意味が合わない。"}], "explanations": {"改善": "悪い点をよくする意味で合う。", "出発": "形は合うが、悪い点を「出発」では意味が合わない。", "旅行": "形は合うが、悪い点を「旅行」では意味が合わない。", "結婚": "形は合うが、悪い点を「結婚」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "改善"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ご飯を食べすぎて、体調が悪く改善した。", "explanation": "体調が悪くなる場面で使っていて、「改善」の意味が逆。"}, {"text": "新しい靴を改善してお店に行った。", "explanation": "「改善」は靴を履く意味ではなく、語の使い方が合わない。"}, {"text": "公園で友だちと改善して遊んだ。", "explanation": "「改善」は遊ぶ動作に使えず、意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37060, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "改善", "is_correct": true, "explanation": "「かいぜん」で、聞いた語と一致する。"}, {"text": "回転", "is_correct": false, "explanation": "「かいてん」で、「ぜ」が「て」に変わる一拍違い。"}, {"text": "会見", "is_correct": false, "explanation": "「かいけん」で、「ぜ」が「け」に変わる一拍違い。"}, {"text": "開演", "is_correct": false, "explanation": "「かいえん」で、「ぜ」が「え」に変わる一拍違い。"}, {"text": "会心", "is_correct": false, "explanation": "「かいしん」で、「ぜ」が「し」に変わる一拍違い。"}], "explanations": {"改善": "「かいぜん」で、聞いた語と一致する。", "回転": "「かいてん」で、「ぜ」が「て」に変わる一拍違い。", "会見": "「かいけん」で、「ぜ」が「け」に変わる一拍違い。", "開演": "「かいえん」で、「ぜ」が「え」に変わる一拍違い。", "会心": "「かいしん」で、「ぜ」が「し」に変わる一拍違い。"}, "sentence_index": null, "correct_answer": "改善"}, "level_3": {"options": [{"text": "改善", "is_correct": true, "explanation": "「改善が必要な点」で、良くする必要がある点という意味に合う。"}, {"text": "旅行", "is_correct": false, "explanation": "形は合うが、「旅行が必要な点」では意味が合わない。"}, {"text": "入学", "is_correct": false, "explanation": "形は合うが、「入学が必要な点」では意味が合わない。"}, {"text": "到着", "is_correct": false, "explanation": "形は合うが、「到着が必要な点」では意味が合わない。"}], "explanations": {"改善": "「改善が必要な点」で、良くする必要がある点という意味に合う。", "旅行": "形は合うが、「旅行が必要な点」では意味が合わない。", "入学": "形は合うが、「入学が必要な点」では意味が合わない。", "到着": "形は合うが、「到着が必要な点」では意味が合わない。"}, "sentence_index": 6, "correct_answer": "改善"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "悪い点を放っておいて、問題をもっと改善した。", "explanation": "放っておいて悪くなる場面で、「改善」の意味が逆。"}, {"text": "毎朝、犬を改善に連れて行く。", "explanation": "「改善」は散歩の場所を表さず、使い方が合わない。"}, {"text": "冷蔵庫の中に改善が入っている。", "explanation": "「改善」は物ではなく、冷蔵庫に入るものとして誤用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
