INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37061, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「微気候の改善」で名詞をつなぐ。"}, {"text": "を", "is_correct": false, "explanation": "「微気候を改善といった側面」は文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「微気候に改善といった」は不自然で成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「微気候へ改善」は方向の助詞が合わず成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「微気候の改善」で名詞をつなぐ。", "を": "「微気候を改善といった側面」は文として成り立たない。", "に": "「微気候に改善といった」は不自然で成り立たない。", "へ": "「微気候へ改善」は方向の助詞が合わず成り立たない。"}, "error_tags": {"を": "object_marker", "に": "target_marker", "へ": "direction"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悪化", "is_correct": true, "explanation": "状態が悪くなる意味で、改善の反対。"}, {"text": "向上", "is_correct": false, "explanation": "良くなる意味で、改善に近い語。反対ではない。"}, {"text": "進歩", "is_correct": false, "explanation": "進んで良くなる意味で、反対ではない。"}, {"text": "改良", "is_correct": false, "explanation": "より良く直す意味で、類義語。"}], "correct_answer": "悪化", "explanations": {"悪化": "状態が悪くなる意味で、改善の反対。", "向上": "良くなる意味で、改善に近い語。反対ではない。", "進歩": "進んで良くなる意味で、反対ではない。", "改良": "より良く直す意味で、類義語。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
