INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37061, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事をより良い状態に変えること。", "primary_collocate": null, "pronunciation": "かいぜん", "ipa": "kaizeɴ", "syllable_count": 4, "sentences": [{"text": "特に、住民の主体的な参加により創出されるガーデンは、生物多様性の回復のみならず、微気候の改善といった側面においても近隣緑地に好影響を及ぼしている。", "target_word": "改善", "complexity_tier": "T6", "furigana": "特[とく]に、住民[じゅうみん]の主体的[しゅたいてき]な参加[さんか]により創出[そうしゅつ]されるガーデンは、生物[せいぶつ]多様性[たようせい]の回復[かいふく]のみならず、微気候[びきこう]の改善[かいぜん]といった側面[そくめん]においても近隣[きんりん]緑地[りょくち]に好影響[こうえいきょう]を及[およ]ぼしている。", "sentence_source": "mined"}, {"text": "食事を改善する。", "target_word": "改善", "complexity_tier": "T1", "furigana": "食事[しょくじ]を改善[かいぜん]する。", "sentence_source": "generated"}, {"text": "生活の改善は大切です。", "target_word": "改善", "complexity_tier": "T2", "furigana": "生活[せいかつ]の改善[かいぜん]は大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "先生が授業を改善しました。", "target_word": "改善", "complexity_tier": "T2", "furigana": "先生[せんせい]が授業[じゅぎょう]を改善[かいぜん]しました。", "sentence_source": "generated"}, {"text": "駅の案内を改善してほしいという声が多い。", "target_word": "改善", "complexity_tier": "T3", "furigana": "駅[えき]の案内[あんない]を改善[かいぜん]してほしいという声[こえ]が多[おお]い。", "sentence_source": "generated"}, {"text": "この薬で、体調が改善しているようだ。", "target_word": "改善", "complexity_tier": "T3", "furigana": "この薬[くすり]で、体調[たいちょう]が改善[かいぜん]しているようだ。", "sentence_source": "generated"}, {"text": "会議では、仕事の進め方の改善について話し合った。", "target_word": "改善", "complexity_tier": "T4", "furigana": "会議[かいぎ]では、仕事[しごと]の進[すす]め方[かた]の改善[かいぜん]について話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "小さな改善を続ければ、大きな成果につながる。", "target_word": "改善", "complexity_tier": "T4", "furigana": "小[ちい]さな改善[かいぜん]を続[つづ]ければ、大[おお]きな成果[せいか]につながる。", "sentence_source": "generated"}, {"text": "待ち時間の改善が求められているため、新しい受付システムが導入された。", "target_word": "改善", "complexity_tier": "T5", "furigana": "待[ま]ち時間[じかん]の改善[かいぜん]が求[もと]められているため、新[あたら]しい受付[うけつけ]システムが導入[どうにゅう]された。", "sentence_source": "generated"}, {"text": "改善の余地はまだたくさんある。", "target_word": "改善", "complexity_tier": "T3", "furigana": "改善[かいぜん]の余地[よち]はまだたくさんある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "改善する", "label": "活用"}, {"form": "改善した", "label": "活用"}, {"form": "改善される", "label": "活用"}, {"form": "改善策", "label": "派生"}, {"form": "改善点", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事をより良い状態に変えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 好影響 (Zipf 2.16)']::text[], 'e3446334-3278-4fc4-9bdd-c73ba1cb63db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
