INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37061, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社は働き方の改善が行って、残業が減った。", "corrected_sentence": "会社は働き方の改善を行って、残業が減った。", "error_description": "「改善」は「行う」の目的語なので「を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37062, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「駅前の群集の中で」と、群集を修飾する「の」。ここで正解。"}, {"text": "が", "is_correct": false, "explanation": "「群集が中で」と主語にすると、文の構造が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「群集を中で」と目的語にすると、文の流れが合わない。"}, {"text": "に", "is_correct": false, "explanation": "「群集に中で」と位置や相手にすると、意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「駅前の群集の中で」と、群集を修飾する「の」。ここで正解。", "が": "「群集が中で」と主語にすると、文の構造が成り立たない。", "を": "「群集を中で」と目的語にすると、文の流れが合わない。", "に": "「群集に中で」と位置や相手にすると、意味が通らない。"}, "error_tags": {"が": "主格の誤り", "を": "目的格の誤り", "に": "位置・相手の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37062, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「群集は驚いて」と、群集を主題に置く「は」。ここで正解。"}, {"text": "で", "is_correct": false, "explanation": "「群集で驚いて」と手段や場所にすると、意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「群集と驚いて」と並べると、驚く主体が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「群集へ驚いて」と方向にすると、文の構造が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「群集は驚いて」と、群集を主題に置く「は」。ここで正解。", "で": "「群集で驚いて」と手段や場所にすると、意味が通らない。", "と": "「群集と驚いて」と並べると、驚く主体が合わない。", "へ": "「群集へ驚いて」と方向にすると、文の構造が成り立たない。"}, "error_tags": {"で": "手段・場所の誤り", "と": "並列・相手の誤り", "へ": "方向の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37062, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "たくさんの人が一つの場所に集まってできた、人の群れのこと。", "primary_collocate": null, "pronunciation": "ぐんしゅう", "ipa": "ɡuɴɕɯː", "syllable_count": 4, "sentences": [{"text": "広場に集まった群集は、花火が上がると一斉に歓声をあげた。", "target_word": "群集", "complexity_tier": "T3", "furigana": "広場[ひろば]に集[あつ]まった群集[ぐんしゅう]は、花火[はなび]が上[あ]がると一斉[いっせい]に歓声[かんせい]をあげた。", "sentence_source": "generated"}, {"text": "駅前の群集の中で、母は子どもの手をしっかり握っていた。", "target_word": "群集", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の群集[ぐんしゅう]の中[なか]で、母[はは]は子[こ]どもの手[て]をしっかり握[にぎ]っていた。", "sentence_source": "generated"}, {"text": "事故の知らせを聞いて、現場には大きな群集ができた。", "target_word": "群集", "complexity_tier": "T3", "furigana": "事故[じこ]の知[し]らせを聞[き]いて、現場[げんば]には大[おお]きな群集[ぐんしゅう]ができた。", "sentence_source": "generated"}, {"text": "群集がゆっくり動き出したので、警官は道を空けるように声をかけた。", "target_word": "群集", "complexity_tier": "T4", "furigana": "群集[ぐんしゅう]がゆっくり動[うご]き出[だ]したので、警官[けいかん]は道[みち]を空[あ]けるように声[こえ]をかけた。", "sentence_source": "generated"}, {"text": "選手がホテルから出てくると、待っていた群集が名前を呼び始めた。", "target_word": "群集", "complexity_tier": "T3", "furigana": "選手[せんしゅ]がホテルから出[で]てくると、待[ま]っていた群集[ぐんしゅう]が名前[なまえ]を呼[よ]び始[はじ]めた。", "sentence_source": "generated"}, {"text": "祭りの夜は、神社へ続く道が群集でいっぱいになる。", "target_word": "群集", "complexity_tier": "T3", "furigana": "祭[まつ]りの夜[よる]は、神社[じんじゃ]へ続[つづ]く道[みち]が群集[ぐんしゅう]でいっぱいになる。", "sentence_source": "generated"}, {"text": "彼は群集にまぎれて、静かに会場を出ていった。", "target_word": "群集", "complexity_tier": "T3", "furigana": "彼[かれ]は群集[ぐんしゅう]にまぎれて、静[しず]かに会場[かいじょう]を出[で]ていった。", "sentence_source": "generated"}, {"text": "大きな音が聞こえて、群集は驚いて後ろへ下がった。", "target_word": "群集", "complexity_tier": "T3", "furigana": "大[おお]きな音[おと]が聞[き]こえて、群集[ぐんしゅう]は驚[おどろ]いて後[うし]ろへ下[さ]がった。", "sentence_source": "generated"}, {"text": "新しい店の前に群集ができ、道を通れなくなった。", "target_word": "群集", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]の前[まえ]に群集[ぐんしゅう]ができ、道[みち]を通[とお]れなくなった。", "sentence_source": "generated"}, {"text": "演説を聞いていた群集の中から、拍手が起こった。", "target_word": "群集", "complexity_tier": "T3", "furigana": "演説[えんぜつ]を聞[き]いていた群集[ぐんしゅう]の中[なか]から、拍手[はくしゅ]が起[お]こった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "群集", "label": "基本形"}, {"form": "群集する", "label": "動詞形"}], "register": "一般", "sense_fingerprint": "多くの人が一か所に集まった人の群れ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bb45688-8400-4456-9927-11fbe9b516ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37062, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "群集", "is_correct": true, "explanation": "正解。集まった人の群れが主語になり、一斉に歓声をあげる文に合う。"}, {"text": "辞書", "is_correct": false, "explanation": "辞書は物で、歓声をあげることはできないので文が成り立たない。"}, {"text": "石鹸", "is_correct": false, "explanation": "石鹸は歓声をあげる主体にならず、「一斉に歓声をあげた」と合わない。"}, {"text": "地図", "is_correct": false, "explanation": "地図は物で、花火を見て歓声をあげることはないので、ここには入らない。"}], "explanations": {"群集": "正解。集まった人の群れが主語になり、一斉に歓声をあげる文に合う。", "辞書": "辞書は物で、歓声をあげることはできないので文が成り立たない。", "石鹸": "石鹸は歓声をあげる主体にならず、「一斉に歓声をあげた」と合わない。", "地図": "地図は物で、花火を見て歓声をあげることはないので、ここには入らない。"}, "sentence_index": 0, "correct_answer": "群集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その交差点には、群集がたった一人で立っていた。", "explanation": "ここは〈個人〉の意味で群集を使っている。群集は多くの人が集まった状態を指すので、単独の人を表す個人の意味には合わない。"}, {"text": "町の人は毎月第二日曜に、公民館で群集を開いて防災の話をする。", "explanation": "ここは〈集会〉の意味。群集は自然に集まった人の群れで、計画して開くものではないので合わない。"}, {"text": "会社の群集は、一人ひとりが別々の場所で仕事をしている。", "explanation": "ここは〈集団〉の意味。群集は同じ場所に集まった人の群れを指し、離れて働く人たちには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37062, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "群集", "is_correct": true, "explanation": "正解。「にまぎれる」の対象として、多くの人の群れを指す。"}, {"text": "包装紙", "is_correct": false, "explanation": "包装紙にまぎれて会場を出るという内容は成り立たない。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団にまぎれて会場を出ることはできないので、文の意味が通らない。"}, {"text": "掲示板", "is_correct": false, "explanation": "掲示板にまぎれるという文は意味が通らず、ここには入らない。"}], "explanations": {"群集": "正解。「にまぎれる」の対象として、多くの人の群れを指す。", "包装紙": "包装紙にまぎれて会場を出るという内容は成り立たない。", "座布団": "座布団にまぎれて会場を出ることはできないので、文の意味が通らない。", "掲示板": "掲示板にまぎれるという文は意味が通らず、ここには入らない。"}, "sentence_index": 6, "correct_answer": "群集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国境の守りに群集を配置した。", "explanation": "ここは〈軍隊〉の意味。群集は集まった人の群れで、配置して守りにつかせるものではない。"}, {"text": "会議室には、群集が三人だけ座っていた。", "explanation": "ここは〈少人数〉の意味。群集はたくさんの人が集まった状態を指すので、三人だけの集まりには合わない。"}, {"text": "図書館の閲覧室で、群集が一人で静かに本を読んでいた。", "explanation": "ここは〈個人〉の意味。群集は多くの人が集まった状態を指すので、一人の人を表す使い方には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37062, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会場の入り口に、群集を集まっていた。", "corrected_sentence": "会場の入り口に、群集が集まっていた。", "error_description": "「集まる」は自動詞で、集まる主体には「が」を使う。ここの「を」は目的語を表すので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37062, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祭りの夜、群集が神社へ押し出した。", "corrected_sentence": "祭りの夜、群集が神社へ押し寄せた。", "error_description": "群集が主語のとき、人が寄ってくる動きは「押し寄せる」。「押し出す」は群集が何かを外へ押しやる意味になり、文が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37063, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「高山植物の群集が見られる」と、見られる主体を示す「が」。ここで正解。"}, {"text": "の", "is_correct": false, "explanation": "「群集の見られる」と続けると、名詞の後に動詞が直接つながって文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「群集と見られる」と並べると、見られる対象が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「群集へ見られる」と方向にすると、文の構造が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「高山植物の群集が見られる」と、見られる主体を示す「が」。ここで正解。", "の": "「群集の見られる」と続けると、名詞の後に動詞が直接つながって文が成り立たない。", "と": "「群集と見られる」と並べると、見られる対象が合わない。", "へ": "「群集へ見られる」と方向にすると、文の構造が成り立たない。"}, "error_tags": {"の": "連体修飾の誤り", "と": "並列・相手の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37063, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「群集は、季節によって変わる」と、群集を主題に置く「は」。ここで正解。"}, {"text": "で", "is_correct": false, "explanation": "「群集で季節によって変わる」と手段や場所にすると、意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「群集の季節によって変わる」と修飾にすると、動詞の主語が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「群集を季節によって変わる」と目的語にすると、自動詞「変わる」と合わない。"}], "correct_answer": "は", "explanations": {"は": "「群集は、季節によって変わる」と、群集を主題に置く「は」。ここで正解。", "で": "「群集で季節によって変わる」と手段や場所にすると、意味が通らない。", "の": "「群集の季節によって変わる」と修飾にすると、動詞の主語が成り立たない。", "を": "「群集を季節によって変わる」と目的語にすると、自動詞「変わる」と合わない。"}, "error_tags": {"で": "手段・場所の誤り", "の": "連体修飾の誤り", "を": "目的格の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37063, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "同じ種類のものが集まってできた集まり。", "primary_collocate": null, "pronunciation": "ぐんしゅう", "ipa": "ɡuɴɕɯː", "syllable_count": 4, "sentences": [{"text": "湖の底には、小さな貝の群集が広がっている。", "target_word": "群集", "complexity_tier": "T3", "furigana": "湖[みずうみ]の底[そこ]には、小[ちい]さな貝[かい]の群集[ぐんしゅう]が広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "山の斜面には、高山植物の群集が見られる。", "target_word": "群集", "complexity_tier": "T3", "furigana": "山[やま]の斜面[しゃめん]には、高山植物[こうざんしょくぶつ]の群集[ぐんしゅう]が見[み]られる。", "sentence_source": "generated"}, {"text": "海の岩場に、フジツボの群集ができていた。", "target_word": "群集", "complexity_tier": "T3", "furigana": "海[うみ]の岩場[いわば]に、フジツボの群集[ぐんしゅう]ができていた。", "sentence_source": "generated"}, {"text": "研究者は川の魚の群集を調べて、水のきれいさを確かめた。", "target_word": "群集", "complexity_tier": "T4", "furigana": "研究者[けんきゅうしゃ]は川[かわ]の魚[さかな]の群集[ぐんしゅう]を調[しら]べて、水[みず]のきれいさを確[たし]かめた。", "sentence_source": "generated"}, {"text": "森が切られたため、そこにいた昆虫の群集が小さくなった。", "target_word": "群集", "complexity_tier": "T4", "furigana": "森[もり]が切[き]られたため、そこにいた昆虫[こんちゅう]の群集[ぐんしゅう]が小[ちい]さくなった。", "sentence_source": "generated"}, {"text": "サンゴ礁には、色とりどりの魚の群集がすんでいる。", "target_word": "群集", "complexity_tier": "T3", "furigana": "サンゴ礁[しょう]には、色[いろ]とりどりの魚[さかな]の群集[ぐんしゅう]がすんでいる。", "sentence_source": "generated"}, {"text": "池の水草の群集を守るために、釣りが禁止された。", "target_word": "群集", "complexity_tier": "T3", "furigana": "池[いけ]の水草[みずくさ]の群集[ぐんしゅう]を守[まも]るために、釣[つ]りが禁止[きんし]された。", "sentence_source": "generated"}, {"text": "土の中の微生物の群集は、季節によって変わる。", "target_word": "群集", "complexity_tier": "T4", "furigana": "土[つち]の中[なか]の微生物[びせいぶつ]の群集[ぐんしゅう]は、季節[きせつ]によって変[か]わる。", "sentence_source": "generated"}, {"text": "火山の島では、最初にコケの群集が育つ。", "target_word": "群集", "complexity_tier": "T3", "furigana": "火山[かざん]の島[しま]では、最初[さいしょ]にコケの群集[ぐんしゅう]が育[そだ]つ。", "sentence_source": "generated"}, {"text": "調査の結果、この干潟には貝の群集が三種類あるとわかった。", "target_word": "群集", "complexity_tier": "T4", "furigana": "調査[ちょうさ]の結果[けっか]、この干潟[ひがた]には貝[かい]の群集[ぐんしゅう]が三種類[さんしゅるい]あるとわかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "群集", "label": "基本形"}, {"form": "群集する", "label": "動詞形"}], "register": "一般", "sense_fingerprint": "同じ種類の生物や物が集まってできた集団", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bb45688-8400-4456-9927-11fbe9b516ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37063, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "群集", "is_correct": true, "explanation": "正解。同じ種類の貝が集まってできた集まりを指し、広がるという文に合う。"}, {"text": "時計", "is_correct": false, "explanation": "時計は広がるものではなく、貝の集まりを表せないので文が成り立たない。"}, {"text": "玄関", "is_correct": false, "explanation": "玄関は場所で、貝の集まりとしては意味が通らない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は貝の集まりを表さず、広がっているという文に合わない。"}], "explanations": {"群集": "正解。同じ種類の貝が集まってできた集まりを指し、広がるという文に合う。", "時計": "時計は広がるものではなく、貝の集まりを表せないので文が成り立たない。", "玄関": "玄関は場所で、貝の集まりとしては意味が通らない。", "教科書": "教科書は貝の集まりを表さず、広がっているという文に合わない。"}, "sentence_index": 0, "correct_answer": "群集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "池のそばに、コイの群集が一匹だけ残っていた。", "explanation": "ここは〈個体〉の意味で群集を使っている。群集は同じ種類の生き物が集まった状態を指すので、一匹だけの個体には合わない。"}, {"text": "この棚には、本と皿の群集が並んでいた。", "explanation": "ここは〈混在〉の意味。群集は同じ種類のものが集まった集まりを指すので、本と皿が混ざった並びには合わない。"}, {"text": "この池には、コイとフナの群集が三百匹ほどいる。", "explanation": "ここは〈混在〉の意味。群集は同じ種類のものが集まった集まりを指すので、コイとフナが混ざった集まりには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37063, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "群集", "is_correct": true, "explanation": "正解。池の水草の集まりを指し、守るという文の目的語に合う。"}, {"text": "石垣", "is_correct": false, "explanation": "石垣は水草の集まりではなく、守るという文の目的語として合わない。"}, {"text": "郵便局", "is_correct": false, "explanation": "郵便局は水草の集まりを表さず、守るという文が成り立たない。"}, {"text": "駅", "is_correct": false, "explanation": "駅は水草の集まりではなく、「池の水草の駅を守る」は意味が通らない。"}], "explanations": {"群集": "正解。池の水草の集まりを指し、守るという文の目的語に合う。", "石垣": "石垣は水草の集まりではなく、守るという文の目的語として合わない。", "郵便局": "郵便局は水草の集まりを表さず、守るという文が成り立たない。", "駅": "駅は水草の集まりではなく、「池の水草の駅を守る」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "群集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この島には、猫と犬の群集が三つ残っている。", "explanation": "ここは〈混在〉の意味。群集は同じ種類のものが集まった集まりを指すので、異なる種類が混ざった集まりには合わない。"}, {"text": "湖には、白鳥が一羽だけ浮かんでいた。", "explanation": "ここは〈個体〉の意味。群集は同じ種類のものが集まった集まりを指すので、一羽だけの個体には合わない。"}, {"text": "この会社には、機械と社員の群集が三つある。", "explanation": "ここは〈混在〉の意味。群集は同じ種類のものが集まった集まりを指すので、機械と人が混ざった集まりには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37063, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湿地の岸には、水草の群集を広がっている。", "corrected_sentence": "湿地の岸には、水草の群集が広がっている。", "error_description": "「広がる」は自動詞なので、主語には「が」を使う。ここの「を」は目的語を表すので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37063, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "森の中で、昆虫の群集が季節ごとに入れ替える。", "corrected_sentence": "森の中で、昆虫の群集が季節ごとに入れ替わる。", "error_description": "「入れ替わる」は自動詞で、群集そのものが変わる意味になる。「入れ替える」は他のものを入れ替える他動詞なので、群集を主語にすると文が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37064, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "単一", "is_correct": true, "explanation": "一種類だけという意味で、多様の反対。"}, {"text": "多彩", "is_correct": false, "explanation": "種類が多いという意味で、類義語。"}, {"text": "豊富", "is_correct": false, "explanation": "たくさんあるという意味で、反対ではない。"}, {"text": "特別", "is_correct": false, "explanation": "普通と違うという意味で、反対ではない。"}], "correct_answer": "単一", "explanations": {"単一": "一種類だけという意味で、多様の反対。", "多彩": "種類が多いという意味で、類義語。", "豊富": "たくさんあるという意味で、反対ではない。", "特別": "普通と違うという意味で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37064, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "画一", "is_correct": true, "explanation": "すべて同じ形という意味で、多様の反対。"}, {"text": "様々", "is_correct": false, "explanation": "いろいろという意味で、類義語。"}, {"text": "莫大", "is_correct": false, "explanation": "量が非常に多いという意味で、反対ではない。"}, {"text": "重大", "is_correct": false, "explanation": "大切で重いという意味で、反対ではない。"}], "correct_answer": "画一", "explanations": {"画一": "すべて同じ形という意味で、多様の反対。", "様々": "いろいろという意味で、類義語。", "莫大": "量が非常に多いという意味で、反対ではない。", "重大": "大切で重いという意味で、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37064, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "いろいろな種類があること。", "primary_collocate": null, "pronunciation": "たよう", "ipa": "tajoː", "syllable_count": 3, "sentences": [{"text": "多様な本がある。", "target_word": "多様", "complexity_tier": "T1", "furigana": "多様[たよう]な本[ほん]がある。", "sentence_source": "generated"}, {"text": "この店の商品は多様です。", "target_word": "多様", "complexity_tier": "T2", "furigana": "この店[みせ]の商品[しょうひん]は多様[たよう]です。", "sentence_source": "generated"}, {"text": "多様な食べ物を食べました。", "target_word": "多様", "complexity_tier": "T2", "furigana": "多様[たよう]な食[た]べ物[もの]を食[た]べました。", "sentence_source": "generated"}, {"text": "公園には多様な花が咲いている。", "target_word": "多様", "complexity_tier": "T3", "furigana": "公園[こうえん]には多様[たよう]な花[はな]が咲[さ]いている。", "sentence_source": "generated"}, {"text": "多様な考えが出て、話し合いが長くなった。", "target_word": "多様", "complexity_tier": "T3", "furigana": "多様[たよう]な考[かんが]えが出[で]て、話[はな]し合[あ]いが長[なが]くなった。", "sentence_source": "generated"}, {"text": "趣味は人によってとても多様だ。", "target_word": "多様", "complexity_tier": "T3", "furigana": "趣味[しゅみ]は人[ひと]によってとても多様[たよう]だ。", "sentence_source": "generated"}, {"text": "仕事の種類が多様になってきた。", "target_word": "多様", "complexity_tier": "T3", "furigana": "仕事[しごと]の種類[しゅるい]が多様[たよう]になってきた。", "sentence_source": "generated"}, {"text": "多様に見える問題も、原因は同じかもしれない。", "target_word": "多様", "complexity_tier": "T4", "furigana": "多様[たよう]に見[み]える問題[もんだい]も、原因[げんいん]は同[おな]じかもしれない。", "sentence_source": "generated"}, {"text": "学ぶ方法は多様であるべきだと思う。", "target_word": "多様", "complexity_tier": "T4", "furigana": "学[まな]ぶ方法[ほうほう]は多様[たよう]であるべきだと思[おも]う。", "sentence_source": "generated"}, {"text": "多様な色の傘が、店先に並んでいる。", "target_word": "多様", "complexity_tier": "T3", "furigana": "多様[たよう]な色[いろ]の傘[かさ]が、店先[みせさき]に並[なら]んでいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "多様な", "label": "活用"}, {"form": "多様に", "label": "活用"}, {"form": "多様だ", "label": "活用"}, {"form": "多様性", "label": "派生"}, {"form": "多様化", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | いろいろな種類があるさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3446334-3278-4fc4-9bdd-c73ba1cb63db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37064, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "多様", "is_correct": true, "explanation": "「たよう」で、聞こえた語と一致する。"}, {"text": "異様", "is_correct": false, "explanation": "「いよう」で、最初の音が違う。"}, {"text": "費用", "is_correct": false, "explanation": "「ひよう」で、最初の音が違う。"}, {"text": "作用", "is_correct": false, "explanation": "「さよう」で、最初の音が違う。"}], "explanations": {"多様": "「たよう」で、聞こえた語と一致する。", "異様": "「いよう」で、最初の音が違う。", "費用": "「ひよう」で、最初の音が違う。", "作用": "「さよう」で、最初の音が違う。"}, "sentence_index": null, "correct_answer": "多様"}, "level_3": {"options": [{"text": "多様", "is_correct": true, "explanation": "いろいろな種類の本があるという意味に合う。"}, {"text": "元気", "is_correct": false, "explanation": "形は合うが、本が元気という意味が合わない。"}, {"text": "暇", "is_correct": false, "explanation": "形は合うが、「暇な本」では意味が合わない。"}, {"text": "熱心", "is_correct": false, "explanation": "形は合うが、本が熱心という意味が合わない。"}], "explanations": {"多様": "いろいろな種類の本があるという意味に合う。", "元気": "形は合うが、本が元気という意味が合わない。", "暇": "形は合うが、「暇な本」では意味が合わない。", "熱心": "形は合うが、本が熱心という意味が合わない。"}, "sentence_index": 0, "correct_answer": "多様"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公園のベンチに多様な猫が一匹だけ座っていた。", "explanation": "多様は種類が多いことなので、一匹だけの猫には使えない。"}, {"text": "今日の公園は多様に寒くて、誰もいなかった。", "explanation": "多様は寒さの程度を表さない。"}, {"text": "この公園の花は多様で、みんな同じ赤い色をしている。", "explanation": "全部同じ色なら多様ではなく、意味が矛盾している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
