INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37065, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "さまざまな種類や性質のものが含まれること。", "primary_collocate": null, "pronunciation": "たよう", "ipa": "tajoː", "syllable_count": 3, "sentences": [{"text": "特に、住民の主体的な参加により創出されるガーデンは、生物多様性の回復のみならず、微気候の改善といった側面においても近隣緑地に好影響を及ぼしている。", "target_word": "多様", "complexity_tier": "T6", "furigana": "特[とく]に、住民[じゅうみん]の主体的[しゅたいてき]な参加[さんか]により創出[そうしゅつ]されるガーデンは、生物[せいぶつ]多様性[たようせい]の回復[かいふく]のみならず、微気候[びきこう]の改善[かいぜん]といった側面[そくめん]においても近隣[きんりん]緑地[りょくち]に好影響[こうえいきょう]を及[およ]ぼしている。", "sentence_source": "mined"}, {"text": "この町には多様な店があります。", "target_word": "多様", "complexity_tier": "T2", "furigana": "この町[まち]には多様[たよう]な店[みせ]があります。", "sentence_source": "generated"}, {"text": "人の考えは多様です。", "target_word": "多様", "complexity_tier": "T2", "furigana": "人[ひと]の考[かんが]えは多様[たよう]です。", "sentence_source": "generated"}, {"text": "多様な意見を聞くことが大切だ。", "target_word": "多様", "complexity_tier": "T3", "furigana": "多様[たよう]な意見[いけん]を聞[き]くことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "世界には、多様な文化が存在している。", "target_word": "多様", "complexity_tier": "T3", "furigana": "世界[せかい]には、多様[たよう]な文化[ぶんか]が存在[そんざい]している。", "sentence_source": "generated"}, {"text": "好みは人によって多様だ。", "target_word": "多様", "complexity_tier": "T3", "furigana": "好[この]みは人[ひと]によって多様[たよう]だ。", "sentence_source": "generated"}, {"text": "働き方が多様になるにつれて、暮らしも変わってきた。", "target_word": "多様", "complexity_tier": "T4", "furigana": "働[はたら]き方[かた]が多様[たよう]になるにつれて、暮[く]らしも変[か]わってきた。", "sentence_source": "generated"}, {"text": "多様な人が集まるほど、新しい発想が生まれやすい。", "target_word": "多様", "complexity_tier": "T4", "furigana": "多様[たよう]な人[ひと]が集[あつ]まるほど、新[あたら]しい発想[はっそう]が生[う]まれやすい。", "sentence_source": "generated"}, {"text": "多様に変化する社会の中で、柔軟に考える力が求められている。", "target_word": "多様", "complexity_tier": "T5", "furigana": "多様[たよう]に変化[へんか]する社会[しゃかい]の中[なか]で、柔軟[じゅうなん]に考[かんが]える力[ちから]が求[もと]められている。", "sentence_source": "generated"}, {"text": "多様な食べ物が並ぶ市場を歩いた。", "target_word": "多様", "complexity_tier": "T3", "furigana": "多様[たよう]な食[た]べ物[もの]が並[なら]ぶ市場[いちば]を歩[ある]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "多様な", "label": "活用"}, {"form": "多様に", "label": "活用"}, {"form": "多様だ", "label": "活用"}, {"form": "多様性", "label": "派生"}, {"form": "多様化", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | さまざまな種類が含まれるさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 好影響 (Zipf 2.16)']::text[], 'e3446334-3278-4fc4-9bdd-c73ba1cb63db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37065, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "多様", "is_correct": true, "explanation": "「たよう」で、聞こえた語と一致する。"}, {"text": "異様", "is_correct": false, "explanation": "「いよう」で、最初の音が違う。"}, {"text": "費用", "is_correct": false, "explanation": "「ひよう」で、最初の音が違う。"}, {"text": "作用", "is_correct": false, "explanation": "「さよう」で、最初の音が違う。"}, {"text": "迷う", "is_correct": false, "explanation": "「まよう」で、最初の音が違う。"}], "explanations": {"多様": "「たよう」で、聞こえた語と一致する。", "異様": "「いよう」で、最初の音が違う。", "費用": "「ひよう」で、最初の音が違う。", "作用": "「さよう」で、最初の音が違う。", "迷う": "「まよう」で、最初の音が違う。"}, "sentence_index": null, "correct_answer": "多様"}, "level_3": {"options": [{"text": "多様", "is_correct": true, "explanation": "生物多様性という語になり、文の意味に合う。"}, {"text": "単一", "is_correct": false, "explanation": "形は合うが、「回復」と意味が合わない。"}, {"text": "特殊", "is_correct": false, "explanation": "形は合うが、生物の性質の回復という意味が合わない。"}, {"text": "画一", "is_correct": false, "explanation": "形は合うが、意味が合わない。"}], "explanations": {"多様": "生物多様性という語になり、文の意味に合う。", "単一": "形は合うが、「回復」と意味が合わない。", "特殊": "形は合うが、生物の性質の回復という意味が合わない。", "画一": "形は合うが、意味が合わない。"}, "sentence_index": 0, "correct_answer": "多様"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "財布の中には多様な千円札が一枚だけ入っていた。", "explanation": "多様は種類が多いことなので、一枚だけの千円札には使えない。"}, {"text": "今年の夏は多様に暑くて、毎日汗をかいた。", "explanation": "多様は程度が強いという意味ではなく、種類が多いという意味。"}, {"text": "全員が同じ意見だったので、多様な会議になった。", "explanation": "同じ意見ばかりなら多様ではなく、意味が矛盾している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37065, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "多様", "is_correct": true, "explanation": "「たよう」で、聞こえた語と一致する。"}, {"text": "多忙", "is_correct": false, "explanation": "「たぼう」で、真ん中の音が違う。"}, {"text": "他方", "is_correct": false, "explanation": "「たほう」で、真ん中の音が違う。"}, {"text": "通う", "is_correct": false, "explanation": "「かよう」で、最初の音が違う。"}, {"text": "無用", "is_correct": false, "explanation": "「むよう」で、最初の音が違う。"}], "explanations": {"多様": "「たよう」で、聞こえた語と一致する。", "多忙": "「たぼう」で、真ん中の音が違う。", "他方": "「たほう」で、真ん中の音が違う。", "通う": "「かよう」で、最初の音が違う。", "無用": "「むよう」で、最初の音が違う。"}, "sentence_index": null, "correct_answer": "多様"}, "level_3": {"options": [{"text": "多様", "is_correct": true, "explanation": "働き方の種類が増えるという意味に合う。"}, {"text": "静か", "is_correct": false, "explanation": "形は合うが、働き方が静かになるという意味が合わない。"}, {"text": "清潔", "is_correct": false, "explanation": "形は合うが、働き方が清潔になるという意味が合わない。"}, {"text": "頑丈", "is_correct": false, "explanation": "形は合うが、働き方が頑丈になるという意味が合わない。"}], "explanations": {"多様": "働き方の種類が増えるという意味に合う。", "静か": "形は合うが、働き方が静かになるという意味が合わない。", "清潔": "形は合うが、働き方が清潔になるという意味が合わない。", "頑丈": "形は合うが、働き方が頑丈になるという意味が合わない。"}, "sentence_index": 6, "correct_answer": "多様"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この市場は多様に大きくて、端まで歩くのに一時間かかる。", "explanation": "多様は大きさを表さず、種類が多いことを表す。"}, {"text": "同じ果物ばかり売っている店は、とても多様だ。", "explanation": "同じ物ばかりの店は多様ではなく、意味が矛盾している。"}, {"text": "多様な値段で売っているので、どの店も千円ちょうどだった。", "explanation": "値段が全部同じなら多様ではなく、意味が矛盾している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37065, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このクラスには多様に国から来た学生がいる。", "corrected_sentence": "このクラスには多様な国から来た学生がいる。", "error_description": "名詞「国」を修飾するので、「多様に」ではなく「多様な」にする。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "多様", "is_correct": true, "explanation": "「多様+な店」となり、文に合う。"}, {"text": "多様性", "is_correct": false, "explanation": "「多様性な店」は言えない。"}, {"text": "多様化", "is_correct": false, "explanation": "「多様化な店」は言えない。"}, {"text": "多様に", "is_correct": false, "explanation": "「多様にな店」は言えない。"}], "correct_form": "多様", "base_form": "多様", "form_label": "語幹（+な）", "sentence_index": 1, "explanations": {"多様": "「多様+な店」となり、文に合う。", "多様性": "「多様性な店」は言えない。", "多様化": "「多様化な店」は言えない。", "多様に": "「多様にな店」は言えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37065, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この図書館には多様の本がそろっている。", "corrected_sentence": "この図書館には多様な本がそろっている。", "error_description": "名詞を修飾するときは「多様の」ではなく「多様な」を使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "多様", "is_correct": true, "explanation": "「多様+な人」となり、文に合う。"}, {"text": "多様化", "is_correct": false, "explanation": "「多様化な人」は言えない。"}, {"text": "多様さ", "is_correct": false, "explanation": "「多様さな人」は言えない。"}, {"text": "多様だ", "is_correct": false, "explanation": "「多様だな人」は言えない。"}], "correct_form": "多様", "base_form": "多様", "form_label": "語幹（+な）", "sentence_index": 7, "explanations": {"多様": "「多様+な人」となり、文に合う。", "多様化": "「多様化な人」は言えない。", "多様さ": "「多様さな人」は言えない。", "多様だ": "「多様だな人」は言えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37066, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「地球は青くて丸い」と、地球を主題に置く「は」。ここで正解。"}, {"text": "を", "is_correct": false, "explanation": "「地球を青くて丸い」と目的語にすると、文の構造が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「地球で青くて丸い」と場所や手段にすると、意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「地球に青くて丸い」と位置や相手にすると、文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「地球は青くて丸い」と、地球を主題に置く「は」。ここで正解。", "を": "「地球を青くて丸い」と目的語にすると、文の構造が成り立たない。", "で": "「地球で青くて丸い」と場所や手段にすると、意味が通らない。", "に": "「地球に青くて丸い」と位置や相手にすると、文が成り立たない。"}, "error_tags": {"を": "目的格の誤り", "で": "場所・手段の誤り", "に": "位置・相手の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
