INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37066, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "わたしたちが住んでいる、とても大きな丸い星のこと。", "primary_collocate": null, "pronunciation": "ちきゅう", "ipa": "tɕikʲɯː", "syllable_count": 3, "sentences": [{"text": "地球は太陽のまわりを一年かけて回っている。", "target_word": "地球", "complexity_tier": "T2", "furigana": "地球[ちきゅう]は太陽[たいよう]のまわりを一年[いちねん]かけて回[まわ]っている。", "sentence_source": "generated"}, {"text": "宇宙から見ると、地球は青くて丸い。", "target_word": "地球", "complexity_tier": "T2", "furigana": "宇宙[うちゅう]から見[み]ると、地球[ちきゅう]は青[あお]くて丸[まる]い。", "sentence_source": "generated"}, {"text": "地球の七割は海でおおわれている。", "target_word": "地球", "complexity_tier": "T3", "furigana": "地球[ちきゅう]の七割[ななわり]は海[うみ]でおおわれている。", "sentence_source": "generated"}, {"text": "動物も植物も、地球で生きている仲間だ。", "target_word": "地球", "complexity_tier": "T3", "furigana": "動物[どうぶつ]も植物[しょくぶつ]も、地球[ちきゅう]で生[い]きている仲間[なかま]だ。", "sentence_source": "generated"}, {"text": "地球が暖かくなると、氷がとけて海の水が増える。", "target_word": "地球", "complexity_tier": "T3", "furigana": "地球[ちきゅう]が暖[あたた]かくなると、氷[こおり]がとけて海[うみ]の水[みず]が増[ふ]える。", "sentence_source": "generated"}, {"text": "飛行機で地球を一周するには、何日もかかる。", "target_word": "地球", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]で地球[ちきゅう]を一周[いっしゅう]するには、何日[なんにち]もかかる。", "sentence_source": "generated"}, {"text": "月は地球のまわりを回る、いちばん近い天体だ。", "target_word": "地球", "complexity_tier": "T3", "furigana": "月[つき]は地球[ちきゅう]のまわりを回[まわ]る、いちばん近[ちか]い天体[てんたい]だ。", "sentence_source": "generated"}, {"text": "地球の未来のために、毎日ごみを分けて捨てている。", "target_word": "地球", "complexity_tier": "T3", "furigana": "地球[ちきゅう]の未来[みらい]のために、毎日[まいにち]ごみを分[わ]けて捨[す]てている。", "sentence_source": "generated"}, {"text": "宇宙飛行士は、地球に帰る日をずっと待っていた。", "target_word": "地球", "complexity_tier": "T3", "furigana": "宇宙飛行士[うちゅうひこうし]は、地球[ちきゅう]に帰[かえ]る日[ひ]をずっと待[ま]っていた。", "sentence_source": "generated"}, {"text": "地球に生きる人は八十億人をこえた。", "target_word": "地球", "complexity_tier": "T3", "furigana": "地球[ちきゅう]に生[い]きる人[ひと]は八十億人[はちじゅうおくにん]をこえた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "地球", "label": "基本形"}], "register": "一般", "sense_fingerprint": "人間が住む、太陽のまわりを回る惑星", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bb45688-8400-4456-9927-11fbe9b516ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37066, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地球", "is_correct": true, "explanation": "正解。太陽のまわりを回る惑星を指し、一年かけて回るという文に合う。"}, {"text": "太陽", "is_correct": false, "explanation": "太陽が太陽のまわりを回るという文は成り立たず、ここには入らない。"}, {"text": "電車", "is_correct": false, "explanation": "電車は太陽のまわりを回らないので、文の意味が通らない。"}, {"text": "銀行", "is_correct": false, "explanation": "銀行は太陽のまわりを回ることはなく、文が成り立たない。"}], "explanations": {"地球": "正解。太陽のまわりを回る惑星を指し、一年かけて回るという文に合う。", "太陽": "太陽が太陽のまわりを回るという文は成り立たず、ここには入らない。", "電車": "電車は太陽のまわりを回らないので、文の意味が通らない。", "銀行": "銀行は太陽のまわりを回ることはなく、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "地球"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子どもたちは公園の地球で、砂遊びに夢中になっていた。", "explanation": "ここは〈地面〉の意味。地球は惑星の名前なので、公園の地面を指す場所には使わない。"}, {"text": "教室の地球を回すと、海の色が変わる。", "explanation": "ここは〈地球儀〉の意味。地球は惑星そのものを指すので、教室にある模型を指す使い方には合わない。"}, {"text": "雨が地球を流れて、川になった。", "explanation": "ここは〈地表〉の意味。地球は惑星全体を指すので、表面を流れる雨の話には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37066, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地球", "is_correct": true, "explanation": "正解。月が回る相手として、太陽系の惑星を指す。"}, {"text": "台所", "is_correct": false, "explanation": "台所は月が回る対象にならず、「台所のまわりを回る」は意味が通らない。"}, {"text": "教室", "is_correct": false, "explanation": "教室は月が回る対象にならず、文として成り立たない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は月が回る対象にならず、天体の文脈に合わない。"}], "explanations": {"地球": "正解。月が回る相手として、太陽系の惑星を指す。", "台所": "台所は月が回る対象にならず、「台所のまわりを回る」は意味が通らない。", "教室": "教室は月が回る対象にならず、文として成り立たない。", "鉛筆": "鉛筆は月が回る対象にならず、天体の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "地球"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電車は地球から地上へ出てくる。", "explanation": "ここは〈地下〉の意味。地球は惑星の名前で、地上と対比する場所を指す使い方には合わない。"}, {"text": "その地球という町は、山の向こうにある。", "explanation": "ここは〈地名〉の意味。地球は惑星を指す語なので、町の名前としては使わない。"}, {"text": "この地球には、古い寺が多く残っている。", "explanation": "ここは〈地域〉の意味。地球は惑星全体を指すので、ある一地方を指す「この」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37066, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "宇宙飛行士が窓から見る地球を、とても美しい。", "corrected_sentence": "宇宙飛行士が窓から見る地球は、とても美しい。", "error_description": "主題を示すには「は」を使う。ここの「を」は目的語を表すので、「美しい」とつながらず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37066, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地球は、ゆっくりと自転させている。", "corrected_sentence": "地球は、ゆっくりと自転している。", "error_description": "「自転する」は地球自身が回る動きを表す。「自転させる」は他のものを回させる意味になり、地球を主語にすると文が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37068, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ある」の主語になる責任を示す。"}, {"text": "を", "is_correct": false, "explanation": "「ある」は目的語を取らないので、「責任をある」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、「責任から、ある」は主語として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、「責任と、ある」は主語として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「ある」の主語になる責任を示す。", "を": "「ある」は目的語を取らないので、「責任をある」は成り立たない。", "から": "「から」は起点を表すので、「責任から、ある」は主語として成り立たない。", "と": "「と」は並列や相手を示すので、「責任と、ある」は主語として成り立たない。"}, "error_tags": {"を": "目的語", "から": "起点", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37068, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ある」の主語になる責任を示す。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すので、「責任より、ある」は比べる意味になり文に合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、「責任から、ある」は主語として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「責任へ、ある」は主語を示せず不自然。"}], "correct_answer": "が", "explanations": {"が": "「ある」の主語になる責任を示す。", "より": "「より」は比較を表すので、「責任より、ある」は比べる意味になり文に合わない。", "から": "「から」は起点を表すので、「責任から、ある」は主語として成り立たない。", "へ": "「へ」は方向を表すので、「責任へ、ある」は主語を示せず不自然。"}, "error_tags": {"より": "比較", "から": "起点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37068, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分がしなければならないこと。", "primary_collocate": null, "pronunciation": "せきにん", "ipa": "sekiniɴ", "syllable_count": 4, "sentences": [{"text": "自分の仕事を最後までやるのは、私の責任だ。", "target_word": "責任", "complexity_tier": "T3", "furigana": "自分[じぶん]の仕事[しごと]を最後[さいご]までやるのは、私[わたし]の責任[せきにん]だ。", "sentence_source": "generated"}, {"text": "親には、子どもを守る責任がある。", "target_word": "責任", "complexity_tier": "T3", "furigana": "親[おや]には、子[こ]どもを守[まも]る責任[せきにん]がある。", "sentence_source": "generated"}, {"text": "約束を守るのは、大人としての責任だと思う。", "target_word": "責任", "complexity_tier": "T3", "furigana": "約束[やくそく]を守[まも]るのは、大人[おとな]としての責任[せきにん]だと思[おも]う。", "sentence_source": "generated"}, {"text": "リーダーは、チームの結果に責任を持つべきだ。", "target_word": "責任", "complexity_tier": "T3", "furigana": "リーダーは、チームの結果[けっか]に責任[せきにん]を持[も]つべきだ。", "sentence_source": "generated"}, {"text": "夜、家の戸締まりを確かめるのは、最後に寝る人の責任だ。", "target_word": "責任", "complexity_tier": "T3", "furigana": "夜、家の戸締[とじ]まりを確[たし]かめるのは、最後[さいご]に寝[ね]る人[ひと]の責任[せきにん]だ。", "sentence_source": "generated"}, {"text": "教室のそうじを毎日するのは、係の子どもたちの責任だ。", "target_word": "責任", "complexity_tier": "T3", "furigana": "教室[きょうしつ]のそうじを毎日[まいにち]するのは、係[かかり]の子[こ]どもたちの責任[せきにん]だ。", "sentence_source": "generated"}, {"text": "彼は仕事に責任を持って取り組んでいる。", "target_word": "責任", "complexity_tier": "T3", "furigana": "彼[かれ]は仕事[しごと]に責任[せきにん]を持[も]って取[と]り組[く]んでいる。", "sentence_source": "generated"}, {"text": "ペットを飼うなら、最後まで世話をする責任がある。", "target_word": "責任", "complexity_tier": "T3", "furigana": "ペットを飼[か]うなら、最後[さいご]まで世話[せわ]をする責任[せきにん]がある。", "sentence_source": "generated"}, {"text": "自分で決めたことには、責任が伴う。", "target_word": "責任", "complexity_tier": "T3", "furigana": "自分[じぶん]で決[き]めたことには、責任[せきにん]が伴[ともな]う。", "sentence_source": "generated"}, {"text": "運転する人には、安全に走る責任がある。", "target_word": "責任", "complexity_tier": "T3", "furigana": "運転[うんてん]する人[ひと]には、安全[あんぜん]に走[はし]る責任[せきにん]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "責任", "label": "基本形"}, {"form": "責任が", "label": "が格"}, {"form": "責任を", "label": "を格"}], "register": "中立", "sense_fingerprint": "自分がやり遂げるべきこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: contains vocabulary far above tier T1: 戸締まり (Zipf 2.22)']::text[], 'e6ccf0ee-587d-4100-bacc-1b9c2c21e01c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37068, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "責任", "is_correct": true, "explanation": "自分がやり遂げるべき務めを表し、「私の〜だ」に入って文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「私の天気だ」は意味が通らず、仕事をやり遂げる文には合わない。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便は仕事をやり遂げる対象ではないので、「私の郵便だ」は文に合わない。"}, {"text": "電車", "is_correct": false, "explanation": "電車は務めの対象にならないので、「私の電車だ」は文の意味が通らない。"}], "explanations": {"責任": "自分がやり遂げるべき務めを表し、「私の〜だ」に入って文に合う。", "天気": "「私の天気だ」は意味が通らず、仕事をやり遂げる文には合わない。", "郵便": "郵便は仕事をやり遂げる対象ではないので、「私の郵便だ」は文に合わない。", "電車": "電車は務めの対象にならないので、「私の電車だ」は文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "責任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は朝食に責任を焼いて食べた。", "explanation": "責任は焼いて食べるものではないので合わない。"}, {"text": "彼は真夏の空に責任を描いた。", "explanation": "責任は描くものではないので合わない。"}, {"text": "彼は責任を犯して、刑務所に入った。", "explanation": "ここは〈罪〉の意味。犯すのは罪で、責任は犯すものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37068, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "責任", "is_correct": true, "explanation": "自分がやり遂げる務めを表し、「仕事に〜を持って取り組む」の位置に入って文に合う。"}, {"text": "切符", "is_correct": false, "explanation": "切符は仕事に持って取り組むものではないので、文の意味が通らない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は仕事に持って取り組むものではないので、「冷蔵庫を持って」は文に合わない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶は仕事に持って取り組む対象ではないので、文の意味が通らない。"}], "explanations": {"責任": "自分がやり遂げる務めを表し、「仕事に〜を持って取り組む」の位置に入って文に合う。", "切符": "切符は仕事に持って取り組むものではないので、文の意味が通らない。", "冷蔵庫": "冷蔵庫は仕事に持って取り組むものではないので、「冷蔵庫を持って」は文に合わない。", "花瓶": "花瓶は仕事に持って取り組む対象ではないので、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "責任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は毎月、責任を支払うために働いている。", "explanation": "責任は支払うものではないので合わない。"}, {"text": "その会社は、取引先と責任を結んだ。", "explanation": "責任は結ぶものではないので合わない。"}, {"text": "チームは、責任を進めて予定通りに終えた。", "explanation": "ここは〈作業〉の意味。進めるのは作業で、責任を進めるとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
