INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37069, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分が引き受けるべき務めや義務。", "primary_collocate": null, "pronunciation": "せきにん", "ipa": "sekiniɴ", "syllable_count": 4, "sentences": [{"text": "社長は、会社を守る重い責任を負っている。", "target_word": "責任", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は、会社[かいしゃ]を守[まも]る重[おも]い責任[せきにん]を負[お]っている。", "sentence_source": "generated"}, {"text": "事故が起きた以上、管理者に責任がある。", "target_word": "責任", "complexity_tier": "T3", "furigana": "事故[じこ]が起[お]きた以上[いじょう]、管理者[かんりしゃ]に責任[せきにん]がある。", "sentence_source": "generated"}, {"text": "約束を果たせず、責任を問われた。", "target_word": "責任", "complexity_tier": "T3", "furigana": "約束[やくそく]を果[は]たせず、責任[せきにん]を問[と]われた。", "sentence_source": "generated"}, {"text": "大臣は問題の責任を取って、辞任した。", "target_word": "責任", "complexity_tier": "T3", "furigana": "大臣[だいじん]は問題[もんだい]の責任[せきにん]を取[と]って、辞任[じにん]した。", "sentence_source": "generated"}, {"text": "彼女は新しい部署の責任を引き受けた。", "target_word": "責任", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は新[あたら]しい部署[ぶしょ]の責任[せきにん]を引[ひ]き受[う]けた。", "sentence_source": "generated"}, {"text": "責任を人に押しつけてはいけない。", "target_word": "責任", "complexity_tier": "T3", "furigana": "責任[せきにん]を人[ひと]に押[お]しつけてはいけない。", "sentence_source": "generated"}, {"text": "市民として、ごみを正しく出す責任がある。", "target_word": "責任", "complexity_tier": "T3", "furigana": "市民[しみん]として、ごみを正[ただ]しく出[だ]す責任[せきにん]がある。", "sentence_source": "generated"}, {"text": "契約が守られなかった場合の責任は、売り手が負う。", "target_word": "責任", "complexity_tier": "T3", "furigana": "契約[けいやく]が守[まも]られなかった場合[ばあい]の責任[せきにん]は、売[う]り手[て]が負[お]う。", "sentence_source": "generated"}, {"text": "責任の重さを感じて、夜も眠れなかった。", "target_word": "責任", "complexity_tier": "T3", "furigana": "責任[せきにん]の重[おも]さを感[かん]じて、夜[よる]も眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "教師には、生徒の安全を守る責任がある。", "target_word": "責任", "complexity_tier": "T3", "furigana": "教師[きょうし]には、生徒[せいと]の安全[あんぜん]を守[まも]る責任[せきにん]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "責任", "label": "基本形"}, {"form": "責任を", "label": "を格"}, {"form": "責任の", "label": "の格"}], "register": "中立", "sense_fingerprint": "引き受けるべき務め・義務、結果への負担", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6ccf0ee-587d-4100-bacc-1b9c2c21e01c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37069, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "責任", "is_correct": true, "explanation": "会社を守る務めを表し、「重い〜を負う」に入って文に合う。"}, {"text": "写真", "is_correct": false, "explanation": "写真は務めとして負うものではないので、「重い写真を負う」は文の意味が通らない。"}, {"text": "地図", "is_correct": false, "explanation": "地図は務めの対象ではなく、「重い地図を負う」は成り立たない。"}, {"text": "日記", "is_correct": false, "explanation": "日記は負う対象にならないので、「重い日記を負っている」は文に合わない。"}], "explanations": {"責任": "会社を守る務めを表し、「重い〜を負う」に入って文に合う。", "写真": "写真は務めとして負うものではないので、「重い写真を負う」は文の意味が通らない。", "地図": "地図は務めの対象ではなく、「重い地図を負う」は成り立たない。", "日記": "日記は負う対象にならないので、「重い日記を負っている」は文に合わない。"}, "sentence_index": 0, "correct_answer": "責任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は責任を犯して、刑務所に入った。", "explanation": "ここは〈罪〉の意味。犯すのは罪で、責任は犯すとは言わないので合わない。"}, {"text": "会社は被害者に責任を払った。", "explanation": "ここは〈賠償金〉の意味。払うのは賠償金で、責任は払うものではないので合わない。"}, {"text": "彼は毎月、責任を返すために働いている。", "explanation": "ここは〈借金〉の意味。返すのは借金で、責任は返すものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37069, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "責任", "is_correct": true, "explanation": "市民が引き受けるべき務めを表し、「〜する責任がある」に入って文に合う。"}, {"text": "電話", "is_correct": false, "explanation": "電話は務めの対象ではないので、「ごみを正しく出す電話がある」は文の意味が通らない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は食品を冷やす家電で、ごみを出す務めの対象ではないので文に合わない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶はごみを出す対象ではないので、「ごみを正しく出す花瓶がある」は成り立たない。"}], "explanations": {"責任": "市民が引き受けるべき務めを表し、「〜する責任がある」に入って文に合う。", "電話": "電話は務めの対象ではないので、「ごみを正しく出す電話がある」は文の意味が通らない。", "冷蔵庫": "冷蔵庫は食品を冷やす家電で、ごみを出す務めの対象ではないので文に合わない。", "花瓶": "花瓶はごみを出す対象ではないので、「ごみを正しく出す花瓶がある」は成り立たない。"}, "sentence_index": 6, "correct_answer": "責任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "探査隊は、宇宙船の責任を無事にかじった。", "explanation": "責任はかじるものではないので合わない。"}, {"text": "市民は、毎年責任を納めている。", "explanation": "ここは〈税金〉の意味。納めるのは税金で、責任は納めるものではないので合わない。"}, {"text": "市は来年の責任を組んだ。", "explanation": "ここは〈予算〉の意味。組むのは予算で、責任は組むものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37069, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "事故の責任を飲んで、管理者が謝った。", "corrected_sentence": "事故の責任を取って、管理者が謝った。", "error_description": "責任は飲むものではないので、「飲んで」は誤り。正しくは「取って」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37069, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は責任を負うして、会社を辞めた。", "corrected_sentence": "彼は責任を負って、会社を辞めた。", "error_description": "「負う」のて形は「負って」。「負うして」は誤りで、正しくは「負って」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37070, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "誇りを象徴するという目的語の関係で、『を』が正しい。"}, {"text": "に", "is_correct": false, "explanation": "『誇りに象徴する』は文型が合わず不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段の『で』は『象徴する』の対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "『誇りと象徴する』は文として意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "誇りを象徴するという目的語の関係で、『を』が正しい。", "に": "『誇りに象徴する』は文型が合わず不自然。", "で": "手段の『で』は『象徴する』の対象を示せない。", "と": "『誇りと象徴する』は文として意味が通らない。"}, "error_tags": {"に": "方向・相手", "で": "手段", "と": "共同・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37070, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "『象徴として』の『と』で、象徴に続く助詞として正しい。"}, {"text": "が", "is_correct": false, "explanation": "『象徴が』は剣が描かれる文の主語を示すもので、象徴の助詞にならない。"}, {"text": "を", "is_correct": false, "explanation": "『象徴を』は目的語として文脈に合わず、『描かれる』とも結びつかない。"}, {"text": "に", "is_correct": false, "explanation": "『象徴に』は『描かれている』の対象として不自然。"}], "correct_answer": "と", "explanations": {"と": "『象徴として』の『と』で、象徴に続く助詞として正しい。", "が": "『象徴が』は剣が描かれる文の主語を示すもので、象徴の助詞にならない。", "を": "『象徴を』は目的語として文脈に合わず、『描かれる』とも結びつかない。", "に": "『象徴に』は『描かれている』の対象として不自然。"}, "error_tags": {"が": "主語", "を": "対象", "に": "方向・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37070, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "目に見えないことを、形があるもののようにして見せること。", "primary_collocate": null, "pronunciation": "しょうちょう", "ipa": "ɕoːtɕoː", "syllable_count": 4, "sentences": [{"text": "白い鳩は、目に見えない平和の象徴だ。", "target_word": "象徴", "complexity_tier": "T3", "furigana": "白[しろ]い鳩[はと]は、目[め]に見[み]えない平和[へいわ]の象徴[しょうちょう]だ。", "sentence_source": "generated"}, {"text": "国旗は、国の誇りを象徴する。", "target_word": "象徴", "complexity_tier": "T3", "furigana": "国旗[こっき]は、国[くに]の誇[ほこ]りを象徴[しょうちょう]する。", "sentence_source": "generated"}, {"text": "指輪は二人の約束を象徴するものだ。", "target_word": "象徴", "complexity_tier": "T3", "furigana": "指輪[ゆびわ]は二人[ふたり]の約束[やくそく]を象徴[しょうちょう]するものだ。", "sentence_source": "generated"}, {"text": "目に見えない愛情を象徴する品として、彼は花を贈った。", "target_word": "象徴", "complexity_tier": "T3", "furigana": "目[め]に見[み]えない愛情[あいじょう]を象徴[しょうちょう]する品[しな]として、彼[かれ]は花[はな]を贈[おく]った。", "sentence_source": "generated"}, {"text": "春の桜は、新しい始まりを象徴している。", "target_word": "象徴", "complexity_tier": "T3", "furigana": "春[はる]の桜[さくら]は、新[あたら]しい始[はじ]まりを象徴[しょうちょう]している。", "sentence_source": "generated"}, {"text": "天秤は、見えない公平さを象徴するために使われる。", "target_word": "象徴", "complexity_tier": "T3", "furigana": "天秤[てんびん]は、見[み]えない公平[こうへい]さを象徴[しょうちょう]するために使[つか]われる。", "sentence_source": "generated"}, {"text": "絵の中の赤いりんごは、命の象徴だと説明された。", "target_word": "象徴", "complexity_tier": "T3", "furigana": "絵[え]の中[なか]の赤[あか]いりんごは、命[いのち]の象徴[しょうちょう]だと説明[せつめい]された。", "sentence_source": "generated"}, {"text": "目に見えない勇気の象徴として、剣が描かれている。", "target_word": "象徴", "complexity_tier": "T3", "furigana": "目[め]に見[み]えない勇気[ゆうき]の象徴[しょうちょう]として、剣[けん]が描[えが]かれている。", "sentence_source": "generated"}, {"text": "この像は、町の復興を象徴する存在になった。", "target_word": "象徴", "complexity_tier": "T3", "furigana": "この像[ぞう]は、町[まち]の復興[ふっこう]を象徴[しょうちょう]する存在[そんざい]になった。", "sentence_source": "generated"}, {"text": "灯台の光は、希望の象徴として歌に出てくる。", "target_word": "象徴", "complexity_tier": "T3", "furigana": "灯台[とうだい]の光[ひかり]は、希望[きぼう]の象徴[しょうちょう]として歌[うた]に出[で]てくる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "象徴する", "label": "サ変動詞 終止形"}, {"form": "象徴している", "label": "継続形"}, {"form": "象徴した", "label": "過去形"}, {"form": "象徴的", "label": "形状詞形"}], "register": "標準的な普通体", "sense_fingerprint": "見えない物事を目に見える形で示すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc4c99e5-c08d-4486-b1ed-5a1851877780') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37070, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "象徴", "is_correct": true, "explanation": "目に見えない平和を、形あるものとして示す意味で文脈に合う。"}, {"text": "渋滞", "is_correct": false, "explanation": "車などが進まない状態の意味で、平和とは結びつかない。"}, {"text": "騒音", "is_correct": false, "explanation": "不快な音の意味で、平和の説明には合わない。"}, {"text": "在庫", "is_correct": false, "explanation": "店などにある品物の意味で、抽象的な平和には使わない。"}], "explanations": {"象徴": "目に見えない平和を、形あるものとして示す意味で文脈に合う。", "渋滞": "車などが進まない状態の意味で、平和とは結びつかない。", "騒音": "不快な音の意味で、平和の説明には合わない。", "在庫": "店などにある品物の意味で、抽象的な平和には使わない。"}, "sentence_index": 0, "correct_answer": "象徴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二つの製品の性能を象徴して、どちらが速いか決めた。", "explanation": "ここは〈比較する〉の意味。象徴は目に見えない考えを形で表す語なので、性能を比べる文脈には合わない。"}, {"text": "首相は新しい方針を、記者会見で象徴した。", "explanation": "ここは〈表明する〉の意味。象徴は形で意味を示す語で、考えを公に言い切る意味はない。"}, {"text": "彼女はクラスを象徴して、先生と話し合った。", "explanation": "ここは〈代表する〉の意味。象徴は目に見えない考えを形で示す語で、人が集団の代わりに立つ意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37070, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "象徴", "is_correct": true, "explanation": "命を形あるりんごで表す意味で、説明文の文脈に合う。"}, {"text": "注文", "is_correct": false, "explanation": "品物を頼む意味で、命には使わない。"}, {"text": "販売", "is_correct": false, "explanation": "商品を売る意味で、命の説明には合わない。"}, {"text": "清掃", "is_correct": false, "explanation": "掃除する意味で、抽象的な命とは結びつかない。"}], "explanations": {"象徴": "命を形あるりんごで表す意味で、説明文の文脈に合う。", "注文": "品物を頼む意味で、命には使わない。", "販売": "商品を売る意味で、命の説明には合わない。", "清掃": "掃除する意味で、抽象的な命とは結びつかない。"}, "sentence_index": 6, "correct_answer": "象徴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "気温を象徴して、記録した。", "explanation": "ここは〈測定する〉の意味。象徴は抽象的な意味を形で表す語で、数値を量る文脈には合わない。"}, {"text": "英文を象徴して、意味を伝えた。", "explanation": "ここは〈翻訳する〉の意味。象徴は意味を別の形で示す語で、訳す操作を表さない。"}, {"text": "長い話を象徴すると、結論は一つだ。", "explanation": "ここは〈要約する〉の意味。象徴は全体を形で示す語で、話を短くまとめる意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37070, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その像は、町の復興を象徴ために建てられた。", "corrected_sentence": "その像は、町の復興を象徴するために建てられた。", "error_description": "象徴ために→象徴するために。名詞の象徴は『する』を付けて動詞として使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37070, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その旗は、平和を象徴に形で掲げられた。", "corrected_sentence": "その旗は、平和を象徴する形で掲げられた。", "error_description": "象徴に→象徴する。「形」を修飾するには「象徴する」の連体形が必要で、「に」では続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37071, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "自然を象徴するという目的語の関係で、『を』が正しい。"}, {"text": "と", "is_correct": false, "explanation": "『自然と象徴する色』は『と』で文が成り立たず、象徴の目的語にならない。"}, {"text": "に", "is_correct": false, "explanation": "『自然に象徴する』は文型が合わず不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段の『で』は『象徴する』の対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "自然を象徴するという目的語の関係で、『を』が正しい。", "と": "『自然と象徴する色』は『と』で文が成り立たず、象徴の目的語にならない。", "に": "『自然に象徴する』は文型が合わず不自然。", "で": "手段の『で』は『象徴する』の対象を示せない。"}, "error_tags": {"と": "共同・相手", "に": "方向・相手", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37071, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "日本を象徴するという目的語の関係で、『を』が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "『日本へ象徴する』は方向の『へ』が目的語の関係に合わず、文として不自然。"}, {"text": "から", "is_correct": false, "explanation": "『日本から象徴する』は起点の『から』が象徴の対象にならず、文として不自然。"}, {"text": "や", "is_correct": false, "explanation": "『や』は並列を表すため、『日本や象徴する』は述語として成り立たず不自然。"}], "correct_answer": "を", "explanations": {"を": "日本を象徴するという目的語の関係で、『を』が正しい。", "へ": "『日本へ象徴する』は方向の『へ』が目的語の関係に合わず、文として不自然。", "から": "『日本から象徴する』は起点の『から』が象徴の対象にならず、文として不自然。", "や": "『や』は並列を表すため、『日本や象徴する』は述語として成り立たず不自然。"}, "error_tags": {"へ": "方向", "から": "起点", "や": "列挙"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37071, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある考えや性質、感情などを、具体的な形やものを通して分かりやすく表すこと。", "primary_collocate": null, "pronunciation": "しょうちょう", "ipa": "ɕoːtɕoː", "syllable_count": 4, "sentences": [{"text": "ハートの形は愛情を象徴している。", "target_word": "象徴", "complexity_tier": "T3", "furigana": "ハートの形[かたち]は愛情[あいじょう]を象徴[しょうちょう]している。", "sentence_source": "generated"}, {"text": "緑色は自然を象徴する色として広く使われる。", "target_word": "象徴", "complexity_tier": "T3", "furigana": "緑色[みどりいろ]は自然[しぜん]を象徴[しょうちょう]する色[いろ]として広[ひろ]く使[つか]われる。", "sentence_source": "generated"}, {"text": "王冠は王の権力を象徴する。", "target_word": "象徴", "complexity_tier": "T3", "furigana": "王冠[おうかん]は王[おう]の権力[けんりょく]を象徴[しょうちょう]する。", "sentence_source": "generated"}, {"text": "ライオンは勇気の象徴として、紋章によく描かれる。", "target_word": "象徴", "complexity_tier": "T3", "furigana": "ライオンは勇気[ゆうき]の象徴[しょうちょう]として、紋章[もんしょう]によく描[えが]かれる。", "sentence_source": "generated"}, {"text": "彼の古い帽子は、旅好きな性格を象徴していた。", "target_word": "象徴", "complexity_tier": "T3", "furigana": "彼[かれ]の古[ふる]い帽子[ぼうし]は、旅好[たびず]きな性格[せいかく]を象徴[しょうちょう]していた。", "sentence_source": "generated"}, {"text": "白い服は清らかさを象徴するので、式でよく着られる。", "target_word": "象徴", "complexity_tier": "T3", "furigana": "白[しろ]い服[ふく]は清[きよ]らかさを象徴[しょうちょう]するので、式[しき]でよく着[き]られる。", "sentence_source": "generated"}, {"text": "この映画では、雨が主人公の悲しみを象徴している。", "target_word": "象徴", "complexity_tier": "T3", "furigana": "この映画[えいが]では、雨[あめ]が主人公[しゅじんこう]の悲[かな]しみを象徴[しょうちょう]している。", "sentence_source": "generated"}, {"text": "富士山は日本を象徴する風景のひとつだ。", "target_word": "象徴", "complexity_tier": "T3", "furigana": "富士山[ふじさん]は日本[にほん]を象徴[しょうちょう]する風景[ふうけい]のひとつだ。", "sentence_source": "generated"}, {"text": "割れた時計は、止まってしまった時間を象徴していた。", "target_word": "象徴", "complexity_tier": "T3", "furigana": "割[わ]れた時計[とけい]は、止[と]まってしまった時間[じかん]を象徴[しょうちょう]していた。", "sentence_source": "generated"}, {"text": "何を象徴するものか分かれば、物語の意味も理解しやすい。", "target_word": "象徴", "complexity_tier": "T3", "furigana": "何[なに]を象徴[しょうちょう]するものか分[わ]かれば、物語[ものがたり]の意味[いみ]も理解[りかい]しやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "象徴する", "label": "サ変動詞 終止形"}, {"form": "象徴している", "label": "継続形"}, {"form": "象徴した", "label": "過去形"}, {"form": "象徴的", "label": "形状詞形"}], "register": "標準的な普通体", "sense_fingerprint": "考えや性質をものの形で分かりやすく表すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc4c99e5-c08d-4486-b1ed-5a1851877780') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37071, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "象徴", "is_correct": true, "explanation": "ハートの形で愛情を表す意味で、文脈に合う。"}, {"text": "残高", "is_correct": false, "explanation": "預金の額を指す意味で、愛情には使わない。"}, {"text": "衝突", "is_correct": false, "explanation": "ぶつかる意味で、愛情を示す文脈に合わない。"}, {"text": "栽培", "is_correct": false, "explanation": "植物を育てる意味で、愛情には結びつかない。"}], "explanations": {"象徴": "ハートの形で愛情を表す意味で、文脈に合う。", "残高": "預金の額を指す意味で、愛情には使わない。", "衝突": "ぶつかる意味で、愛情を示す文脈に合わない。", "栽培": "植物を育てる意味で、愛情には結びつかない。"}, "sentence_index": 0, "correct_answer": "象徴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "売上を象徴して、月ごとにまとめた。", "explanation": "ここは〈集計する〉の意味。象徴は考えを形で表す語で、数字を合計する文脈には合わない。"}, {"text": "道路を象徴して、安全にした。", "explanation": "ここは〈整備する〉の意味。象徴は意味を示す語で、施設を直す操作には使わない。"}, {"text": "ケーキを象徴して、安く売った。", "explanation": "ここは〈割引する〉の意味。象徴は値段を下げる意味を持たず、商品には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37071, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "象徴", "is_correct": true, "explanation": "雨で悲しみを表す意味で、映画の説明に合う。"}, {"text": "点滅", "is_correct": false, "explanation": "明かりが点いたり消えたりする意味で、悲しみには使わない。"}, {"text": "乾燥", "is_correct": false, "explanation": "水分がなくなる意味で、感情の説明には合わない。"}, {"text": "解約", "is_correct": false, "explanation": "契約を終わらせる意味で、悲しみとは結びつかない。"}], "explanations": {"象徴": "雨で悲しみを表す意味で、映画の説明に合う。", "点滅": "明かりが点いたり消えたりする意味で、悲しみには使わない。", "乾燥": "水分がなくなる意味で、感情の説明には合わない。", "解約": "契約を終わらせる意味で、悲しみとは結びつかない。"}, "sentence_index": 6, "correct_answer": "象徴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は実験の手順を象徴した。", "explanation": "ここは〈説明する〉の意味。象徴は考えを形で表す語で、手順を述べる文脈には合わない。"}, {"text": "その実験は、同じ条件でもう一度象徴できた。", "explanation": "ここは〈再現する〉の意味。象徴は考えを具体的な形で表す語で、実験をもう一度行う意味はない。"}, {"text": "先生は話し合いで、ついに問題を象徴した。", "explanation": "ここは〈解決する〉の意味。象徴は考えを形で示す語で、問題を片付ける意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37071, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "赤い花は、喜びを象徴に色として使われる。", "corrected_sentence": "赤い花は、喜びを象徴する色として使われる。", "error_description": "象徴に→象徴する。「色」を修飾するには「象徴する」の連体形が必要で、「に」では名詞を修飾できない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37071, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その詩は、孤独を象徴でいた。", "corrected_sentence": "その詩は、孤独を象徴していた。", "error_description": "象徴していた→象徴でいた。『する』の継続形『している』の『し』が抜けている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37072, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "全体", "is_correct": true, "explanation": "正解。「全体」は「一人ひとり」の個々と対になる語で、ここの「個々の意見」と対比される。"}, {"text": "窓", "is_correct": false, "explanation": "窓は具体的な物の名で、全体と個々のように対になる関係にはない。"}, {"text": "給食", "is_correct": false, "explanation": "給食は学校で出る食事のことで、個々の対義語にはならない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は学習に使う本で、個々と対義の関係にはない。"}], "correct_answer": "全体", "explanations": {"全体": "正解。「全体」は「一人ひとり」の個々と対になる語で、ここの「個々の意見」と対比される。", "窓": "窓は具体的な物の名で、全体と個々のように対になる関係にはない。", "給食": "給食は学校で出る食事のことで、個々の対義語にはならない。", "教科書": "教科書は学習に使う本で、個々と対義の関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37072, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「個々の力」と、力を修飾する「の」。ここで正解。"}, {"text": "へ", "is_correct": false, "explanation": "「個々へ力は弱くても」と方向にすると、文の構造が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「個々と力は弱くても」と並べると、主語の関係が合わない。"}, {"text": "を", "is_correct": false, "explanation": "「個々を力は弱くても」と目的語にすると、後ろの「力は」とつながらず文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「個々の力」と、力を修飾する「の」。ここで正解。", "へ": "「個々へ力は弱くても」と方向にすると、文の構造が成り立たない。", "と": "「個々と力は弱くても」と並べると、主語の関係が合わない。", "を": "「個々を力は弱くても」と目的語にすると、後ろの「力は」とつながらず文が成り立たない。"}, "error_tags": {"へ": "方向の誤り", "と": "並列・相手の誤り", "を": "目的格の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37072, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "一人ひとりのこと。", "primary_collocate": null, "pronunciation": "ここ", "ipa": "koko", "syllable_count": 2, "sentences": [{"text": "先生は生徒の個々の力に合わせて、宿題を変えている。", "target_word": "個々", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]の個々[ここ]の力[ちから]に合[あ]わせて、宿題[しゅくだい]を変[か]えている。", "sentence_source": "generated"}, {"text": "全体の数字だけでなく、個々の店の売り上げも調べよう。", "target_word": "個々", "complexity_tier": "T4", "furigana": "全体[ぜんたい]の数字[すうじ]だけでなく、個々[ここ]の店[みせ]の売[う]り上[あ]げも調[しら]べよう。", "sentence_source": "generated"}, {"text": "好みは個々に違うので、料理は全部の人に同じ味にはできない。", "target_word": "個々", "complexity_tier": "T4", "furigana": "好[この]みは個々[ここ]に違[ちが]うので、料理[りょうり]は全部[ぜんぶ]の人[ひと]に同[おな]じ味[あじ]にはできない。", "sentence_source": "generated"}, {"text": "会議では、個々の意見を紙に書いてから話し合った。", "target_word": "個々", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、個々[ここ]の意見[いけん]を紙[かみ]に書[か]いてから話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "町の決まりを守ることは大切だが、個々の事情も考えてほしい。", "target_word": "個々", "complexity_tier": "T4", "furigana": "町[まち]の決[き]まりを守[まも]ることは大切[たいせつ]だが、個々[ここ]の事情[じじょう]も考[かんが]えてほしい。", "sentence_source": "generated"}, {"text": "医者は患者個々の体の状態を見て、薬を選ぶ。", "target_word": "個々", "complexity_tier": "T4", "furigana": "医者[いしゃ]は患者[かんじゃ]個々[ここ]の体[からだ]の状態[じょうたい]を見[み]て、薬[くすり]を選[えら]ぶ。", "sentence_source": "generated"}, {"text": "団体旅行だが、昼ごはんは個々に好きな店で食べてよい。", "target_word": "個々", "complexity_tier": "T3", "furigana": "団体旅行[だんたいりょこう]だが、昼[ひる]ごはんは個々[ここ]に好[す]きな店[みせ]で食[た]べてよい。", "sentence_source": "generated"}, {"text": "個々の力は弱くても、みんなで協力すれば大きな仕事ができる。", "target_word": "個々", "complexity_tier": "T4", "furigana": "個々[ここ]の力[ちから]は弱[よわ]くても、みんなで協力[きょうりょく]すれば大[おお]きな仕事[しごと]ができる。", "sentence_source": "generated"}, {"text": "社員個々の目標を決めて、年末に確かめる。", "target_word": "個々", "complexity_tier": "T4", "furigana": "社員[しゃいん]個々[ここ]の目標[もくひょう]を決[き]めて、年末[ねんまつ]に確[たし]かめる。", "sentence_source": "generated"}, {"text": "個々の問題を一つずつ解決していくしかない。", "target_word": "個々", "complexity_tier": "T3", "furigana": "個々[ここ]の問題[もんだい]を一[ひと]つずつ解決[かいけつ]していくしかない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "個々", "label": "基本形"}, {"form": "個々の", "label": "連体修飾（の）"}, {"form": "個々に", "label": "副詞的用法（に）"}], "register": "一般", "sense_fingerprint": "全体ではなく、一人ひとり・一つひとつを別々に取り上げること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bb45688-8400-4456-9927-11fbe9b516ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37072, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "個々", "is_correct": true, "explanation": "正解。一人ひとりの力という意味で、生徒の力を修飾する。"}, {"text": "教科書", "is_correct": false, "explanation": "「生徒の教科書の力」は意味が通らず、ここには入らない。"}, {"text": "給食", "is_correct": false, "explanation": "「生徒の給食の力」は不自然で、文の意味が合わない。"}, {"text": "窓", "is_correct": false, "explanation": "「生徒の窓の力」は成り立たず、ここには入らない。"}], "explanations": {"個々": "正解。一人ひとりの力という意味で、生徒の力を修飾する。", "教科書": "「生徒の教科書の力」は意味が通らず、ここには入らない。", "給食": "「生徒の給食の力」は不自然で、文の意味が合わない。", "窓": "「生徒の窓の力」は成り立たず、ここには入らない。"}, "sentence_index": 0, "correct_answer": "個々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この池には、コイの個々が一つにまとまって泳いでいる。", "explanation": "ここは〈まとまり〉の意味。個々は一人ひとりを別々に見る語なので、一つにまとまった群れには合わない。"}, {"text": "彼女は個々が強く、みんなの前でも物怖じしない。", "explanation": "ここは〈個性〉の意味。個々は一人ひとりを指すだけで、性格の強さを言うのには使わない。"}, {"text": "会議では、個々が一つになって結論を出した。", "explanation": "ここは〈全員〉の意味。個々は一人ひとりを別々に見る語なので、全員がまとまる場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37072, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "個々", "is_correct": true, "explanation": "正解。「個々に」の形で、一人ひとりが別々に好きな店で食べるという意味になる。"}, {"text": "全体", "is_correct": false, "explanation": "「全体に好きな店で食べてよい」は意味が通らず、ここには入らない。"}, {"text": "組織", "is_correct": false, "explanation": "「組織に好きな店で食べてよい」は成り立たず、文の意味が合わない。"}, {"text": "集合", "is_correct": false, "explanation": "「集合に好きな店で食べてよい」は意味が通らず、ここには入らない。"}], "explanations": {"個々": "正解。「個々に」の形で、一人ひとりが別々に好きな店で食べるという意味になる。", "全体": "「全体に好きな店で食べてよい」は意味が通らず、ここには入らない。", "組織": "「組織に好きな店で食べてよい」は成り立たず、文の意味が合わない。", "集合": "「集合に好きな店で食べてよい」は意味が通らず、ここには入らない。"}, "sentence_index": 6, "correct_answer": "個々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "レストランの個々で、家族の誕生日を祝った。", "explanation": "ここは〈個室〉の意味。個々は一人ひとりを表し、部屋や場所を指さないので「個々で祝う」は合わない。"}, {"text": "個々が一斉に拍手した。", "explanation": "ここは〈揃って〉の意味。個々は一人ひとりを別々に見る語なので、全員が揃って同じ動きをする場面には合わない。"}, {"text": "個々が同時に出発した。", "explanation": "ここは〈足並みをそろえる〉の意味。個々は一人ひとりを別々に見る語なので、全員が足並みをそろえて動く場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37072, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議では、個々を意見を聞いた。", "corrected_sentence": "会議では、個々の意見を聞いた。", "error_description": "「個々」が「意見」を修飾するときは「の」を使う。ここの「を」は目的語を表すので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37072, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社は社員個々が目標を与えた。", "corrected_sentence": "会社は社員個々に目標を与えた。", "error_description": "目標を与える相手には「に」を使う。ここの「が」は主語を表すので、社員が目標を与える側になり誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ce010df-c122-4bab-b2c2-8301fabd80bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37074, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37074, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「重さの軽減に」の「に」。「軽減には」の形で、軽減が話題の対象になる場面に合う。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「軽減へ鉄ではなく」では方向の意味になり、文が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「軽減をは」は不自然で、文として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「軽減がは」と重なってしまい、「は」と並ばないので文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「重さの軽減に」の「に」。「軽減には」の形で、軽減が話題の対象になる場面に合う。", "へ": "「へ」は方向を示す。「軽減へ鉄ではなく」では方向の意味になり、文が通らない。", "を": "「を」は目的語を示す。「軽減をは」は不自然で、文として成り立たない。", "が": "「が」は主語を示す。「軽減がは」と重なってしまい、「は」と並ばないので文が成り立たない。"}, "error_tags": {"へ": "direction", "が": "subject", "を": "object"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37074, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "重たいものを、もっとかるくすること。", "primary_collocate": null, "pronunciation": "けいげん", "ipa": "keːgeɴ", "syllable_count": 4, "sentences": [{"text": "荷物の重さを軽減するため、中身を二つの袋に分けた。", "target_word": "軽減", "complexity_tier": "T3", "furigana": "荷物[にもつ]の重[おも]さを軽減[けいげん]するため、中身[なかみ]を二[ふた]つの袋[ふくろ]に分[わ]けた。", "sentence_source": "generated"}, {"text": "新しい素材を使って、車体の重さを軽減した。", "target_word": "軽減", "complexity_tier": "T3", "furigana": "新[あたら]しい素材[そざい]を使[つか]って、車体[しゃたい]の重[おも]さを軽減[けいげん]した。", "sentence_source": "generated"}, {"text": "登山では、荷物の軽減が疲れを減らす近道だ。", "target_word": "軽減", "complexity_tier": "T3", "furigana": "登山[とざん]では、荷物[にもつ]の軽減[けいげん]が疲[つか]れを減[へ]らす近道[ちかみち]だ。", "sentence_source": "generated"}, {"text": "この椅子は部品を減らして、重量を軽減できた。", "target_word": "軽減", "complexity_tier": "T3", "furigana": "この椅子[いす]は部品[ぶひん]を減[へ]らして、重量[じゅうりょう]を軽減[けいげん]できた。", "sentence_source": "generated"}, {"text": "軽減された荷物のおかげで、坂道も楽に登れた。", "target_word": "軽減", "complexity_tier": "T3", "furigana": "軽減[けいげん]された荷物[にもつ]のおかげで、坂道[さかみち]も楽[らく]に登[のぼ]れた。", "sentence_source": "generated"}, {"text": "機体の重さを軽減するため、金属の代わりに炭素繊維を使う。", "target_word": "軽減", "complexity_tier": "T3", "furigana": "機体[きたい]の重[おも]さを軽減[けいげん]するため、金属[きんぞく]の代[か]わりに炭素繊維[たんそせんい]を使[つか]う。", "sentence_source": "generated"}, {"text": "かばんの重さを軽減したくて、教科書を学校に置いて帰る。", "target_word": "軽減", "complexity_tier": "T3", "furigana": "かばんの重[おも]さを軽減[けいげん]したくて、教科書[きょうかしょ]を学校[がっこう]に置[お]いて帰[かえ]る。", "sentence_source": "generated"}, {"text": "自転車の重さの軽減には、鉄ではなく軽い金属を使うとよい。", "target_word": "軽減", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]の重[おも]さの軽減[けいげん]には、鉄[てつ]ではなく軽[かる]い金属[きんぞく]を使[つか]うとよい。", "sentence_source": "generated"}, {"text": "旅行の荷物を軽減しようと、着替えを半分にした。", "target_word": "軽減", "complexity_tier": "T3", "furigana": "旅行[りょこう]の荷物[にもつ]を軽減[けいげん]しようと、着替[きが]えを半分[はんぶん]にした。", "sentence_source": "generated"}, {"text": "重さを軽減したバッグは、長く持っても肩が痛くならない。", "target_word": "軽減", "complexity_tier": "T3", "furigana": "重[おも]さを軽減[けいげん]したバッグは、長[なが]く持[も]っても肩[かた]が痛[いた]くならない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "軽減する", "label": "基本形"}, {"form": "軽減した", "label": "過去形"}, {"form": "軽減される", "label": "受身形"}, {"form": "軽減しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "物の重さを減らして軽くすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cbca891-b8d0-4115-b6d9-b9455770d26a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37074, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "軽減", "is_correct": true, "explanation": "ここは「重さを軽くする」の意味で、軽減が正解。「重さを」に続く他動詞として自然に使える。"}, {"text": "運搬", "is_correct": false, "explanation": "運搬は物を別の場所へ運ぶ意味。「重さを運搬」は重さそのものを運ぶことになり、文が成り立たない。"}, {"text": "接続", "is_correct": false, "explanation": "接続は物と物をつなぐ意味。「重さを接続」は目的語が合わず、文の意味が通らない。"}, {"text": "固定", "is_correct": false, "explanation": "固定は動かないように据えておくこと。「重さを固定」とは言わず、重さを減らす文脈に合わない。"}], "explanations": {"軽減": "ここは「重さを軽くする」の意味で、軽減が正解。「重さを」に続く他動詞として自然に使える。", "運搬": "運搬は物を別の場所へ運ぶ意味。「重さを運搬」は重さそのものを運ぶことになり、文が成り立たない。", "接続": "接続は物と物をつなぐ意味。「重さを接続」は目的語が合わず、文の意味が通らない。", "固定": "固定は動かないように据えておくこと。「重さを固定」とは言わず、重さを減らす文脈に合わない。"}, "sentence_index": 0, "correct_answer": "軽減"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は作文の字数を軽減して、三百字にした。", "explanation": "ここは〈減らす〉の意味。字数は重さではないので軽減は合わず、字数を減らすのが自然。"}, {"text": "先生はクラスの人数を軽減して、少人数の授業にした。", "explanation": "ここは〈絞る〉の意味。人数は重さではないので軽減は使わず、人数を絞るのが自然。"}, {"text": "彼は書類の枚数を軽減して、二枚にまとめた。", "explanation": "ここは〈削る〉の意味。枚数は重さではないので軽減は使わず、枚数を削るのが自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37074, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "軽減", "is_correct": true, "explanation": "「重さを軽減したくて」の空欄には、重さを軽くする意味の軽減が入る。"}, {"text": "冷却", "is_correct": false, "explanation": "冷却は温度を下げること。「重さを冷却」は重さに対して温度の意味になり、文が通らない。"}, {"text": "装着", "is_correct": false, "explanation": "装着は身につけたり取り付けたりすること。「重さを装着」は目的語が合わない。"}, {"text": "収納", "is_correct": false, "explanation": "収納はしまうこと。「重さを収納」は重さをしまう意味になり、文脈に合わない。"}], "explanations": {"軽減": "「重さを軽減したくて」の空欄には、重さを軽くする意味の軽減が入る。", "冷却": "冷却は温度を下げること。「重さを冷却」は重さに対して温度の意味になり、文が通らない。", "装着": "装着は身につけたり取り付けたりすること。「重さを装着」は目的語が合わない。", "収納": "収納はしまうこと。「重さを収納」は重さをしまう意味になり、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "軽減"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "町は車道の幅を軽減して、歩道を広げた。", "explanation": "ここは〈狭める〉の意味。道幅は重さではないので軽減とは言えず、幅を狭めるのが自然。"}, {"text": "彼はピアノの音色を軽減した。", "explanation": "ここは「調整する」の意味。音色は重さではないので軽減とは言えず、音色を整える場面では調整が自然。"}, {"text": "彼は試合のウェアの色を軽減した。", "explanation": "ここは「変える」の意味。色は重さではないので、軽減は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37074, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ハンドルの重さで軽減するため、部品を一つ外した。", "corrected_sentence": "ハンドルの重さを軽減するため、部品を一つ外した。", "error_description": "誤りは助詞「で」。正しくは「重さを軽減する」で、軽減の対象を示す「を」が必要。「重さで軽減」では対象が示されず文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37074, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ベルトの重さを軽減れば、体が楽になる。", "corrected_sentence": "ベルトの重さを軽減すれば、体が楽になる。", "error_description": "誤りは動詞の活用。正しくは「軽減すれば」。軽減はサ変名詞なので、「する」の仮定形「すれば」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37075, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「頭の痛みが軽減した」の「が」。軽減した主体（痛み）を示す助詞で、文に合う。"}, {"text": "に", "is_correct": false, "explanation": "「頭の痛みに軽減した」は成り立たない。「に」では主語を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示す。「頭の痛みで軽減した」は主語が示せず不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「頭の痛みから軽減した」は起点の意味になり、主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「頭の痛みが軽減した」の「が」。軽減した主体（痛み）を示す助詞で、文に合う。", "に": "「頭の痛みに軽減した」は成り立たない。「に」では主語を示せない。", "で": "「で」は手段や場所を示す。「頭の痛みで軽減した」は主語が示せず不自然。", "から": "「から」は起点を示す。「頭の痛みから軽減した」は起点の意味になり、主語を示せない。"}, "error_tags": {"に": "case_mismatch", "で": "means", "から": "source"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37075, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「不安を軽減する」の「を」。軽減の対象（不安）を示す目的語の助詞で、文に合う。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「不安へ軽減する」は対象が示せず、文が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示す。「不安と軽減する」は文の構造が崩れる。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示す。「不安より軽減する」は比較の意味になり、対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「不安を軽減する」の「を」。軽減の対象（不安）を示す目的語の助詞で、文に合う。", "へ": "「へ」は方向を示す。「不安へ軽減する」は対象が示せず、文が通らない。", "と": "「と」は並列や相手を示す。「不安と軽減する」は文の構造が崩れる。", "より": "「より」は比較の基準を示す。「不安より軽減する」は比較の意味になり、対象を示せない。"}, "error_tags": {"へ": "direction", "と": "companion", "より": "comparison"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37075, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "負担や苦しみ、重さなどを少なくすること。", "primary_collocate": null, "pronunciation": "けいげん", "ipa": "keːgeɴ", "syllable_count": 4, "sentences": [{"text": "新しい制度で、親の経済的な負担が軽減された。", "target_word": "軽減", "complexity_tier": "T3", "furigana": "新[あたら]しい制度[せいど]で、親[おや]の経済的[けいざいてき]な負担[ふたん]が軽減[けいげん]された。", "sentence_source": "generated"}, {"text": "薬を飲んだら、頭の痛みが軽減した。", "target_word": "軽減", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]んだら、頭[あたま]の痛[いた]みが軽減[けいげん]した。", "sentence_source": "generated"}, {"text": "税金の軽減を求める声が、町の商店主たちから上がっている。", "target_word": "軽減", "complexity_tier": "T3", "furigana": "税金[ぜいきん]の軽減[けいげん]を求[もと]める声[こえ]が、町[まち]の商店主[しょうてんしゅ]たちから上[あ]がっている。", "sentence_source": "generated"}, {"text": "家事を分担して、母の負担を軽減した。", "target_word": "軽減", "complexity_tier": "T3", "furigana": "家事[かじ]を分担[ぶんたん]して、母[はは]の負担[ふたん]を軽減[けいげん]した。", "sentence_source": "generated"}, {"text": "休みを取ったことで、心の苦しみが少し軽減した。", "target_word": "軽減", "complexity_tier": "T3", "furigana": "休[やす]みを取[と]ったことで、心[こころ]の苦[くる]しみが少[すこ]し軽減[けいげん]した。", "sentence_source": "generated"}, {"text": "国は災害にあった人の負担を軽減するため、費用を一部出した。", "target_word": "軽減", "complexity_tier": "T3", "furigana": "国[くに]は災害[さいがい]にあった人[ひと]の負担[ふたん]を軽減[けいげん]するため、費用[ひよう]を一部[いちぶ]出[だ]した。", "sentence_source": "generated"}, {"text": "機械の導入は、作業員の疲れを軽減する効果がある。", "target_word": "軽減", "complexity_tier": "T3", "furigana": "機械[きかい]の導入[どうにゅう]は、作業員[さぎょういん]の疲[つか]れを軽減[けいげん]する効果[こうか]がある。", "sentence_source": "generated"}, {"text": "手術の前に、不安を軽減する説明を受けた。", "target_word": "軽減", "complexity_tier": "T3", "furigana": "手術[しゅじゅつ]の前[まえ]に、不安[ふあん]を軽減[けいげん]する説明[せつめい]を受[う]けた。", "sentence_source": "generated"}, {"text": "交通費を軽減するため、会社は社員に自転車通勤を勧めている。", "target_word": "軽減", "complexity_tier": "T3", "furigana": "交通費[こうつうひ]を軽減[けいげん]するため、会社[かいしゃ]は社員[しゃいん]に自転車通勤[じてんしゃつうきん]を勧[すす]めている。", "sentence_source": "generated"}, {"text": "痛みを軽減する薬は、飲んで三十分ほどで効く。", "target_word": "軽減", "complexity_tier": "T3", "furigana": "痛[いた]みを軽減[けいげん]する薬[くすり]は、飲[の]んで三十分[さんじゅっぷん]ほどで効[き]く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "軽減する", "label": "基本形"}, {"form": "軽減した", "label": "過去形"}, {"form": "軽減される", "label": "受身形"}, {"form": "軽減しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "負担や痛み、苦しみを和らげて減らすこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cbca891-b8d0-4115-b6d9-b9455770d26a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37075, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "軽減", "is_correct": true, "explanation": "「親の経済的な負担が軽減された」の空欄には、負担を減らす意味の軽減が入る。"}, {"text": "冷却", "is_correct": false, "explanation": "冷却は温度を下げること。「負担が冷却された」は意味が通らない。"}, {"text": "点火", "is_correct": false, "explanation": "点火は火をつけること。負担には使えず、文の意味が成り立たない。"}, {"text": "施錠", "is_correct": false, "explanation": "施錠は鍵をかけること。「負担が施錠された」は意味をなさない。"}], "explanations": {"軽減": "「親の経済的な負担が軽減された」の空欄には、負担を減らす意味の軽減が入る。", "冷却": "冷却は温度を下げること。「負担が冷却された」は意味が通らない。", "点火": "点火は火をつけること。負担には使えず、文の意味が成り立たない。", "施錠": "施錠は鍵をかけること。「負担が施錠された」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "軽減"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ジュースを水で軽減した。", "explanation": "ここは「薄める」の意味。濃さを下げる場面で、負担や痛み、重さを減らす軽減は使わない。"}, {"text": "彼は約束の期限を軽減して、仕事を遅らせた。", "explanation": "ここは「延長する」の意味。期限を延ばす場面で、負担を減らす軽減は合わない。"}, {"text": "彼は絵の具の色を軽減して、明るく仕上げた。", "explanation": "ここは「変える」の意味。色を変える場面で、負担や苦しみを減らす軽減は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37075, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "軽減", "is_correct": true, "explanation": "「作業員の疲れを軽減する効果」の空欄には、疲れを和らげる意味の軽減が入る。"}, {"text": "収納", "is_correct": false, "explanation": "収納はしまうこと。「疲れを収納する」は意味が通らない。"}, {"text": "固定", "is_correct": false, "explanation": "固定は動かないように据えること。「疲れを固定する」は意味をなさない。"}, {"text": "配送", "is_correct": false, "explanation": "配送は品物を届けること。疲れには使えず、文の意味が合わない。"}], "explanations": {"軽減": "「作業員の疲れを軽減する効果」の空欄には、疲れを和らげる意味の軽減が入る。", "収納": "収納はしまうこと。「疲れを収納する」は意味が通らない。", "固定": "固定は動かないように据えること。「疲れを固定する」は意味をなさない。", "配送": "配送は品物を届けること。疲れには使えず、文の意味が合わない。"}, "sentence_index": 6, "correct_answer": "軽減"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は窓の数を軽減して、三つにした。", "explanation": "ここは〈減らす〉の意味。窓の数は負担ではないので、数を減らす場面では軽減は使わない。"}, {"text": "彼は古い写真を軽減して、アルバムを作った。", "explanation": "ここは「取り除く」の意味。写真を減らす場面では削除が自然で、負担を和らげる軽減は合わない。"}, {"text": "彼はチームの勝ち星を軽減した。", "explanation": "ここは〈減らす〉の意味。勝ち星は重さや負担ではないので軽減は合わず、勝ち星を減らすと言うのが自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37075, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもの負担に軽減するため、制度を作った。", "corrected_sentence": "子どもの負担を軽減するため、制度を作った。", "error_description": "誤りは助詞「に」。正しくは「負担を軽減する」で、軽減の対象を示す「を」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37075, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "不安を軽減た説明は、受けるだけで気持ちが楽になる。", "corrected_sentence": "不安を軽減する説明は、受けるだけで気持ちが楽になる。", "error_description": "誤りは動詞の活用。正しくは「軽減する」。軽減はサ変名詞なので、「する」の連体形が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37076, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「食を味わう」の「を」。味わう対象（食べ物）を示す目的語の助詞で、文に合う。"}, {"text": "に", "is_correct": false, "explanation": "「食に味わう」は成り立たない。「味わう」は「に」を取らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「食へ味わう」は方向の意味になり、文が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示す。「食と味わう」は文の構造が崩れる。"}], "correct_answer": "を", "explanations": {"を": "「食を味わう」の「を」。味わう対象（食べ物）を示す目的語の助詞で、文に合う。", "に": "「食に味わう」は成り立たない。「味わう」は「に」を取らない。", "へ": "「へ」は方向を示す。「食へ味わう」は方向の意味になり、文が通らない。", "と": "「と」は並列や相手を示す。「食と味わう」は文の構造が崩れる。"}, "error_tags": {"に": "case_mismatch", "へ": "direction", "と": "companion"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37076, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「食で作られる」の「で」。材料や手段を示す助詞で、体が食から作られる意味に合う。"}, {"text": "を", "is_correct": false, "explanation": "「食を作られる」は受身の形と合わず、不自然になる。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示す。「食より作られる」は材料の意味にならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を示す。「食の作られる」は受身の文として成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「食で作られる」の「で」。材料や手段を示す助詞で、体が食から作られる意味に合う。", "を": "「食を作られる」は受身の形と合わず、不自然になる。", "より": "「より」は比較の基準を示す。「食より作られる」は材料の意味にならない。", "の": "「の」は所属や修飾を示す。「食の作られる」は受身の文として成り立たない。"}, "error_tags": {"を": "object", "より": "comparison", "の": "possessive"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37076, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "たべもののことです。", "primary_collocate": null, "pronunciation": "しょく", "ipa": "ɕokɯ", "syllable_count": 2, "sentences": [{"text": "食の安全を守るため、店は毎日材料を検査している。", "target_word": "食", "complexity_tier": "T3", "furigana": "食[しょく]の安全[あんぜん]を守[まも]るため、店[みせ]は毎日[まいにち]材料[ざいりょう]を検査[けんさ]している。", "sentence_source": "generated"}, {"text": "旅行の楽しみは、その土地の食を味わうことだ。", "target_word": "食", "complexity_tier": "T3", "furigana": "旅行[りょこう]の楽[たの]しみは、その土地[とち]の食[しょく]を味[あじ]わうことだ。", "sentence_source": "generated"}, {"text": "最近は食に気をつかう人が増えている。", "target_word": "食", "complexity_tier": "T3", "furigana": "最近[さいきん]は食[しょく]に気[き]をつかう人[ひと]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "食の好みは国によって大きく違う。", "target_word": "食", "complexity_tier": "T3", "furigana": "食[しょく]の好[この]みは国[くに]によって大[おお]きく違[ちが]う。", "sentence_source": "generated"}, {"text": "母は食を大切にする人で、いつも残さず食べなさいと言う。", "target_word": "食", "complexity_tier": "T3", "furigana": "母[はは]は食[しょく]を大切[たいせつ]にする人[ひと]で、いつも残[のこ]さず食[た]べなさいと言[い]う。", "sentence_source": "generated"}, {"text": "この町は食が豊かで、海でも山でもおいしい物が採れる。", "target_word": "食", "complexity_tier": "T3", "furigana": "この町[まち]は食[しょく]が豊[ゆた]かで、海[うみ]でも山[やま]でもおいしい物[もの]が採[と]れる。", "sentence_source": "generated"}, {"text": "世界の食を紹介する番組が、毎週楽しみだ。", "target_word": "食", "complexity_tier": "T3", "furigana": "世界[せかい]の食[しょく]を紹介[しょうかい]する番組[ばんぐみ]が、毎週[まいしゅう]楽[たの]しみだ。", "sentence_source": "generated"}, {"text": "体は食で作られるので、毎日何を選ぶかが大切だ。", "target_word": "食", "complexity_tier": "T3", "furigana": "体[からだ]は食[しょく]で作[つく]られるので、毎日[まいにち]何[なに]を選[えら]ぶかが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "祖父の若いころは食が乏しく、米も自由に買えなかった。", "target_word": "食", "complexity_tier": "T3", "furigana": "祖父[そふ]の若[わか]いころは食[しょく]が乏[とぼ]しく、米[こめ]も自由[じゆう]に買[か]えなかった。", "sentence_source": "generated"}, {"text": "食の問題を話し合う集会に、農家や店の人が集まった。", "target_word": "食", "complexity_tier": "T3", "furigana": "食[しょく]の問題[もんだい]を話[はな]し合[あ]う集会[しゅうかい]に、農家[のうか]や店[みせ]の人[ひと]が集[あつ]まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "食", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人が食べる物、食べ物全般", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cbca891-b8d0-4115-b6d9-b9455770d26a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37076, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食", "is_correct": true, "explanation": "「食の安全」の空欄には、食べ物を指す食が入る。"}, {"text": "雨", "is_correct": false, "explanation": "雨は天気の語で、「雨の安全を守る店」は文脈に合わない。"}, {"text": "空", "is_correct": false, "explanation": "空は天空を指す語で、「空の安全」は材料の検査と結びつかない。"}, {"text": "石", "is_correct": false, "explanation": "石は鉱物の語で、食べ物の安全を守る文脈には入らない。"}], "explanations": {"食": "「食の安全」の空欄には、食べ物を指す食が入る。", "雨": "雨は天気の語で、「雨の安全を守る店」は文脈に合わない。", "空": "空は天空を指す語で、「空の安全」は材料の検査と結びつかない。", "石": "石は鉱物の語で、食べ物の安全を守る文脈には入らない。"}, "sentence_index": 0, "correct_answer": "食"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は食の上に本を置いたまま、料理を運んだ。", "explanation": "ここは〈食卓〉の意味。本を置くのは食卓で、食（たべもの）の上に置くとは言わないので合わない。"}, {"text": "今夜は月の食が見られるので、家族で外に出た。", "explanation": "ここは「月食」の意味。天体の現象を指す語で、食べ物の意味の食とは合わない。"}, {"text": "彼は仕事の合間に、食を一時間寝かせた。", "explanation": "ここは〈生地〉を寝かせるの意味。生地なら寝かせて使うが、食（たべもの）全体は寝かせる対象として使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37076, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食", "is_correct": true, "explanation": "「世界の食を紹介する番組」の空欄には、食べ物の食が入る。"}, {"text": "騒音", "is_correct": false, "explanation": "騒音は不快な音のこと。「世界の騒音を紹介する番組」は内容が成り立たない。"}, {"text": "借金", "is_correct": false, "explanation": "借金は返すべき金銭の債務。「世界の借金を紹介する番組」は文脈に合わない。"}, {"text": "砂利", "is_correct": false, "explanation": "砂利は小石の集まり。「世界の砂利を紹介する番組」は食べ物の紹介と結びつかない。"}], "explanations": {"食": "「世界の食を紹介する番組」の空欄には、食べ物の食が入る。", "騒音": "騒音は不快な音のこと。「世界の騒音を紹介する番組」は内容が成り立たない。", "借金": "借金は返すべき金銭の債務。「世界の借金を紹介する番組」は文脈に合わない。", "砂利": "砂利は小石の集まり。「世界の砂利を紹介する番組」は食べ物の紹介と結びつかない。"}, "sentence_index": 6, "correct_answer": "食"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会社の食で昼食を取った。", "explanation": "ここは〈食堂〉の意味。食（たべもの）は場所を指さないので、場所を言うなら食堂が自然。"}, {"text": "彼は食を読み直して、感想を書いた。", "explanation": "食べ物は読む対象ではないので、この文脈では成り立たない。"}, {"text": "祖父は食を毎朝ピアノで弾いて楽しんだ。", "explanation": "ここは〈曲〉の意味。食は演奏する対象ではないので、ピアノで弾くのは曲だと言うのが自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37076, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "最近は健康のために食が気をつかう人が多い。", "corrected_sentence": "最近は健康のために食に気をつかう人が多い。", "error_description": "誤りは助詞「が」。正しくは「食に気をつかう」で、「気をつかう」は「に」を取るので「に」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37076, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "世界の食に紹介する番組が毎週放送されている。", "corrected_sentence": "世界の食を紹介する番組が毎週放送されている。", "error_description": "誤りは助詞「に」。正しくは「食を紹介する」で、紹介の対象を示す「を」が必要。「食に紹介する」では対象が示されず文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37078, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「自立を助ける」の「を」。助ける対象（自立）を示す目的語の助詞で、文に合う。"}, {"text": "に", "is_correct": false, "explanation": "「子どもの自立に助ける」は成り立たない。「助ける」は「に」で対象を取らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示す。「自立で助ける」は対象を示せず不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「自立から助ける」は起点の意味になり、対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「自立を助ける」の「を」。助ける対象（自立）を示す目的語の助詞で、文に合う。", "に": "「子どもの自立に助ける」は成り立たない。「助ける」は「に」で対象を取らない。", "で": "「で」は手段や場所を示す。「自立で助ける」は対象を示せず不自然。", "から": "「から」は起点を示す。「自立から助ける」は起点の意味になり、対象を示せない。"}, "error_tags": {"に": "direction", "で": "means", "から": "source"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37078, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「自立を促す」の「を」。促す対象（自立）を示す目的語の助詞で、文に合う。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や対象を示す。「自立に促す」は対象が合わず、文が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示す。「自立と促す」は文の構造が崩れる。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示す。「自立より促す」は比較の意味になり、対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「自立を促す」の「を」。促す対象（自立）を示す目的語の助詞で、文に合う。", "に": "「に」は相手や対象を示す。「自立に促す」は対象が合わず、文が通らない。", "と": "「と」は並列や相手を示す。「自立と促す」は文の構造が崩れる。", "より": "「より」は比較の基準を示す。「自立より促す」は比較の意味になり、対象を示せない。"}, "error_tags": {"に": "target", "と": "companion", "より": "comparison"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37078, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "自分で考えて行動し、他の人に頼らないこと。", "primary_collocate": null, "pronunciation": "じりつ", "ipa": "dʑiɾitsɯ", "syllable_count": 3, "sentences": [{"text": "大学生になって、親に頼らず自立した生活を始めた。", "target_word": "自立", "complexity_tier": "T3", "furigana": "大学生[だいがくせい]になって、親[おや]に頼[たよ]らず自立[じりつ]した生活[せいかつ]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "子どもの自立を助けるために、親は手を出しすぎないほうがよい。", "target_word": "自立", "complexity_tier": "T3", "furigana": "子[こ]どもの自立[じりつ]を助[たす]けるために、親[おや]は手[て]を出[だ]しすぎないほうがよい。", "sentence_source": "generated"}, {"text": "彼女は自分で考えて動ける、自立した人だ。", "target_word": "自立", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は自分[じぶん]で考[かんが]えて動[うご]ける、自立[じりつ]した人[ひと]だ。", "sentence_source": "generated"}, {"text": "一人暮らしを始めてから、少しずつ自立できてきた。", "target_word": "自立", "complexity_tier": "T3", "furigana": "一人暮[ひとりぐ]らしを始[はじ]めてから、少[すこ]しずつ自立[じりつ]できてきた。", "sentence_source": "generated"}, {"text": "自立するには、まず自分で決めることを覚えなければならない。", "target_word": "自立", "complexity_tier": "T3", "furigana": "自立[じりつ]するには、まず自分[じぶん]で決[き]めることを覚[おぼ]えなければならない。", "sentence_source": "generated"}, {"text": "弟はいつも兄に聞いてばかりで、まだ自立していない。", "target_word": "自立", "complexity_tier": "T3", "furigana": "弟[おとうと]はいつも兄[あに]に聞[き]いてばかりで、まだ自立[じりつ]していない。", "sentence_source": "generated"}, {"text": "息子が自立して家を出る日が近づき、母は少しさみしそうだ。", "target_word": "自立", "complexity_tier": "T3", "furigana": "息子[むすこ]が自立[じりつ]して家[いえ]を出[で]る日[ひ]が近[ちか]づき、母[はは]は少[すこ]しさみしそうだ。", "sentence_source": "generated"}, {"text": "先生は生徒の自立を促すため、答えをすぐには教えない。", "target_word": "自立", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]の自立[じりつ]を促[うなが]すため、答[こた]えをすぐには教[おし]えない。", "sentence_source": "generated"}, {"text": "就職して初めての給料をもらい、自立への一歩を踏み出した。", "target_word": "自立", "complexity_tier": "T3", "furigana": "就職[しゅうしょく]して初[はじ]めての給料[きゅうりょう]をもらい、自立[じりつ]への一歩[いっぽ]を踏[ふ]み出[だ]した。", "sentence_source": "generated"}, {"text": "自立した大人とは、自分の行動に責任を持てる人のことだ。", "target_word": "自立", "complexity_tier": "T3", "furigana": "自立[じりつ]した大人[おとな]とは、自分[じぶん]の行動[こうどう]に責任[せきにん]を持[も]てる人[ひと]のことだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自立する", "label": "基本形"}, {"form": "自立した", "label": "過去形"}, {"form": "自立して", "label": "て形"}, {"form": "自立しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "人が自分で考え行動し、他人に頼らないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cbca891-b8d0-4115-b6d9-b9455770d26a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37078, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自立", "is_correct": true, "explanation": "「親に頼らず自立した生活」の空欄には、他人に頼らない意味の自立が入る。"}, {"text": "停滞", "is_correct": false, "explanation": "停滞は進まずに止まること。「停滞した生活」では頼らない意味にならず、文脈に合わない。"}, {"text": "解体", "is_correct": false, "explanation": "解体は組織や物をばらすこと。生活の文脈には合わない。"}, {"text": "放置", "is_correct": false, "explanation": "放置はそのまま見捨てておくこと。「放置した生活」は頼らない意味にならない。"}], "explanations": {"自立": "「親に頼らず自立した生活」の空欄には、他人に頼らない意味の自立が入る。", "停滞": "停滞は進まずに止まること。「停滞した生活」では頼らない意味にならず、文脈に合わない。", "解体": "解体は組織や物をばらすこと。生活の文脈には合わない。", "放置": "放置はそのまま見捨てておくこと。「放置した生活」は頼らない意味にならない。"}, "sentence_index": 0, "correct_answer": "自立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は自分の欠点を自立していなかった。", "explanation": "ここは〈自覚〉の意味。欠点は意識するものなので、自立の対象にはならない。"}, {"text": "この村は野菜を自立して、毎日市場に出している。", "explanation": "ここは「自分で作る」の意味で、自給を使うのが普通。他人に頼らない意味の自立とは違う。"}, {"text": "彼は練習の時間を自立の時間にして、毎朝走った。", "explanation": "ここは〈決まった〉の意味。練習の時間は自立ではなく、決まった時間と言うのが自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37078, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自立", "is_correct": true, "explanation": "「息子が自立して家を出る」の空欄には、他人に頼らず独り立ちする意味の自立が入る。"}, {"text": "停電", "is_correct": false, "explanation": "停電は電気が止まること。「息子が停電して家を出る」は意味が通らない。"}, {"text": "収穫", "is_correct": false, "explanation": "収穫は作物を取り入れること。人には使えず、文が成り立たない。"}, {"text": "採点", "is_correct": false, "explanation": "採点は答案の点数をつけること。「息子が採点して家を出る」は文脈に合わない。"}], "explanations": {"自立": "「息子が自立して家を出る」の空欄には、他人に頼らず独り立ちする意味の自立が入る。", "停電": "停電は電気が止まること。「息子が停電して家を出る」は意味が通らない。", "収穫": "収穫は作物を取り入れること。人には使えず、文が成り立たない。", "採点": "採点は答案の点数をつけること。「息子が採点して家を出る」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "自立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は夢を自立させ、毎日努力した。", "explanation": "ここは〈かなえる〉の意味。夢は自立させる対象ではないので、かなえると言うのが自然。"}, {"text": "この箱は底が広いので、自立して机の上に立つ。", "explanation": "ここは〈倒れずに立つ〉の意味。人の独立ではないので、この義項の自立とは違う。"}, {"text": "この卵は殻が硬く、机の上で自立していた。", "explanation": "ここは〈倒れずに立つ〉の意味。人の独立ではないので、この義項の自立とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37078, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもの自立で助けるために、家事を任せる。", "corrected_sentence": "子どもの自立を助けるために、家事を任せる。", "error_description": "誤りは助詞「で」。正しくは「自立を助ける」で、助ける対象を示す「を」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37078, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "親は子どもの自立を促しため、手助けを減らしている。", "corrected_sentence": "親は子どもの自立を促すため、手助けを減らしている。", "error_description": "誤りは動詞の活用。正しくは「促すため」。「促す」の終止形の形を保つ必要があり、「促しため」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37079, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「経済が自立する」で、経済が主語になる。"}, {"text": "を", "is_correct": false, "explanation": "自立するは目的語を取らないので、「経済を自立する」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「経済に自立する」では対象の関係が示せず、不自然になる。"}, {"text": "の", "is_correct": false, "explanation": "「経済の自立する」は連体修飾として文が続かない。"}], "correct_answer": "が", "explanations": {"が": "「経済が自立する」で、経済が主語になる。", "を": "自立するは目的語を取らないので、「経済を自立する」は成り立たない。", "に": "「経済に自立する」では対象の関係が示せず、不自然になる。", "の": "「経済の自立する」は連体修飾として文が続かない。"}, "error_tags": {"を": "目的語の誤り", "に": "方向・対象の誤り", "の": "連体修飾の誤り"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "依存", "is_correct": true, "explanation": "他のものに頼る意味で、「自分の力で成り立つ」の対義語として辞書に載る。"}, {"text": "協力", "is_correct": false, "explanation": "力を合わせる意味で、自立の対義語ではない。"}, {"text": "運営", "is_correct": false, "explanation": "組織を動かす意味で、対義語の関係にはない。"}, {"text": "製造", "is_correct": false, "explanation": "物を作る意味で、対義語の関係にはない。"}], "correct_answer": "依存", "explanations": {"依存": "他のものに頼る意味で、「自分の力で成り立つ」の対義語として辞書に載る。", "協力": "力を合わせる意味で、自立の対義語ではない。", "運営": "組織を動かす意味で、対義語の関係にはない。", "製造": "物を作る意味で、対義語の関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37079, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「被災地の自立」で、被災地と自立を結ぶ連体修飾になる。"}, {"text": "に", "is_correct": false, "explanation": "「被災地に自立を支える」は支える対象を示す格として成り立たず、不自然になる。"}, {"text": "より", "is_correct": false, "explanation": "比較の意味になり、「支える」の対象として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表し、「被災地から自立を支える」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「被災地の自立」で、被災地と自立を結ぶ連体修飾になる。", "に": "「被災地に自立を支える」は支える対象を示す格として成り立たず、不自然になる。", "より": "比較の意味になり、「支える」の対象として成り立たない。", "から": "起点を表し、「被災地から自立を支える」は意味が通らない。"}, "error_tags": {"より": "比較の誤り", "から": "起点の誤り", "に": "対象の誤り"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "依存", "is_correct": true, "explanation": "他に頼る意味で、「自分の力で成り立つ」の対義語として辞書に載る。"}, {"text": "経営", "is_correct": false, "explanation": "事業を運営する意味で、対義語の関係にはない。"}, {"text": "売上", "is_correct": false, "explanation": "商売で得た金額の意味で、対義語の関係にはない。"}, {"text": "開業", "is_correct": false, "explanation": "事業を始める意味で、対義語の関係にはない。"}], "correct_answer": "依存", "explanations": {"依存": "他に頼る意味で、「自分の力で成り立つ」の対義語として辞書に載る。", "経営": "事業を運営する意味で、対義語の関係にはない。", "売上": "商売で得た金額の意味で、対義語の関係にはない。", "開業": "事業を始める意味で、対義語の関係にはない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37079, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "他のものに依存せず、自分の力で物事を行うこと。", "primary_collocate": null, "pronunciation": "じりつ", "ipa": "dʑiɾitsɯ", "syllable_count": 3, "sentences": [{"text": "町は補助金に頼らず、自立した運営を目指している。", "target_word": "自立", "complexity_tier": "T3", "furigana": "町[まち]は補助金[ほじょきん]に頼[たよ]らず、自立[じりつ]した運営[うんえい]を目指[めざ]している。", "sentence_source": "generated"}, {"text": "国の経済が自立するには、輸入に頼りすぎない産業が必要だ。", "target_word": "自立", "complexity_tier": "T3", "furigana": "国[くに]の経済[けいざい]が自立[じりつ]するには、輸入[ゆにゅう]に頼[たよ]りすぎない産業[さんぎょう]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "この会社は親会社から離れ、自立して事業を続けている。", "target_word": "自立", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は親会社[おやがいしゃ]から離[はな]れ、自立[じりつ]して事業[じぎょう]を続[つづ]けている。", "sentence_source": "generated"}, {"text": "障害のある人が自立して暮らせる社会を目指す。", "target_word": "自立", "complexity_tier": "T3", "furigana": "障害[しょうがい]のある人[ひと]が自立[じりつ]して暮[く]らせる社会[しゃかい]を目指[めざ]す。", "sentence_source": "generated"}, {"text": "電気を自分で作る家は、電力会社に頼らず自立している。", "target_word": "自立", "complexity_tier": "T3", "furigana": "電気[でんき]を自分[じぶん]で作[つく]る家[いえ]は、電力会社[でんりょくがいしゃ]に頼[たよ]らず自立[じりつ]している。", "sentence_source": "generated"}, {"text": "農家が自立するためには、自分で売り先を見つける力も要る。", "target_word": "自立", "complexity_tier": "T3", "furigana": "農家[のうか]が自立[じりつ]するためには、自分[じぶん]で売[う]り先[さき]を見[み]つける力[ちから]も要[い]る。", "sentence_source": "generated"}, {"text": "小さな島の自立のために、島の人々は観光以外の仕事を作った。", "target_word": "自立", "complexity_tier": "T3", "furigana": "小[ちい]さな島[しま]の自立[じりつ]のために、島[しま]の人々[ひとびと]は観光以外[かんこういがい]の仕事[しごと]を作[つく]った。", "sentence_source": "generated"}, {"text": "被災地の自立を支えるため、仕事づくりの活動が続けられている。", "target_word": "自立", "complexity_tier": "T3", "furigana": "被災地[ひさいち]の自立[じりつ]を支[ささ]えるため、仕事[しごと]づくりの活動[かつどう]が続[つづ]けられている。", "sentence_source": "generated"}, {"text": "この団体は寄付がなくなっても自立できるよう、商品を売り始めた。", "target_word": "自立", "complexity_tier": "T3", "furigana": "この団体[だんたい]は寄付[きふ]がなくなっても自立[じりつ]できるよう、商品[しょうひん]を売[う]り始[はじ]めた。", "sentence_source": "generated"}, {"text": "新しい店は開店から一年で赤字がなくなり、やっと自立した。", "target_word": "自立", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]は開店[かいてん]から一年[いちねん]で赤字[あかじ]がなくなり、やっと自立[じりつ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自立する", "label": "基本形"}, {"form": "自立した", "label": "過去形"}, {"form": "自立して", "label": "て形"}, {"form": "自立しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "他に依存せず自分の力で成り立つこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cbca891-b8d0-4115-b6d9-b9455770d26a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37079, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自立", "is_correct": true, "explanation": "「自立した運営」の形で、補助金に頼らず運営する意味に合う。"}, {"text": "依存", "is_correct": false, "explanation": "「頼らず」と矛盾し、「依存した運営」では文の意味が逆になる。"}, {"text": "無断", "is_correct": false, "explanation": "「無断した運営」は名詞の用法として成り立たない。"}, {"text": "放棄", "is_correct": false, "explanation": "運営を放棄するなら「目指している」という文脈と合わない。"}], "explanations": {"自立": "「自立した運営」の形で、補助金に頼らず運営する意味に合う。", "依存": "「頼らず」と矛盾し、「依存した運営」では文の意味が逆になる。", "無断": "「無断した運営」は名詞の用法として成り立たない。", "放棄": "運営を放棄するなら「目指している」という文脈と合わない。"}, "sentence_index": 0, "correct_answer": "自立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この棚は業者に頼まず、自立で作った。", "explanation": "ここは〈自力〉の意味。業者に頼まず自分の手で作ることは自力で言い、自立とは言わないので合わない。"}, {"text": "彼は自分の欠点に気づき、自立して反省した。", "explanation": "ここは〈自覚〉の意味。欠点に気づくことは自覚で、自立では意味が通らない。"}, {"text": "彼は自分の力に自立を持って、難しい試験に挑んだ。", "explanation": "ここは〈自信〉の意味。自分の力を信じる気持ちは自信で、自立は持つものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37079, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自立", "is_correct": true, "explanation": "「島の自立のために」で、島が自分の力で成り立つことを表す。"}, {"text": "浪費", "is_correct": false, "explanation": "「浪費のために仕事を作った」では目的として成り立たない。"}, {"text": "混乱", "is_correct": false, "explanation": "「混乱のために仕事を作った」は意味が通らない。"}, {"text": "停滞", "is_correct": false, "explanation": "「停滞のために仕事を作った」は目的として不自然で、文脈とも合わない。"}], "explanations": {"自立": "「島の自立のために」で、島が自分の力で成り立つことを表す。", "浪費": "「浪費のために仕事を作った」では目的として成り立たない。", "混乱": "「混乱のために仕事を作った」は意味が通らない。", "停滞": "「停滞のために仕事を作った」は目的として不自然で、文脈とも合わない。"}, "sentence_index": 6, "correct_answer": "自立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この扉は、人が近づくと自立して開く。", "explanation": "ここは〈自動〉の意味。人が操作しなくても機械が動くことは自動で言い、自立とは言わないので合わない。"}, {"text": "彼は寝る時間を守るため、自立のルールを作った。", "explanation": "ここは〈自律〉の意味。自分で決めた規範に従うのは自律で、「自立のルール」とは言わない。"}, {"text": "彼女は頼まれる前に、自立して手伝いを申し出た。", "explanation": "ここは〈自発〉の意味。頼まれる前に進んで行うことは自発で言い、自立では意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37079, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は経済的な自立に目指して働いている。", "corrected_sentence": "彼は経済的な自立を目指して働いている。", "error_description": "「目指す」は「〜を目指す」の形を取るので、「自立」には「を」が付く。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37079, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家族は子どもの自立に応援することにした。", "corrected_sentence": "家族は子どもの自立を応援することにした。", "error_description": "「応援する」は「〜を応援する」の形を取るので、「自立」には「を」が付く。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37080, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「端を結ぶ」で、結ぶ動作の目的語を示す。"}, {"text": "の", "is_correct": false, "explanation": "「端の結んで」は連体修飾として文が続かない。"}, {"text": "より", "is_correct": false, "explanation": "比較の意味になり、ロープの端を結ぶ文脈に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「端と結んで」は相手を示すようになり、不自然になる。"}], "correct_answer": "を", "explanations": {"を": "「端を結ぶ」で、結ぶ動作の目的語を示す。", "の": "「端の結んで」は連体修飾として文が続かない。", "より": "比較の意味になり、ロープの端を結ぶ文脈に合わない。", "と": "「端と結んで」は相手を示すようになり、不自然になる。"}, "error_tags": {"の": "連体修飾の誤り", "より": "比較の誤り", "と": "並列・相手の誤り"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解く", "is_correct": true, "explanation": "結び目をほどく意味で、「結ぶ」の対義語として辞書に載る。"}, {"text": "持つ", "is_correct": false, "explanation": "手に保つ意味で、「結ぶ」との対義関係はない。"}, {"text": "置く", "is_correct": false, "explanation": "物を据える意味で、「結ぶ」との対義関係はない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "別の場所へ移す意味で、「結ぶ」との対義関係はない。"}], "correct_answer": "解く", "explanations": {"解く": "結び目をほどく意味で、「結ぶ」の対義語として辞書に載る。", "持つ": "手に保つ意味で、「結ぶ」との対義関係はない。", "置く": "物を据える意味で、「結ぶ」との対義関係はない。", "運ぶ": "別の場所へ移す意味で、「結ぶ」との対義関係はない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37080, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「ひもで結ぶ」で、手段・道具を表す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「ひもへ結ぶ」は不自然になる。"}, {"text": "から", "is_correct": false, "explanation": "起点を表し、「ひもから結ぶ」は意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「ひもが結ばない」は文の主語として合わない。"}], "correct_answer": "で", "explanations": {"で": "「ひもで結ぶ」で、手段・道具を表す。", "へ": "方向を表すが、「ひもへ結ぶ」は不自然になる。", "から": "起点を表し、「ひもから結ぶ」は意味が通らない。", "が": "主語を示すが、「ひもが結ばない」は文の主語として合わない。"}, "error_tags": {"へ": "方向の誤り", "から": "起点の誤り", "が": "主語の誤り"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解く", "is_correct": true, "explanation": "ネクタイなどの結び目をほどく意味で、「結ぶ」の対義語として辞書に載る。"}, {"text": "押す", "is_correct": false, "explanation": "力を加える意味で、「結ぶ」との対義関係はない。"}, {"text": "掛ける", "is_correct": false, "explanation": "物を引っかける意味で、「結ぶ」との対義関係はない。"}, {"text": "開く", "is_correct": false, "explanation": "閉じたものを広げる意味で、「結ぶ」との対義関係はない。"}], "correct_answer": "解く", "explanations": {"解く": "ネクタイなどの結び目をほどく意味で、「結ぶ」の対義語として辞書に載る。", "押す": "力を加える意味で、「結ぶ」との対義関係はない。", "掛ける": "物を引っかける意味で、「結ぶ」との対義関係はない。", "開く": "閉じたものを広げる意味で、「結ぶ」との対義関係はない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37080, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "二つのものを一つにつなげる。", "primary_collocate": null, "pronunciation": "むすぶ", "ipa": "mɯsɯbɯ", "syllable_count": 3, "sentences": [{"text": "靴ひもをしっかり結んでから、走り出した。", "target_word": "結んで", "complexity_tier": "T3", "furigana": "靴[くつ]ひもをしっかり結[むす]んでから、走[はし]り出[だ]した。", "sentence_source": "generated"}, {"text": "切れたロープの端と端を結んで、もう一度使えるようにした。", "target_word": "結んで", "complexity_tier": "T3", "furigana": "切[き]れたロープの端[はし]と端[はし]を結[むす]んで、もう一度[いちど]使[つか]えるようにした。", "sentence_source": "generated"}, {"text": "点と点を線で結ぶと、きれいな星の形になる。", "target_word": "結ぶ", "complexity_tier": "T3", "furigana": "点[てん]と点[てん]を線[せん]で結[むす]ぶと、きれいな星[ほし]の形[かたち]になる。", "sentence_source": "generated"}, {"text": "この橋は島と本土を結んでいる。", "target_word": "結んでいる", "complexity_tier": "T3", "furigana": "この橋[はし]は島[しま]と本土[ほんど]を結[むす]んでいる。", "sentence_source": "generated"}, {"text": "東京と大阪を結ぶ新幹線は、朝早くから走っている。", "target_word": "結ぶ", "complexity_tier": "T3", "furigana": "東京[とうきょう]と大阪[おおさか]を結[むす]ぶ新幹線[しんかんせん]は、朝早[あさはや]くから走[はし]っている。", "sentence_source": "generated"}, {"text": "姉は髪を後ろで結んで、台所に立った。", "target_word": "結んで", "complexity_tier": "T3", "furigana": "姉[あね]は髪[かみ]を後[うし]ろで結[むす]んで、台所[だいどころ]に立[た]った。", "sentence_source": "generated"}, {"text": "贈り物の箱にリボンを結ぶと、ずっと華やかになった。", "target_word": "結ぶ", "complexity_tier": "T3", "furigana": "贈[おく]り物[もの]の箱[はこ]にリボンを結[むす]ぶと、ずっと華[はな]やかになった。", "sentence_source": "generated"}, {"text": "新聞の束をひもで結ばないと、ごみに出せない。", "target_word": "結ばない", "complexity_tier": "T3", "furigana": "新聞[しんぶん]の束[たば]をひもで結[むす]ばないと、ごみに出[だ]せない。", "sentence_source": "generated"}, {"text": "二本の糸を結んでも、細すぎてすぐにほどけてしまう。", "target_word": "結んでも", "complexity_tier": "T3", "furigana": "二本[にほん]の糸[いと]を結[むす]んでも、細[ほそ]すぎてすぐにほどけてしまう。", "sentence_source": "generated"}, {"text": "入学式の朝、父は鏡の前でネクタイを結んだ。", "target_word": "結んだ", "complexity_tier": "T3", "furigana": "入学式[にゅうがくしき]の朝[あさ]、父[ちち]は鏡[かがみ]の前[まえ]でネクタイを結[むす]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "結ぶ", "label": "基本形"}, {"form": "結んだ", "label": "過去形"}, {"form": "結んで", "label": "て形"}, {"form": "結ばない", "label": "否定形"}, {"form": "結べる", "label": "可能形"}, {"form": "結ばれる", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "ひもや線、道などで二つのものをつなぐ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cbca891-b8d0-4115-b6d9-b9455770d26a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37080, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "結んで", "is_correct": true, "explanation": "「〜てから」に続く形で、ひもを結んだ後に走り出す流れに合う。"}, {"text": "結ばず", "is_correct": false, "explanation": "否定の連用形で「〜てから」に続かず、文として成り立たない。"}, {"text": "結べ", "is_correct": false, "explanation": "命令形で、「〜てから」と続けると文が成り立たない。"}, {"text": "結ぼう", "is_correct": false, "explanation": "意志形で、「〜てから」に続けると文が成り立たない。"}], "explanations": {"結んで": "「〜てから」に続く形で、ひもを結んだ後に走り出す流れに合う。", "結ばず": "否定の連用形で「〜てから」に続かず、文として成り立たない。", "結べ": "命令形で、「〜てから」と続けると文が成り立たない。", "結ぼう": "意志形で、「〜てから」に続けると文が成り立たない。"}, "sentence_index": 0, "correct_answer": "結んで"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は落ちてくる箱を両手で結んだ。", "explanation": "ここは〈つかむ〉の意味。手でしっかり受け止めることは掴むで、結ぶは物と物をつなぐ意味では合わない。"}, {"text": "壁に絵を結んで、部屋を飾った。", "explanation": "ここは〈掛ける〉の意味。絵は結ぶのではなく壁に掛けるものなので、この文脈では合わない。"}, {"text": "上着のボタンを結んで閉めた。", "explanation": "ここは〈留める〉の意味。ボタンは結ぶものではなく留めるものなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37080, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "結ぶ", "is_correct": true, "explanation": "「リボンを結ぶと」の形で、飾り付けの条件として続く。"}, {"text": "結べ", "is_correct": false, "explanation": "命令形は「〜と」に続けられず、文が成り立たない。"}, {"text": "結び", "is_correct": false, "explanation": "名詞形で、「〜と、華やかになった」と文が成り立たない。"}, {"text": "結びつけ", "is_correct": false, "explanation": "連用形で、「〜と」に続けると文が成り立たない。"}], "explanations": {"結ぶ": "「リボンを結ぶと」の形で、飾り付けの条件として続く。", "結べ": "命令形は「〜と」に続けられず、文が成り立たない。", "結び": "名詞形で、「〜と、華やかになった」と文が成り立たない。", "結びつけ": "連用形で、「〜と」に続けると文が成り立たない。"}, "sentence_index": 6, "correct_answer": "結ぶ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "司会者は話題を結んで、場を盛り上げた。", "explanation": "ここは〈つなぐ（途切れさせない）〉の意味。話題は結ぶものではないので合わない。"}, {"text": "子どもたちは先生を結んで、写真を撮った。", "explanation": "ここは〈囲む〉の意味。人を取り囲むことは囲むで言い、結ぶは物と物をつなぐ意味では合わないので、この文脈では誤り。"}, {"text": "寒い夜は、窓をしっかり結んで部屋を暖めた。", "explanation": "ここは〈閉める〉の意味。窓は結ぶものではなく閉めるものなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37080, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二つの箱をひもで結ぶで、運びやすくした。", "corrected_sentence": "二つの箱をひもで結んで、運びやすくした。", "error_description": "「結んで」が正しいて形。「結ぶで」は誤った活用形で、て形は「結んで」になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "結んで", "is_correct": true, "explanation": "「ロープの端を結んで」の形で、後の「使えるようにした」へ続くて形。"}, {"text": "結ぶ", "is_correct": false, "explanation": "基本形では「〜て、もう一度使えるようにした」と続かない。"}, {"text": "結ぼう", "is_correct": false, "explanation": "意志形は文を言い切る形で、「〜もう一度使えるようにした」と続く形にならない。"}, {"text": "結ばない", "is_correct": false, "explanation": "否定形では、ロープを結ぶ動作の実行と逆の意味になる。"}], "correct_form": "結んで", "base_form": "結ぶ", "form_label": "て形", "sentence_index": 1, "explanations": {"結んで": "「ロープの端を結んで」の形で、後の「使えるようにした」へ続くて形。", "結ぶ": "基本形では「〜て、もう一度使えるようにした」と続かない。", "結ぼう": "意志形は文を言い切る形で、「〜もう一度使えるようにした」と続く形にならない。", "結ばない": "否定形では、ロープを結ぶ動作の実行と逆の意味になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37080, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小さな箱にリボンを結ぼると、ぐっと華やかになる。", "corrected_sentence": "小さな箱にリボンを結ぶと、ぐっと華やかになる。", "error_description": "「結ぶと」が正しい（辞書形＋と）。「結ぼると」は存在しない活用形で、誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "結ばない", "is_correct": true, "explanation": "否定形で「〜ないと」の形を取り、結ばないと困る意味に合う。"}, {"text": "結べ", "is_correct": false, "explanation": "命令形は「〜ないと」に続けられず、文が成り立たない。"}, {"text": "結ばれる", "is_correct": false, "explanation": "受身形になり、ひもを結ぶ主体が変わってしまう。"}, {"text": "結んで", "is_correct": false, "explanation": "て形では「〜ないと」と続かず、文が成り立たない。"}], "correct_form": "結ばない", "base_form": "結ぶ", "form_label": "否定形", "sentence_index": 7, "explanations": {"結ばない": "否定形で「〜ないと」の形を取り、結ばないと困る意味に合う。", "結べ": "命令形は「〜ないと」に続けられず、文が成り立たない。", "結ばれる": "受身形になり、ひもを結ぶ主体が変わってしまう。", "結んで": "て形では「〜ないと」と続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37082, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『掛け橋になった』の『に』。なる先を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。『掛け橋がなった』は文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。『なる』は目的語を取らないため誤り。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。『掛け橋でなった』は状態の変化を表せない。"}], "correct_answer": "に", "explanations": {"に": "『掛け橋になった』の『に』。なる先を示す。", "が": "主語を示す。『掛け橋がなった』は文が成り立たない。", "を": "目的語を示す。『なる』は目的語を取らないため誤り。", "で": "手段や場所を示す。『掛け橋でなった』は状態の変化を表せない。"}, "error_tags": {"が": "主語（動作主と不一致）", "を": "目的語（なるは取らない）", "で": "手段（変化の表現と合わない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37082, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『掛け橋になる』の『に』。なる先を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。『なる』は目的語を取らないため誤り。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。比べる文脈がなく不自然。"}, {"text": "の", "is_correct": false, "explanation": "修飾を示す。『掛け橋のなる』は文として成立しない。"}], "correct_answer": "に", "explanations": {"に": "『掛け橋になる』の『に』。なる先を示す。", "を": "目的語を示す。『なる』は目的語を取らないため誤り。", "より": "比較を示す。比べる文脈がなく不自然。", "の": "修飾を示す。『掛け橋のなる』は文として成立しない。"}, "error_tags": {"を": "目的語（なるは取らない）", "より": "比較（比べる対象なし）", "の": "修飾（なるとつながらない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37082, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ふたつのものを、真ん中でつなぐ役割をするものです。", "primary_collocate": null, "pronunciation": "かけはし", "ipa": "kakehaɕi", "syllable_count": 4, "sentences": [{"text": "この商店街は、古い町と新しい町をつなぐ掛け橋だ。", "target_word": "掛け橋", "complexity_tier": "T3", "furigana": "この商店街[しょうてんがい]は、古[ふる]い町[まち]と新[あたら]しい町[まち]をつなぐ掛[か]け橋[はし]だ。", "sentence_source": "generated"}, {"text": "翻訳された本は、二つの国の文化の掛け橋になった。", "target_word": "掛け橋", "complexity_tier": "T3", "furigana": "翻訳[ほんやく]された本[ほん]は、二[ふた]つの国[くに]の文化[ぶんか]の掛[か]け橋[はし]になった。", "sentence_source": "generated"}, {"text": "音楽は、国や年齢の違う人たちの心をつなぐ掛け橋だと思う。", "target_word": "掛け橋", "complexity_tier": "T3", "furigana": "音楽[おんがく]は、国[くに]や年齢[ねんれい]の違[ちが]う人[ひと]たちの心[こころ]をつなぐ掛[か]け橋[はし]だと思[おも]う。", "sentence_source": "generated"}, {"text": "駅前の広場が、学校と地域の掛け橋として使われている。", "target_word": "掛け橋", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の広場[ひろば]が、学校[がっこう]と地域[ちいき]の掛[か]け橋[はし]として使[つか]われている。", "sentence_source": "generated"}, {"text": "手紙は、離れて暮らす家族の掛け橋になっている。", "target_word": "掛け橋", "complexity_tier": "T3", "furigana": "手紙[てがみ]は、離[はな]れて暮[く]らす家族[かぞく]の掛[か]け橋[はし]になっている。", "sentence_source": "generated"}, {"text": "昔の物語は、過去と今をつなぐ掛け橋のような存在だ。", "target_word": "掛け橋", "complexity_tier": "T3", "furigana": "昔[むかし]の物語[ものがたり]は、過去[かこ]と今[いま]をつなぐ掛[か]け橋[はし]のような存在[そんざい]だ。", "sentence_source": "generated"}, {"text": "彼は日本とブラジルの掛け橋になりたいと言った。", "target_word": "掛け橋", "complexity_tier": "T3", "furigana": "彼[かれ]は日本[にほん]とブラジルの掛[か]け橋[はし]になりたいと言[い]った。", "sentence_source": "generated"}, {"text": "絵本は、親と子の心の掛け橋になる。", "target_word": "掛け橋", "complexity_tier": "T3", "furigana": "絵本[えほん]は、親[おや]と子[こ]の心[こころ]の掛[か]け橋[はし]になる。", "sentence_source": "generated"}, {"text": "このイベントは、都会と田舎の掛け橋を目指している。", "target_word": "掛け橋", "complexity_tier": "T3", "furigana": "このイベントは、都会[とかい]と田舎[いなか]の掛[か]け橋[はし]を目指[めざ]している。", "sentence_source": "generated"}, {"text": "スポーツは言葉が通じなくても、人と人の掛け橋になれる。", "target_word": "掛け橋", "complexity_tier": "T3", "furigana": "スポーツは言葉[ことば]が通[つう]じなくても、人[ひと]と人[ひと]の掛[か]け橋[はし]になれる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "掛け橋", "label": "基本形"}], "register": "中立", "sense_fingerprint": "離れた二つのものをつなぐ役目をするもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6723961-33ca-4712-8f1a-8170a5f30020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37082, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "掛け橋", "is_correct": true, "explanation": "二つのものをつなぐ役目をするものを表し、『町と町をつなぐ〜だ』に合う。"}, {"text": "迷路", "is_correct": false, "explanation": "入り組んだ道の意味で、町をつなぐ役目とは合わない。"}, {"text": "水槽", "is_correct": false, "explanation": "魚などを入れる容器で、町をつなぐ文脈に合わない。"}, {"text": "屋根", "is_correct": false, "explanation": "建物の上を覆うもので、町をつなぐ意味にならない。"}], "explanations": {"掛け橋": "二つのものをつなぐ役目をするものを表し、『町と町をつなぐ〜だ』に合う。", "迷路": "入り組んだ道の意味で、町をつなぐ役目とは合わない。", "水槽": "魚などを入れる容器で、町をつなぐ文脈に合わない。", "屋根": "建物の上を覆うもので、町をつなぐ意味にならない。"}, "sentence_index": 0, "correct_answer": "掛け橋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国境は、二つの国の掛け橋として働いている。", "explanation": "〈境界〉と混同した形。国境は二国を隔てるもので、つなぐ『掛け橋』とは逆になる。"}, {"text": "この高い壁は、古い町と新しい町の掛け橋だ。", "explanation": "〈壁〉と混同。遮るものなので、つなぐ『掛け橋』とは言わない。"}, {"text": "戦争は、二つの国の掛け橋になった。", "explanation": "〈分断〉と混同。国を引き裂く結果で、つなぐ『掛け橋』とは逆の内容になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37082, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掛け橋", "is_correct": true, "explanation": "二つのものをつなぐ役目をするものを表し、『日本とブラジルの〜になりたい』に合う。"}, {"text": "花瓶", "is_correct": false, "explanation": "花を生ける容器で、国同士をつなぐ意味にならない。"}, {"text": "墓石", "is_correct": false, "explanation": "墓に立てる石で、国の関係を表す文脈に合わない。"}, {"text": "断崖", "is_correct": false, "explanation": "切り立った崖の意味で、つなぐ役目とは逆の内容になる。"}], "explanations": {"掛け橋": "二つのものをつなぐ役目をするものを表し、『日本とブラジルの〜になりたい』に合う。", "花瓶": "花を生ける容器で、国同士をつなぐ意味にならない。", "墓石": "墓に立てる石で、国の関係を表す文脈に合わない。", "断崖": "切り立った崖の意味で、つなぐ役目とは逆の内容になる。"}, "sentence_index": 6, "correct_answer": "掛け橋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二人の間の掛け橋を深めた。", "explanation": "〈溝〉と混同。溝は深まるもので、掛け橋を深めるとは言わない。"}, {"text": "二人の関係に掛け橋が入った。", "explanation": "〈亀裂が入る〉と混同。亀裂は入るが、掛け橋が入るとは言わない。"}, {"text": "二つの部屋を隔てるのは、掛け橋の役割だ。", "explanation": "〈仕切り〉と混同。部屋を分けるものは、つなぐ『掛け橋』の役割ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37082, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母の手紙は、遠くに住む家族の掛け橋をなった。", "corrected_sentence": "祖母の手紙は、遠くに住む家族の掛け橋になった。", "error_description": "『なる』は『〜になる』の形で、『掛け橋』の後に『に』が必要。『掛け橋を』は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37082, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二人の間の掛け橋を、友人が頑張った。", "corrected_sentence": "二人の間の掛け橋として、友人が頑張った。", "error_description": "『頑張る』は目的語を取らない。役割は『として』で表すので、『掛け橋を』は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37083, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『掛け橋になってくれた』の『に』。なる先を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。『掛け橋がなってくれた』は主語が合わず成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。『なる』は目的語を取らないため誤り。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。『掛け橋でなってくれた』は役割の変化を表せない。"}], "correct_answer": "に", "explanations": {"に": "『掛け橋になってくれた』の『に』。なる先を示す。", "が": "主語を示す。『掛け橋がなってくれた』は主語が合わず成り立たない。", "を": "目的語を示す。『なる』は目的語を取らないため誤り。", "で": "手段や場所を示す。『掛け橋でなってくれた』は役割の変化を表せない。"}, "error_tags": {"が": "主語（動作主と不一致）", "を": "目的語（なるは取らない）", "で": "手段（変化の表現と合わない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37083, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『工場の掛け橋』の『の』。工場と掛け橋を結ぶ修飾の関係を示す。"}, {"text": "に", "is_correct": false, "explanation": "相手や方向を示す。『工場に掛け橋』では名詞同士が結ばれず不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。『工場から掛け橋』は工場から出たものの意味になり合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。比べる文脈がなく不自然。"}], "correct_answer": "の", "explanations": {"の": "『工場の掛け橋』の『の』。工場と掛け橋を結ぶ修飾の関係を示す。", "に": "相手や方向を示す。『工場に掛け橋』では名詞同士が結ばれず不自然。", "から": "起点を示す。『工場から掛け橋』は工場から出たものの意味になり合わない。", "より": "比較を示す。比べる文脈がなく不自然。"}, "error_tags": {"に": "方向・相手（名詞の結びつかない）", "から": "起点（意味が合わない）", "より": "比較（比べる対象なし）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37083, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "両者の間を取り持つ役割を果たすもの。仲介役。", "primary_collocate": null, "pronunciation": "かけはし", "ipa": "kakehaɕi", "syllable_count": 4, "sentences": [{"text": "彼女は新入社員と先輩の掛け橋として、いつも双方の話を聞いている。", "target_word": "掛け橋", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は新入社員[しんにゅうしゃいん]と先輩[せんぱい]の掛[か]け橋[はし]として、いつも双方[そうほう]の話[はなし]を聞[き]いている。", "sentence_source": "generated"}, {"text": "姉は、けんかした両親と私の間の掛け橋になってくれた。", "target_word": "掛け橋", "complexity_tier": "T3", "furigana": "姉[あね]は、けんかした両親[りょうしん]と私[わたし]の間[あいだ]の掛[か]け橋[はし]になってくれた。", "sentence_source": "generated"}, {"text": "大使は二つの国の掛け橋として、会談を成功させた。", "target_word": "掛け橋", "complexity_tier": "T3", "furigana": "大使[たいし]は二[ふた]つの国[くに]の掛[か]け橋[はし]として、会談[かいだん]を成功[せいこう]させた。", "sentence_source": "generated"}, {"text": "私は留学生と地元の学生の掛け橋を務めている。", "target_word": "掛け橋", "complexity_tier": "T3", "furigana": "私[わたし]は留学生[りゅうがくせい]と地元[じもと]の学生[がくせい]の掛[か]け橋[はし]を務[つと]めている。", "sentence_source": "generated"}, {"text": "通訳者は、話す人と聞く人の掛け橋だ。", "target_word": "掛け橋", "complexity_tier": "T3", "furigana": "通訳者[つうやくしゃ]は、話[はな]す人[ひと]と聞[き]く人[ひと]の掛[か]け橋[はし]だ。", "sentence_source": "generated"}, {"text": "担任の先生が、保護者と学校の掛け橋になった。", "target_word": "掛け橋", "complexity_tier": "T3", "furigana": "担任[たんにん]の先生[せんせい]が、保護者[ほごしゃ]と学校[がっこう]の掛[か]け橋[はし]になった。", "sentence_source": "generated"}, {"text": "社長と社員の掛け橋になる人が、会社には必要だ。", "target_word": "掛け橋", "complexity_tier": "T3", "furigana": "社長[しゃちょう]と社員[しゃいん]の掛[か]け橋[はし]になる人[ひと]が、会社[かいしゃ]には必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "彼は取引先と工場の掛け橋として、毎日走り回っている。", "target_word": "掛け橋", "complexity_tier": "T3", "furigana": "彼[かれ]は取引先[とりひきさき]と工場[こうじょう]の掛[か]け橋[はし]として、毎日[まいにち]走[はし]り回[まわ]っている。", "sentence_source": "generated"}, {"text": "二人の誤解を解くため、友人が掛け橋になって話し合いの場を作った。", "target_word": "掛け橋", "complexity_tier": "T3", "furigana": "二人[ふたり]の誤解[ごかい]を解[と]くため、友人[ゆうじん]が掛[か]け橋[はし]になって話[はな]し合[あ]いの場[ば]を作[つく]った。", "sentence_source": "generated"}, {"text": "町内会長は、住民と市役所の掛け橋の役割を果たしている。", "target_word": "掛け橋", "complexity_tier": "T3", "furigana": "町内会長[ちょうないかいちょう]は、住民[じゅうみん]と市役所[しやくしょ]の掛[か]け橋[はし]の役割[やくわり]を果[は]たしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "掛け橋", "label": "基本形"}], "register": "中立", "sense_fingerprint": "対立や距離のある両者の間に立って取り持つ仲介役", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6723961-33ca-4712-8f1a-8170a5f30020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37083, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "掛け橋", "is_correct": true, "explanation": "両者の間を取り持つ仲介役を表し、『新入社員と先輩の〜として』に合う。"}, {"text": "屋根", "is_correct": false, "explanation": "覆うものの意味で、人の間を取り持つ役割とは合わない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花を生ける容器で、人の仲介の文脈に合わない。"}, {"text": "迷路", "is_correct": false, "explanation": "入り組んだ道の意味で、仲介役の意味にならない。"}], "explanations": {"掛け橋": "両者の間を取り持つ仲介役を表し、『新入社員と先輩の〜として』に合う。", "屋根": "覆うものの意味で、人の間を取り持つ役割とは合わない。", "花瓶": "花を生ける容器で、人の仲介の文脈に合わない。", "迷路": "入り組んだ道の意味で、仲介役の意味にならない。"}, "sentence_index": 0, "correct_answer": "掛け橋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二人の掛け橋として、相手を殴った。", "explanation": "〈仲裁〉と混同した形。仲裁は争いを止める役だが、相手を殴る行為は取り持つ役割とは結びつかないため、掛け橋とは合わない。"}, {"text": "二人を対立させる掛け橋になってしまった。", "explanation": "〈対立を深める〉と混同。仲介役は両者を結ぶ役で、対立させる役ではない。"}, {"text": "試合の掛け橋として、相手チームと戦った。", "explanation": "〈対戦相手〉と混同。仲介役は対戦相手にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37083, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掛け橋", "is_correct": true, "explanation": "両者の間を取り持つ役割を表し、『〜になる人が必要だ』に合う。"}, {"text": "墓石", "is_correct": false, "explanation": "墓に立てる石で、社長と社員をつなぐ文脈に合わない。"}, {"text": "断崖", "is_correct": false, "explanation": "切り立った崖の意味で、人の仲介の文脈に合わない。"}, {"text": "水槽", "is_correct": false, "explanation": "魚などを入れる容器で、人の間を取り持つ意味にならない。"}], "explanations": {"掛け橋": "両者の間を取り持つ役割を表し、『〜になる人が必要だ』に合う。", "墓石": "墓に立てる石で、社長と社員をつなぐ文脈に合わない。", "断崖": "切り立った崖の意味で、人の仲介の文脈に合わない。", "水槽": "魚などを入れる容器で、人の間を取り持つ意味にならない。"}, "sentence_index": 6, "correct_answer": "掛け橋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は生徒の掛け橋として、教室の中を見張っている。", "explanation": "〈監視役〉と混同。見張る役は両者を取り持つ仲介役ではない。"}, {"text": "彼は門の掛け橋として、入口に立っている。", "explanation": "〈門番〉と混同。通す・止める役で、取り持つ仲介役とは違う。"}, {"text": "二人の間に掛け橋が立ちはだかっている。", "explanation": "〈障壁〉と混同。立ちはだかるのは障害で、仲介役は立ちはだからない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37083, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は新人と先輩の掛け橋に、毎朝指導を続けている。", "corrected_sentence": "彼は新人と先輩の掛け橋として、毎朝指導を続けている。", "error_description": "役割を表すには『〜として』を使う。『掛け橋に』は『なる』と結ぶ形で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37083, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は取引先と工場の掛け橋が務めている。", "corrected_sentence": "彼は取引先と工場の掛け橋を務めている。", "error_description": "『務める』は目的語に『を』を取る。『掛け橋が』は誤りで、正しくは『掛け橋を』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37084, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「部屋に運ぶ」で、到着点を示す。"}, {"text": "を", "is_correct": false, "explanation": "「部屋を運ぶ」は場所を目的語にする形になり、机を目的語とする文と二重になる。"}, {"text": "の", "is_correct": false, "explanation": "「部屋の運んで」は連体修飾として文が続かない。"}, {"text": "より", "is_correct": false, "explanation": "比較の意味になり、到着点を示す文脈に合わない。"}], "correct_answer": "に", "explanations": {"に": "「部屋に運ぶ」で、到着点を示す。", "を": "「部屋を運ぶ」は場所を目的語にする形になり、机を目的語とする文と二重になる。", "の": "「部屋の運んで」は連体修飾として文が続かない。", "より": "比較の意味になり、到着点を示す文脈に合わない。"}, "error_tags": {"を": "二重の目的語の誤り", "の": "連体修飾の誤り", "より": "比較の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37084, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "「病院へ運ぶ」で、移動先を示す。"}, {"text": "で", "is_correct": false, "explanation": "場所を示すが、移動先にはならず「病院で運んだ」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "相手を示すが、「病院と運んだ」は移動先の意味にならない。"}, {"text": "を", "is_correct": false, "explanation": "目的語が重なり、「人を病院を運んだ」は文として成り立たない。"}], "correct_answer": "へ", "explanations": {"へ": "「病院へ運ぶ」で、移動先を示す。", "で": "場所を示すが、移動先にはならず「病院で運んだ」は意味が通らない。", "と": "相手を示すが、「病院と運んだ」は移動先の意味にならない。", "を": "目的語が重なり、「人を病院を運んだ」は文として成り立たない。"}, "error_tags": {"で": "場所の誤り", "と": "相手・並列の誤り", "を": "目的語の重複の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37084, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものを、どこかへ はこぶ。", "primary_collocate": null, "pronunciation": "はこぶ", "ipa": "hakobɯ", "syllable_count": 3, "sentences": [{"text": "重い荷物を二階まで運びます。", "target_word": "運びます", "complexity_tier": "T3", "furigana": "重[おも]い荷物[にもつ]を二階[にかい]まで運[はこ]びます。", "sentence_source": "generated"}, {"text": "引っ越しの日、友達が大きな机を部屋に運んでくれた。", "target_word": "運んで", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの日[ひ]、友達[ともだち]が大[おお]きな机[つくえ]を部屋[へや]に運[はこ]んでくれた。", "sentence_source": "generated"}, {"text": "雨が降りそうなので、洗濯物を家の中に運んだ。", "target_word": "運んだ", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]りそうなので、洗濯物[せんたくもの]を家[いえ]の中[なか]に運[はこ]んだ。", "sentence_source": "generated"}, {"text": "このカートを使えば、重い本も楽に運べる。", "target_word": "運べる", "complexity_tier": "T3", "furigana": "このカートを使[つか]えば、重[おも]い本[ほん]も楽[らく]に運[はこ]べる。", "sentence_source": "generated"}, {"text": "店員は料理をテーブルまで運んでいる。", "target_word": "運んで", "complexity_tier": "T3", "furigana": "店員[てんいん]は料理[りょうり]をテーブルまで運[はこ]んでいる。", "sentence_source": "generated"}, {"text": "力が弱くて、一人ではこの箱を運べません。", "target_word": "運べません", "complexity_tier": "T3", "furigana": "力[ちから]が弱[よわ]くて、一人[ひとり]ではこの箱[はこ]を運[はこ]べません。", "sentence_source": "generated"}, {"text": "工事の人がトラックで砂を運んでいます。", "target_word": "運んで", "complexity_tier": "T3", "furigana": "工事[こうじ]の人[ひと]がトラックで砂[すな]を運[はこ]んでいます。", "sentence_source": "generated"}, {"text": "けがをした人を車で病院へ運んだ。", "target_word": "運んだ", "complexity_tier": "T3", "furigana": "けがをした人[ひと]を車[くるま]で病院[びょういん]へ運[はこ]んだ。", "sentence_source": "generated"}, {"text": "毎朝、牛乳を店まで運ぶのが私の仕事です。", "target_word": "運ぶ", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、牛乳[ぎゅうにゅう]を店[みせ]まで運[はこ]ぶのが私[わたし]の仕事[しごと]です。", "sentence_source": "generated"}, {"text": "この机は重いから、二人で運ぼう。", "target_word": "運ぼう", "complexity_tier": "T3", "furigana": "この机[つくえ]は重[おも]いから、二人[ふたり]で運[はこ]ぼう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "運ぶ", "label": "dictionary form"}, {"form": "運びます", "label": "polite form"}, {"form": "運んで", "label": "te-form"}, {"form": "運んだ", "label": "past form"}, {"form": "運ばない", "label": "negative form"}, {"form": "運べる", "label": "potential form"}], "register": "neutral", "sense_fingerprint": "物を別の場所へ持って行く、移す(物の移動)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cbca891-b8d0-4115-b6d9-b9455770d26a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37084, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "運びます", "is_correct": true, "explanation": "丁寧な終止形で、「二階まで運びます。」として文を終えられる。"}, {"text": "運んで", "is_correct": false, "explanation": "て形は文を終えられず、「二階まで運んで。」として不完全になる。"}, {"text": "運ばず", "is_correct": false, "explanation": "否定の連用形は文を終えられず、文として成り立たない。"}, {"text": "運ばれ", "is_correct": false, "explanation": "受身の連用形は文を終えられず、意味も主語の関係が変わる。"}], "explanations": {"運びます": "丁寧な終止形で、「二階まで運びます。」として文を終えられる。", "運んで": "て形は文を終えられず、「二階まで運んで。」として不完全になる。", "運ばず": "否定の連用形は文を終えられず、文として成り立たない。", "運ばれ": "受身の連用形は文を終えられず、意味も主語の関係が変わる。"}, "sentence_index": 0, "correct_answer": "運びます"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店員は客の苦情を運んで、丁寧に対応した。", "explanation": "ここは〈扱う・対応する〉の意味。苦情は運ぶものではなく扱うものなので、この文脈では合わない。"}, {"text": "社長は会社の責任を一人で運んでいる。", "explanation": "ここは〈担う〉の意味。責任は運ぶものではなく担うものなので、この文脈では合わない。"}, {"text": "お礼の言葉を、先生に運んだ。", "explanation": "ここは〈伝え届ける〉の意味。言葉は運ぶものではなく届けるものなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37084, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "運んで", "is_correct": true, "explanation": "「運んでいます」の形で、砂を運んでいる最中の動作を表す。"}, {"text": "運べ", "is_correct": false, "explanation": "命令形では「運べいます」となり、「いる」に続かない。"}, {"text": "運ばせ", "is_correct": false, "explanation": "使役の連用形では「いる」に続かず、文が成り立たない。"}, {"text": "運ぼう", "is_correct": false, "explanation": "意志形では「運ぼういます」となり、「いる」に続かない。"}], "explanations": {"運んで": "「運んでいます」の形で、砂を運んでいる最中の動作を表す。", "運べ": "命令形では「運べいます」となり、「いる」に続かない。", "運ばせ": "使役の連用形では「いる」に続かず、文が成り立たない。", "運ぼう": "意志形では「運ぼういます」となり、「いる」に続かない。"}, "sentence_index": 6, "correct_answer": "運んで"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎週、図書館を運んで勉強している。", "explanation": "ここは〈通う〉の意味。決まった場所へ繰り返し行くことは通うで言い、運ぶとは言わないので合わない。"}, {"text": "書類は、メールで運んだ。", "explanation": "ここは〈送る〉の意味。メールは運ぶものではなく送るものなので合わない。"}, {"text": "別れ際に、手を大きく運んだ。", "explanation": "ここは〈振る〉の意味。手は運ぶものではなく振るものなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37084, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "重い箱を、一人で部屋まで運べれた。", "corrected_sentence": "重い箱を、一人で部屋まで運べた。", "error_description": "「運べた」が正しい。「運べれた」は可能形「運べる」にさらに「れる」を重ねた誤り（ら抜き言葉の二重化）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "運んで", "is_correct": true, "explanation": "「机を部屋に運んでくれた」の形で、て形から「くれた」へ続く。"}, {"text": "運ぶ", "is_correct": false, "explanation": "基本形では「運ぶくれた」となり、「くれた」に続かない。"}, {"text": "運んだ", "is_correct": false, "explanation": "過去形では「くれた」と続かず、文の形が合わない。"}, {"text": "運ばない", "is_correct": false, "explanation": "否定形では、運ぶ動作を行った事実と逆の意味になる。"}], "correct_form": "運んで", "base_form": "運ぶ", "form_label": "て形", "sentence_index": 1, "explanations": {"運んで": "「机を部屋に運んでくれた」の形で、て形から「くれた」へ続く。", "運ぶ": "基本形では「運ぶくれた」となり、「くれた」に続かない。", "運んだ": "過去形では「くれた」と続かず、文の形が合わない。", "運ばない": "否定形では、運ぶ動作を行った事実と逆の意味になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37084, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "重い棚を、二人で部屋の奥へ運ぶた。", "corrected_sentence": "重い棚を、二人で部屋の奥へ運んだ。", "error_description": "過去形は「運んだ」が正しい。「運ぶた」は誤った活用形で、存在しない形。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "運んだ", "is_correct": true, "explanation": "過去形で、「けがをした人を病院へ運んだ」と完了した動作を表す。"}, {"text": "運ばず", "is_correct": false, "explanation": "否定の連用形は文を言い切れず、「運ばず。」として不完全になる。"}, {"text": "運んで", "is_correct": false, "explanation": "て形では文を終えられず、「運んで。」として不完全になる。"}, {"text": "運ばれ", "is_correct": false, "explanation": "受身の連用形は文を言い切れず、「運ばれ。」として不完全になる。"}], "correct_form": "運んだ", "base_form": "運ぶ", "form_label": "過去形", "sentence_index": 7, "explanations": {"運んだ": "過去形で、「けがをした人を病院へ運んだ」と完了した動作を表す。", "運ばず": "否定の連用形は文を言い切れず、「運ばず。」として不完全になる。", "運んで": "て形では文を終えられず、「運んで。」として不完全になる。", "運ばれ": "受身の連用形は文を言い切れず、「運ばれ。」として不完全になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37086, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「車を買う」で、買う動作の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「新しい車が買いました」は、車が買う主体になり文の意味が合わない。"}, {"text": "に", "is_correct": false, "explanation": "「車に買う」は対象の関係にならず、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「車と買う」は共同の意味になり、文の意味が合わない。"}], "correct_answer": "を", "explanations": {"を": "「車を買う」で、買う動作の目的語を示す。", "が": "「新しい車が買いました」は、車が買う主体になり文の意味が合わない。", "に": "「車に買う」は対象の関係にならず、不自然。", "と": "「車と買う」は共同の意味になり、文の意味が合わない。"}, "error_tags": {"が": "主語の誤り", "に": "方向・対象の誤り", "と": "並列・相手の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
