INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37086, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人がのったり、ものをのせたりするのりものです。", "primary_collocate": null, "pronunciation": "くるま", "ipa": "kɯɾɯma", "syllable_count": 3, "sentences": [{"text": "駅まで車で迎えに行きます。", "target_word": "車", "complexity_tier": "T3", "furigana": "駅[えき]まで車[くるま]で迎[むか]えに行[い]きます。", "sentence_source": "generated"}, {"text": "父は新しい車を買いました。", "target_word": "車", "complexity_tier": "T3", "furigana": "父[ちち]は新[あたら]しい車[くるま]を買[か]いました。", "sentence_source": "generated"}, {"text": "車の後ろに大きな荷物をのせた。", "target_word": "車", "complexity_tier": "T3", "furigana": "車[くるま]の後[うし]ろに大[おお]きな荷物[にもつ]をのせた。", "sentence_source": "generated"}, {"text": "雨の日は、車に乗って学校へ行く人が多い。", "target_word": "車", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、車[くるま]に乗[の]って学校[がっこう]へ行[い]く人[ひと]が多[おお]い。", "sentence_source": "generated"}, {"text": "道がせまいので、大きい車は通れません。", "target_word": "車", "complexity_tier": "T3", "furigana": "道[みち]がせまいので、大[おお]きい車[くるま]は通[とお]れません。", "sentence_source": "generated"}, {"text": "私は車がないので、どこへでも歩いて行きます。", "target_word": "車", "complexity_tier": "T3", "furigana": "私[わたし]は車[くるま]がないので、どこへでも歩[ある]いて行[い]きます。", "sentence_source": "generated"}, {"text": "車の中で弟は寝てしまった。", "target_word": "車", "complexity_tier": "T3", "furigana": "車[くるま]の中[なか]で弟[おとうと]は寝[ね]てしまった。", "sentence_source": "generated"}, {"text": "大きな車なら、家族みんなが乗れる。", "target_word": "車", "complexity_tier": "T3", "furigana": "大[おお]きな車[くるま]なら、家族[かぞく]みんなが乗[の]れる。", "sentence_source": "generated"}, {"text": "車を止めて、少し休みましょう。", "target_word": "車", "complexity_tier": "T3", "furigana": "車[くるま]を止[と]めて、少[すこ]し休[やす]みましょう。", "sentence_source": "generated"}, {"text": "兄は毎日、車で会社に通っている。", "target_word": "車", "complexity_tier": "T3", "furigana": "兄[あに]は毎日[まいにち]、車[くるま]で会社[かいしゃ]に通[かよ]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "車", "label": "base form"}], "register": "neutral", "sense_fingerprint": "人や荷物をのせて移動する乗り物(自動車を中心とする)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cbca891-b8d0-4115-b6d9-b9455770d26a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37086, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "車", "is_correct": true, "explanation": "「駅まで車で迎えに行きます」で、移動の手段を表す。"}, {"text": "空港", "is_correct": false, "explanation": "場所の名詞で、移動の手段として「空港で迎えに行く」は成り立たない。"}, {"text": "花瓶", "is_correct": false, "explanation": "移動の手段にならず、「花瓶で迎えに行く」は意味が通らない。"}, {"text": "電池", "is_correct": false, "explanation": "移動の手段にならず、「電池で迎えに行く」は不自然。"}], "explanations": {"車": "「駅まで車で迎えに行きます」で、移動の手段を表す。", "空港": "場所の名詞で、移動の手段として「空港で迎えに行く」は成り立たない。", "花瓶": "移動の手段にならず、「花瓶で迎えに行く」は意味が通らない。", "電池": "移動の手段にならず、「電池で迎えに行く」は不自然。"}, "sentence_index": 0, "correct_answer": "車"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この時計の車が止まってしまった。", "explanation": "ここは〈乗り物〉の意味。時計の部品は車ではなく歯車と言うので、この文脈では誤り。"}, {"text": "船は海を進む車だ。", "explanation": "ここは〈陸上の車両〉の意味。海を進む船は車とは呼ばないので、この文脈では合わない。"}, {"text": "大事な書類を、車の袋に入れて持ち歩いた。", "explanation": "ここは〈乗り物〉の意味。書類を入れる袋は車とは言わず、乗り物の意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37086, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "車", "is_correct": true, "explanation": "「車の中で寝てしまった」で、弟がいた場所を示す。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "人が寝る場所としては成り立たず、「冷蔵庫の中で寝てしまった」は不自然。"}, {"text": "金庫", "is_correct": false, "explanation": "人が寝る場所としては成り立たず、文の意味が合わない。"}, {"text": "鍋", "is_correct": false, "explanation": "人が寝る場所としては成り立たず、文として不自然。"}], "explanations": {"車": "「車の中で寝てしまった」で、弟がいた場所を示す。", "冷蔵庫": "人が寝る場所としては成り立たず、「冷蔵庫の中で寝てしまった」は不自然。", "金庫": "人が寝る場所としては成り立たず、文の意味が合わない。", "鍋": "人が寝る場所としては成り立たず、文として不自然。"}, "sentence_index": 6, "correct_answer": "車"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この建物の車は、三階まで続いている。", "explanation": "ここは〈乗り物〉の意味。階段は車とは言わないので、この文脈では誤り。"}, {"text": "扇風機の車が回らないので、部屋が暑い。", "explanation": "ここは〈乗り物〉の意味。扇風機の羽根は車とは呼ばないので、この文脈では合わない。"}, {"text": "ネックレスの車が外れてしまった。", "explanation": "ここは〈乗り物〉の意味。留め具は車とは言わないので、この文脈では誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37086, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の日は、車を乗って出かける。", "corrected_sentence": "雨の日は、車に乗って出かける。", "error_description": "「乗る」は「〜に乗る」の形を取るので、「車」には「に」が付く。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37086, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大きな車を乗って、家族で旅行した。", "corrected_sentence": "大きな車に乗って、家族で旅行した。", "error_description": "「乗って」は「〜に乗って」の形を取るので、乗り物の「車」には「に」が付く。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37087, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37087, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「車で二時間走った」の〈で〉。乗り物という手段を示すので自然。"}, {"text": "に", "is_correct": false, "explanation": "「車に二時間走った」は乗り物への移動を示す〈に〉としては不自然。"}, {"text": "と", "is_correct": false, "explanation": "「車と二時間走った」は一緒に行く相手を示すが、乗り物を相手にする意味にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「車へ二時間走った」は方向を示す〈へ〉だが、手段を表す文脈に合わない。"}], "correct_answer": "で", "explanations": {"で": "「車で二時間走った」の〈で〉。乗り物という手段を示すので自然。", "に": "「車に二時間走った」は乗り物への移動を示す〈に〉としては不自然。", "と": "「車と二時間走った」は一緒に行く相手を示すが、乗り物を相手にする意味にはならない。", "へ": "「車へ二時間走った」は方向を示す〈へ〉だが、手段を表す文脈に合わない。"}, "error_tags": {"に": "場所・乗り込み", "と": "相手・同伴", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37087, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人や物を運ぶための乗り物。タイヤがついていて、道を走る。", "primary_collocate": null, "pronunciation": "くるま", "ipa": "kɯɾɯma", "syllable_count": 3, "sentences": [{"text": "赤い車が信号の前で止まった。", "target_word": "車", "complexity_tier": "T3", "furigana": "赤[あか]い車[くるま]が信号[しんごう]の前[まえ]で止[と]まった。", "sentence_source": "generated"}, {"text": "車はタイヤが四つあって、道を走る。", "target_word": "車", "complexity_tier": "T3", "furigana": "車[くるま]はタイヤが四[よっ]つあって、道[みち]を走[はし]る。", "sentence_source": "generated"}, {"text": "車が多いので、道を渡るときは気をつけてください。", "target_word": "車", "complexity_tier": "T3", "furigana": "車[くるま]が多[おお]いので、道[みち]を渡[わた]るときは気[き]をつけてください。", "sentence_source": "generated"}, {"text": "雪の道では、車がすべりやすい。", "target_word": "車", "complexity_tier": "T3", "furigana": "雪[ゆき]の道[みち]では、車[くるま]がすべりやすい。", "sentence_source": "generated"}, {"text": "この車は小さいが、荷物がたくさん入る。", "target_word": "車", "complexity_tier": "T3", "furigana": "この車[くるま]は小[ちい]さいが、荷物[にもつ]がたくさん入[はい]る。", "sentence_source": "generated"}, {"text": "車のタイヤが古くなったので、新しいのに替えた。", "target_word": "車", "complexity_tier": "T3", "furigana": "車[くるま]のタイヤが古[ふる]くなったので、新[あたら]しいのに替[か]えた。", "sentence_source": "generated"}, {"text": "夜の道を、車の光が明るく照らしていた。", "target_word": "車", "complexity_tier": "T3", "furigana": "夜[よる]の道[みち]を、車[くるま]の光[ひかり]が明[あか]るく照[て]らしていた。", "sentence_source": "generated"}, {"text": "高速道路を車で二時間走った。", "target_word": "車", "complexity_tier": "T3", "furigana": "高速道路[こうそくどうろ]を車[くるま]で二時間[にじかん]走[はし]った。", "sentence_source": "generated"}, {"text": "車を運転するには、免許が必要です。", "target_word": "車", "complexity_tier": "T3", "furigana": "車[くるま]を運転[うんてん]するには、免許[めんきょ]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "店の前には白い車ばかり並んでいた。", "target_word": "車", "complexity_tier": "T3", "furigana": "店[みせ]の前[まえ]には白[しろ]い車[くるま]ばかり並[なら]んでいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "車", "label": "base form"}], "register": "neutral", "sense_fingerprint": "タイヤで道路を走る乗り物(自動車)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cbca891-b8d0-4115-b6d9-b9455770d26a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37087, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "車", "is_correct": true, "explanation": "「赤い車が信号の前で止まった」の主語。道路を走る乗り物として自然に入る。"}, {"text": "花", "is_correct": false, "explanation": "花は自分で動いて信号の前で止まらないので、この空所には入らない。"}, {"text": "机", "is_correct": false, "explanation": "机は動いて止まることがないので、「止まった」と合わない。"}, {"text": "雲", "is_correct": false, "explanation": "雲が信号の前で止まるのは不自然で、文の主語として合わない。"}], "explanations": {"車": "「赤い車が信号の前で止まった」の主語。道路を走る乗り物として自然に入る。", "花": "花は自分で動いて信号の前で止まらないので、この空所には入らない。", "机": "机は動いて止まることがないので、「止まった」と合わない。", "雲": "雲が信号の前で止まるのは不自然で、文の主語として合わない。"}, "sentence_index": 0, "correct_answer": "車"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日は車で空を飛んで、外国へ行く。", "explanation": "ここは〈飛行機〉の話。車は道路を走る乗り物で空は飛べないので、〈飛行機〉を〈車〉に置き換えた誤用になる。"}, {"text": "教室で、黒板を車で消した。", "explanation": "ここは〈黒板消し〉の話。車は黒板を消せないので、〈黒板消し〉の代わりに〈車〉を入れると誤りになる。"}, {"text": "疲れたので、車を一段ずつ上った。", "explanation": "ここは〈階段〉を上る話。車は自分で階段を上れないので、〈階段〉の代わりに〈車〉を入れると誤りになる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37087, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "車", "is_correct": true, "explanation": "「夜の道を、車の光が明るく照らしていた」の〈車〉。車のライトの光を指すので自然。"}, {"text": "机", "is_correct": false, "explanation": "机は光を出さないので、「机の光」は文脈に合わない。"}, {"text": "靴", "is_correct": false, "explanation": "靴は光を出さず、「靴の光」は意味が通らない。"}, {"text": "本", "is_correct": false, "explanation": "本は光を出すものではなく、「本の光」は不自然で文脈に合わない。"}], "explanations": {"車": "「夜の道を、車の光が明るく照らしていた」の〈車〉。車のライトの光を指すので自然。", "机": "机は光を出さないので、「机の光」は文脈に合わない。", "靴": "靴は光を出さず、「靴の光」は意味が通らない。", "本": "本は光を出すものではなく、「本の光」は不自然で文脈に合わない。"}, "sentence_index": 6, "correct_answer": "車"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅のホームに、車がゆっくり入ってきた。", "explanation": "ここは〈電車〉の話。ホームに入ってくるのは電車で、車はレールの上を走れないので、〈電車〉の代わりに〈車〉を入れると誤りになる。"}, {"text": "夏の海で、車が泳いだ。", "explanation": "ここは〈人〉が泳ぐ話。車は泳げないので、主語として〈車〉を置くと合わない。"}, {"text": "車で顔を洗う。", "explanation": "ここは〈洗面所〉で顔を洗う話。車は顔を洗う場所にも道具にもならないので、〈洗面所〉の代わりには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37087, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明日は車を海まで行く予定だ。", "corrected_sentence": "明日は車で海まで行く予定だ。", "error_description": "手段を表す〈で〉が正しい形。〈車を〉は目的語の助詞なので、移動の手段を示す〈車で〉とすべき。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37087, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜の道を車を走ると、ライトがよく見える。", "corrected_sentence": "夜の道を車で走ると、ライトがよく見える。", "error_description": "移動の手段を表す〈で〉が正しい。〈車を〉は目的語の助詞なので、〈車を走る〉は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37088, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "汚い", "is_correct": true, "explanation": "〈奇麗〉の対義語。汚れがある状態を表し、清潔の反対になる。"}, {"text": "硬い", "is_correct": false, "explanation": "〈硬い〉は固さを表すので、汚れの有無の対義語にはならない。"}, {"text": "重い", "is_correct": false, "explanation": "〈重い〉は重さを表すので、清潔さの対義語にはならない。"}, {"text": "暑い", "is_correct": false, "explanation": "〈暑い〉は気温を表すので、汚れの有無とは関係がない。"}], "correct_answer": "汚い", "explanations": {"汚い": "〈奇麗〉の対義語。汚れがある状態を表し、清潔の反対になる。", "硬い": "〈硬い〉は固さを表すので、汚れの有無の対義語にはならない。", "重い": "〈重い〉は重さを表すので、清潔さの対義語にはならない。", "暑い": "〈暑い〉は気温を表すので、汚れの有無とは関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37088, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "汚い", "is_correct": true, "explanation": "〈奇麗〉の対義語。汚れがある状態を表し、清潔の反対になる。"}, {"text": "寒い", "is_correct": false, "explanation": "〈寒い〉は気温を表すので、汚れの有無の対義語にはならない。"}, {"text": "狭い", "is_correct": false, "explanation": "〈狭い〉は広さを表すので、清潔さの対義語にはならない。"}, {"text": "薄い", "is_correct": false, "explanation": "〈薄い〉は厚みや濃さを表すので、汚れの有無とは関係がない。"}], "correct_answer": "汚い", "explanations": {"汚い": "〈奇麗〉の対義語。汚れがある状態を表し、清潔の反対になる。", "寒い": "〈寒い〉は気温を表すので、汚れの有無の対義語にはならない。", "狭い": "〈狭い〉は広さを表すので、清潔さの対義語にはならない。", "薄い": "〈薄い〉は厚みや濃さを表すので、汚れの有無とは関係がない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37088, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "ものが、よごれていないこと。", "primary_collocate": null, "pronunciation": "きれい", "ipa": "kiɾeː", "syllable_count": 3, "sentences": [{"text": "毎日そうじをするので、部屋はいつも奇麗です。", "target_word": "奇麗", "complexity_tier": "T3", "furigana": "毎日[まいにち]そうじをするので、部屋[へや]はいつも奇麗[きれい]です。", "sentence_source": "generated"}, {"text": "手を洗って、奇麗なタオルでふいた。", "target_word": "奇麗", "complexity_tier": "T3", "furigana": "手[て]を洗[あら]って、奇麗[きれい]なタオルでふいた。", "sentence_source": "generated"}, {"text": "奇麗な水で野菜を洗ってください。", "target_word": "奇麗", "complexity_tier": "T3", "furigana": "奇麗[きれい]な水[みず]で野菜[やさい]を洗[あら]ってください。", "sentence_source": "generated"}, {"text": "雨のあとなのに、くつが奇麗なままだった。", "target_word": "奇麗", "complexity_tier": "T3", "furigana": "雨[あめ]のあとなのに、くつが奇麗[きれい]なままだった。", "sentence_source": "generated"}, {"text": "このシャツは洗ったばかりで奇麗だ。", "target_word": "奇麗", "complexity_tier": "T3", "furigana": "このシャツは洗[あら]ったばかりで奇麗[きれい]だ。", "sentence_source": "generated"}, {"text": "机の上を奇麗にしてから、勉強を始めた。", "target_word": "奇麗", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]を奇麗[きれい]にしてから、勉強[べんきょう]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "川の水が奇麗なので、魚がたくさんすんでいる。", "target_word": "奇麗", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]が奇麗[きれい]なので、魚[さかな]がたくさんすんでいる。", "sentence_source": "generated"}, {"text": "汚れた窓をふいたら、奇麗になった。", "target_word": "奇麗", "complexity_tier": "T3", "furigana": "汚[よご]れた窓[まど]をふいたら、奇麗[きれい]になった。", "sentence_source": "generated"}, {"text": "奇麗な服に着がえて、食事をしましょう。", "target_word": "奇麗", "complexity_tier": "T3", "furigana": "奇麗[きれい]な服[ふく]に着[き]がえて、食事[しょくじ]をしましょう。", "sentence_source": "generated"}, {"text": "台所が奇麗だと、料理をするのが楽しい。", "target_word": "奇麗", "complexity_tier": "T3", "furigana": "台所[だいどころ]が奇麗[きれい]だと、料理[りょうり]をするのが楽[たの]しい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "奇麗だ", "label": "plain predicate form"}, {"form": "奇麗です", "label": "polite form"}, {"form": "奇麗な", "label": "attributive form"}, {"form": "奇麗に", "label": "adverbial form"}], "register": "neutral", "sense_fingerprint": "汚れがなく清潔な状態(清潔さ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cbca891-b8d0-4115-b6d9-b9455770d26a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37088, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "奇麗", "is_correct": true, "explanation": "「部屋はいつも奇麗です」の〈奇麗〉。汚れがなく清潔な状態を表すので自然。"}, {"text": "得意", "is_correct": false, "explanation": "「部屋はいつも得意です」は意味が通らず、部屋の状態を表さない。"}, {"text": "不思議", "is_correct": false, "explanation": "「部屋はいつも不思議です」は不自然で、汚れのなさを表さない。"}, {"text": "確か", "is_correct": false, "explanation": "「部屋はいつも確かです」は意味が通らず、清潔さを表さない。"}], "explanations": {"奇麗": "「部屋はいつも奇麗です」の〈奇麗〉。汚れがなく清潔な状態を表すので自然。", "得意": "「部屋はいつも得意です」は意味が通らず、部屋の状態を表さない。", "不思議": "「部屋はいつも不思議です」は不自然で、汚れのなさを表さない。", "確か": "「部屋はいつも確かです」は意味が通らず、清潔さを表さない。"}, "sentence_index": 0, "correct_answer": "奇麗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "宿題を奇麗に忘れてしまった。", "explanation": "ここは〈すっかり〉の意味。〈奇麗〉の定義（汚れがない）とは別の意味で、忘れた程度を表している。"}, {"text": "床には奇麗なしみがべったりついていた。", "explanation": "〈奇麗〉を〈美しい〉の意味に取ると、汚れのしみを褒める文になる。〈奇麗〉は汚れがないことなので、汚れのしみとは矛盾する。"}, {"text": "机の上の本を奇麗に並べてから、出かけた。", "explanation": "ここは〈整然と〉の意味。〈奇麗〉の定義（汚れがない）とは別の意味で使われている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37088, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "奇麗", "is_correct": true, "explanation": "「川の水が奇麗なので」の〈奇麗〉。水が汚れていないことを表し、魚が住める理由になる。"}, {"text": "平気", "is_correct": false, "explanation": "「川の水が平気なので」は理由として意味が通らない。"}, {"text": "元気", "is_correct": false, "explanation": "「川の水が元気なので」は水を生き物のように言う不自然な表現になる。"}, {"text": "不明", "is_correct": false, "explanation": "「川の水が不明なので」は意味が通らず、理由としても成り立たない。"}], "explanations": {"奇麗": "「川の水が奇麗なので」の〈奇麗〉。水が汚れていないことを表し、魚が住める理由になる。", "平気": "「川の水が平気なので」は理由として意味が通らない。", "元気": "「川の水が元気なので」は水を生き物のように言う不自然な表現になる。", "不明": "「川の水が不明なので」は意味が通らず、理由としても成り立たない。"}, "sentence_index": 6, "correct_answer": "奇麗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "借りたお金は奇麗に返して、ほっとした。", "explanation": "ここは〈すっかり〉の意味。〈奇麗〉の定義（汚れがない）とは別の意味で、返す程度を表している。"}, {"text": "かばんの中身を奇麗にまとめて、家を出た。", "explanation": "ここは〈整然と〉の意味。〈奇麗〉の定義（汚れがない）とは別の意味で使われている。"}, {"text": "山の上から見た夕焼けが奇麗だった。", "explanation": "ここは〈美しい〉の意味。〈奇麗〉の定義（汚れがない）とは別の意味で、景色の美しさを表している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37088, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓は奇麗を拭いてあった。", "corrected_sentence": "窓は奇麗に拭いてあった。", "error_description": "〈奇麗〉は動詞〈拭く〉を修飾する副詞形〈奇麗に〉にする必要がある。〈奇麗を〉は目的語の助詞として誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "奇麗だ", "is_correct": false, "explanation": "終止形なので、名詞の前には置けない。「奇麗だタオル」とは言えず、この位置には入らない。"}, {"text": "奇麗です", "is_correct": false, "explanation": "丁寧な終止形で、名詞を修飾できない。「奇麗ですタオル」は成り立たない。"}, {"text": "奇麗な", "is_correct": true, "explanation": "「奇麗なタオル」の〈奇麗な〉。名詞を修飾する連体形で、タオルの前に置くのが正しい。"}, {"text": "奇麗に", "is_correct": false, "explanation": "副詞形で、名詞を直接修飾できない。「奇麗にタオル」は文が成り立たない。"}], "correct_form": "奇麗な", "base_form": "奇麗", "form_label": "連体形", "sentence_index": 1, "explanations": {"奇麗だ": "終止形なので、名詞の前には置けない。「奇麗だタオル」とは言えず、この位置には入らない。", "奇麗です": "丁寧な終止形で、名詞を修飾できない。「奇麗ですタオル」は成り立たない。", "奇麗な": "「奇麗なタオル」の〈奇麗な〉。名詞を修飾する連体形で、タオルの前に置くのが正しい。", "奇麗に": "副詞形で、名詞を直接修飾できない。「奇麗にタオル」は文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37088, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓を奇麗だあと、部屋が明るくなった。", "corrected_sentence": "窓を奇麗にしたあと、部屋が明るくなった。", "error_description": "〈奇麗〉は〈にする〉の形で動作の結果を表す。〈窓を奇麗だ〉は述語として成り立たないので、〈窓を奇麗にした〉とすべき。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "奇麗だった", "is_correct": false, "explanation": "過去の終止形で、「奇麗だったになった」は成り立たない。変化の結果を表す副詞形ではない。"}, {"text": "奇麗じゃない", "is_correct": false, "explanation": "否定形で、「奇麗じゃないになった」は成り立たない。「奇麗じゃなくなった」なら自然だが、この位置には入らない。"}, {"text": "奇麗に", "is_correct": true, "explanation": "「奇麗になった」の〈奇麗に〉。「なる」に続く副詞形で、状態の変化を表す。"}, {"text": "奇麗でした", "is_correct": false, "explanation": "丁寧体の過去形で、「奇麗でしたになった」は不自然で、変化を表す位置には入らない。"}], "correct_form": "奇麗に", "base_form": "奇麗", "form_label": "副詞形", "sentence_index": 7, "explanations": {"奇麗だった": "過去の終止形で、「奇麗だったになった」は成り立たない。変化の結果を表す副詞形ではない。", "奇麗じゃない": "否定形で、「奇麗じゃないになった」は成り立たない。「奇麗じゃなくなった」なら自然だが、この位置には入らない。", "奇麗に": "「奇麗になった」の〈奇麗に〉。「なる」に続く副詞形で、状態の変化を表す。", "奇麗でした": "丁寧体の過去形で、「奇麗でしたになった」は不自然で、変化を表す位置には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f684db3-9863-415a-a57d-a5a1901631b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37092, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "打つ対象の顎を示す「を」で、「顎を打つ」は正しい。"}, {"text": "が", "is_correct": false, "explanation": "「顎が打つ」は顎を主語にしてしまい、打つ主体が不明になるので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「顎に打つ」は場所を示す「に」だが、打つ対象には「を」が必要なので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「顎から打つ」は起点を示す「から」で、打撃を加える対象を示す文にはならない。"}], "correct_answer": "を", "explanations": {"を": "打つ対象の顎を示す「を」で、「顎を打つ」は正しい。", "が": "「顎が打つ」は顎を主語にしてしまい、打つ主体が不明になるので合わない。", "に": "「顎に打つ」は場所を示す「に」だが、打つ対象には「を」が必要なので合わない。", "から": "「顎から打つ」は起点を示す「から」で、打撃を加える対象を示す文にはならない。"}, "error_tags": {"を": "対象", "が": "主格", "に": "位置", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37092, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37092, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "顔の下端にある、口の下の部分。", "primary_collocate": null, "pronunciation": "あご", "ipa": "aɡo", "syllable_count": 2, "sentences": [{"text": "彼はひげがのびて、顎が青くなった。", "target_word": "顎", "complexity_tier": "T3", "furigana": "彼[かれ]はひげがのびて、顎[あご]が青[あお]くなった。", "sentence_source": "generated"}, {"text": "転んで顎を打ち、少し血が出た。", "target_word": "顎", "complexity_tier": "T3", "furigana": "転[ころ]んで顎[あご]を打[う]ち、少[すこ]し血[ち]が出[で]た。", "sentence_source": "generated"}, {"text": "考えるとき、姉は顎に手を当てる癖がある。", "target_word": "顎", "complexity_tier": "T3", "furigana": "考[かんが]えるとき、姉[あね]は顎[あご]に手[て]を当[あ]てる癖[くせ]がある。", "sentence_source": "generated"}, {"text": "顎を上げて、まっすぐ前を見ろ。", "target_word": "顎", "complexity_tier": "T3", "furigana": "顎[あご]を上[あ]げて、まっすぐ前[まえ]を見[み]ろ。", "sentence_source": "generated"}, {"text": "顎が細い人は、すっきりした顔に見える。", "target_word": "顎", "complexity_tier": "T3", "furigana": "顎[あご]が細[ほそ]い人[ひと]は、すっきりした顔[かお]に見[み]える。", "sentence_source": "generated"}, {"text": "疲れて、電車で顎が胸につくほど眠ってしまった。", "target_word": "顎", "complexity_tier": "T3", "furigana": "疲[つか]れて、電車[でんしゃ]で顎[あご]が胸[むね]につくほど眠[ねむ]ってしまった。", "sentence_source": "generated"}, {"text": "ボクサーは顎を守るために、両手を上げた。", "target_word": "顎", "complexity_tier": "T3", "furigana": "ボクサーは顎[あご]を守[まも]るために、両手[りょうて]を上[あ]げた。", "sentence_source": "generated"}, {"text": "兄は寒くて、顎まで布団をかぶった。", "target_word": "顎", "complexity_tier": "T3", "furigana": "兄[あに]は寒[さむ]くて、顎[あご]まで布団[ふとん]をかぶった。", "sentence_source": "generated"}, {"text": "犬は私の膝に顎をのせて、じっとしていた。", "target_word": "顎", "complexity_tier": "T3", "furigana": "犬[いぬ]は私[わたし]の膝[ひざ]に顎[あご]をのせて、じっとしていた。", "sentence_source": "generated"}, {"text": "マフラーを顎まで引き上げて、寒い道を歩いた。", "target_word": "顎", "complexity_tier": "T3", "furigana": "マフラーを顎[あご]まで引[ひ]き上[あ]げて、寒[さむ]い道[みち]を歩[ある]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "顎", "label": "基本形"}, {"form": "顎が", "label": "主格"}, {"form": "顎を", "label": "対格"}], "register": "標準的な普通体", "sense_fingerprint": "顔の下側にある、あご", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc4c99e5-c08d-4486-b1ed-5a1851877780') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37092, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "顎", "is_correct": true, "explanation": "ひげがのびると青く見えるのは、あごの部分なので文に合う。"}, {"text": "肩", "is_correct": false, "explanation": "肩はひげが生えて青くなる部位ではないので、この文には合わない。"}, {"text": "膝", "is_correct": false, "explanation": "膝はひげと関係がなく、ひげがのびて青くなるとは言わない。"}, {"text": "腰", "is_correct": false, "explanation": "腰はひげがのびて青くなる部位ではないので、文が成り立たない。"}], "explanations": {"顎": "ひげがのびると青く見えるのは、あごの部分なので文に合う。", "肩": "肩はひげが生えて青くなる部位ではないので、この文には合わない。", "膝": "膝はひげと関係がなく、ひげがのびて青くなるとは言わない。", "腰": "腰はひげがのびて青くなる部位ではないので、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "顎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寝ぐせで顎がはねていた。", "explanation": "ここは〈髪〉の意味。寝ぐせではねるのは髪で、顎がはねるとは言わないので合わない。"}, {"text": "子どもは怒って、顎をふくらませた。", "explanation": "ここは〈頬〉の意味。ふくらませるのは頬で、顎をふくらませるとは言わないので合わない。"}, {"text": "寒くて、顎をすくめて歩いた。", "explanation": "ここは〈首〉の意味。すくめるのは首や肩で、顎をすくめるとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37092, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "顎", "is_correct": true, "explanation": "ボクサーがパンチから守る部位で、あごのこと。文に合う。"}, {"text": "爪", "is_correct": false, "explanation": "爪を守るために両手を上げるとは考えにくく、文の意味に合わない。"}, {"text": "髪", "is_correct": false, "explanation": "髪を守るために両手を上げる動作にはならないので、この文には合わない。"}, {"text": "膝", "is_correct": false, "explanation": "膝は両手を上げて守る部位ではないので、この文には合わない。"}], "explanations": {"顎": "ボクサーがパンチから守る部位で、あごのこと。文に合う。", "爪": "爪を守るために両手を上げるとは考えにくく、文の意味に合わない。", "髪": "髪を守るために両手を上げる動作にはならないので、この文には合わない。", "膝": "膝は両手を上げて守る部位ではないので、この文には合わない。"}, "sentence_index": 6, "correct_answer": "顎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風邪で顎をすすりながら、会議に出た。", "explanation": "ここは〈鼻〉の意味。鼻はすするが、顎はすすれないので合わない。"}, {"text": "彼は疑わしそうに、顎をひそめた。", "explanation": "ここは〈眉〉の意味。眉をひそめるのは眉の動きで、顎をひそめるとは言わないので合わない。"}, {"text": "風邪で顎がかれて、声が出なかった。", "explanation": "ここは〈喉〉の意味。声がかれるのは喉で、顎がかれるとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37092, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒い夜、彼女は顎に毛布をかけて眠った。", "corrected_sentence": "寒い夜、彼女は顎まで毛布をかけて眠った。", "error_description": "「顎に」が誤りで、正しくは「顎まで」。毛布が顎に届く範囲を示すには「まで」が必要で、「に」では顎の位置を示すだけになり文意が合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37092, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "試合の途中で、彼は顎から強い一発を受けて倒れた。", "corrected_sentence": "試合の途中で、彼は顎に強い一発を受けて倒れた。", "error_description": "「顎から」が誤りで、正しくは「顎に」。打撃を受ける場所を示すには「に」が自然で、「から」は起点を示すため文意に合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37093, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "顎に属する骨を示す「の」で、「顎の骨」は正しい。"}, {"text": "を", "is_correct": false, "explanation": "「顎を骨が動く」は文の形が崩れ、動く主語が示せないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「顎に骨が動く」は位置の「に」になり、骨の所属を表せないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「顎へ骨が動く」は方向の「へ」で、骨の所属を示せないので合わない。"}], "correct_answer": "の", "explanations": {"の": "顎に属する骨を示す「の」で、「顎の骨」は正しい。", "を": "「顎を骨が動く」は文の形が崩れ、動く主語が示せないので合わない。", "に": "「顎に骨が動く」は位置の「に」になり、骨の所属を表せないので合わない。", "へ": "「顎へ骨が動く」は方向の「へ」で、骨の所属を示せないので合わない。"}, "error_tags": {"の": "所属", "を": "対象", "に": "位置", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37093, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "動かす対象の顎を示す「を」で、「顎を動かして」は正しい。"}, {"text": "が", "is_correct": false, "explanation": "「顎が動かして」は顎を主語にしてしまい、他動詞「動かす」の対象が示せないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「顎へ動かす」は方向の「へ」で、動かす対象を示せないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「顎と動かす」は並列の「と」で、動かす対象を示す文にはならないので合わない。"}], "correct_answer": "を", "explanations": {"を": "動かす対象の顎を示す「を」で、「顎を動かして」は正しい。", "が": "「顎が動かして」は顎を主語にしてしまい、他動詞「動かす」の対象が示せないので合わない。", "へ": "「顎へ動かす」は方向の「へ」で、動かす対象を示せないので合わない。", "と": "「顎と動かす」は並列の「と」で、動かす対象を示す文にはならないので合わない。"}, "error_tags": {"を": "対象", "が": "主格", "へ": "方向", "と": "共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37093, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "口の下の部分で、食べ物をかむときに動く骨のあるところ。", "primary_collocate": null, "pronunciation": "あご", "ipa": "aɡo", "syllable_count": 2, "sentences": [{"text": "かたい肉を食べると、顎が疲れる。", "target_word": "顎", "complexity_tier": "T3", "furigana": "かたい肉[にく]を食[た]べると、顎[あご]が疲[つか]れる。", "sentence_source": "generated"}, {"text": "食べ物をかむとき、顎の骨が動く。", "target_word": "顎", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]をかむとき、顎[あご]の骨[ほね]が動[うご]く。", "sentence_source": "generated"}, {"text": "大きなあくびをして、顎が外れそうになった。", "target_word": "顎", "complexity_tier": "T3", "furigana": "大[おお]きなあくびをして、顎[あご]が外[はず]れそうになった。", "sentence_source": "generated"}, {"text": "歯医者で、顎の動きを調べてもらった。", "target_word": "顎", "complexity_tier": "T3", "furigana": "歯医者[はいしゃ]で、顎[あご]の動[うご]きを調[しら]べてもらった。", "sentence_source": "generated"}, {"text": "ガムを長くかんでいたら、顎が痛くなった。", "target_word": "顎", "complexity_tier": "T3", "furigana": "ガムを長[なが]くかんでいたら、顎[あご]が痛[いた]くなった。", "sentence_source": "generated"}, {"text": "赤ちゃんは顎を動かして、ミルクを飲む。", "target_word": "顎", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは顎[あご]を動[うご]かして、ミルクを飲[の]む。", "sentence_source": "generated"}, {"text": "顎が弱いので、やわらかい物を選んで食べている。", "target_word": "顎", "complexity_tier": "T3", "furigana": "顎[あご]が弱[よわ]いので、やわらかい物[もの]を選[えら]んで食[た]べている。", "sentence_source": "generated"}, {"text": "顎をしっかり動かして、ゆっくりかみなさい。", "target_word": "顎", "complexity_tier": "T3", "furigana": "顎[あご]をしっかり動[うご]かして、ゆっくりかみなさい。", "sentence_source": "generated"}, {"text": "ワニの顎は、かたい骨もかみ砕けるほど強い。", "target_word": "顎", "complexity_tier": "T3", "furigana": "ワニの顎[あご]は、かたい骨[ほね]もかみ砕[くだ]けるほど強[つよ]い。", "sentence_source": "generated"}, {"text": "口を開けると顎のあたりで音がして、心配になった。", "target_word": "顎", "complexity_tier": "T3", "furigana": "口[くち]を開[あ]けると顎[あご]のあたりで音[おと]がして、心配[しんぱい]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "顎", "label": "基本形"}, {"form": "顎が", "label": "主格"}, {"form": "顎を", "label": "対格"}], "register": "標準的な普通体", "sense_fingerprint": "食べ物をかむときに動く、口の下の骨の部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc4c99e5-c08d-4486-b1ed-5a1851877780') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37093, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "顎", "is_correct": true, "explanation": "かたい肉をかむと疲れるのはあごの部分なので、文に合う。"}, {"text": "髪", "is_correct": false, "explanation": "髪は食べ物をかむ動作で疲れないので、この文には合わない。"}, {"text": "爪", "is_correct": false, "explanation": "爪は食べ物をかんでも疲れないので、文が成り立たない。"}, {"text": "額", "is_correct": false, "explanation": "額は食べ物をかむ動作と関係なく疲れるとは考えにくく、文に合わない。"}], "explanations": {"顎": "かたい肉をかむと疲れるのはあごの部分なので、文に合う。", "髪": "髪は食べ物をかむ動作で疲れないので、この文には合わない。", "爪": "爪は食べ物をかんでも疲れないので、文が成り立たない。", "額": "額は食べ物をかむ動作と関係なく疲れるとは考えにくく、文に合わない。"}, "sentence_index": 0, "correct_answer": "顎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "本を読むとき、顎を立てて座った。", "explanation": "ここは〈膝〉の意味。膝を立てるのは膝の動作で、顎を立てるとは言わないので合わない。"}, {"text": "かたい肉を食べたあと、顎を磨いた。", "explanation": "ここは〈歯〉の意味。磨くのは歯で、顎を磨く対象にはならないので合わない。"}, {"text": "考えるとき、顎を組んで黙った。", "explanation": "ここは〈腕〉の意味。腕を組むのは腕の動作で、顎を組むとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37093, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "顎", "is_correct": true, "explanation": "かむ力が弱いことを表す、あごの部分で、やわらかい物を選ぶ理由になる。"}, {"text": "眉", "is_correct": false, "explanation": "眉が弱いことは食べ物を選ぶ理由にならず、文が成り立たない。"}, {"text": "肩", "is_correct": false, "explanation": "肩が弱いことはかむ力の話ではないので、やわらかい物を選んで食べる理由にならず、文に合わない。"}, {"text": "膝", "is_correct": false, "explanation": "膝が弱いことは食べ物をかむ力とは関係がなく、やわらかい物を選ぶ理由にならないので合わない。"}], "explanations": {"顎": "かむ力が弱いことを表す、あごの部分で、やわらかい物を選ぶ理由になる。", "眉": "眉が弱いことは食べ物を選ぶ理由にならず、文が成り立たない。", "肩": "肩が弱いことはかむ力の話ではないので、やわらかい物を選んで食べる理由にならず、文に合わない。", "膝": "膝が弱いことは食べ物をかむ力とは関係がなく、やわらかい物を選ぶ理由にならないので合わない。"}, "sentence_index": 6, "correct_answer": "顎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は不満そうに、顎を尖らせた。", "explanation": "ここは〈唇〉の意味。唇を尖らせるのは唇の動作で、顎を尖らせるとは言わないので合わない。"}, {"text": "嬉しくて、顎を細めた。", "explanation": "ここは〈目〉の意味。目を細めるのは目の動作で、顎を細めるとは言わないので合わない。"}, {"text": "かたい肉を食べるとき、うっかり顎を巻いてしまった。", "explanation": "ここは〈舌〉の意味。舌を巻くのは舌の動作で、顎を巻くとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37093, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "かたいせんべいをかむと、顎で筋肉が痛くなる。", "corrected_sentence": "かたいせんべいをかむと、顎の筋肉が痛くなる。", "error_description": "「顎で」が誤りで、正しくは「顎の」。「で」は手段を示してしまい、顎に属する筋肉を示す文にならない。所属を示す「の」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37093, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ひどくかたいパンを食べたら、顎を痛くなった。", "corrected_sentence": "ひどくかたいパンを食べたら、顎が痛くなった。", "error_description": "「顎を」が誤りで、正しくは「顎が」。痛くなるのは顎なので主語の「が」が必要で、「を」は対象を示すため文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
