INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37094, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "水やお風呂の中に全身を入れること。", "primary_collocate": null, "pronunciation": "つかる", "ipa": "tsɯkaɾɯ", "syllable_count": 3, "sentences": [{"text": "寒い日は、ゆっくりお風呂に浸かると体が温まる。", "target_word": "浸かる", "complexity_tier": "T3", "furigana": "寒[さむ]い日[ひ]は、ゆっくりお風呂[ふろ]に浸[つ]かると体[からだ]が温[あたた]まる。", "sentence_source": "generated"}, {"text": "疲れたので、温泉に肩まで浸かってのんびりした。", "target_word": "浸かって", "complexity_tier": "T3", "furigana": "疲[つか]れたので、温泉[おんせん]に肩[かた]まで浸[つ]かってのんびりした。", "sentence_source": "generated"}, {"text": "父は毎晩、四十度のお湯に十分ほど浸かる。", "target_word": "浸かる", "complexity_tier": "T3", "furigana": "父[ちち]は毎晩[まいばん]、四十度[よんじゅうど]のお湯[ゆ]に十分[じゅっぷん]ほど浸[つ]かる。", "sentence_source": "generated"}, {"text": "子どもが湯船に浸かったまま寝てしまった。", "target_word": "浸かった", "complexity_tier": "T3", "furigana": "子[こ]どもが湯船[ゆぶね]に浸[つ]かったまま寝[ね]てしまった。", "sentence_source": "generated"}, {"text": "冬至の日は、ゆず湯に浸かる習慣がある。", "target_word": "浸かる", "complexity_tier": "T3", "furigana": "冬至[とうじ]の日[ひ]は、ゆず湯[ゆ]に浸[つ]かる習慣[しゅうかん]がある。", "sentence_source": "generated"}, {"text": "風邪をひいているときは、長く湯に浸かってはいけない。", "target_word": "浸かって", "complexity_tier": "T3", "furigana": "風邪[かぜ]をひいているときは、長[なが]く湯[ゆ]に浸[つ]かってはいけない。", "sentence_source": "generated"}, {"text": "日本人は毎日お風呂に浸かりたがる人が多い。", "target_word": "浸かり", "complexity_tier": "T3", "furigana": "日本人[にほんじん]は毎日[まいにち]お風呂[ふろ]に浸[つ]かりたがる人[ひと]が多[おお]い。", "sentence_source": "generated"}, {"text": "お湯が熱すぎて、長く浸かっていられなかった。", "target_word": "浸かって", "complexity_tier": "T3", "furigana": "お湯[ゆ]が熱[あつ]すぎて、長[なが]く浸[つ]かっていられなかった。", "sentence_source": "generated"}, {"text": "旅行先の大きなお風呂に浸かって、一日の疲れをとった。", "target_word": "浸かって", "complexity_tier": "T3", "furigana": "旅行先[りょこうさき]の大[おお]きなお風呂[ふろ]に浸[つ]かって、一日[いちにち]の疲[つか]れをとった。", "sentence_source": "generated"}, {"text": "運動のあと、冷たい水風呂に浸かると足の痛みが楽になる。", "target_word": "浸かる", "complexity_tier": "T3", "furigana": "運動[うんどう]のあと、冷[つめ]たい水風呂[みずぶろ]に浸[つ]かると足[あし]の痛[いた]みが楽[らく]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "浸かる", "label": "辞書形"}, {"form": "浸かります", "label": "ます形"}, {"form": "浸かって", "label": "て形"}, {"form": "浸かった", "label": "た形"}, {"form": "浸からない", "label": "ない形"}], "register": "日常語・普通体（だ・である調）", "sense_fingerprint": "お風呂や湯の中に体を入れてつかる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1ecbb5a-fd75-4d21-9035-16b121ce40ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37094, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浸かる", "is_correct": true, "explanation": "お風呂の中に体を入れる意味で、「お風呂に〜と体が温まる」に合う。"}, {"text": "洗う", "is_correct": false, "explanation": "体や物の汚れを落とす動作で、お風呂の中に入る意味にはならない。「お風呂に洗うと」は続かない。"}, {"text": "浴びる", "is_correct": false, "explanation": "湯や水を体にかける動作で、お風呂の中に全身を入れることとは違う。「お風呂に浴びると」は不自然。"}, {"text": "沸かす", "is_correct": false, "explanation": "お風呂の湯を温める動作で、目的語は「お風呂を」や「湯を」になる。「お風呂に沸かすと」は続かない。"}], "explanations": {"浸かる": "お風呂の中に体を入れる意味で、「お風呂に〜と体が温まる」に合う。", "洗う": "体や物の汚れを落とす動作で、お風呂の中に入る意味にはならない。「お風呂に洗うと」は続かない。", "浴びる": "湯や水を体にかける動作で、お風呂の中に全身を入れることとは違う。「お風呂に浴びると」は不自然。", "沸かす": "お風呂の湯を温める動作で、目的語は「お風呂を」や「湯を」になる。「お風呂に沸かすと」は続かない。"}, "sentence_index": 0, "correct_answer": "浸かる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "汗を流すため、シャワーに浸かってから出かけた。", "explanation": "ここは〈浴びる〉の意味。浸かるは体全体を湯や液体の中に入れる動作で、シャワーの下に立つだけなら〈浴びる〉を使う。"}, {"text": "寒いので、ストーブの前に浸かって体を温めた。", "explanation": "ここは〈当たる〉の意味。浸かるは液体の中に入ることなので、ストーブの前で暖まる場面には合わない。"}, {"text": "寒いので、布団に浸かって眠った。", "explanation": "ここは〈入る〉の意味。布団は液体ではないので、浸かるは使えず「布団に入る」と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37094, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浸かり", "is_correct": true, "explanation": "お風呂の中に体を入れる意味で、「〜たがる人が多い」に続く形として合う。"}, {"text": "掃除し", "is_correct": false, "explanation": "お風呂を掃除する動作で、「お風呂に」と続くと不自然になる。"}, {"text": "流し", "is_correct": false, "explanation": "汗や汚れを流す動作で、「お風呂に流したがる」とは言わない。"}, {"text": "出し", "is_correct": false, "explanation": "湯を出す、外に出すなどの動作で、「お風呂に出したがる」とは続かない。"}], "explanations": {"浸かり": "お風呂の中に体を入れる意味で、「〜たがる人が多い」に続く形として合う。", "掃除し": "お風呂を掃除する動作で、「お風呂に」と続くと不自然になる。", "流し": "汗や汚れを流す動作で、「お風呂に流したがる」とは言わない。", "出し": "湯を出す、外に出すなどの動作で、「お風呂に出したがる」とは続かない。"}, "sentence_index": 6, "correct_answer": "浸かり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "疲れたので、ベンチに浸かって休んだ。", "explanation": "ここは〈座る〉の意味。ベンチは液体ではないので、浸かるは合わず「ベンチに座って」と言う。"}, {"text": "試験の前に、教科書に浸かって勉強した。", "explanation": "ここは〈没頭する〉の意味。浸かるは液体の中に体を入れる動作で、教科書に入るような比喩には使わない。"}, {"text": "雨の日は、傘に浸かって歩いた。", "explanation": "ここは〈差す〉の意味。浸かるは液体に入る動作で、雨をよける傘には使えず「傘を差して」と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37094, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒い夜は、ゆっくり湯船を浸かると体が温まる。", "corrected_sentence": "寒い夜は、ゆっくり湯船に浸かると体が温まる。", "error_description": "「湯船に浸かる」が正しく、「湯船を浸かる」は誤り。浸かるは自動詞で、入る先は「に」で示す。「を」は他動詞の目的語に使うので合わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "浸かって", "is_correct": true, "explanation": "て形。「〜てのんびりした」へつながる形で、文中の形と一致する。"}, {"text": "浸かります", "is_correct": false, "explanation": "ます形。「〜てのんびりした」の接続には使えない。"}, {"text": "浸かった", "is_correct": false, "explanation": "た形。「浸かったのんびりした」とは続かず、文として成立しない。"}, {"text": "浸からない", "is_correct": false, "explanation": "ない形。否定の意味になり、温泉で楽にしている文脈と合わない。"}], "correct_form": "浸かって", "base_form": "浸かる", "form_label": "て形", "sentence_index": 1, "explanations": {"浸かって": "て形。「〜てのんびりした」へつながる形で、文中の形と一致する。", "浸かります": "ます形。「〜てのんびりした」の接続には使えない。", "浸かった": "た形。「浸かったのんびりした」とは続かず、文として成立しない。", "浸からない": "ない形。否定の意味になり、温泉で楽にしている文脈と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37094, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏は毎晩、水風呂に浸かったがる人もいる。", "corrected_sentence": "夏は毎晩、水風呂に浸かりたがる人もいる。", "error_description": "「〜たがる」は動詞のます形の語幹（浸かり）に付く。「浸かったがる」は誤りで、正しくは「浸かりたがる」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "浸かって", "is_correct": true, "explanation": "て形。「〜ていられなかった」へ続く形で、文中の形と一致する。"}, {"text": "浸かろう", "is_correct": false, "explanation": "意向形。誘いや決意の意味になり、「いられなかった」の過去の状況と合わない。"}, {"text": "浸かれ", "is_correct": false, "explanation": "命令形。「〜ていられなかった」の文脈とは成立しない。"}, {"text": "浸かれば", "is_correct": false, "explanation": "仮定形。「〜ていられなかった」と続かず、文が成立しない。"}], "correct_form": "浸かって", "base_form": "浸かる", "form_label": "て形", "sentence_index": 7, "explanations": {"浸かって": "て形。「〜ていられなかった」へ続く形で、文中の形と一致する。", "浸かろう": "意向形。誘いや決意の意味になり、「いられなかった」の過去の状況と合わない。", "浸かれ": "命令形。「〜ていられなかった」の文脈とは成立しない。", "浸かれば": "仮定形。「〜ていられなかった」と続かず、文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
