INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37095, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "液体の中に体の全部または一部を入れる。", "primary_collocate": null, "pronunciation": "つかる", "ipa": "tsɯkaɾɯ", "syllable_count": 3, "sentences": [{"text": "足首まで川に浸かって遊んだ。", "target_word": "浸かって", "complexity_tier": "T3", "furigana": "足首[あしくび]まで川[かわ]に浸[つ]かって遊[あそ]んだ。", "sentence_source": "generated"}, {"text": "海に腰まで浸かると、思ったより冷たかった。", "target_word": "浸かる", "complexity_tier": "T3", "furigana": "海[うみ]に腰[こし]まで浸[つ]かると、思[おも]ったより冷[つめ]たかった。", "sentence_source": "generated"}, {"text": "田んぼに膝まで浸かって、田植えを手伝った。", "target_word": "浸かって", "complexity_tier": "T3", "furigana": "田[た]んぼに膝[ひざ]まで浸[つ]かって、田植[たう]えを手伝[てつだ]った。", "sentence_source": "generated"}, {"text": "温泉街の足湯は、観光の合間に足首まで湯に浸かる人でにぎわっている。", "target_word": "浸かる", "complexity_tier": "T3", "furigana": "温泉街[おんせんがい]の足湯[あしゆ]は、観光[かんこう]の合間[あいま]に足首[あしくび]まで湯[ゆ]に浸[つ]かる人[ひと]でにぎわっている。", "sentence_source": "generated"}, {"text": "プールの浅いところに浸かって、水に慣れる練習をした。", "target_word": "浸かって", "complexity_tier": "T3", "furigana": "プールの浅[あさ]いところに浸[つ]かって、水[みず]に慣[な]れる練習[れんしゅう]をした。", "sentence_source": "generated"}, {"text": "手首まで水に浸かったので、袖がびしょぬれになった。", "target_word": "浸かった", "complexity_tier": "T3", "furigana": "手首[てくび]まで水[みず]に浸[つ]かったので、袖[そで]がびしょぬれになった。", "sentence_source": "generated"}, {"text": "池に落ちた犬は、首まで水に浸かって震えていた。", "target_word": "浸かって", "complexity_tier": "T3", "furigana": "池[いけ]に落[お]ちた犬[いぬ]は、首[くび]まで水[みず]に浸[つ]かって震[ふる]えていた。", "sentence_source": "generated"}, {"text": "川の中に胸まで浸かって、魚をとる人を見た。", "target_word": "浸かって", "complexity_tier": "T3", "furigana": "川[かわ]の中[なか]に胸[むね]まで浸[つ]かって、魚[さかな]をとる人[ひと]を見[み]た。", "sentence_source": "generated"}, {"text": "冷たい水に足が浸かった瞬間、思わず声が出た。", "target_word": "浸かった", "complexity_tier": "T3", "furigana": "冷[つめ]たい水[みず]に足[あし]が浸[つ]かった瞬間[しゅんかん]、思[おも]わず声[こえ]が出[で]た。", "sentence_source": "generated"}, {"text": "うっかり池の浅いところに浸かって、靴下までぬれた。", "target_word": "浸かって", "complexity_tier": "T3", "furigana": "うっかり池[いけ]の浅[あさ]いところに浸[つ]かって、靴下[くつした]までぬれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "浸かる", "label": "辞書形"}, {"form": "浸かります", "label": "ます形"}, {"form": "浸かって", "label": "て形"}, {"form": "浸かった", "label": "た形"}, {"form": "浸からない", "label": "ない形"}], "register": "日常語・普通体（だ・である調）", "sense_fingerprint": "水などの液体に体の一部が入る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1ecbb5a-fd75-4d21-9035-16b121ce40ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37095, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浸かって", "is_correct": true, "explanation": "液体の中に体の一部を入れる意味で、「足首まで川に〜遊んだ」に合う。"}, {"text": "洗って", "is_correct": false, "explanation": "体や物を洗う動作で、「川に洗って遊んだ」は続かない。"}, {"text": "渡って", "is_correct": false, "explanation": "川を横切る動作で、「足首まで川に渡って」は意味が通らない。"}, {"text": "拾って", "is_correct": false, "explanation": "物を拾う動作で、「川に拾って遊んだ」とは続かない。"}], "explanations": {"浸かって": "液体の中に体の一部を入れる意味で、「足首まで川に〜遊んだ」に合う。", "洗って": "体や物を洗う動作で、「川に洗って遊んだ」は続かない。", "渡って": "川を横切る動作で、「足首まで川に渡って」は意味が通らない。", "拾って": "物を拾う動作で、「川に拾って遊んだ」とは続かない。"}, "sentence_index": 0, "correct_answer": "浸かって"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "川べりの石に浸かって、しばらく休んでいた。", "explanation": "ここは〈座る〉の意味。石は液体ではないので、浸かるは使えず「石に座って」と言う。"}, {"text": "寒いので、焚き火に浸かって体を温めた。", "explanation": "ここは〈当たる〉の意味。焚き火は液体ではないので、浸かるは合わず「焚き火に当たって」と言う。"}, {"text": "雨でぬれた服は、日なたに浸かって乾いた。", "explanation": "ここは〈干す〉の意味。日なたの場所に入るのは浸かるとは言わず、洗濯物は日なたに干して乾かす。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37095, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浸かって", "is_correct": true, "explanation": "液体の中に体を入れ、震えている状態を表す。「首まで水に〜震えていた」に合う。"}, {"text": "叫んで", "is_correct": false, "explanation": "声を出す動作で、「首まで水に叫んで震えていた」は続かない。"}, {"text": "跳ねて", "is_correct": false, "explanation": "飛び上がる動作で、首まで水に入った状態とは合わない。"}, {"text": "数えて", "is_correct": false, "explanation": "数を数える動作で、水に入る状態を表せない。"}], "explanations": {"浸かって": "液体の中に体を入れ、震えている状態を表す。「首まで水に〜震えていた」に合う。", "叫んで": "声を出す動作で、「首まで水に叫んで震えていた」は続かない。", "跳ねて": "飛び上がる動作で、首まで水に入った状態とは合わない。", "数えて": "数を数える動作で、水に入る状態を表せない。"}, "sentence_index": 6, "correct_answer": "浸かって"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもたちは、ボートに浸かって川を渡った。", "explanation": "ここは〈乗る〉の意味。ボートは液体ではないので、浸かるは合わず「ボートに乗って」と言う。"}, {"text": "急な斜面を、岩に浸かって登った。", "explanation": "ここは〈つかまる〉の意味。岩は液体ではないので、浸かるは使えず「岩につかまって」と言う。"}, {"text": "真夏の部屋に浸かって、汗をかいていた。", "explanation": "ここは〈過ごす〉の意味。浸かるは液体に体を入れる動作で、暑い部屋で時間を過ごす意味には使えず、「暑い部屋で過ごす」と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37095, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "川を膝まで浸かると、水の冷たさがわかる。", "corrected_sentence": "川に膝まで浸かると、水の冷たさがわかる。", "error_description": "「川に浸かる」が正しく、「川を浸かる」は誤り。浸かるは自動詞で、対象を直接取る「を」とは合わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "浸かる", "is_correct": true, "explanation": "辞書形。「海に腰まで浸かると」の条件の形と一致する。"}, {"text": "浸かります", "is_correct": false, "explanation": "ます形。丁寧な語形になり、普通体で書かれた本文と合わない。"}, {"text": "浸かった", "is_correct": false, "explanation": "た形。過去の出来事を表し、「浸かったと」は一般的な条件を表さない。"}, {"text": "浸からない", "is_correct": false, "explanation": "ない形。否定の意味になり、腰まで入る状況と合わない。"}], "correct_form": "浸かる", "base_form": "浸かる", "form_label": "辞書形", "sentence_index": 1, "explanations": {"浸かる": "辞書形。「海に腰まで浸かると」の条件の形と一致する。", "浸かります": "ます形。丁寧な語形になり、普通体で書かれた本文と合わない。", "浸かった": "た形。過去の出来事を表し、「浸かったと」は一般的な条件を表さない。", "浸からない": "ない形。否定の意味になり、腰まで入る状況と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37095, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "浅い池に浸かりないように、子どもを注意した。", "corrected_sentence": "浅い池に浸からないように、子どもを注意した。", "error_description": "ない形は未然形（浸から）に「ない」を付ける。「浸かりない」は誤りで、正しくは「浸からない」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "浸かって", "is_correct": true, "explanation": "て形。「胸まで〜魚をとる人を見た」と続く形で、文中の形と一致する。"}, {"text": "浸かろう", "is_correct": false, "explanation": "意向形。誘いや決意の意味になり、見た出来事の文と合わない。"}, {"text": "浸かれ", "is_correct": false, "explanation": "命令形。見た出来事を述べる文には使えない。"}, {"text": "浸かれば", "is_correct": false, "explanation": "仮定形。「魚をとる人を見た」と続かず、文が成立しない。"}], "correct_form": "浸かって", "base_form": "浸かる", "form_label": "て形", "sentence_index": 7, "explanations": {"浸かって": "て形。「胸まで〜魚をとる人を見た」と続く形で、文中の形と一致する。", "浸かろう": "意向形。誘いや決意の意味になり、見た出来事の文と合わない。", "浸かれ": "命令形。見た出来事を述べる文には使えない。", "浸かれば": "仮定形。「魚をとる人を見た」と続かず、文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37096, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "絵をかく動作が行われる場所を示す。「仕事場で毎日絵をかいている」と自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "仕事場を目的語にすると、かく対象として不自然になる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞で、仕事場が絵をかく、という意味になり成立しない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す助詞で、ここでは動作の場所を表せない。"}], "correct_answer": "で", "explanations": {"で": "絵をかく動作が行われる場所を示す。「仕事場で毎日絵をかいている」と自然に続く。", "を": "仕事場を目的語にすると、かく対象として不自然になる。", "が": "主語を示す助詞で、仕事場が絵をかく、という意味になり成立しない。", "と": "並列や相手を示す助詞で、ここでは動作の場所を表せない。"}, "error_tags": {"を": "目的語", "が": "主語", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37096, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "大工さんの仕事場という所属・所有の関係を示す。「大工さんの仕事場は」と自然に続く。"}, {"text": "に", "is_correct": false, "explanation": "「大工さんに仕事場は」は所属の関係にならず、場所の関係も合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す助詞で、大工さんから仕事場という関係にはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞で、所有や所属の関係を示せない。"}], "correct_answer": "の", "explanations": {"の": "大工さんの仕事場という所属・所有の関係を示す。「大工さんの仕事場は」と自然に続く。", "に": "「大工さんに仕事場は」は所属の関係にならず、場所の関係も合わない。", "から": "起点を示す助詞で、大工さんから仕事場という関係にはならない。", "より": "比較の助詞で、所有や所属の関係を示せない。"}, "error_tags": {"に": "場所・相手", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37096, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "しごとをするへややばしょのこと。", "primary_collocate": null, "pronunciation": "しごとば", "ipa": "ɕigotoba", "syllable_count": 4, "sentences": [{"text": "父の仕事場は駅の近くにある小さな部屋だ。", "target_word": "仕事場", "complexity_tier": "T3", "furigana": "父[ちち]の仕事場[しごとば]は駅[えき]の近[ちか]くにある小[ちい]さな部屋[へや]だ。", "sentence_source": "generated"}, {"text": "画家は自分の仕事場で毎日絵をかいている。", "target_word": "仕事場", "complexity_tier": "T3", "furigana": "画家[がか]は自分[じぶん]の仕事場[しごとば]で毎日[まいにち]絵[え]をかいている。", "sentence_source": "generated"}, {"text": "私の仕事場には大きな机と本だながある。", "target_word": "仕事場", "complexity_tier": "T3", "furigana": "私[わたし]の仕事場[しごとば]には大[おお]きな机[つくえ]と本[ほん]だながある。", "sentence_source": "generated"}, {"text": "仕事場がせまいので、新しい部屋をさがしている。", "target_word": "仕事場", "complexity_tier": "T3", "furigana": "仕事場[しごとば]がせまいので、新[あたら]しい部屋[へや]をさがしている。", "sentence_source": "generated"}, {"text": "祖父の仕事場には、木のいいにおいがいつもしていた。", "target_word": "仕事場", "complexity_tier": "T3", "furigana": "祖父[そふ]の仕事場[しごとば]には、木[き]のいいにおいがいつもしていた。", "sentence_source": "generated"}, {"text": "兄は家の二階を仕事場にして、一人で働いている。", "target_word": "仕事場", "complexity_tier": "T3", "furigana": "兄[あに]は家[いえ]の二階[にかい]を仕事場[しごとば]にして、一人[ひとり]で働[はたら]いている。", "sentence_source": "generated"}, {"text": "仕事場が家から遠いので、毎朝早く起きる。", "target_word": "仕事場", "complexity_tier": "T3", "furigana": "仕事場[しごとば]が家[いえ]から遠[とお]いので、毎朝[まいあさ]早[はや]く起[お]きる。", "sentence_source": "generated"}, {"text": "大工さんの仕事場は、道具がきれいにならべてある。", "target_word": "仕事場", "complexity_tier": "T3", "furigana": "大工[だいく]さんの仕事場[しごとば]は、道具[どうぐ]がきれいにならべてある。", "sentence_source": "generated"}, {"text": "母は仕事場にお弁当を持っていく。", "target_word": "仕事場", "complexity_tier": "T3", "furigana": "母[はは]は仕事場[しごとば]にお弁当[べんとう]を持[も]っていく。", "sentence_source": "generated"}, {"text": "雨がもれて、仕事場の本がぬれてしまった。", "target_word": "仕事場", "complexity_tier": "T3", "furigana": "雨[あめ]がもれて、仕事場[しごとば]の本[ほん]がぬれてしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "仕事場", "label": "基本形"}], "register": "日常語・普通体（だ・である調）", "sense_fingerprint": "仕事をするための部屋や場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1ecbb5a-fd75-4d21-9035-16b121ce40ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37096, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仕事場", "is_correct": true, "explanation": "仕事をする小さな部屋という意味で、「駅の近くにある小さな部屋だ」と合う。"}, {"text": "公園", "is_correct": false, "explanation": "人が遊ぶ広い屋外の場所で、小さな部屋とは合わない。"}, {"text": "駐車場", "is_correct": false, "explanation": "車を止める場所で、小さな部屋という説明と一致しない。"}, {"text": "商店街", "is_correct": false, "explanation": "店が並ぶ通りで、小さな部屋とは言えない。"}], "explanations": {"仕事場": "仕事をする小さな部屋という意味で、「駅の近くにある小さな部屋だ」と合う。", "公園": "人が遊ぶ広い屋外の場所で、小さな部屋とは合わない。", "駐車場": "車を止める場所で、小さな部屋という説明と一致しない。", "商店街": "店が並ぶ通りで、小さな部屋とは言えない。"}, "sentence_index": 0, "correct_answer": "仕事場"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子どもたちは、仕事場で夏休みの宿題をした。", "explanation": "ここは〈勉強部屋〉の意味。仕事場は働くための場所で、子どもが宿題をする部屋とは言わない。"}, {"text": "仕事場が三つの支店に分かれている。", "explanation": "ここは〈会社〉の意味。仕事場は小さな部屋を指すので、支店が集まる規模の組織は言わない。"}, {"text": "木を切るため、仕事場の上にのこぎりを置いた。", "explanation": "ここは〈作業台〉の意味。道具を置く台は作業台と言い、部屋そのものを指す仕事場とは区別する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37096, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仕事場", "is_correct": true, "explanation": "仕事をする場所という意味で、「家から遠いので、毎朝早く起きる」という文脈に合う。"}, {"text": "作業服", "is_correct": false, "explanation": "働くときに着る服で、家から遠いという文脈には合わない。"}, {"text": "道具", "is_correct": false, "explanation": "作業に使う物で、場所として家から遠いとは言えない。"}, {"text": "機械", "is_correct": false, "explanation": "機器のことで、家から遠いという説明が成立しない。"}], "explanations": {"仕事場": "仕事をする場所という意味で、「家から遠いので、毎朝早く起きる」という文脈に合う。", "作業服": "働くときに着る服で、家から遠いという文脈には合わない。", "道具": "作業に使う物で、場所として家から遠いとは言えない。", "機械": "機器のことで、家から遠いという説明が成立しない。"}, "sentence_index": 6, "correct_answer": "仕事場"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅先で、仕事場の大きな湖を眺めた。", "explanation": "ここは〈景勝地〉の意味。仕事場は人が働く場所で、湖や景色の見どころを指すことはない。"}, {"text": "体重を量るため、仕事場に乗った。", "explanation": "ここは〈体重計〉の意味。仕事場は人が働く場所で、体重を量る器具に乗るとは言わない。"}, {"text": "夏休みに、子どもたちは仕事場でプールに入って遊んだ。", "explanation": "ここは〈遊び場〉の意味。仕事場は働くための場所で、子どもが遊ぶプールのある場所とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37096, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は毎朝、仕事場が行くため、六時に家を出る。", "corrected_sentence": "父は毎朝、仕事場に行くため、六時に家を出る。", "error_description": "「仕事場に行く」が正しく、「仕事場が行く」は誤り。行く先は「に」で示すもので、仕事場は行く動作の主語にならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37096, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "駅前に小さな仕事場を食べた。", "corrected_sentence": "駅前に小さな仕事場を借りた。", "error_description": "「仕事場を借りた」が正しい。「食べた」は仕事場とは合わず、場所を得る動作は「借りる」「探す」「建てる」などで表す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37097, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "仕事場と空気をつなぎ、空気の所在を示す。「仕事場の空気が悪く」と自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "「仕事場を空気が悪く」は目的語として成立せず、不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞。「仕事場へ空気が悪く」は場所の関係にならず、文として成立しない。"}, {"text": "に", "is_correct": false, "explanation": "場所を示す助詞だが、「仕事場に空気が悪く」は空気の所在を表す意味にならない。"}], "correct_answer": "の", "explanations": {"の": "仕事場と空気をつなぎ、空気の所在を示す。「仕事場の空気が悪く」と自然に続く。", "を": "「仕事場を空気が悪く」は目的語として成立せず、不自然になる。", "へ": "方向を示す助詞。「仕事場へ空気が悪く」は場所の関係にならず、文として成立しない。", "に": "場所を示す助詞だが、「仕事場に空気が悪く」は空気の所在を表す意味にならない。"}, "error_tags": {"を": "目的語", "へ": "方向", "に": "場所・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37097, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "仕事場と棚をつなぎ、棚がある場所・所属を示す。「仕事場の棚を」と自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "目的語が二つ重なるため不自然。「仕事場を棚を」は成立しない。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞で、場所の関係を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、「仕事場へ棚を壁に固定した」は場所の意味にならない。"}], "correct_answer": "の", "explanations": {"の": "仕事場と棚をつなぎ、棚がある場所・所属を示す。「仕事場の棚を」と自然に続く。", "を": "目的語が二つ重なるため不自然。「仕事場を棚を」は成立しない。", "より": "比較の助詞で、場所の関係を示せない。", "へ": "方向を示す助詞で、「仕事場へ棚を壁に固定した」は場所の意味にならない。"}, "error_tags": {"を": "目的語の重複", "より": "比較", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37097, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が仕事をするための場所。オフィスや工場など。", "primary_collocate": null, "pronunciation": "しごとば", "ipa": "ɕigotoba", "syllable_count": 4, "sentences": [{"text": "この工場は、千人以上が働く大きな仕事場だ。", "target_word": "仕事場", "complexity_tier": "T3", "furigana": "この工場[こうじょう]は、千人[せんにん]以上[いじょう]が働[はたら]く大[おお]きな仕事場[しごとば]だ。", "sentence_source": "generated"}, {"text": "仕事場の空気が悪く、社員が次々に体調をくずした。", "target_word": "仕事場", "complexity_tier": "T3", "furigana": "仕事場[しごとば]の空気[くうき]が悪[わる]く、社員[しゃいん]が次々[つぎつぎ]に体調[たいちょう]をくずした。", "sentence_source": "generated"}, {"text": "新しい仕事場は、駅から歩いて五分の事務所だ。", "target_word": "仕事場", "complexity_tier": "T3", "furigana": "新[あたら]しい仕事場[しごとば]は、駅[えき]から歩[ある]いて五分[ごふん]の事務所[じむしょ]だ。", "sentence_source": "generated"}, {"text": "仕事場では、安全のためにヘルメットをかぶる決まりだ。", "target_word": "仕事場", "complexity_tier": "T3", "furigana": "仕事場[しごとば]では、安全[あんぜん]のためにヘルメットをかぶる決[き]まりだ。", "sentence_source": "generated"}, {"text": "仕事場の人間関係がよいので、毎日楽しく働ける。", "target_word": "仕事場", "complexity_tier": "T3", "furigana": "仕事場[しごとば]の人間関係[にんげんかんけい]がよいので、毎日[まいにち]楽[たの]しく働[はたら]ける。", "sentence_source": "generated"}, {"text": "火事で仕事場が使えなくなり、会社は別のビルに移った。", "target_word": "仕事場", "complexity_tier": "T3", "furigana": "火事[かじ]で仕事場[しごとば]が使[つか]えなくなり、会社[かいしゃ]は別[べつ]のビルに移[うつ]った。", "sentence_source": "generated"}, {"text": "彼は仕事場に家族の話を持ちこまない人だ。", "target_word": "仕事場", "complexity_tier": "T3", "furigana": "彼[かれ]は仕事場[しごとば]に家族[かぞく]の話[はなし]を持[も]ちこまない人[ひと]だ。", "sentence_source": "generated"}, {"text": "地震にそなえて、仕事場の棚を壁に固定した。", "target_word": "仕事場", "complexity_tier": "T3", "furigana": "地震[じしん]にそなえて、仕事場[しごとば]の棚[たな]を壁[かべ]に固定[こてい]した。", "sentence_source": "generated"}, {"text": "病院は医者や看護師にとって、命をあずかる仕事場だ。", "target_word": "仕事場", "complexity_tier": "T3", "furigana": "病院[びょういん]は医者[いしゃ]や看護師[かんごし]にとって、命[いのち]をあずかる仕事場[しごとば]だ。", "sentence_source": "generated"}, {"text": "仕事場が暑すぎるので、エアコンを入れてほしいと頼んだ。", "target_word": "仕事場", "complexity_tier": "T3", "furigana": "仕事場[しごとば]が暑[あつ]すぎるので、エアコンを入[い]れてほしいと頼[たの]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "仕事場", "label": "基本形"}], "register": "日常語・普通体（だ・である調）", "sense_fingerprint": "オフィスや工場など働く人が集まる職場", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1ecbb5a-fd75-4d21-9035-16b121ce40ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37097, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仕事場", "is_correct": true, "explanation": "千人以上が働く職場という意味で、「千人以上が働く大きな〜だ」に合う。"}, {"text": "空気", "is_correct": false, "explanation": "「大きな空気だ」とは言わず、働く場所の説明にならない。"}, {"text": "時間", "is_correct": false, "explanation": "「大きな時間だ」とは言わず、場所を表す語として合わない。"}, {"text": "天気", "is_correct": false, "explanation": "「大きな天気だ」は成立せず、働く場所の説明にならない。"}], "explanations": {"仕事場": "千人以上が働く職場という意味で、「千人以上が働く大きな〜だ」に合う。", "空気": "「大きな空気だ」とは言わず、働く場所の説明にならない。", "時間": "「大きな時間だ」とは言わず、場所を表す語として合わない。", "天気": "「大きな天気だ」は成立せず、働く場所の説明にならない。"}, "sentence_index": 0, "correct_answer": "仕事場"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "休日は、仕事場で友達とボール遊びをする。", "explanation": "ここは〈運動場〉の意味。仕事場は働くための場所で、遊ぶ場所とは言わない。"}, {"text": "子どもたちは、仕事場で砂遊びをした。", "explanation": "ここは〈公園〉の意味。仕事場は働くための場所で、子どもが遊ぶ場所とは言わない。"}, {"text": "その仕事場の内容は、難しくて面白い。", "explanation": "ここは〈業務〉の意味。仕事場は場所のことで、業務の中身を指すときは仕事と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37097, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仕事場", "is_correct": true, "explanation": "仕事をする職場という意味で、「家族の話を持ちこまない人」という文脈に合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食品を冷やす家電で、家族の話を持ちこむ先にはならない。"}, {"text": "洗濯機", "is_correct": false, "explanation": "衣類を洗う機械で、話を持ちこむ場所にはならない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "書く道具で、人が話を持ちこむ場所にはならない。"}], "explanations": {"仕事場": "仕事をする職場という意味で、「家族の話を持ちこまない人」という文脈に合う。", "冷蔵庫": "食品を冷やす家電で、家族の話を持ちこむ先にはならない。", "洗濯機": "衣類を洗う機械で、話を持ちこむ場所にはならない。", "鉛筆": "書く道具で、人が話を持ちこむ場所にはならない。"}, "sentence_index": 6, "correct_answer": "仕事場"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "入院中の母を、仕事場で見舞った。", "explanation": "ここは〈病室〉の意味。仕事場は働く場所で、患者が入院する部屋には使わない。"}, {"text": "毎朝、仕事場で国語の授業を受けた。", "explanation": "ここは〈教室〉の意味。仕事場は働く場所で、授業を受ける場所とは言わない。"}, {"text": "髪を切るため、仕事場の予約を取った。", "explanation": "ここは〈美容院〉の意味。髪を切ってもらう店は美容院と言い、仕事場とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37097, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山田さんの仕事場を古い機械が並んでいる。", "corrected_sentence": "山田さんの仕事場には古い機械が並んでいる。", "error_description": "「仕事場には〜並んでいる」が正しい。並んでいるは自動詞で、場所は「には」で示す。「を」は他動詞の目的語に使うので合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37097, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社は、仕事場を郊外のビルに溶かした。", "corrected_sentence": "会社は、仕事場を郊外のビルに移した。", "error_description": "「移した」が正しい。仕事場を別の場所へ動かすときは「移す」を使う。「溶かす」は仕事場には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37098, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「朝の電車」の「の」で、朝が電車を修飾する関係を示す。"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」では、電車を修飾する形にならない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」では、電車を修飾する形にならない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段の「で」では、「朝で電車は」が成り立たず不自然。"}], "correct_answer": "の", "explanations": {"の": "「朝の電車」の「の」で、朝が電車を修飾する関係を示す。", "が": "主格の「が」では、電車を修飾する形にならない。", "を": "目的語の「を」では、電車を修飾する形にならない。", "で": "場所・手段の「で」では、「朝で電車は」が成り立たず不自然。"}, "error_tags": {"が": "主格で連体修飾にならない", "を": "目的語の格", "で": "場所・手段の格で時を表せない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
