INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37098, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あさというのは、ひがのぼってから、ひるまえまでのじかんです。", "primary_collocate": null, "pronunciation": "あさ", "ipa": "asa", "syllable_count": 2, "sentences": [{"text": "朝、起きるとすぐに顔を洗います。", "target_word": "朝", "complexity_tier": "T2", "furigana": "朝[あさ]、起[お]きるとすぐに顔[かお]を洗[あら]います。", "sentence_source": "generated"}, {"text": "朝の電車はとても混んでいます。", "target_word": "朝", "complexity_tier": "T2", "furigana": "朝[あさ]の電車[でんしゃ]はとても混[こ]んでいます。", "sentence_source": "generated"}, {"text": "冬の朝は、外が暗くて寒いです。", "target_word": "朝", "complexity_tier": "T2", "furigana": "冬[ふゆ]の朝[あさ]は、外[そと]が暗[くら]くて寒[さむ]いです。", "sentence_source": "generated"}, {"text": "私は朝六時に家を出て、学校へ行きます。", "target_word": "朝", "complexity_tier": "T2", "furigana": "私[わたし]は朝[あさ]六時[ろくじ]に家[いえ]を出[で]て、学校[がっこう]へ行[い]きます。", "sentence_source": "generated"}, {"text": "朝は父がコーヒーを入れてくれます。", "target_word": "朝", "complexity_tier": "T2", "furigana": "朝[あさ]は父[ちち]がコーヒーを入[い]れてくれます。", "sentence_source": "generated"}, {"text": "朝のうちに宿題を終わらせて、午後は友だちと遊びます。", "target_word": "朝", "complexity_tier": "T3", "furigana": "朝[あさ]のうちに宿題[しゅくだい]を終[お]わらせて、午後[ごご]は友[とも]だちと遊[あそ]びます。", "sentence_source": "generated"}, {"text": "朝の空気は冷たくて、気持ちがいいです。", "target_word": "朝", "complexity_tier": "T2", "furigana": "朝[あさ]の空気[くうき]は冷[つめ]たくて、気持[きも]ちがいいです。", "sentence_source": "generated"}, {"text": "日曜日の朝は、ゆっくり起きて新聞を読みます。", "target_word": "朝", "complexity_tier": "T3", "furigana": "日曜日[にちようび]の朝[あさ]は、ゆっくり起[お]きて新聞[しんぶん]を読[よ]みます。", "sentence_source": "generated"}, {"text": "朝になると、鳥が庭で鳴き始めます。", "target_word": "朝", "complexity_tier": "T3", "furigana": "朝[あさ]になると、鳥[とり]が庭[にわ]で鳴[な]き始[はじ]めます。", "sentence_source": "generated"}, {"text": "朝から何も食べていないので、おなかがぺこぺこです。", "target_word": "朝", "complexity_tier": "T3", "furigana": "朝[あさ]から何[なに]も食[た]べていないので、おなかがぺこぺこです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "朝", "label": "基本形"}, {"form": "朝の", "label": "連体(の)"}, {"form": "朝に", "label": "時を表す(に)"}], "register": "丁寧(です・ます体が中心)", "sense_fingerprint": "日が昇ってから昼前までの時間帯。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: contains vocabulary far above tier T1: ぺこぺこ (Zipf 2.37)']::text[], '0f6b1235-7c2d-4e61-9691-9f3fcb3a9405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37098, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "朝", "is_correct": true, "explanation": "夜が明けてから昼前までの時間帯を指し、起きてすぐ顔を洗う文脈に合う。"}, {"text": "夕", "is_correct": false, "explanation": "夕は夕方を指し、起きてすぐ顔を洗う時間帯としては合わない。"}, {"text": "正午", "is_correct": false, "explanation": "正午は昼の時刻で、起床の時間としては不自然。"}, {"text": "年末", "is_correct": false, "explanation": "年末は一年の終わりを指し、毎日の起床の時間には合わない。"}], "explanations": {"朝": "夜が明けてから昼前までの時間帯を指し、起きてすぐ顔を洗う文脈に合う。", "夕": "夕は夕方を指し、起きてすぐ顔を洗う時間帯としては合わない。", "正午": "正午は昼の時刻で、起床の時間としては不自然。", "年末": "年末は一年の終わりを指し、毎日の起床の時間には合わない。"}, "sentence_index": 0, "correct_answer": "朝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝が明けて、空が白くなりました。", "explanation": "「夜が明ける」の「夜」を「朝」に替えた文。朝が明けるという言い方はしません。"}, {"text": "朝が沈んで、辺りが暗くなりました。", "explanation": "「日が沈む」の「日」を「朝」に替えた文。朝が沈むという言い方はしません。"}, {"text": "朝が更けて、街が静かになりました。", "explanation": "「夜が更ける」の「夜」を「朝」に替えた文。朝が更けるという言い方はしません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37098, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "朝", "is_correct": true, "explanation": "夜が明けてから昼前までを指し、朝の空気が冷たくて気持ちがいいという文脈に合う。"}, {"text": "盛夏", "is_correct": false, "explanation": "盛夏は真夏を指し、空気が冷たいという文脈とは合わない。"}, {"text": "夏休み", "is_correct": false, "explanation": "夏休みは期間を指し、空気が冷たいという描写とは合わない。"}, {"text": "正午", "is_correct": false, "explanation": "正午は昼の時刻で、朝の冷たい空気という描写には合わない。"}], "explanations": {"朝": "夜が明けてから昼前までを指し、朝の空気が冷たくて気持ちがいいという文脈に合う。", "盛夏": "盛夏は真夏を指し、空気が冷たいという文脈とは合わない。", "夏休み": "夏休みは期間を指し、空気が冷たいという描写とは合わない。", "正午": "正午は昼の時刻で、朝の冷たい空気という描写には合わない。"}, "sentence_index": 6, "correct_answer": "朝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒い部屋で仕事をして、朝を明かしました。", "explanation": "「夜を明かす」（夜通し過ごす）の「夜」を「朝」に替えた文。朝を明かすという言い方はしません。"}, {"text": "夕方の空に、朝焼けがきれいに広がりました。", "explanation": "「夕焼け」の「夕」を「朝」に替えた文。夕方の空に朝焼けは見られません。"}, {"text": "朝日が沈んで、辺りが暗くなりました。", "explanation": "「夕日が沈む」の「夕」を「朝」に替えた文。沈むのは夕日で、朝日は沈みません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37098, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏の朝を日差しが強くて外に出られませんでした。", "corrected_sentence": "夏の朝は日差しが強くて外に出られませんでした。", "error_description": "時を主題として示すのは「は」。「朝を」は誤りで、正しくは「朝は」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37098, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "面接の朝を緊張して、朝ごはんを残しました。", "corrected_sentence": "面接の朝は緊張して、朝ごはんを残しました。", "error_description": "時を主題として示すのは「は」。「朝を」は誤りで、正しくは「朝は」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37099, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「朝のこの散歩」の「の」で、朝がこの散歩を修飾する関係を示す。"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」では、この散歩を修飾する形にならない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」では、この散歩を修飾する形にならない。"}, {"text": "に", "is_correct": false, "explanation": "位置や時を示す「に」では、この散歩を修飾する形にならない。"}], "correct_answer": "の", "explanations": {"の": "「朝のこの散歩」の「の」で、朝がこの散歩を修飾する関係を示す。", "が": "主格の「が」では、この散歩を修飾する形にならない。", "を": "目的語の「を」では、この散歩を修飾する形にならない。", "に": "位置や時を示す「に」では、この散歩を修飾する形にならない。"}, "error_tags": {"が": "主格で連体修飾にならない", "を": "目的語の格", "に": "位置・時の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37099, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「朝から雨が降っていた」の「から」で、朝を起点とする時間の範囲を示す。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す「で」では、時間の起点を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では、時間の起点を表せない。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用を示す「と」では、時間の起点を表せない。"}], "correct_answer": "から", "explanations": {"から": "「朝から雨が降っていた」の「から」で、朝を起点とする時間の範囲を示す。", "で": "手段や場所を示す「で」では、時間の起点を表せない。", "へ": "方向を示す「へ」では、時間の起点を表せない。", "と": "共同や引用を示す「と」では、時間の起点を表せない。"}, "error_tags": {"で": "手段・場所の格", "へ": "方向の格", "と": "共同・引用の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37099, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "一日のうち、夜が明けてから昼前までの時間。", "primary_collocate": null, "pronunciation": "あさ", "ipa": "asa", "syllable_count": 2, "sentences": [{"text": "夜が明け、太陽が農場を照らし始める朝、農家の男は鶏舎へと足を運ぶ。", "target_word": "朝", "complexity_tier": "T4", "furigana": "夜[よる]が明[あ]け、太陽[たいよう]が農場[のうじょう]を照[て]らし始[はじ]める朝[あさ]、農家[のうか]の男[おとこ]は鶏舎[けいしゃ]へと足[あし]を運[はこ]ぶ。", "sentence_source": "mined"}, {"text": "彼は朝のこの散歩を、毎日の楽しみにしている。", "target_word": "朝", "complexity_tier": "T3", "furigana": "彼[かれ]は朝[あさ]のこの散歩[さんぽ]を、毎日[まいにち]の楽[たの]しみにしている。", "sentence_source": "generated"}, {"text": "朝は忙しいので、いつもパンとコーヒーだけで済ませる。", "target_word": "朝", "complexity_tier": "T3", "furigana": "朝[あさ]は忙[いそが]しいので、いつもパンとコーヒーだけで済[す]ませる。", "sentence_source": "generated"}, {"text": "冬の朝は寒いので、布団から出るのがつらい。", "target_word": "朝", "complexity_tier": "T3", "furigana": "冬[ふゆ]の朝[あさ]は寒[さむ]いので、布団[ふとん]から出[で]るのがつらい。", "sentence_source": "generated"}, {"text": "朝の公園では、お年寄りが散歩したり体操したりしている。", "target_word": "朝", "complexity_tier": "T3", "furigana": "朝[あさ]の公園[こうえん]では、お年寄[としよ]りが散歩[さんぽ]したり体操[たいそう]したりしている。", "sentence_source": "generated"}, {"text": "朝、窓を開けると、新しい空気が部屋に入ってきた。", "target_word": "朝", "complexity_tier": "T3", "furigana": "朝[あさ]、窓[まど]を開[あ]けると、新[あたら]しい空気[くうき]が部屋[へや]に入[はい]ってきた。", "sentence_source": "generated"}, {"text": "試験の朝は緊張して、ごはんがあまり食べられなかった。", "target_word": "朝", "complexity_tier": "T3", "furigana": "試験[しけん]の朝[あさ]は緊張[きんちょう]して、ごはんがあまり食[た]べられなかった。", "sentence_source": "generated"}, {"text": "朝から雨が降っていたが、昼には止んで青空が見えた。", "target_word": "朝", "complexity_tier": "T3", "furigana": "朝[あさ]から雨[あめ]が降[ふ]っていたが、昼[ひる]には止[や]んで青空[あおぞら]が見[み]えた。", "sentence_source": "generated"}, {"text": "母は朝が早く、五時にはもう台所で料理を始める。", "target_word": "朝", "complexity_tier": "T3", "furigana": "母[はは]は朝[あさ]が早[はや]く、五時[ごじ]にはもう台所[だいどころ]で料理[りょうり]を始[はじ]める。", "sentence_source": "generated"}, {"text": "朝は頭がすっきりしているので、難しい勉強は朝のうちにする。", "target_word": "朝", "complexity_tier": "T3", "furigana": "朝[あさ]は頭[あたま]がすっきりしているので、難[むずか]しい勉強[べんきょう]は朝[あさ]のうちにする。", "sentence_source": "generated"}], "morphological_forms": [{"form": "朝", "label": "基本形"}, {"form": "朝の", "label": "連体(の)"}], "register": "標準(中立)", "sense_fingerprint": "夜明けから昼前までの時間帯。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: 鶏舎 (Zipf 2.02)']::text[], '0f6b1235-7c2d-4e61-9691-9f3fcb3a9405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37099, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "朝", "is_correct": true, "explanation": "夜明けから昼前までを指し、夜が明けて農家の男が出かける時間帯に合う。"}, {"text": "夕", "is_correct": false, "explanation": "夕は夕方を指し、太陽が照らし始める時間帯には合わない。"}, {"text": "昼", "is_correct": false, "explanation": "昼は昼前以降を指し、夜明けの時間帯には合わない。"}, {"text": "夜", "is_correct": false, "explanation": "夜は夜明け前の時間帯で、夜が明けた後の文脈には合わない。"}], "explanations": {"朝": "夜明けから昼前までを指し、夜が明けて農家の男が出かける時間帯に合う。", "夕": "夕は夕方を指し、太陽が照らし始める時間帯には合わない。", "昼": "昼は昼前以降を指し、夜明けの時間帯には合わない。", "夜": "夜は夜明け前の時間帯で、夜が明けた後の文脈には合わない。"}, "sentence_index": 0, "correct_answer": "朝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝が明けて、部屋が少しずつ明るくなった。", "explanation": "「夜が明ける」の「夜」を「朝」に替えた文。朝が明けるという言い方はしない。"}, {"text": "朝が暮れて、部屋がだんだん暗くなった。", "explanation": "「日が暮れる」の「日」を「朝」に替えた文。朝が暮れるという言い方はしない。"}, {"text": "朝が更けて、街がしんと静かになった。", "explanation": "「夜が更ける」の「夜」を「朝」に替えた文。朝が更けるという言い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37099, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "朝", "is_correct": true, "explanation": "試験当日の朝を指し、緊張して食事が進まなかった流れに合う。"}, {"text": "夕暮れ", "is_correct": false, "explanation": "夕暮れは食事をとらない文脈とは合わず、緊張で食べられなかった流れに合わない。"}, {"text": "正午", "is_correct": false, "explanation": "正午は食事時で、食べられなかったという文脈と噛み合わない。"}, {"text": "真夜中", "is_correct": false, "explanation": "真夜中は眠る時間で、ごはんを食べる文脈に合わない。"}], "explanations": {"朝": "試験当日の朝を指し、緊張して食事が進まなかった流れに合う。", "夕暮れ": "夕暮れは食事をとらない文脈とは合わず、緊張で食べられなかった流れに合わない。", "正午": "正午は食事時で、食べられなかったという文脈と噛み合わない。", "真夜中": "真夜中は眠る時間で、ごはんを食べる文脈に合わない。"}, "sentence_index": 6, "correct_answer": "朝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒い部屋で仕事をして、朝を明かした。", "explanation": "「夜を明かす」（夜通し過ごす）の「夜」を「朝」に替えた文。朝を明かすという言い方はしない。"}, {"text": "朝日が沈んで、辺りが暗くなった。", "explanation": "「夕日が沈む」の「夕」を「朝」に替えた文。沈むのは夕日で、朝日は沈まない。"}, {"text": "夕方の空に、朝焼けがきれいに広がった。", "explanation": "「夕焼け」の「夕」を「朝」に替えた文。夕方の空に朝焼けは見られない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
