INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37100, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "function", "definition": "くらべるときにつかうことばです。バスやでんしゃのほうがいい、とくらべます。", "primary_collocate": null, "pronunciation": "ほう", "ipa": "hoː", "syllable_count": 2, "sentences": [{"text": "バスより電車の方が時間どおりに来る。", "target_word": "方", "complexity_tier": "T3", "furigana": "バスより電車[でんしゃ]の方[ほう]が時間[じかん]どおりに来[く]る。", "sentence_source": "generated"}, {"text": "肉と魚なら、私は魚の方が好きだ。", "target_word": "方", "complexity_tier": "T3", "furigana": "肉[にく]と魚[さかな]なら、私[わたし]は魚[さかな]の方[ほう]が好[す]きだ。", "sentence_source": "generated"}, {"text": "家で食べるより、外で食べる方が高くつく。", "target_word": "方", "complexity_tier": "T3", "furigana": "家[いえ]で食[た]べるより、外[そと]で食[た]べる方[ほう]が高[たか]くつく。", "sentence_source": "generated"}, {"text": "夏と冬では、冬の方が出かけるのが楽しい。", "target_word": "方", "complexity_tier": "T3", "furigana": "夏[なつ]と冬[ふゆ]では、冬[ふゆ]の方[ほう]が出[で]かけるのが楽[たの]しい。", "sentence_source": "generated"}, {"text": "兄と弟のうち、弟の方が料理が上手だ。", "target_word": "方", "complexity_tier": "T3", "furigana": "兄[あに]と弟[おとうと]のうち、弟[おとうと]の方[ほう]が料理[りょうり]が上手[じょうず]だ。", "sentence_source": "generated"}, {"text": "歩くより自転車の方が速いが、雨の日は大変だ。", "target_word": "方", "complexity_tier": "T3", "furigana": "歩[ある]くより自転車[じてんしゃ]の方[ほう]が速[はや]いが、雨[あめ]の日[ひ]は大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "紅茶とコーヒーなら、コーヒーの方を選ぶ。", "target_word": "方", "complexity_tier": "T3", "furigana": "紅茶[こうちゃ]とコーヒーなら、コーヒーの方[ほう]を選[えら]ぶ。", "sentence_source": "generated"}, {"text": "駅からは遠いが、こちらの店の方が安い。", "target_word": "方", "complexity_tier": "T3", "furigana": "駅[えき]からは遠[とお]いが、こちらの店[みせ]の方[ほう]が安[やす]い。", "sentence_source": "generated"}, {"text": "電話よりメールの方が、相手の都合を気にしなくていい。", "target_word": "方", "complexity_tier": "T3", "furigana": "電話[でんわ]よりメールの方[ほう]が、相手[あいて]の都合[つごう]を気[き]にしなくていい。", "sentence_source": "generated"}, {"text": "この二つの中では、左の方が私に合うと思う。", "target_word": "方", "complexity_tier": "T3", "furigana": "この二[ふた]つの中[なか]では、左[ひだり]の方[ほう]が私[わたし]に合[あ]うと思[おも]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "方", "label": "基本形"}], "register": "日常語・普通体（だ・である調）", "sense_fingerprint": "二つをくらべて一方を取り上げる「〜の方が」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1ecbb5a-fd75-4d21-9035-16b121ce40ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37100, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "方", "is_correct": true, "explanation": "「AよりBの方が」の「方」。二つを比べて電車を取り上げる形で、この空欄にはこれだけが入る。"}, {"text": "所", "is_correct": false, "explanation": "「ところ」は場所や部分を指す。「電車の所が時間どおりに来る」は比べる形にならず、意味が通らない。"}, {"text": "点", "is_correct": false, "explanation": "「点」は観点や項目の意味。「電車の点が」では比較の主語にならず、不自然。"}, {"text": "面", "is_correct": false, "explanation": "「面」は側面・一面の意味。「電車の面が時間どおりに来る」は成り立たない。"}], "explanations": {"方": "「AよりBの方が」の「方」。二つを比べて電車を取り上げる形で、この空欄にはこれだけが入る。", "所": "「ところ」は場所や部分を指す。「電車の所が時間どおりに来る」は比べる形にならず、意味が通らない。", "点": "「点」は観点や項目の意味。「電車の点が」では比較の主語にならず、不自然。", "面": "「面」は側面・一面の意味。「電車の面が時間どおりに来る」は成り立たない。"}, "sentence_index": 0, "correct_answer": "方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この計算の解き方を教えてください。", "explanation": "ここは「やり方・方法」の意味（解き方）。二つを比べる用法ではないので、この定義には合わない。"}, {"text": "あの方はどなたですか。", "explanation": "ここは丁寧に人を指す「方」の意味。二つの程度を比べる用法ではないので合わない。"}, {"text": "その件は私の方で処理します。", "explanation": "ここは「こちら側・担当の側」の意味。比べる用法ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37100, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方", "is_correct": true, "explanation": "「コーヒーの方を選ぶ」で、二つのうちどちらを取るかを示す「方」。この空欄にはこれだけが入る。"}, {"text": "件", "is_correct": false, "explanation": "「件」は事柄・案件の意味。「コーヒーの件を選ぶ」は意味が通らない。"}, {"text": "辺", "is_correct": false, "explanation": "「辺」はあたり・周辺の意味。選ぶ対象にならず、「コーヒーの辺を選ぶ」は不自然。"}, {"text": "数", "is_correct": false, "explanation": "「数」は数量の意味。「コーヒーの数を選ぶ」は選択の対象として成り立たない。"}], "explanations": {"方": "「コーヒーの方を選ぶ」で、二つのうちどちらを取るかを示す「方」。この空欄にはこれだけが入る。", "件": "「件」は事柄・案件の意味。「コーヒーの件を選ぶ」は意味が通らない。", "辺": "「辺」はあたり・周辺の意味。選ぶ対象にならず、「コーヒーの辺を選ぶ」は不自然。", "数": "「数」は数量の意味。「コーヒーの数を選ぶ」は選択の対象として成り立たない。"}, "sentence_index": 6, "correct_answer": "方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅の北の方に新しい店ができた。", "explanation": "ここは「方角・方面」の意味。比べる用法ではないので、この定義には合わない。"}, {"text": "まずは私の方から連絡する。", "explanation": "ここは「こちら側・自分の側」の意味。比べる用法ではないので、この定義には合わない。"}, {"text": "遠くの方から声が聞こえる。", "explanation": "「あたり」の意味で使うと方角の用法になり、この定義の比べる意味とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37100, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "電車より歩く方を体にいい。", "corrected_sentence": "電車より歩く方が体にいい。", "error_description": "「方」の後には主語を示す「が」が入る。「を」は目的語用なので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37100, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校までは歩くより、自転車の方を速かった。", "corrected_sentence": "学校までは歩くより、自転車の方が速かった。", "error_description": "形容詞「速い」の主語には「が」が入る。「を」は目的語用で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
