INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37101, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "function", "definition": "二つのものをくらべるとき、あとに出てくるもののほうが、前より程度が大きいことをあらわす言い方。", "primary_collocate": null, "pronunciation": "ほう", "ipa": "hoː", "syllable_count": 2, "sentences": [{"text": "東京より大阪の方が、夏は暑く感じる。", "target_word": "方", "complexity_tier": "T3", "furigana": "東京[とうきょう]より大阪[おおさか]の方[ほう]が、夏[なつ]は暑[あつ]く感[かん]じる。", "sentence_source": "generated"}, {"text": "姉より妹の方が、背が高い。", "target_word": "方", "complexity_tier": "T3", "furigana": "姉[あね]より妹[いもうと]の方[ほう]が、背[せ]が高[たか]い。", "sentence_source": "generated"}, {"text": "去年より今年の方が、雪がたくさん降った。", "target_word": "方", "complexity_tier": "T3", "furigana": "去年[きょねん]より今年[ことし]の方[ほう]が、雪[ゆき]がたくさん降[ふ]った。", "sentence_source": "generated"}, {"text": "新しい部屋の方が前の部屋より広い。", "target_word": "方", "complexity_tier": "T3", "furigana": "新[あたら]しい部屋[へや]の方[ほう]が前[まえ]の部屋[へや]より広[ひろ]い。", "sentence_source": "generated"}, {"text": "昼より夜の方が、この町は静かになる。", "target_word": "方", "complexity_tier": "T3", "furigana": "昼[ひる]より夜[よる]の方[ほう]が、この町[まち]は静[しず]かになる。", "sentence_source": "generated"}, {"text": "日本語は、話すより書く方が難しいと思う。", "target_word": "方", "complexity_tier": "T3", "furigana": "日本語[にほんご]は、話[はな]すより書[か]く方[ほう]が難[むずか]しいと思[おも]う。", "sentence_source": "generated"}, {"text": "弟より私の方が、ずっと早く起きる。", "target_word": "方", "complexity_tier": "T3", "furigana": "弟[おとうと]より私[わたし]の方[ほう]が、ずっと早[はや]く起[お]きる。", "sentence_source": "generated"}, {"text": "薬を飲むより、休む方が熱は下がりやすい。", "target_word": "方", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]むより、休[やす]む方[ほう]が熱[ねつ]は下[さ]がりやすい。", "sentence_source": "generated"}, {"text": "山のふもとより頂上の方が、気温が低い。", "target_word": "方", "complexity_tier": "T3", "furigana": "山[やま]のふもとより頂上[ちょうじょう]の方[ほう]が、気温[きおん]が低[ひく]い。", "sentence_source": "generated"}, {"text": "昨日より今日の方が、体の調子がいい。", "target_word": "方", "complexity_tier": "T3", "furigana": "昨日[きのう]より今日[きょう]の方[ほう]が、体[からだ]の調子[ちょうし]がいい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "方", "label": "基本形"}], "register": "日常語・普通体（だ・である調）", "sense_fingerprint": "「AよりBの方が〜」でBの程度が大きいと表す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1ecbb5a-fd75-4d21-9035-16b121ce40ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37101, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "方", "is_correct": true, "explanation": "「AよりBの方が」の「方」。大阪を比べて取り上げる形で、この空欄にはこれだけが入る。"}, {"text": "所", "is_correct": false, "explanation": "「ところ」は場所を指す。「大阪の所が夏は暑く感じる」は比較の文として成り立たない。"}, {"text": "件", "is_correct": false, "explanation": "「件」は事柄の意味。「大阪の件が」は比べる主語にならず、意味が通らない。"}, {"text": "面", "is_correct": false, "explanation": "「面」は側面の意味。「大阪の面が暑く感じる」は不自然で、比べる形にならない。"}], "explanations": {"方": "「AよりBの方が」の「方」。大阪を比べて取り上げる形で、この空欄にはこれだけが入る。", "所": "「ところ」は場所を指す。「大阪の所が夏は暑く感じる」は比較の文として成り立たない。", "件": "「件」は事柄の意味。「大阪の件が」は比べる主語にならず、意味が通らない。", "面": "「面」は側面の意味。「大阪の面が暑く感じる」は不自然で、比べる形にならない。"}, "sentence_index": 0, "correct_answer": "方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この機械の使い方を説明してください。", "explanation": "ここは「やり方」の意味（使い方）。二つを比べる用法ではないので、この定義には合わない。"}, {"text": "先ほどの方がお見えです。", "explanation": "ここは丁寧に人を指す「方」の意味。比べる用法ではないので合わない。"}, {"text": "その件は私の方で責任を持ちます。", "explanation": "ここは「こちら側・担当の側」の意味。比べる用法ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37101, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方", "is_correct": true, "explanation": "「AよりBの方が」の「方」。私を比べて取り上げる形で、この空欄にはこれだけが入る。"}, {"text": "点", "is_correct": false, "explanation": "「点」は観点の意味。「私の点が」では比べる主語にならず、不自然。"}, {"text": "数", "is_correct": false, "explanation": "「数」は数量の意味。「私の数が早く起きる」は意味が通らない。"}, {"text": "段", "is_correct": false, "explanation": "「段」は段階や段差の意味。「私の段が早く起きる」は成り立たない。"}], "explanations": {"方": "「AよりBの方が」の「方」。私を比べて取り上げる形で、この空欄にはこれだけが入る。", "点": "「点」は観点の意味。「私の点が」では比べる主語にならず、不自然。", "数": "「数」は数量の意味。「私の数が早く起きる」は意味が通らない。", "段": "「段」は段階や段差の意味。「私の段が早く起きる」は成り立たない。"}, "sentence_index": 6, "correct_answer": "方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市役所の東の方に学校がある。", "explanation": "ここは「方角・方面」の意味。比べる用法ではないので、この定義には合わない。"}, {"text": "まずは私の方から伝える。", "explanation": "ここは「こちら側・自分の側」の意味。比べる用法ではないので、この定義には合わない。"}, {"text": "近くの方から足音が聞こえる。", "explanation": "「あたり」の意味で使うと方角の用法になり、比べる意味とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37101, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄より弟の方に、よく食べる。", "corrected_sentence": "兄より弟の方が、よく食べる。", "error_description": "「方」の後には主語を示す「が」が入る。「に」では「よく食べる」の主語にならず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37101, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この道より、あの道の方を近かったです。", "corrected_sentence": "この道より、あの道の方が近かったです。", "error_description": "形容詞「近い」の主語には「が」が入る。「を」は目的語用で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37102, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "汚す対象の手を示す「を」で、「手を汚さない」は正しい。"}, {"text": "が", "is_correct": false, "explanation": "「手が汚さない」は手を主語にしてしまい、汚す対象が示せないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「手に汚さない」は位置の「に」で、汚す対象を示せないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「手と汚さない」は並列の「と」で、文が成り立たないので合わない。"}], "correct_answer": "を", "explanations": {"を": "汚す対象の手を示す「を」で、「手を汚さない」は正しい。", "が": "「手が汚さない」は手を主語にしてしまい、汚す対象が示せないので合わない。", "に": "「手に汚さない」は位置の「に」で、汚す対象を示せないので合わない。", "と": "「手と汚さない」は並列の「と」で、文が成り立たないので合わない。"}, "error_tags": {"を": "対象", "が": "主格", "に": "位置", "と": "共同"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "清める", "is_correct": true, "explanation": "物や場所を汚すの反対で、きれいにするという意味の対義語。"}, {"text": "運ぶ", "is_correct": false, "explanation": "移動させる意味で、汚すの対義語ではないので合わない。"}, {"text": "並べる", "is_correct": false, "explanation": "整えて置く意味で、汚すの対義語ではないので合わない。"}, {"text": "届ける", "is_correct": false, "explanation": "人のもとに渡す意味で、汚すの対義語ではないので合わない。"}], "correct_answer": "清める", "explanations": {"清める": "物や場所を汚すの反対で、きれいにするという意味の対義語。", "運ぶ": "移動させる意味で、汚すの対義語ではないので合わない。", "並べる": "整えて置く意味で、汚すの対義語ではないので合わない。", "届ける": "人のもとに渡す意味で、汚すの対義語ではないので合わない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37102, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "清める", "is_correct": true, "explanation": "物や場所を汚すの反対で、きれいにするという意味の対義語。"}, {"text": "増やす", "is_correct": false, "explanation": "数量を増す意味で、汚すの対義語ではないので合わない。"}, {"text": "縮める", "is_correct": false, "explanation": "長さや距離を短くする意味で、汚すの対義語ではないので合わない。"}, {"text": "写す", "is_correct": false, "explanation": "複写や撮影をする意味で、汚すの対義語ではないので合わない。"}], "correct_answer": "清める", "explanations": {"清める": "物や場所を汚すの反対で、きれいにするという意味の対義語。", "増やす": "数量を増す意味で、汚すの対義語ではないので合わない。", "縮める": "長さや距離を短くする意味で、汚すの対義語ではないので合わない。", "写す": "複写や撮影をする意味で、汚すの対義語ではないので合わない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37102, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "きたないものにする。", "primary_collocate": null, "pronunciation": "よごす", "ipa": "joɡosɯ", "syllable_count": 3, "sentences": [{"text": "白いシャツを泥で汚してしまった。", "target_word": "汚して", "complexity_tier": "T3", "furigana": "白[しろ]いシャツを泥[どろ]で汚[よご]してしまった。", "sentence_source": "generated"}, {"text": "手を汚さないように、手袋をはめた。", "target_word": "汚さない", "complexity_tier": "T3", "furigana": "手[て]を汚[よご]さないように、手袋[てぶくろ]をはめた。", "sentence_source": "generated"}, {"text": "子どもが床をジュースで汚した。", "target_word": "汚した", "complexity_tier": "T3", "furigana": "子[こ]どもが床[ゆか]をジュースで汚[よご]した。", "sentence_source": "generated"}, {"text": "新しい靴を汚すのが嫌で、雨の日ははかない。", "target_word": "汚す", "complexity_tier": "T3", "furigana": "新[あたら]しい靴[くつ]を汚[よご]すのが嫌[いや]で、雨[あめ]の日[ひ]ははかない。", "sentence_source": "generated"}, {"text": "服を汚したら、すぐに洗えばいい。", "target_word": "汚した", "complexity_tier": "T3", "furigana": "服[ふく]を汚[よご]したら、すぐに洗[あら]えばいい。", "sentence_source": "generated"}, {"text": "壁にペンで落書きして、きれいな部屋を汚した。", "target_word": "汚した", "complexity_tier": "T3", "furigana": "壁[かべ]にペンで落書[らくが]きして、きれいな部屋[へや]を汚[よご]した。", "sentence_source": "generated"}, {"text": "川を汚す人が増えたため、掃除の活動が始まった。", "target_word": "汚す", "complexity_tier": "T3", "furigana": "川[かわ]を汚[よご]す人[ひと]が増[ふ]えたため、掃除[そうじ]の活動[かつどう]が始[はじ]まった。", "sentence_source": "generated"}, {"text": "汚れた手で本を触ると、ページを汚す。", "target_word": "汚す", "complexity_tier": "T3", "furigana": "汚[よご]れた手[て]で本[ほん]を触[さわ]ると、ページを汚[よご]す。", "sentence_source": "generated"}, {"text": "料理中にソースを飛ばして、エプロンを汚した。", "target_word": "汚した", "complexity_tier": "T3", "furigana": "料理中[りょうりちゅう]にソースを飛[と]ばして、エプロンを汚[よご]した。", "sentence_source": "generated"}, {"text": "犬が庭を汚さないように、フンはすぐ片づける。", "target_word": "汚さない", "complexity_tier": "T3", "furigana": "犬[いぬ]が庭[にわ]を汚[よご]さないように、フンはすぐ片[かた]づける。", "sentence_source": "generated"}], "morphological_forms": [{"form": "汚す", "label": "終止形"}, {"form": "汚した", "label": "過去形"}, {"form": "汚して", "label": "て形"}, {"form": "汚さない", "label": "否定形"}, {"form": "汚せば", "label": "仮定形"}, {"form": "汚そう", "label": "意志形"}], "register": "標準的な普通体", "sense_fingerprint": "ものをよごれた状態にする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc4c99e5-c08d-4486-b1ed-5a1851877780') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37102, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汚して", "is_correct": true, "explanation": "泥でシャツをよごしたという意味で、「汚してしまった」の正しい形。"}, {"text": "買って", "is_correct": false, "explanation": "「泥で買う」という意味になり、この文の意味に合わない。"}, {"text": "切って", "is_correct": false, "explanation": "「泥で切る」という意味になり、この文には合わない。"}, {"text": "消して", "is_correct": false, "explanation": "「泥で消す」という意味になり、この文の意味に合わない。"}], "explanations": {"汚して": "泥でシャツをよごしたという意味で、「汚してしまった」の正しい形。", "買って": "「泥で買う」という意味になり、この文の意味に合わない。", "切って": "「泥で切る」という意味になり、この文には合わない。", "消して": "「泥で消す」という意味になり、この文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "汚して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜更かしで健康を汚してしまった。", "explanation": "ここは〈損なう〉の意味。健康は損なうもので、汚すとは言わないので合わない。"}, {"text": "彼は大事な約束を汚さないよう、手帳に書いた。", "explanation": "ここは〈破る〉の意味。約束は破るもので、汚すとは言わないので合わない。"}, {"text": "宿題を汚して、夜中まで終わらなかった。", "explanation": "ここは〈ためる〉の意味。宿題はためるもので、汚すとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37102, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汚す", "is_correct": true, "explanation": "川をよごす人、という意味で文に合う。"}, {"text": "数える", "is_correct": false, "explanation": "川を数える人、という意味になり、文の意味に合わない。"}, {"text": "曲げる", "is_correct": false, "explanation": "川を曲げる人、という意味になり、この文には合わない。"}, {"text": "叩く", "is_correct": false, "explanation": "川を叩く人、という意味になり、文が成り立たない。"}], "explanations": {"汚す": "川をよごす人、という意味で文に合う。", "数える": "川を数える人、という意味になり、文の意味に合わない。", "曲げる": "川を曲げる人、という意味になり、この文には合わない。", "叩く": "川を叩く人、という意味になり、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "汚す"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は重い罪を汚して、長く刑務所に入った。", "explanation": "ここは〈犯す〉の意味。罪は犯すもので、汚すとは言わないので合わない。"}, {"text": "取引先の機密を外部に汚してしまった。", "explanation": "ここは〈漏らす〉の意味。機密は漏らすもので、汚すとは言わないので合わない。"}, {"text": "重い荷物を持って、腰を汚してしまった。", "explanation": "ここは〈痛める〉の意味。腰は痛めるもので、汚すとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37102, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもがペンで壁に汚した。", "corrected_sentence": "子どもがペンで壁を汚した。", "error_description": "「壁に」が誤りで、正しくは「壁を」。汚す対象を示すには対象の「を」が必要で、「に」は場所を示すため文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "汚さない", "is_correct": true, "explanation": "「〜ないように」に続く否定形で、手を汚さないという意味になる。"}, {"text": "汚せ", "is_correct": false, "explanation": "命令形は「ように」の前に置けず、文の形が崩れるので合わない。"}, {"text": "汚して", "is_correct": false, "explanation": "て形は「〜ように」の前に置けず、文の形が崩れるので合わない。"}, {"text": "汚せば", "is_correct": false, "explanation": "仮定形は「〜ように」と合わず、手を汚す仮定の意味になってしまうので合わない。"}], "correct_form": "汚さない", "base_form": "汚す", "form_label": "否定形", "sentence_index": 1, "explanations": {"汚さない": "「〜ないように」に続く否定形で、手を汚さないという意味になる。", "汚せ": "命令形は「ように」の前に置けず、文の形が崩れるので合わない。", "汚して": "て形は「〜ように」の前に置けず、文の形が崩れるので合わない。", "汚せば": "仮定形は「〜ように」と合わず、手を汚す仮定の意味になってしまうので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37102, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ソースをこぼして、服で汚してしまった。", "corrected_sentence": "ソースをこぼして、服を汚してしまった。", "error_description": "「服で」が誤りで、正しくは「服を」。汚す対象を示すには「を」が必要で、「で」は手段を示すため文の意味が合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "汚す", "is_correct": true, "explanation": "「〜と」に続く終止形で、ページを汚すという意味になり文に合う。"}, {"text": "汚そう", "is_correct": false, "explanation": "意志形は話し手の意向を表すため、「触ると」に続けると事実を述べる文にならず、文の形に合わない。"}, {"text": "汚し", "is_correct": false, "explanation": "連用形は文末で止まれず、「と」に続けても文が完結しないので合わない。"}, {"text": "汚さ", "is_correct": false, "explanation": "未然形は「と」の前に置けず、文が成り立たないので合わない。"}], "correct_form": "汚す", "base_form": "汚す", "form_label": "終止形", "sentence_index": 7, "explanations": {"汚す": "「〜と」に続く終止形で、ページを汚すという意味になり文に合う。", "汚そう": "意志形は話し手の意向を表すため、「触ると」に続けると事実を述べる文にならず、文の形に合わない。", "汚し": "連用形は文末で止まれず、「と」に続けても文が完結しないので合わない。", "汚さ": "未然形は「と」の前に置けず、文が成り立たないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37103, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "清める", "is_correct": true, "explanation": "物や場所を汚すの反対で、きれいにするという意味の対義語。"}, {"text": "測る", "is_correct": false, "explanation": "長さや量をはかる意味で、汚すの対義語ではないので合わない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "移動させる意味で、汚すの対義語ではないので合わない。"}, {"text": "語る", "is_correct": false, "explanation": "話して聞かせる意味で、汚すの対義語ではないので合わない。"}], "correct_answer": "清める", "explanations": {"清める": "物や場所を汚すの反対で、きれいにするという意味の対義語。", "測る": "長さや量をはかる意味で、汚すの対義語ではないので合わない。", "運ぶ": "移動させる意味で、汚すの対義語ではないので合わない。", "語る": "話して聞かせる意味で、汚すの対義語ではないので合わない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
