INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37103, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物や場所を不潔にしたり、きれいでなくしたりする。", "primary_collocate": null, "pronunciation": "よごす", "ipa": "joɡosɯ", "syllable_count": 3, "sentences": [{"text": "公園のトイレを汚さないように、きれいに使おう。", "target_word": "汚さない", "complexity_tier": "T3", "furigana": "公園[こうえん]のトイレを汚[よご]さないように、きれいに使[つか]おう。", "sentence_source": "generated"}, {"text": "机をインクで汚して、先生に注意された。", "target_word": "汚して", "complexity_tier": "T3", "furigana": "机[つくえ]をインクで汚[よご]して、先生[せんせい]に注意[ちゅうい]された。", "sentence_source": "generated"}, {"text": "排気ガスは空気を汚す原因のひとつだ。", "target_word": "汚す", "complexity_tier": "T3", "furigana": "排気[はいき]ガスは空気[くうき]を汚[よご]す原因[げんいん]のひとつだ。", "sentence_source": "generated"}, {"text": "海にごみを捨てて、きれいな砂浜を汚してはいけない。", "target_word": "汚して", "complexity_tier": "T3", "furigana": "海[うみ]にごみを捨[す]てて、きれいな砂浜[すなはま]を汚[よご]してはいけない。", "sentence_source": "generated"}, {"text": "彼は食べこぼしでテーブルを汚した。", "target_word": "汚した", "complexity_tier": "T3", "furigana": "彼[かれ]は食[た]べこぼしでテーブルを汚[よご]した。", "sentence_source": "generated"}, {"text": "新品のカーペットを汚さないよう、上に紙を敷いた。", "target_word": "汚さない", "complexity_tier": "T3", "furigana": "新品[しんぴん]のカーペットを汚[よご]さないよう、上[うえ]に紙[かみ]を敷[し]いた。", "sentence_source": "generated"}, {"text": "油で台所を汚してしまい、掃除に一時間かかった。", "target_word": "汚して", "complexity_tier": "T3", "furigana": "油[あぶら]で台所[だいどころ]を汚[よご]してしまい、掃除[そうじ]に一時間[いちじかん]かかった。", "sentence_source": "generated"}, {"text": "汚した場所は、使った人が自分で掃除する決まりだ。", "target_word": "汚した", "complexity_tier": "T3", "furigana": "汚[よご]した場所[ばしょ]は、使[つか]った人[ひと]が自分[じぶん]で掃除[そうじ]する決[き]まりだ。", "sentence_source": "generated"}, {"text": "犬の足が廊下を汚したので、タオルでふいた。", "target_word": "汚した", "complexity_tier": "T3", "furigana": "犬[いぬ]の足[あし]が廊下[ろうか]を汚[よご]したので、タオルでふいた。", "sentence_source": "generated"}, {"text": "川を汚すと、魚や生き物が住めなくなる。", "target_word": "汚す", "complexity_tier": "T3", "furigana": "川[かわ]を汚[よご]すと、魚[さかな]や生[い]き物[もの]が住[す]めなくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "汚す", "label": "終止形"}, {"form": "汚した", "label": "過去形"}, {"form": "汚して", "label": "て形"}, {"form": "汚さない", "label": "否定形"}, {"form": "汚せば", "label": "仮定形"}, {"form": "汚そう", "label": "意志形"}], "register": "標準的な普通体", "sense_fingerprint": "物や場所を不潔にして、きれいでなくする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc4c99e5-c08d-4486-b1ed-5a1851877780') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37103, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汚さない", "is_correct": true, "explanation": "トイレをよごさないように、という意味で、否定形がこの文の意味に合う。"}, {"text": "食べない", "is_correct": false, "explanation": "トイレを食べる、という意味になり、この文には合わない。"}, {"text": "歌わない", "is_correct": false, "explanation": "トイレを歌う、という意味になり、文が成り立たない。"}, {"text": "乗らない", "is_correct": false, "explanation": "トイレに乗る、という意味になり、きれいに使うという文の意味に合わない。"}], "explanations": {"汚さない": "トイレをよごさないように、という意味で、否定形がこの文の意味に合う。", "食べない": "トイレを食べる、という意味になり、この文には合わない。", "歌わない": "トイレを歌う、という意味になり、文が成り立たない。", "乗らない": "トイレに乗る、という意味になり、きれいに使うという文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "汚さない"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜、部屋の明かりを汚して、本を読んだ。", "explanation": "ここは〈消す〉の意味。明かりは消すもので、汚すとは言わないので合わない。"}, {"text": "会議の進行を汚すような発言は慎みなさい。", "explanation": "ここは〈乱す〉の意味。進行は乱すもので、汚すとは言わないので合わない。"}, {"text": "会議室の外では、声を汚して話した。", "explanation": "ここは〈落とす〉の意味。声は落とすもので、汚すとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37103, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汚して", "is_correct": true, "explanation": "油で台所をよごしたという意味で、「汚してしまい」の正しい形。"}, {"text": "眺めて", "is_correct": false, "explanation": "台所を眺めるという意味になり、油で汚れた状況に合わないので合わない。"}, {"text": "組んで", "is_correct": false, "explanation": "台所を組むという意味になり、この文の意味には合わない。"}, {"text": "乗って", "is_correct": false, "explanation": "台所に乗るという意味になり、掃除に時間がかかる文脈に合わない。"}], "explanations": {"汚して": "油で台所をよごしたという意味で、「汚してしまい」の正しい形。", "眺めて": "台所を眺めるという意味になり、油で汚れた状況に合わないので合わない。", "組んで": "台所を組むという意味になり、この文の意味には合わない。", "乗って": "台所に乗るという意味になり、掃除に時間がかかる文脈に合わない。"}, "sentence_index": 6, "correct_answer": "汚して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は大会で大きな成果を汚した。", "explanation": "ここは〈挙げる〉の意味。成果は挙げるもので、汚すとは言わないので合わない。"}, {"text": "会社は数か月で競争相手との差を汚した。", "explanation": "ここは〈縮める〉の意味。差は縮めるもので、汚すとは言わないので合わない。"}, {"text": "店は来月から客の数を汚す計画だ。", "explanation": "ここは〈増やす〉の意味。数は増やすもので、汚すとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37103, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもが絵の具で廊下に汚した。", "corrected_sentence": "子どもが絵の具で廊下を汚した。", "error_description": "「廊下に」が誤りで、正しくは「廊下を」。汚す対象を示すには「を」が必要で、「に」は場所を示すため文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "汚して", "is_correct": true, "explanation": "「汚して、先生に注意された」と続くて形で、文の流れに合う。"}, {"text": "汚せ", "is_correct": false, "explanation": "命令形は文の途中で「、」に続けられず、文が成り立たないので合わない。"}, {"text": "汚す", "is_correct": false, "explanation": "終止形では文を切ってしまい、後ろの文とつながらないので合わない。"}, {"text": "汚そう", "is_correct": false, "explanation": "意志形では文の意味が合わず、後ろの文にもつながらないので合わない。"}], "correct_form": "汚して", "base_form": "汚す", "form_label": "て形", "sentence_index": 1, "explanations": {"汚して": "「汚して、先生に注意された」と続くて形で、文の流れに合う。", "汚せ": "命令形は文の途中で「、」に続けられず、文が成り立たないので合わない。", "汚す": "終止形では文を切ってしまい、後ろの文とつながらないので合わない。", "汚そう": "意志形では文の意味が合わず、後ろの文にもつながらないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37103, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭の花壇が泥で汚してしまった。", "corrected_sentence": "庭の花壇を泥で汚してしまった。", "error_description": "「花壇が」が誤りで、正しくは「花壇を」。汚す対象には「を」が必要で、「が」は主語を示すため、汚す文の形が崩れる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "汚した", "is_correct": true, "explanation": "過去形で名詞を修飾でき、「汚した場所」という形になり文に合う。"}, {"text": "汚して", "is_correct": false, "explanation": "て形では名詞を直接修飾できず、「汚して場所」は成り立たないので合わない。"}, {"text": "汚せば", "is_correct": false, "explanation": "仮定形は名詞を修飾できず、文の形が崩れるので合わない。"}, {"text": "汚そう", "is_correct": false, "explanation": "意志形は名詞を修飾できず、文の形が崩れるので合わない。"}], "correct_form": "汚した", "base_form": "汚す", "form_label": "過去形", "sentence_index": 7, "explanations": {"汚した": "過去形で名詞を修飾でき、「汚した場所」という形になり文に合う。", "汚して": "て形では名詞を直接修飾できず、「汚して場所」は成り立たないので合わない。", "汚せば": "仮定形は名詞を修飾できず、文の形が崩れるので合わない。", "汚そう": "意志形は名詞を修飾できず、文の形が崩れるので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37106, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "存在の場所を示す「に」。「〜に〜があります」の形で、場所として正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を示す。存在を表す「あります」の文には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は動作が行われる場所を示す。存在文の場所には使えない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示す。「あります」の文には対象がないため合わない。"}], "correct_answer": "に", "explanations": {"に": "存在の場所を示す「に」。「〜に〜があります」の形で、場所として正しい。", "へ": "「へ」は移動の方向を示す。存在を表す「あります」の文には合わない。", "で": "「で」は動作が行われる場所を示す。存在文の場所には使えない。", "を": "「を」は動作の対象を示す。「あります」の文には対象がないため合わない。"}, "error_tags": {"へ": "方向", "で": "動作の場所", "を": "目的語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37106, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "話題を示す「は」。「ドアの側は寒い」と、その場所について述べる。"}, {"text": "に", "is_correct": false, "explanation": "「に」は存在や到達の場所を示す。「寒い」の前では文として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示す。形容詞「寒い」は目的語を取らないため合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を示す。「寒い」の前では方向の意味が成り立たず、不自然。"}], "correct_answer": "は", "explanations": {"は": "話題を示す「は」。「ドアの側は寒い」と、その場所について述べる。", "に": "「に」は存在や到達の場所を示す。「寒い」の前では文として成り立たない。", "を": "「を」は動作の対象を示す。形容詞「寒い」は目的語を取らないため合わない。", "へ": "「へ」は移動の方向を示す。「寒い」の前では方向の意味が成り立たず、不自然。"}, "error_tags": {"に": "存在・到達の場所", "を": "目的語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37106, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある基準で分けたときの、一方の位置や面をさす名詞です。", "primary_collocate": null, "pronunciation": "がわ", "ipa": "ɡawa", "syllable_count": 2, "sentences": [{"text": "川の北の側に大きな公園があります。", "target_word": "側", "complexity_tier": "T3", "furigana": "川[かわ]の北[きた]の側[がわ]に大[おお]きな公園[こうえん]があります。", "sentence_source": "generated"}, {"text": "道路の向こうの側に、小さな店があります。", "target_word": "側", "complexity_tier": "T3", "furigana": "道路[どうろ]の向[む]こうの側[がわ]に、小[ちい]さな店[みせ]があります。", "sentence_source": "generated"}, {"text": "山の東の側は雪が少ないです。", "target_word": "側", "complexity_tier": "T3", "furigana": "山[やま]の東[ひがし]の側[がわ]は雪[ゆき]が少[すく]ないです。", "sentence_source": "generated"}, {"text": "池の反対の側から、鳥の声が聞こえてきました。", "target_word": "側", "complexity_tier": "T3", "furigana": "池[いけ]の反対[はんたい]の側[がわ]から、鳥[とり]の声[こえ]が聞[き]こえてきました。", "sentence_source": "generated"}, {"text": "机の左の側にペンを置きました。", "target_word": "側", "complexity_tier": "T3", "furigana": "机[つくえ]の左[ひだり]の側[がわ]にペンを置[お]きました。", "sentence_source": "generated"}, {"text": "駅の南の側は静かで、住みやすいです。", "target_word": "側", "complexity_tier": "T3", "furigana": "駅[えき]の南[みなみ]の側[がわ]は静[しず]かで、住[す]みやすいです。", "sentence_source": "generated"}, {"text": "海の側は風が強いので、窓を閉めました。", "target_word": "側", "complexity_tier": "T3", "furigana": "海[うみ]の側[がわ]は風[かぜ]が強[つよ]いので、窓[まど]を閉[し]めました。", "sentence_source": "generated"}, {"text": "部屋のドアの側は寒いから、ストーブを置いた。", "target_word": "側", "complexity_tier": "T3", "furigana": "部屋[へや]のドアの側[がわ]は寒[さむ]いから、ストーブを置[お]いた。", "sentence_source": "generated"}, {"text": "橋のこちらの側は雨が降っていたが、向こうは晴れていた。", "target_word": "側", "complexity_tier": "T3", "furigana": "橋[はし]のこちらの側[がわ]は雨[あめ]が降[ふ]っていたが、向[む]こうは晴[は]れていた。", "sentence_source": "generated"}, {"text": "町の西の側には、古い家が多く残っています。", "target_word": "側", "complexity_tier": "T3", "furigana": "町[まち]の西[にし]の側[がわ]には、古[ふる]い家[いえ]が多[おお]く残[のこ]っています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "側", "label": "基本形"}], "register": "中立（標準的な話し言葉・書き言葉）", "sense_fingerprint": "ある基準を中心に、他と分けたときの一方の位置・面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1ecbb5a-fd75-4d21-9035-16b121ce40ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37106, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "側", "is_correct": true, "explanation": "「川の北の側」で場所を指す「側」。この空欄にはこれだけが入る。"}, {"text": "点", "is_correct": false, "explanation": "「点」は観点や項目の意味。「川の北の点に公園がある」は場所の文として成り立たない。"}, {"text": "件", "is_correct": false, "explanation": "「件」は事柄の意味。場所を示す形にならず、意味が通らない。"}, {"text": "数", "is_correct": false, "explanation": "「数」は数量の意味。「川の北の数に公園がある」は場所の文として不自然。"}], "explanations": {"側": "「川の北の側」で場所を指す「側」。この空欄にはこれだけが入る。", "点": "「点」は観点や項目の意味。「川の北の点に公園がある」は場所の文として成り立たない。", "件": "「件」は事柄の意味。場所を示す形にならず、意味が通らない。", "数": "「数」は数量の意味。「川の北の数に公園がある」は場所の文として不自然。"}, "sentence_index": 0, "correct_answer": "側"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏と冬では、冬の側が出かけやすい。", "explanation": "ここは「側」を比べる言い方として使った誤り。「Aより/と比べてBの方が」の比較は「方」で表すので、「側」は合わない。"}, {"text": "私は会社の側に立ちます。", "explanation": "ここは「味方・立場」の意味。場所を指す用法ではないので、この定義には合わない。"}, {"text": "昼より夜の側が、この町は静かになる。", "explanation": "ここは「側」を比較に使った誤り。比べる文の形では「方」が正しく、「側」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37106, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "側", "is_correct": true, "explanation": "「海の側」で、海のあたりの場所を指す「側」。この空欄にはこれだけが入る。"}, {"text": "組", "is_correct": false, "explanation": "「組」は集まりの意味。「海の組は風が強い」は場所として成り立たない。"}, {"text": "度", "is_correct": false, "explanation": "「度」は程度の意味。「海の度は風が強い」は不自然。"}, {"text": "段", "is_correct": false, "explanation": "「段」は段階の意味。「海の段は風が強い」は場所を表せない。"}], "explanations": {"側": "「海の側」で、海のあたりの場所を指す「側」。この空欄にはこれだけが入る。", "組": "「組」は集まりの意味。「海の組は風が強い」は場所として成り立たない。", "度": "「度」は程度の意味。「海の度は風が強い」は不自然。", "段": "「段」は段階の意味。「海の段は風が強い」は場所を表せない。"}, "sentence_index": 6, "correct_answer": "側"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "姉より妹の側が背が高い。", "explanation": "「AよりBの方が」の比較用法で使うのは「方」。「側」を入れると比べる言い方にならず、この文は不自然。"}, {"text": "雨より晴れの側が、交通が混みやすい。", "explanation": "ここは「側」を比べる言い方として使った誤り。比べるときの「〜の方が」は「方」で、「側」は合わない。"}, {"text": "電車より歩く側が、体にいいと言う人もいる。", "explanation": "ここは「側」を比較に使った誤り。比べる文では「方」を使い、「側」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37106, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "港の西の側を、古い倉庫が多く残っています。", "corrected_sentence": "港の西の側には、古い倉庫が多く残っています。", "error_description": "「残っている」と場所を示すには「には」が必要。「を」は目的語用で、ここでは場所として合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37106, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "川の南の側で、小さな橋があります。", "corrected_sentence": "川の南の側に、小さな橋があります。", "error_description": "存在を示す「あります」には「に」が必要。「で」は動作の場所を示すので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37107, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「側に」は場所や立場を示す「に」。「会社の側にも〜」の形で、ここでは正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を示す。「悪いところがあった」とは合わない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「会社の側を悪いところがありました」では文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示す。「会社の側と悪いところがあった」は成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「側に」は場所や立場を示す「に」。「会社の側にも〜」の形で、ここでは正しい。", "へ": "「へ」は移動の方向を示す。「悪いところがあった」とは合わない。", "を": "「を」は目的語を示す。「会社の側を悪いところがありました」では文として成り立たない。", "と": "「と」は並列や相手を示す。「会社の側と悪いところがあった」は成り立たない。"}, "error_tags": {"へ": "方向", "を": "目的語", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37107, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「負けた側の選手」と名詞同士をつなぐ「の」。「側」は「負けた立場」を指す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「負けた側を選手たち」では名詞同士の関係にならない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到達点や場所を示すが、「負けた側に選手たち」は関係が不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「負けた側へ選手たちも」では人の位置を表せず、不自然。"}], "correct_answer": "の", "explanations": {"の": "「負けた側の選手」と名詞同士をつなぐ「の」。「側」は「負けた立場」を指す。", "を": "「を」は目的語を示す。「負けた側を選手たち」では名詞同士の関係にならない。", "に": "「に」は到達点や場所を示すが、「負けた側に選手たち」は関係が不自然。", "へ": "「へ」は方向を示す。「負けた側へ選手たちも」では人の位置を表せず、不自然。"}, "error_tags": {"を": "目的語", "に": "存在・到達の場所", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37107, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "対立する二つのうち、一方の立場や当事者を指す名詞です。", "primary_collocate": null, "pronunciation": "がわ", "ipa": "ɡawa", "syllable_count": 2, "sentences": [{"text": "客の側に立って考えることが大切です。", "target_word": "側", "complexity_tier": "T3", "furigana": "客[きゃく]の側[がわ]に立[た]って考[かんが]えることが大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "会社の側にも、悪いところがありました。", "target_word": "側", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の側[がわ]にも、悪[わる]いところがありました。", "sentence_source": "generated"}, {"text": "先生の側から見ると、その生徒は元気そうでした。", "target_word": "側", "complexity_tier": "T3", "furigana": "先生[せんせい]の側[がわ]から見[み]ると、その生徒[せいと]は元気[げんき]そうでした。", "sentence_source": "generated"}, {"text": "親の側は反対したが、子どもの側は行きたがった。", "target_word": "側", "complexity_tier": "T3", "furigana": "親[おや]の側[がわ]は反対[はんたい]したが、子[こ]どもの側[がわ]は行[い]きたがった。", "sentence_source": "generated"}, {"text": "相手の側の意見も、ちゃんと聞いてください。", "target_word": "側", "complexity_tier": "T3", "furigana": "相手[あいて]の側[がわ]の意見[いけん]も、ちゃんと聞[き]いてください。", "sentence_source": "generated"}, {"text": "私は弱い人の側に立ちたいと思います。", "target_word": "側", "complexity_tier": "T3", "furigana": "私[わたし]は弱[よわ]い人[ひと]の側[がわ]に立[た]ちたいと思[おも]います。", "sentence_source": "generated"}, {"text": "店の側が間違いを認めて、お金を返してくれた。", "target_word": "側", "complexity_tier": "T3", "furigana": "店[みせ]の側[がわ]が間違[まちが]いを認[みと]めて、お金[かね]を返[かえ]してくれた。", "sentence_source": "generated"}, {"text": "負けた側の選手たちも、笑顔で拍手をしました。", "target_word": "側", "complexity_tier": "T3", "furigana": "負[ま]けた側[がわ]の選手[せんしゅ]たちも、笑顔[えがお]で拍手[はくしゅ]をしました。", "sentence_source": "generated"}, {"text": "市の側は、新しい道路を作る計画を発表しました。", "target_word": "側", "complexity_tier": "T3", "furigana": "市[し]の側[がわ]は、新[あたら]しい道路[どうろ]を作[つく]る計画[けいかく]を発表[はっぴょう]しました。", "sentence_source": "generated"}, {"text": "作る側の気持ちも、食べる側の気持ちも大事です。", "target_word": "側", "complexity_tier": "T3", "furigana": "作[つく]る側[がわ]の気持[きも]ちも、食[た]べる側[がわ]の気持[きも]ちも大事[だいじ]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "側", "label": "基本形"}], "register": "中立（標準的な話し言葉・書き言葉）", "sense_fingerprint": "対立する二者のうち、一方の立場・グループ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1ecbb5a-fd75-4d21-9035-16b121ce40ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37107, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "側", "is_correct": true, "explanation": "「客の側に立つ」で、相手の立場や味方になる意味の「側」。この空欄にはこれだけが入る。"}, {"text": "点", "is_correct": false, "explanation": "「点」は観点の意味。「客の点に立つ」は立場を表す言い方にならない。"}, {"text": "件", "is_correct": false, "explanation": "「件」は事柄の意味。「客の件に立つ」は成り立たない。"}, {"text": "数", "is_correct": false, "explanation": "「数」は数量の意味。「客の数に立つ」は意味が通らない。"}], "explanations": {"側": "「客の側に立つ」で、相手の立場や味方になる意味の「側」。この空欄にはこれだけが入る。", "点": "「点」は観点の意味。「客の点に立つ」は立場を表す言い方にならない。", "件": "「件」は事柄の意味。「客の件に立つ」は成り立たない。", "数": "「数」は数量の意味。「客の数に立つ」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "側"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨より晴れの側が、交通が混みやすい。", "explanation": "ここは「側」を比べる言い方として使った誤り。比べるときは「方」を使うので、「側」は合わない。"}, {"text": "夏より冬の側が出かけやすい。", "explanation": "比べる言い方の「方」と取り違えた例。「側」は立場を表すので、比べる文には合わない。"}, {"text": "バスの側が、三十分遅れて来た。", "explanation": "ここは「側」を乗り物を主語にして使った誤り。立場や方向を表す「側」ではこの言い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37107, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "側", "is_correct": true, "explanation": "「店の側」で、店という当事者の立場を指す「側」。この空欄にはこれだけが入る。"}, {"text": "組", "is_correct": false, "explanation": "「組」は集まりの意味。当事者の立場を表す形にならず、不自然。"}, {"text": "度", "is_correct": false, "explanation": "「度」は程度の意味。「店の度が間違いを認めて」は成り立たない。"}, {"text": "段", "is_correct": false, "explanation": "「段」は段階の意味。「店の段が」は主語として不自然。"}], "explanations": {"側": "「店の側」で、店という当事者の立場を指す「側」。この空欄にはこれだけが入る。", "組": "「組」は集まりの意味。当事者の立場を表す形にならず、不自然。", "度": "「度」は程度の意味。「店の度が間違いを認めて」は成り立たない。", "段": "「段」は段階の意味。「店の段が」は主語として不自然。"}, "sentence_index": 6, "correct_answer": "側"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜より朝の側が、この町は静かになる。", "explanation": "ここは「側」を比べる言い方として使った誤り。比較は「方」で表すので、「側」は合わない。"}, {"text": "昨日より今日の側が体の調子がいい。", "explanation": "「方」の比較用法を取り違えた例。「側」は立場を表すので、比べる文の形には使えない。"}, {"text": "電車の側が、五分遅れて来た。", "explanation": "ここは「側」を乗り物を主語にして使った誤り。立場や方向を表す「側」ではこの言い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37107, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上司の側に見ると、新人は落ち着いて見えます。", "corrected_sentence": "上司の側から見ると、新人は落ち着いて見えます。", "error_description": "「立場から見る」は「〜の側から見る」。「に」は場所を表すので、この立場からの見方を表せない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37107, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は弱い人の側を立ちたいと思います。", "corrected_sentence": "私は弱い人の側に立つべきだと思います。", "error_description": "「側に立つ」の形で、「立つ」は「に」を取る。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37110, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「人の勝ち」は名詞をつなぐ「の」で、その人が得る勝利という意味になる。"}, {"text": "を", "is_correct": false, "explanation": "「人を勝ちです」は、とった人が主語なので目的語の「を」で示すことはできず、不自然な文になる。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すもので、名詞どうしをつなぐ役割はない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「人と勝ち」では人と勝利が並ぶ意味にならない。"}], "correct_answer": "の", "explanations": {"の": "「人の勝ち」は名詞をつなぐ「の」で、その人が得る勝利という意味になる。", "を": "「人を勝ちです」は、とった人が主語なので目的語の「を」で示すことはできず、不自然な文になる。", "で": "「で」は場所や手段を示すもので、名詞どうしをつなぐ役割はない。", "と": "「と」は並列や相手を示すが、「人と勝ち」では人と勝利が並ぶ意味にならない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "と": "並列・相手"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "負け", "is_correct": true, "explanation": "勝ちの対義語で、試合や遊びで相手に敗れること。"}, {"text": "引き分け", "is_correct": false, "explanation": "勝ちも負けもつかない結果で、勝ちの対義語ではない。"}, {"text": "失敗", "is_correct": false, "explanation": "成功の対義語で、勝ち負けの対義語ではない。"}, {"text": "練習", "is_correct": false, "explanation": "勝負に向けた準備であり、結果の対義語ではない。"}], "correct_answer": "負け", "explanations": {"負け": "勝ちの対義語で、試合や遊びで相手に敗れること。", "引き分け": "勝ちも負けもつかない結果で、勝ちの対義語ではない。", "失敗": "成功の対義語で、勝ち負けの対義語ではない。", "練習": "勝負に向けた準備であり、結果の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37110, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "負け", "is_correct": true, "explanation": "勝ちの対義語で、試合や遊びで相手に敗れること。"}, {"text": "応援", "is_correct": false, "explanation": "選手を支える行動で、結果の対義語ではない。"}, {"text": "準備", "is_correct": false, "explanation": "試合の前に行うことで、勝ち負けの対義語ではない。"}, {"text": "見学", "is_correct": false, "explanation": "試合を見ることで、結果の反対を表す語ではない。"}], "correct_answer": "負け", "explanations": {"負け": "勝ちの対義語で、試合や遊びで相手に敗れること。", "応援": "選手を支える行動で、結果の対義語ではない。", "準備": "試合の前に行うことで、勝ち負けの対義語ではない。", "見学": "試合を見ることで、結果の反対を表す語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37110, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "まけるの はんたい。たたかいや ゲームで いちばんに なること。", "primary_collocate": null, "pronunciation": "かち", "ipa": "katɕi", "syllable_count": 2, "sentences": [{"text": "じゃんけんで、わたしの勝ちになりました。", "target_word": "勝ち", "complexity_tier": "T3", "furigana": "じゃんけんで、わたしの勝[か]ちになりました。", "sentence_source": "generated"}, {"text": "このゲームは、先に五回とった人の勝ちです。", "target_word": "勝ち", "complexity_tier": "T3", "furigana": "このゲームは、先[さき]に五回[ごかい]とった人[ひと]の勝[か]ちです。", "sentence_source": "generated"}, {"text": "最後の一枚を出して、ぼくの勝ちだ。", "target_word": "勝ち", "complexity_tier": "T3", "furigana": "最後[さいご]の一枚[いちまい]を出[だ]して、ぼくの勝[か]ちだ。", "sentence_source": "generated"}, {"text": "かけっこは、いちばんにゴールした人の勝ちです。", "target_word": "勝ち", "complexity_tier": "T3", "furigana": "かけっこは、いちばんにゴールした人[ひと]の勝[か]ちです。", "sentence_source": "generated"}, {"text": "時間までにボールを多く入れたチームの勝ちと決めた。", "target_word": "勝ち", "complexity_tier": "T3", "furigana": "時間[じかん]までにボールを多[おお]く入[い]れたチームの勝[か]ちと決[き]めた。", "sentence_source": "generated"}, {"text": "今日は勝ちを兄にゆずってあげました。", "target_word": "勝ち", "complexity_tier": "T3", "furigana": "今日[きょう]は勝[か]ちを兄[あに]にゆずってあげました。", "sentence_source": "generated"}, {"text": "勝ちが決まると、みんなでよろこびました。", "target_word": "勝ち", "complexity_tier": "T3", "furigana": "勝[か]ちが決[き]まると、みんなでよろこびました。", "sentence_source": "generated"}, {"text": "負けても楽しかったけれど、やっぱり勝ちはうれしいです。", "target_word": "勝ち", "complexity_tier": "T3", "furigana": "負[ま]けても楽[たの]しかったけれど、やっぱり勝[か]ちはうれしいです。", "sentence_source": "generated"}, {"text": "このおにごっこは、つかまらなかった人の勝ちです。", "target_word": "勝ち", "complexity_tier": "T3", "furigana": "このおにごっこは、つかまらなかった人[ひと]の勝[か]ちです。", "sentence_source": "generated"}, {"text": "さいごに点が多い人が勝ちで、少ない人は負けです。", "target_word": "勝ち", "complexity_tier": "T3", "furigana": "さいごに点[てん]が多[おお]い人[ひと]が勝[か]ちで、少[すく]ない人[ひと]は負[ま]けです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "勝ち", "label": "基本形"}], "register": "中立（日常会話・遊びの場面）", "sense_fingerprint": "遊びやゲームで、相手より先に・多く取って一番になること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: ゆずっ (Zipf 2.48)','sentence 8 above tier T2: contains vocabulary far above tier T2: つかまら (Zipf 2.12)']::text[], 'c1ecbb5a-fd75-4d21-9035-16b121ce40ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37110, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "勝ち", "is_correct": true, "explanation": "「わたしの勝ち」はじゃんけんで勝った結果を表し、「なりました」と自然につながる。"}, {"text": "紙", "is_correct": false, "explanation": "じゃんけんの手の名前で、結果を表す名詞ではない。「わたしの紙になりました」は意味が通らない。"}, {"text": "石", "is_correct": false, "explanation": "じゃんけんのグーの名前で、勝負の結果としては使えない。「わたしの石になりました」は成り立たない。"}, {"text": "点", "is_correct": false, "explanation": "得点を表すが、じゃんけんの結果を「わたしの点になりました」とは言わない。"}], "explanations": {"勝ち": "「わたしの勝ち」はじゃんけんで勝った結果を表し、「なりました」と自然につながる。", "紙": "じゃんけんの手の名前で、結果を表す名詞ではない。「わたしの紙になりました」は意味が通らない。", "石": "じゃんけんのグーの名前で、勝負の結果としては使えない。「わたしの石になりました」は成り立たない。", "点": "得点を表すが、じゃんけんの結果を「わたしの点になりました」とは言わない。"}, "sentence_index": 0, "correct_answer": "勝ち"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "くじの勝ちは、箱入りの菓子だった。", "explanation": "「勝ち」を賞品の意味で使うのは誤り。勝ちは競争の結果を表し、もらえる品物を指す語ではない。"}, {"text": "雨がひどくなって、勝ちは中止になった。", "explanation": "「勝ち」を試合そのものの意味で使うのは誤り。勝ちは結果なので、中止になるのは試合のほうだ。"}, {"text": "後半に勝ちが入って、同点になった。", "explanation": "「勝ち」をボールや点のように入るものの意味で使うのは誤り。勝ちは勝利という結果を表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37110, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "勝ち", "is_correct": true, "explanation": "「勝ちが決まる」は勝敗が確定することを表し、文に合う。"}, {"text": "駒", "is_correct": false, "explanation": "ゲームで使う道具だが、「駒が決まる」は意味が通らない。"}, {"text": "札", "is_correct": false, "explanation": "トランプなどの一枚で、勝敗の決定を表さない。「札が決まる」は成り立たない。"}, {"text": "屋根", "is_correct": false, "explanation": "建物の一部で、「屋根が決まる」は勝敗の決定とは結びつかず、文が成り立たない。"}], "explanations": {"勝ち": "「勝ちが決まる」は勝敗が確定することを表し、文に合う。", "駒": "ゲームで使う道具だが、「駒が決まる」は意味が通らない。", "札": "トランプなどの一枚で、勝敗の決定を表さない。「札が決まる」は成り立たない。", "屋根": "建物の一部で、「屋根が決まる」は勝敗の決定とは結びつかず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "勝ち"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大会の勝ちが記念品を受け取った。", "explanation": "「勝ち」を勝者（人）の意味で使うのは誤り。勝ちは勝利という出来事なので、記念品を受け取る人にはなれない。"}, {"text": "勝ちが笛を吹いて、試合が終わった。", "explanation": "「勝ち」を審判の意味で使うのは誤り。勝ちは結果なので、笛を吹く人にはなれない。"}, {"text": "勝ちは次の大会に向けて練習を続けた。", "explanation": "「勝ち」をチームの意味で使うのは誤り。勝ちは勝利という結果なので、練習を続ける主体にはなれない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37110, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先に三点とったら、勝ちを決まる。", "corrected_sentence": "先に三点とったら、勝ちが決まる。", "error_description": "「決まる」は自動詞なので、主語を示す「が」が必要。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37110, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先に十点とった人が勝ちでなる。", "corrected_sentence": "先に十点とった人が勝ちになる。", "error_description": "「なる」は変化の結果を「に」で示す。「で」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37111, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「宣言する」は他動詞で、宣言の対象を「を」で示す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や相手を示すが、「勝ちに宣言した」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示し、宣言の対象にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐもので、後ろに宣言する動詞が続く文型にならない。"}], "correct_answer": "を", "explanations": {"を": "「宣言する」は他動詞で、宣言の対象を「を」で示す。", "に": "「に」は方向や相手を示すが、「勝ちに宣言した」は成り立たない。", "で": "「で」は場所や手段を示し、宣言の対象にはならない。", "の": "「の」は名詞をつなぐもので、後ろに宣言する動詞が続く文型にならない。"}, "error_tags": {"に": "方向・相手", "で": "場所・手段", "の": "名詞をつなぐ"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "負け", "is_correct": true, "explanation": "勝ちの対義語で、試合で相手に敗れること。"}, {"text": "同点", "is_correct": false, "explanation": "得点が並んだ状態で、勝ちの反対語ではない。"}, {"text": "得点", "is_correct": false, "explanation": "点を取ることで、勝敗の反対を表す語ではない。"}, {"text": "練習", "is_correct": false, "explanation": "結果を出すための準備で、対義語ではない。"}], "correct_answer": "負け", "explanations": {"負け": "勝ちの対義語で、試合で相手に敗れること。", "同点": "得点が並んだ状態で、勝ちの反対語ではない。", "得点": "点を取ることで、勝敗の反対を表す語ではない。", "練習": "結果を出すための準備で、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37111, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「今回の勝ち」は名詞をつなぐ「の」で、今回の勝利という意味になる。"}, {"text": "が", "is_correct": false, "explanation": "「今回が勝ち」では今回そのものが勝ちになり、不自然な文になる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すもので、勝ちにつながる役割はない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示し、今回と勝ちが並ぶ意味になり不自然。"}], "correct_answer": "の", "explanations": {"の": "「今回の勝ち」は名詞をつなぐ「の」で、今回の勝利という意味になる。", "が": "「今回が勝ち」では今回そのものが勝ちになり、不自然な文になる。", "へ": "「へ」は方向を示すもので、勝ちにつながる役割はない。", "と": "「と」は並列や相手を示し、今回と勝ちが並ぶ意味になり不自然。"}, "error_tags": {"が": "主語", "へ": "方向", "と": "並列・相手"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "負け", "is_correct": true, "explanation": "勝ちの対義語で、試合で相手に敗れること。"}, {"text": "引き分け", "is_correct": false, "explanation": "勝ち負けが決まらない結果で、勝ちの反対語ではない。"}, {"text": "応援", "is_correct": false, "explanation": "選手を支える行動で、結果の対義語ではない。"}, {"text": "準備", "is_correct": false, "explanation": "試合の前に行うことで、勝ち負けの対義語ではない。"}], "correct_answer": "負け", "explanations": {"負け": "勝ちの対義語で、試合で相手に敗れること。", "引き分け": "勝ち負けが決まらない結果で、勝ちの反対語ではない。", "応援": "選手を支える行動で、結果の対義語ではない。", "準備": "試合の前に行うことで、勝ち負けの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37111, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "競争や試合などで、他の人やチームよりも優れた結果を出すこと。", "primary_collocate": null, "pronunciation": "かち", "ipa": "katɕi", "syllable_count": 2, "sentences": [{"text": "九回の逆転で、うちのチームの勝ちが決まった。", "target_word": "勝ち", "complexity_tier": "T3", "furigana": "九回[きゅうかい]の逆転[ぎゃくてん]で、うちのチームの勝[か]ちが決[き]まった。", "sentence_source": "generated"}, {"text": "審判は、赤い選手の勝ちを宣言した。", "target_word": "勝ち", "complexity_tier": "T3", "furigana": "審判[しんぱん]は、赤[あか]い選手[せんしゅ]の勝[か]ちを宣言[せんげん]した。", "sentence_source": "generated"}, {"text": "相手が棄権したので、不戦のまま彼女の勝ちとなった。", "target_word": "勝ち", "complexity_tier": "T3", "furigana": "相手[あいて]が棄権[きけん]したので、不戦[ふせん]のまま彼女[かのじょ]の勝[か]ちとなった。", "sentence_source": "generated"}, {"text": "三対二で、地元チームの勝ちに終わった。", "target_word": "勝ち", "complexity_tier": "T3", "furigana": "三対二[さんたいに]で、地元[じもと]チームの勝[か]ちに終[お]わった。", "sentence_source": "generated"}, {"text": "一点を守りきって、苦しい試合に勝ちを収めた。", "target_word": "勝ち", "complexity_tier": "T3", "furigana": "一点[いってん]を守[まも]りきって、苦[くる]しい試合[しあい]に勝[か]ちを収[おさ]めた。", "sentence_source": "generated"}, {"text": "勝ちが続いているので、監督は選手の調子に満足している。", "target_word": "勝ち", "complexity_tier": "T3", "furigana": "勝[か]ちが続[つづ]いているので、監督[かんとく]は選手[せんしゅ]の調子[ちょうし]に満足[まんぞく]している。", "sentence_source": "generated"}, {"text": "最後の一問に正解して、君の勝ちだよ。", "target_word": "勝ち", "complexity_tier": "T3", "furigana": "最後[さいご]の一問[いちもん]に正解[せいかい]して、君[きみ]の勝[か]ちだよ。", "sentence_source": "generated"}, {"text": "今回の勝ちは、毎日の練習のおかげだと思います。", "target_word": "勝ち", "complexity_tier": "T3", "furigana": "今回[こんかい]の勝[か]ちは、毎日[まいにち]の練習[れんしゅう]のおかげだと思[おも]います。", "sentence_source": "generated"}, {"text": "判定の結果、青コーナーの選手の勝ちとなりました。", "target_word": "勝ち", "complexity_tier": "T3", "furigana": "判定[はんてい]の結果[けっか]、青[あお]コーナーの選手[せんしゅ]の勝[か]ちとなりました。", "sentence_source": "generated"}, {"text": "彼は大きな勝ちより、小さな勝ちを積み重ねるほうを大切にしている。", "target_word": "勝ち", "complexity_tier": "T3", "furigana": "彼[かれ]は大[おお]きな勝[か]ちより、小[ちい]さな勝[か]ちを積[つ]み重[かさ]ねるほうを大切[たいせつ]にしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "勝ち", "label": "基本形"}], "register": "中立（試合・報道でも使う）", "sense_fingerprint": "試合や競争で、相手より優れた結果を出して得た結果としての勝利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: 不戦 (Zipf 2.33)']::text[], 'c1ecbb5a-fd75-4d21-9035-16b121ce40ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37111, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "勝ち", "is_correct": true, "explanation": "「チームの勝ちが決まった」は試合の勝利が確定したことを表し、文に合う。"}, {"text": "観客", "is_correct": false, "explanation": "試合を見る人で、「観客が決まった」は意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "試合の周囲の状況で、勝敗の決定とは結びつかない。"}, {"text": "芝生", "is_correct": false, "explanation": "グラウンドの一部で、「芝生が決まった」は成り立たない。"}], "explanations": {"勝ち": "「チームの勝ちが決まった」は試合の勝利が確定したことを表し、文に合う。", "観客": "試合を見る人で、「観客が決まった」は意味が通らない。", "天気": "試合の周囲の状況で、勝敗の決定とは結びつかない。", "芝生": "グラウンドの一部で、「芝生が決まった」は成り立たない。"}, "sentence_index": 0, "correct_answer": "勝ち"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大雨で勝ちが翌日に延期された。", "explanation": "「勝ち」を試合そのものの意味で使うのは誤り。勝ちは結果を指すので、延期されるのは試合のほうだ。"}, {"text": "後半に勝ちが入って、試合が動いた。", "explanation": "「勝ち」をボールや点のように入るものの意味で使うのは誤り。勝ちは勝利という結果を表す。"}, {"text": "前半の失点が響いて、勝ちを喫した。", "explanation": "「喫する」は敗北や苦杯を目的語にするので、勝ちを目的語にするのは誤り。勝ちは勝利という結果を表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37111, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "勝ち", "is_correct": true, "explanation": "「君の勝ちだよ」は試合や問題で勝ったことを表し、文に合う。"}, {"text": "答案", "is_correct": false, "explanation": "解答用紙を指すが、「君の答案だよ」では勝ちの意味にならない。"}, {"text": "解説", "is_correct": false, "explanation": "問題の説明を指すので、勝利を表す文には合わない。"}, {"text": "問題", "is_correct": false, "explanation": "解く対象であり、「君の問題だよ」では勝利を示せない。"}], "explanations": {"勝ち": "「君の勝ちだよ」は試合や問題で勝ったことを表し、文に合う。", "答案": "解答用紙を指すが、「君の答案だよ」では勝ちの意味にならない。", "解説": "問題の説明を指すので、勝利を表す文には合わない。", "問題": "解く対象であり、「君の問題だよ」では勝利を示せない。"}, "sentence_index": 6, "correct_answer": "勝ち"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合の判定を下すのは勝ちだ。", "explanation": "「勝ち」を審判の意味で使うのは誤り。勝ちは結果なので、判定を下す人にはなれない。"}, {"text": "勝ちは、記者会見で喜びを語った。", "explanation": "「勝ち」を勝者（人）の意味で使うのは誤り。勝ちは出来事なので、喜びを語る主体にはなれない。"}, {"text": "勝ちは、選手を集めて作戦を説明した。", "explanation": "「勝ち」を監督の意味で使うのは誤り。勝ちは結果なので、選手を集めて説明する人にはなれない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37111, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "接戦の末、ぼくのチームは勝ちに得た。", "corrected_sentence": "接戦の末、ぼくのチームは勝ちを得た。", "error_description": "「得る」は目的語を「を」で示す。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37111, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "延長戦の末、ぼくのチームは勝ちを終わった。", "corrected_sentence": "延長戦の末、ぼくのチームは勝ちに終わった。", "error_description": "「終わる」は結果の状態を「に」で示す。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37112, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「広場では」の「で」は場所を示し、子どもたちが遊ぶ場所を表す。"}, {"text": "が", "is_correct": false, "explanation": "「広場が」は主語になるが、後ろに「は」が続くと意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「広場をは」では文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐもので、「広場のは」では文の骨組みが合わない。"}], "correct_answer": "で", "explanations": {"で": "「広場では」の「で」は場所を示し、子どもたちが遊ぶ場所を表す。", "が": "「広場が」は主語になるが、後ろに「は」が続くと意味が通らない。", "を": "「を」は目的語を示すが、「広場をは」では文が成り立たない。", "の": "「の」は名詞をつなぐもので、「広場のは」では文の骨組みが合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "の": "名詞をつなぐ"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37112, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「広場でハトにえさをやる」の「で」は、行う場所を示す。"}, {"text": "に", "is_correct": false, "explanation": "「広場にハトに」は場所と相手が重なり、不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、えさをやる場所の意味にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示し、広場とハトが並ぶ意味になり不自然。"}], "correct_answer": "で", "explanations": {"で": "「広場でハトにえさをやる」の「で」は、行う場所を示す。", "に": "「広場にハトに」は場所と相手が重なり、不自然になる。", "へ": "「へ」は方向を示すので、えさをやる場所の意味にはならない。", "と": "「と」は並列や相手を示し、広場とハトが並ぶ意味になり不自然。"}, "error_tags": {"に": "方向・相手", "へ": "方向", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37112, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "みんながつかう、ひろいそとばのことです。", "primary_collocate": null, "pronunciation": "ひろば", "ipa": "çiɾoba", "syllable_count": 3, "sentences": [{"text": "駅の前の広場で、友だちと待ち合わせをしました。", "target_word": "広場", "complexity_tier": "T3", "furigana": "駅[えき]の前[まえ]の広場[ひろば]で、友[とも]だちと待[ま]ち合[あ]わせをしました。", "sentence_source": "generated"}, {"text": "広場では、子どもたちがボールで遊んでいます。", "target_word": "広場", "complexity_tier": "T3", "furigana": "広場[ひろば]では、子[こ]どもたちがボールで遊[あそ]んでいます。", "sentence_source": "generated"}, {"text": "日曜日の広場には、野菜を売る店が出ます。", "target_word": "広場", "complexity_tier": "T3", "furigana": "日曜日[にちようび]の広場[ひろば]には、野菜[やさい]を売[う]る店[みせ]が出[で]ます。", "sentence_source": "generated"}, {"text": "広場のまん中に、大きな木が立っています。", "target_word": "広場", "complexity_tier": "T3", "furigana": "広場[ひろば]のまん中[なか]に、大[おお]きな木[き]が立[た]っています。", "sentence_source": "generated"}, {"text": "町のみんなが広場に集まって、お祭りをしました。", "target_word": "広場", "complexity_tier": "T3", "furigana": "町[まち]のみんなが広場[ひろば]に集[あつ]まって、お祭[まつ]りをしました。", "sentence_source": "generated"}, {"text": "広場にはベンチがあるので、少し休みましょう。", "target_word": "広場", "complexity_tier": "T3", "furigana": "広場[ひろば]にはベンチがあるので、少[すこ]し休[やす]みましょう。", "sentence_source": "generated"}, {"text": "雨がやんだので、広場に人が出てきた。", "target_word": "広場", "complexity_tier": "T3", "furigana": "雨[あめ]がやんだので、広場[ひろば]に人[ひと]が出[で]てきた。", "sentence_source": "generated"}, {"text": "広場でハトにえさをやるのが好きです。", "target_word": "広場", "complexity_tier": "T3", "furigana": "広場[ひろば]でハトにえさをやるのが好[す]きです。", "sentence_source": "generated"}, {"text": "学校の広場は広いので、運動会にも使います。", "target_word": "広場", "complexity_tier": "T3", "furigana": "学校[がっこう]の広場[ひろば]は広[ひろ]いので、運動会[うんどうかい]にも使[つか]います。", "sentence_source": "generated"}, {"text": "夜の広場は静かで、少しこわかった。", "target_word": "広場", "complexity_tier": "T3", "furigana": "夜[よる]の広場[ひろば]は静[しず]かで、少[すこ]しこわかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "広場", "label": "基本形"}], "register": "中立（日常会話）", "sense_fingerprint": "みんなが集まって遊んだり休んだりする、広い屋外の場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1ecbb5a-fd75-4d21-9035-16b121ce40ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37112, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "広場", "is_correct": true, "explanation": "駅前の広場で待ち合わせるという文脈に合う。"}, {"text": "切符", "is_correct": false, "explanation": "駅で使う物で、「駅の前の切符で待ち合わせ」は場所として成り立たない。"}, {"text": "時刻表", "is_correct": false, "explanation": "駅にある掲示物で、待ち合わせの場所としては合わない。"}, {"text": "線路", "is_correct": false, "explanation": "電車が走る場所で、待ち合わせの場所にはならない。"}], "explanations": {"広場": "駅前の広場で待ち合わせるという文脈に合う。", "切符": "駅で使う物で、「駅の前の切符で待ち合わせ」は場所として成り立たない。", "時刻表": "駅にある掲示物で、待ち合わせの場所としては合わない。", "線路": "電車が走る場所で、待ち合わせの場所にはならない。"}, "sentence_index": 0, "correct_answer": "広場"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "広場に帰って、家族と夕食をとった。", "explanation": "「広場」を家の意味で使うのは誤り。広場は屋外の公共空間で、帰って暮らす場所ではない。"}, {"text": "広場の保育室で、子どもが昼寝をした。", "explanation": "「広場」を保育室の意味で使うのは誤り。広場は屋外で、昼寝をする部屋ではない。"}, {"text": "広場のかぎをかけて、出かけた。", "explanation": "「広場」を玄関の意味で使うのは誤り。広場にはかぎをかける出入り口がないので、かぎをかける場所として合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37112, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "広場", "is_correct": true, "explanation": "雨がやんで人が出てくる屋外の場所として自然に合う。"}, {"text": "水たまり", "is_correct": false, "explanation": "雨の後にできるが、人が出てくる場所ではない。「水たまりに人が出てきた」は不自然。"}, {"text": "花瓶", "is_correct": false, "explanation": "屋内で使う容器で、人が出てくる場所にはならない。"}, {"text": "郵便ポスト", "is_correct": false, "explanation": "手紙を入れる箱で、人が出てくる場所ではない。"}], "explanations": {"広場": "雨がやんで人が出てくる屋外の場所として自然に合う。", "水たまり": "雨の後にできるが、人が出てくる場所ではない。「水たまりに人が出てきた」は不自然。", "花瓶": "屋内で使う容器で、人が出てくる場所にはならない。", "郵便ポスト": "手紙を入れる箱で、人が出てくる場所ではない。"}, "sentence_index": 6, "correct_answer": "広場"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "広場の機械が、一日中大きな音を立てている。", "explanation": "「広場」を工場の意味で使うのは誤り。広場に機械はなく、機械が動く場所とは言えない。"}, {"text": "広場の流しで、野菜を洗った。", "explanation": "「広場」を台所の意味で使うのは誤り。流しは台所の設備で、広場にはない。"}, {"text": "広場の診察台に、子どもを寝かせた。", "explanation": "「広場」を診察室の意味で使うのは誤り。広場には診察台がなく、患者を診る部屋とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37112, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅前の広場を、人がたくさん集まっている。", "corrected_sentence": "駅前の広場に、人がたくさん集まっている。", "error_description": "「集まる」は到達する場所を「に」で示す。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37112, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもたちが広場が走っている。", "corrected_sentence": "子どもたちが広場を走っている。", "error_description": "「走る」は通る場所を「を」で示す。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37113, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「市役所の広場」は名詞をつなぐ「の」で、市役所に属する広場を表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語につくが、「市役所を広場で」は文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「市役所で広場で」と場所が二重になり、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「市役所へ広場で」では意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「市役所の広場」は名詞をつなぐ「の」で、市役所に属する広場を表す。", "を": "「を」は目的語につくが、「市役所を広場で」は文が成り立たない。", "で": "「市役所で広場で」と場所が二重になり、不自然。", "へ": "「へ」は方向を示すが、「市役所へ広場で」では意味が通らない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
