INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37113, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "建物に囲まれていない、広くて開けた場所。公園や駅前などの公共の空間。", "primary_collocate": null, "pronunciation": "ひろば", "ipa": "çiɾoba", "syllable_count": 3, "sentences": [{"text": "駅前の広場には、大きな時計が立っている。", "target_word": "広場", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の広場[ひろば]には、大[おお]きな時計[とけい]が立[た]っている。", "sentence_source": "generated"}, {"text": "市役所の広場で、週末に朝市が開かれる。", "target_word": "広場", "complexity_tier": "T3", "furigana": "市役所[しやくしょ]の広場[ひろば]で、週末[しゅうまつ]に朝市[あさいち]が開[ひら]かれる。", "sentence_source": "generated"}, {"text": "ヨーロッパの古い町には、教会の前に広場がある。", "target_word": "広場", "complexity_tier": "T3", "furigana": "ヨーロッパの古[ふる]い町[まち]には、教会[きょうかい]の前[まえ]に広場[ひろば]がある。", "sentence_source": "generated"}, {"text": "広場の周りには、カフェや店が並んでいる。", "target_word": "広場", "complexity_tier": "T3", "furigana": "広場[ひろば]の周[まわ]りには、カフェや店[みせ]が並[なら]んでいる。", "sentence_source": "generated"}, {"text": "広場を横切ると、美術館の入り口が見えます。", "target_word": "広場", "complexity_tier": "T3", "furigana": "広場[ひろば]を横切[よこぎ]ると、美術館[びじゅつかん]の入[い]り口[ぐち]が見[み]えます。", "sentence_source": "generated"}, {"text": "新しい広場ができて、駅前が明るくなった。", "target_word": "広場", "complexity_tier": "T3", "furigana": "新[あたら]しい広場[ひろば]ができて、駅前[えきまえ]が明[あか]るくなった。", "sentence_source": "generated"}, {"text": "広場に噴水があり、観光客が写真を撮っている。", "target_word": "広場", "complexity_tier": "T3", "furigana": "広場[ひろば]に噴水[ふんすい]があり、観光客[かんこうきゃく]が写真[しゃしん]を撮[と]っている。", "sentence_source": "generated"}, {"text": "選手たちは、広場に集まって出発式を行った。", "target_word": "広場", "complexity_tier": "T3", "furigana": "選手[せんしゅ]たちは、広場[ひろば]に集[あつ]まって出発式[しゅっぱつしき]を行[おこな]った。", "sentence_source": "generated"}, {"text": "広場でコンサートが開かれるので、道が混んでいる。", "target_word": "広場", "complexity_tier": "T3", "furigana": "広場[ひろば]でコンサートが開[ひら]かれるので、道[みち]が混[こ]んでいる。", "sentence_source": "generated"}, {"text": "住民が広場の掃除を毎月みんなでしている。", "target_word": "広場", "complexity_tier": "T3", "furigana": "住民[じゅうみん]が広場[ひろば]の掃除[そうじ]を毎月[まいつき]みんなでしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "広場", "label": "基本形"}], "register": "中立（標準的な話し言葉・書き言葉）", "sense_fingerprint": "駅前や建物の前などにある、開けた公共の空間", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1ecbb5a-fd75-4d21-9035-16b121ce40ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37113, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "広場", "is_correct": true, "explanation": "駅前の屋外の開けた場所で、大きな時計が立つ場所として合う。"}, {"text": "天井", "is_correct": false, "explanation": "屋内の上部で、「駅前の天井に大きな時計が立っている」は成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "建物の開口部で、時計が立つ場所としては不自然。"}, {"text": "床", "is_correct": false, "explanation": "建物の下部の面で、駅前には当てはまらず「立っている」と合わない。"}], "explanations": {"広場": "駅前の屋外の開けた場所で、大きな時計が立つ場所として合う。", "天井": "屋内の上部で、「駅前の天井に大きな時計が立っている」は成り立たない。", "窓": "建物の開口部で、時計が立つ場所としては不自然。", "床": "建物の下部の面で、駅前には当てはまらず「立っている」と合わない。"}, "sentence_index": 0, "correct_answer": "広場"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "広場の湯船で、ゆっくり体を温めた。", "explanation": "「広場」を浴室の意味で使うのは誤り。広場に湯船はなく、お湯につかる場所とは言えない。"}, {"text": "広場の職員室で、先生たちが会議を開いた。", "explanation": "「広場」を職員室の意味で使うのは誤り。広場には先生の机や部屋はなく、職員が集まる場所とは言えない。"}, {"text": "広場の金庫に、大切な書類をしまった。", "explanation": "「広場」を金庫の意味で使うのは誤り。広場は屋外で、物を中にしまって守る場所ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37113, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "広場", "is_correct": true, "explanation": "屋外の広い場所で、噴水があり観光客が写真を撮る場面に合う。"}, {"text": "教室", "is_correct": false, "explanation": "屋内の部屋で、「教室に噴水があり」は成り立たない。"}, {"text": "倉庫", "is_correct": false, "explanation": "物をしまう建物で、噴水があり観光客が写真を撮る場所ではない。"}, {"text": "本棚", "is_correct": false, "explanation": "家具の一つで、噴水があるとは言えない。"}], "explanations": {"広場": "屋外の広い場所で、噴水があり観光客が写真を撮る場面に合う。", "教室": "屋内の部屋で、「教室に噴水があり」は成り立たない。", "倉庫": "物をしまう建物で、噴水があり観光客が写真を撮る場所ではない。", "本棚": "家具の一つで、噴水があるとは言えない。"}, "sentence_index": 6, "correct_answer": "広場"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "広場のベッドで、子どもがぐっすり寝ていた。", "explanation": "「広場」を寝室の意味で使うのは誤り。広場には寝るためのベッドがなく、眠る部屋とは言えない。"}, {"text": "広場の書斎で、一日中本を読んだ。", "explanation": "「広場」を書斎の意味で使うのは誤り。広場には机や本棚がなく、一人で静かに読書する部屋とは言えない。"}, {"text": "広場のチャイムが鳴ったので、ドアを開けた。", "explanation": "「広場」を玄関の意味で使うのは誤り。広場にはチャイムもドアもないので、家の入り口とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37113, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏祭りは、駅前の広場を行われる。", "corrected_sentence": "夏祭りは、駅前の広場で行われる。", "error_description": "「行われる」の行われる場所は「で」で示す。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37113, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祭りの日は、人が広場が埋め尽くす。", "corrected_sentence": "祭りの日は、人が広場を埋め尽くす。", "error_description": "「埋め尽くす」は目的語を「を」で示す。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef2771f5-6117-445f-b5eb-cd3467362fc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37114, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37114, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "遊ぶ場所を表す「で」で、屋内の施設で遊ぶ文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「屋内の施設が遊ぶ」は施設を主語にできず、文として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「遊ぶ」は目的語を取らないので、「施設を遊ぶ」とは言えない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を表すので、その場での動作には合わない。"}], "correct_answer": "で", "explanations": {"で": "遊ぶ場所を表す「で」で、屋内の施設で遊ぶ文に合う。", "が": "「屋内の施設が遊ぶ」は施設を主語にできず、文として成り立たない。", "を": "「遊ぶ」は目的語を取らないので、「施設を遊ぶ」とは言えない。", "へ": "「へ」は移動の方向を表すので、その場での動作には合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37114, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "みんながつかうものやばしょ", "primary_collocate": null, "pronunciation": "しせつ", "ipa": "ɕisetsɯ", "syllable_count": 3, "sentences": [{"text": "この町には、子どもが遊べる施設が多い。", "target_word": "施設", "complexity_tier": "T3", "furigana": "この町[まち]には、子[こ]どもが遊[あそ]べる施設[しせつ]が多[おお]い。", "sentence_source": "generated"}, {"text": "図書館は、だれでも使える施設だ。", "target_word": "施設", "complexity_tier": "T3", "furigana": "図書館[としょかん]は、だれでも使[つか]える施設[しせつ]だ。", "sentence_source": "generated"}, {"text": "新しい施設ができて、近所の人が集まるようになった。", "target_word": "施設", "complexity_tier": "T3", "furigana": "新[あたら]しい施設[しせつ]ができて、近所[きんじょ]の人[ひと]が集[あつ]まるようになった。", "sentence_source": "generated"}, {"text": "施設の中では、大きな声で話してはいけない。", "target_word": "施設", "complexity_tier": "T3", "furigana": "施設[しせつ]の中[なか]では、大[おお]きな声[こえ]で話[はな]してはいけない。", "sentence_source": "generated"}, {"text": "古い施設は、使う人が減って閉鎖された。", "target_word": "施設", "complexity_tier": "T3", "furigana": "古[ふる]い施設[しせつ]は、使[つか]う人[ひと]が減[へ]って閉鎖[へいさ]された。", "sentence_source": "generated"}, {"text": "駅の近くに運動の施設があり、毎週通っている。", "target_word": "施設", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くに運動[うんどう]の施設[しせつ]があり、毎週[まいしゅう]通[かよ]っている。", "sentence_source": "generated"}, {"text": "施設の利用時間は、朝九時から夜九時までだ。", "target_word": "施設", "complexity_tier": "T3", "furigana": "施設[しせつ]の利用時間[りようじかん]は、朝[あさ]九時[くじ]から夜[よる]九時[くじ]までだ。", "sentence_source": "generated"}, {"text": "雨の日は、屋内の施設で遊ぶことにした。", "target_word": "施設", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、屋内[おくない]の施設[しせつ]で遊[あそ]ぶことにした。", "sentence_source": "generated"}, {"text": "温泉の施設で、一日ゆっくり過ごした。", "target_word": "施設", "complexity_tier": "T3", "furigana": "温泉[おんせん]の施設[しせつ]で、一日[いちにち]ゆっくり過[す]ごした。", "sentence_source": "generated"}, {"text": "学校の施設を、休みの日に地域の人も使える。", "target_word": "施設", "complexity_tier": "T3", "furigana": "学校[がっこう]の施設[しせつ]を、休[やす]みの日[ひ]に地域[ちいき]の人[ひと]も使[つか]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "施設", "label": "基本形"}, {"form": "施設の", "label": "連体形"}, {"form": "施設を", "label": "対格"}], "register": "標準的な普通体", "sense_fingerprint": "多くの人が使う建物や場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc4c99e5-c08d-4486-b1ed-5a1851877780') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37114, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "施設", "is_correct": true, "explanation": "「子どもが遊べる施設」は、みんなが使う建物や場所を指すので、この文に合う。"}, {"text": "病院", "is_correct": false, "explanation": "「子どもが遊べる病院」とは言えず、遊ぶ場所として合わない。"}, {"text": "空港", "is_correct": false, "explanation": "「子どもが遊べる空港」は不自然で、遊びの場にならない。"}, {"text": "銀行", "is_correct": false, "explanation": "銀行は遊ぶ場所ではないので、「子どもが遊べる」と続かない。"}], "explanations": {"施設": "「子どもが遊べる施設」は、みんなが使う建物や場所を指すので、この文に合う。", "病院": "「子どもが遊べる病院」とは言えず、遊ぶ場所として合わない。", "空港": "「子どもが遊べる空港」は不自然で、遊びの場にならない。", "銀行": "銀行は遊ぶ場所ではないので、「子どもが遊べる」と続かない。"}, "sentence_index": 0, "correct_answer": "施設"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋には、新しいエアコンという施設がついている。", "explanation": "ここは〈設備〉の意味。エアコンのような備え付けの機器は、施設ではなく設備と言う。"}, {"text": "この町の子ども会は、地域の施設として毎月活動している。", "explanation": "ここは〈団体〉の意味。子ども会は人の集まりなので、施設ではなく団体と言う。"}, {"text": "この鍋は、台所で一番大切な施設だ。", "explanation": "ここは〈道具〉の意味。鍋は手に持って使う道具なので、施設とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37114, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "施設", "is_correct": true, "explanation": "「施設の利用時間」の施設で、みんなが使う建物や場所を指すので合う。"}, {"text": "料金", "is_correct": false, "explanation": "「料金の利用時間」とは言えず、文の意味が成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "天気に利用時間はなく、「天気の利用時間」は不自然。"}, {"text": "運動会", "is_correct": false, "explanation": "「運動会の利用時間」とは言わず、夜九時までの利用には合わない。"}], "explanations": {"施設": "「施設の利用時間」の施設で、みんなが使う建物や場所を指すので合う。", "料金": "「料金の利用時間」とは言えず、文の意味が成り立たない。", "天気": "天気に利用時間はなく、「天気の利用時間」は不自然。", "運動会": "「運動会の利用時間」とは言わず、夜九時までの利用には合わない。"}, "sentence_index": 6, "correct_answer": "施設"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この洗濯機は、家庭に欠かせない施設だ。", "explanation": "ここは〈装置〉の意味。洗濯機のような一台の機械は、施設ではなく装置と言う。"}, {"text": "うちは三階建ての施設だ。", "explanation": "ここは〈建物〉の意味。個人の家は、みんなが使う施設とは言わない。"}, {"text": "うちの祖父は、家族みんなが頼る施設だ。", "explanation": "ここは〈人〉の意味。祖父は人なので、施設とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37114, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市民は施設に利用できる。", "corrected_sentence": "市民は施設を利用できる。", "error_description": "「利用する」は目的語に「を」を取る。「施設に」は誤りで、「施設を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37114, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は、この施設の運営している。", "corrected_sentence": "市は、この施設を運営している。", "error_description": "「運営する」は目的語に「を」を取る。「施設の」は誤りで、「施設を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37115, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「なる」の結果を示す「に」で、施設になるという文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「なる」は目的語を取らないので、「施設をなる」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「施設へなる」は文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表すので、「施設でなる」は不自然。"}], "correct_answer": "に", "explanations": {"に": "「なる」の結果を示す「に」で、施設になるという文に合う。", "を": "「なる」は目的語を取らないので、「施設をなる」は不自然。", "へ": "「へ」は方向を表すので、「施設へなる」は文として成り立たない。", "で": "「で」は手段や場所を表すので、「施設でなる」は不自然。"}, "error_tags": {"を": "目的語", "へ": "方向", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37115, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「作られる」の主語を示す「が」で、施設が作られるという文に合う。"}, {"text": "の", "is_correct": false, "explanation": "「施設の作られ」は続きが不自然で、名詞を修飾する形にもならない。"}, {"text": "と", "is_correct": false, "explanation": "「施設と作られ」は意味が通らず、「と」では作られる文にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は、この文の主語を作れない。"}], "correct_answer": "が", "explanations": {"が": "「作られる」の主語を示す「が」で、施設が作られるという文に合う。", "の": "「施設の作られ」は続きが不自然で、名詞を修飾する形にもならない。", "と": "「施設と作られ」は意味が通らず、「と」では作られる文にならない。", "より": "比較の「より」は、この文の主語を作れない。"}, "error_tags": {"の": "連体修飾", "と": "並列・相手", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37115, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "公共のために作られた設備や建物", "primary_collocate": null, "pronunciation": "しせつ", "ipa": "ɕisetsɯ", "syllable_count": 3, "sentences": [{"text": "市が税金で作った施設は、だれでも利用できる。", "target_word": "施設", "complexity_tier": "T3", "furigana": "市[し]が税金[ぜいきん]で作[つく]った施設[しせつ]は、だれでも利用[りよう]できる。", "sentence_source": "generated"}, {"text": "災害のとき、学校は避難する人を受け入れる施設になる。", "target_word": "施設", "complexity_tier": "T3", "furigana": "災害[さいがい]のとき、学校[がっこう]は避難[ひなん]する人[ひと]を受[う]け入[い]れる施設[しせつ]になる。", "sentence_source": "generated"}, {"text": "町の水をきれいにする施設が、郊外に完成した。", "target_word": "施設", "complexity_tier": "T3", "furigana": "町[まち]の水[みず]をきれいにする施設[しせつ]が、郊外[こうがい]に完成[かんせい]した。", "sentence_source": "generated"}, {"text": "老朽化した施設は、安全のために修理が必要だ。", "target_word": "施設", "complexity_tier": "T3", "furigana": "老朽化[ろうきゅうか]した施設[しせつ]は、安全[あんぜん]のために修理[しゅうり]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "福祉の施設で、お年寄りの世話をする仕事をしている。", "target_word": "施設", "complexity_tier": "T3", "furigana": "福祉[ふくし]の施設[しせつ]で、お年寄[としよ]りの世話[せわ]をする仕事[しごと]をしている。", "sentence_source": "generated"}, {"text": "市民のための施設なので、利用料は安く決められている。", "target_word": "施設", "complexity_tier": "T3", "furigana": "市民[しみん]のための施設[しせつ]なので、利用料[りようりょう]は安[やす]く決[き]められている。", "sentence_source": "generated"}, {"text": "図書館や体育館のような施設を、町は増やす計画だ。", "target_word": "施設", "complexity_tier": "T3", "furigana": "図書館[としょかん]や体育館[たいいくかん]のような施設[しせつ]を、町[まち]は増[ふ]やす計画[けいかく]だ。", "sentence_source": "generated"}, {"text": "公園に新しい休憩の施設が作られ、市民に喜ばれた。", "target_word": "施設", "complexity_tier": "T3", "furigana": "公園[こうえん]に新[あたら]しい休憩[きゅうけい]の施設[しせつ]が作[つく]られ、市民[しみん]に喜[よろこ]ばれた。", "sentence_source": "generated"}, {"text": "ごみを処理する施設は、町の暮らしを支えている。", "target_word": "施設", "complexity_tier": "T3", "furigana": "ごみを処理[しょり]する施設[しせつ]は、町[まち]の暮[く]らしを支[ささ]えている。", "sentence_source": "generated"}, {"text": "施設の整備には、多くの費用と時間がかかる。", "target_word": "施設", "complexity_tier": "T3", "furigana": "施設[しせつ]の整備[せいび]には、多[おお]くの費用[ひよう]と時間[じかん]がかかる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "施設", "label": "基本形"}, {"form": "施設の", "label": "連体形"}, {"form": "施設を", "label": "対格"}], "register": "標準的な普通体", "sense_fingerprint": "社会のために作られた設備や建物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc4c99e5-c08d-4486-b1ed-5a1851877780') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37115, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "施設", "is_correct": true, "explanation": "公共のために作られた設備や建物を指し、税金で作ったものに合う。"}, {"text": "制服", "is_correct": false, "explanation": "「作った制服は、だれでも利用できる」とは言えず、文の意味が成り立たない。"}, {"text": "税金", "is_correct": false, "explanation": "税金は作るものではないので、「作った税金」は文として不自然。"}, {"text": "会議", "is_correct": false, "explanation": "会議は作って利用するものではなく、この文に合わない。"}], "explanations": {"施設": "公共のために作られた設備や建物を指し、税金で作ったものに合う。", "制服": "「作った制服は、だれでも利用できる」とは言えず、文の意味が成り立たない。", "税金": "税金は作るものではないので、「作った税金」は文として不自然。", "会議": "会議は作って利用するものではなく、この文に合わない。"}, "sentence_index": 0, "correct_answer": "施設"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "うちの台所の冷蔵庫は、毎日使う大切な施設だ。", "explanation": "ここは〈家電〉の意味。個人の家の冷蔵庫は、公共のために作られた施設ではないので、施設とは言えない。"}, {"text": "町内会は、地域の大切な施設として毎月会議を開く。", "explanation": "ここは〈組織〉の意味。町内会は人の集まりなので、施設ではなく組織と言う。"}, {"text": "私の家は、家族が住む大きな施設だ。", "explanation": "ここは〈住居〉の意味。家族が住む家は、公共のために作られた建物ではないので、施設とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37115, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "施設", "is_correct": true, "explanation": "図書館や体育館のような、人々が使う公共の建物を指すので、この文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「図書館や体育館のような天気」は意味が通らず、増やす対象にもならない。"}, {"text": "予算", "is_correct": false, "explanation": "予算は図書館や体育館のような建物と並べられず、不自然。"}, {"text": "教師", "is_correct": false, "explanation": "教師は図書館や体育館と同じ種類のものではなく、「のような」で並べられない。"}], "explanations": {"施設": "図書館や体育館のような、人々が使う公共の建物を指すので、この文に合う。", "天気": "「図書館や体育館のような天気」は意味が通らず、増やす対象にもならない。", "予算": "予算は図書館や体育館のような建物と並べられず、不自然。", "教師": "教師は図書館や体育館と同じ種類のものではなく、「のような」で並べられない。"}, "sentence_index": 6, "correct_answer": "施設"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "週末に作るカレーは、家族が楽しむ施設だ。", "explanation": "ここは〈料理〉の意味。カレーは料理なので、施設とは言わない。"}, {"text": "工場の機械は、町の大切な施設として点検された。", "explanation": "ここは〈装置〉の意味。工場の一台の機械は、施設ではなく装置と言う。"}, {"text": "市内のサッカーの団体は、地域の施設として登録されている。", "explanation": "ここは〈団体〉の意味。サッカーのチームは人の集まりなので、施設ではなく団体と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37115, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は、老朽化した施設の解体する。", "corrected_sentence": "市は、老朽化した施設を解体する。", "error_description": "「解体する」は目的語に「を」が必要。「施設の」は誤りで、「施設を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37115, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は、公園の施設を操縦している。", "corrected_sentence": "市は、公園の施設を管理している。", "error_description": "施設を管理することは「管理」と言う。「操縦」は乗り物などを動かす語なので、施設には使わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37116, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「仕様になっている」の「に」で、ある状態に変わったことを示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」では、「仕様をなっている」と「なっている」が結びつかず成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す「で」では、「仕様でなっている」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、状態の変化を表す文には合わない。"}], "correct_answer": "に", "explanations": {"に": "「仕様になっている」の「に」で、ある状態に変わったことを示す。", "を": "目的語の「を」では、「仕様をなっている」と「なっている」が結びつかず成り立たない。", "で": "手段や場所を示す「で」では、「仕様でなっている」は意味が通らない。", "へ": "方向を示す「へ」は、状態の変化を表す文には合わない。"}, "error_tags": {"に": "状態の変化", "を": "目的語", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37116, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ソフトの仕様を変えた」の「を」で、変えられる対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」では、「変えました」の対象である仕様を示せず、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、動詞「変えました」には直接つかず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では、「仕様へ変えました」は変化の先を表し、目的語を示せない。"}], "correct_answer": "を", "explanations": {"を": "「ソフトの仕様を変えた」の「を」で、変えられる対象を示す。", "が": "主語の「が」では、「変えました」の対象である仕様を示せず、文が成り立たない。", "の": "「の」は名詞をつなぐ助詞で、動詞「変えました」には直接つかず、文が成り立たない。", "へ": "方向を示す「へ」では、「仕様へ変えました」は変化の先を表し、目的語を示せない。"}, "error_tags": {"を": "目的語", "が": "主語", "へ": "方向", "の": "動詞に直接つかない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37116, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものごとの、やりかたや、しくみを、きめたものです。", "primary_collocate": null, "pronunciation": "しよう", "ipa": "ɕijoː", "syllable_count": 3, "sentences": [{"text": "このアプリの仕様は、先月の会議で正式に決まりました。", "target_word": "仕様", "complexity_tier": "T3", "furigana": "このアプリの仕様[しよう]は、先月[せんげつ]の会議[かいぎ]で正式[せいしき]に決[き]まりました。", "sentence_source": "generated"}, {"text": "新しい電話は、画面が二つあるという仕様になっている。", "target_word": "仕様", "complexity_tier": "T3", "furigana": "新[あたら]しい電話[でんわ]は、画面[がめん]が二[ふた]つあるという仕様[しよう]になっている。", "sentence_source": "generated"}, {"text": "仕様を読むと、この機械は水の中では使えないとわかる。", "target_word": "仕様", "complexity_tier": "T3", "furigana": "仕様[しよう]を読[よ]むと、この機械[きかい]は水[みず]の中[なか]では使[つか]えないとわかる。", "sentence_source": "generated"}, {"text": "店の注文システムの仕様を、全員が同じように理解しておく必要があります。", "target_word": "仕様", "complexity_tier": "T3", "furigana": "店[みせ]の注文[ちゅうもん]システムの仕様[しよう]を、全員[ぜんいん]が同[おな]じように理解[りかい]しておく必要[ひつよう]があります。", "sentence_source": "generated"}, {"text": "車の仕様がちがうので、同じ部品を付けることはできません。", "target_word": "仕様", "complexity_tier": "T3", "furigana": "車[くるま]の仕様[しよう]がちがうので、同[おな]じ部品[ぶひん]を付[つ]けることはできません。", "sentence_source": "generated"}, {"text": "仕様が決まっていないまま作り始めたせいで、何度もやり直した。", "target_word": "仕様", "complexity_tier": "T3", "furigana": "仕様[しよう]が決[き]まっていないまま作[つく]り始[はじ]めたせいで、何度[なんど]もやり直[なお]した。", "sentence_source": "generated"}, {"text": "このカメラの仕様では、夜の写真はあまりきれいに撮れない。", "target_word": "仕様", "complexity_tier": "T3", "furigana": "このカメラの仕様[しよう]では、夜[よる]の写真[しゃしん]はあまりきれいに撮[と]れない。", "sentence_source": "generated"}, {"text": "お客さんの希望に合わせて、ソフトの仕様を少し変えました。", "target_word": "仕様", "complexity_tier": "T3", "furigana": "お客[きゃく]さんの希望[きぼう]に合[あ]わせて、ソフトの仕様[しよう]を少[すこ]し変[か]えました。", "sentence_source": "generated"}, {"text": "ゲームの仕様を説明する資料が、チームに配られました。", "target_word": "仕様", "complexity_tier": "T3", "furigana": "ゲームの仕様[しよう]を説明[せつめい]する資料[しりょう]が、チームに配[くば]られました。", "sentence_source": "generated"}, {"text": "仕様どおりに動かないと、検査に合格できません。", "target_word": "仕様", "complexity_tier": "T3", "furigana": "仕様[しよう]どおりに動[うご]かないと、検査[けんさ]に合格[ごうかく]できません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "仕様", "label": "基本形"}], "register": "ややかたい", "sense_fingerprint": "機械やソフトなどの作りやしくみについて、あらかじめ決めた内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1150120c-165e-4f2c-8c6f-3d4fb6877a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37116, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仕様", "is_correct": true, "explanation": "アプリの作りや内容を決める語で、「決まりました」と合う。"}, {"text": "感情", "is_correct": false, "explanation": "人の気持ちを指す語で、アプリの内容として決まるものではない。"}, {"text": "性格", "is_correct": false, "explanation": "人や動物の特徴を表す語で、アプリには使わない。"}, {"text": "体温", "is_correct": false, "explanation": "人の体の温度を表す語で、アプリの文には合わない。"}], "explanations": {"仕様": "アプリの作りや内容を決める語で、「決まりました」と合う。", "感情": "人の気持ちを指す語で、アプリの内容として決まるものではない。", "性格": "人や動物の特徴を表す語で、アプリには使わない。", "体温": "人の体の温度を表す語で、アプリの文には合わない。"}, "sentence_index": 0, "correct_answer": "仕様"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店の仕様は、とてもいい。", "explanation": "ここは〈評判〉の意味。店の世間的な評価は「評判」で言い、仕様は機械やソフトの作りを指すので合わない。"}, {"text": "学校の仕様を、全員が守る必要がある。", "explanation": "ここは〈規則〉の意味。守るべき決まりは「規則」で、仕様はものの作りの取り決めなので合わない。"}, {"text": "食事の仕様を、子どもに教える。", "explanation": "ここは〈作法〉の意味。食事のふるまい方は「作法」で言い、仕様は機械やソフトの作りなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37116, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仕様", "is_correct": true, "explanation": "カメラの機能や作りを表す語で、「撮れない」の原因として合う。"}, {"text": "気分", "is_correct": false, "explanation": "人の気持ちを表す語で、カメラの特徴には使わない。"}, {"text": "年齢", "is_correct": false, "explanation": "人や生き物に使う語で、カメラには当てはまらない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語で、カメラの作りを示す文には合わない。"}], "explanations": {"仕様": "カメラの機能や作りを表す語で、「撮れない」の原因として合う。", "気分": "人の気持ちを表す語で、カメラの特徴には使わない。", "年齢": "人や生き物に使う語で、カメラには当てはまらない。", "天気": "空模様を表す語で、カメラの作りを示す文には合わない。"}, "sentence_index": 6, "correct_answer": "仕様"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このエンジンは、仕様が高くて速い。", "explanation": "ここは〈性能〉の意味。能力の高さは「性能」で言い、仕様は作りの取り決めなので「高い」とは言わない。"}, {"text": "旅行の仕様が、もう決まった。", "explanation": "ここは〈日程〉の意味。旅行の予定の組み方は「日程」で言い、仕様は機械やソフトの作りなので合わない。"}, {"text": "このスープは、仕様がとても濃い。", "explanation": "ここは〈味〉の意味。濃さは「味」で言い、仕様は機械やソフトの作りなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37116, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しいパソコンの仕様が、ホームページで確認しました。", "corrected_sentence": "新しいパソコンの仕様を、ホームページで確認しました。", "error_description": "「確認する」は目的語に「を」を取る。「仕様が」と主語にしたため、仕様が確認するという誤った文になっている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37116, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この部品は、仕様を合うように作られている。", "corrected_sentence": "この部品は、仕様に合うように作られている。", "error_description": "「合う」は「に」を取る（〜に合う）。「仕様を合う」は動詞の結びつきが誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37117, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「仕様」は「変わり」の主語になるので「が」が入る。「申し込みの仕様が変わり」で文が成立する。"}, {"text": "を", "is_correct": false, "explanation": "「変わる」は自動詞なので目的語の「を」は取れず、「仕様を変わり」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や原因を表すが、「仕様で変わり」では主語を示せず、文の流れも不自然になる。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を表すが、「仕様と変わり」では変化の主語にならず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「仕様」は「変わり」の主語になるので「が」が入る。「申し込みの仕様が変わり」で文が成立する。", "を": "「変わる」は自動詞なので目的語の「を」は取れず、「仕様を変わり」は成り立たない。", "で": "「で」は手段や原因を表すが、「仕様で変わり」では主語を示せず、文の流れも不自然になる。", "と": "「と」は相手や並列を表すが、「仕様と変わり」では変化の主語にならず、文が成り立たない。"}, "error_tags": {"を": "自動詞には目的語を取れない", "で": "手段・原因の助詞", "と": "並列・相手の助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37117, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「仕様」は「違う」の主語になるので「が」が入る。「会社ごとに仕様が違う」で文が成立する。"}, {"text": "に", "is_correct": false, "explanation": "「違う」は「〜と違う」と使うため、「に」は直接つかず、「仕様に違う」は成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「違う」は目的語を取らないので、「仕様を違う」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すが、「違う」の主語を示せず、「仕様より違う」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「仕様」は「違う」の主語になるので「が」が入る。「会社ごとに仕様が違う」で文が成立する。", "に": "「違う」は「〜と違う」と使うため、「に」は直接つかず、「仕様に違う」は成り立たない。", "を": "「違う」は目的語を取らないので、「仕様を違う」は成り立たない。", "より": "「より」は比較を表すが、「違う」の主語を示せず、「仕様より違う」は成り立たない。"}, "error_tags": {"に": "変化・相手を示す助詞", "より": "比較の助詞", "を": "目的語を取れない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37117, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を行うときの決まりや方法。", "primary_collocate": null, "pronunciation": "しよう", "ipa": "ɕijoː", "syllable_count": 3, "sentences": [{"text": "工事のやり方を書いた仕様に従って、職人さんが壁を作った。", "target_word": "仕様", "complexity_tier": "T3", "furigana": "工事[こうじ]のやり方[かた]を書[か]いた仕様[しよう]に従[したが]って、職人[しょくにん]さんが壁[かべ]を作[つく]った。", "sentence_source": "generated"}, {"text": "申し込みの仕様が変わり、来月からはネットだけで受け付けることになりました。", "target_word": "仕様", "complexity_tier": "T3", "furigana": "申[もう]し込[こ]みの仕様[しよう]が変[か]わり、来月[らいげつ]からはネットだけで受[う]け付[つ]けることになりました。", "sentence_source": "generated"}, {"text": "このサイトの仕様で、登録には必ずメールアドレスが必要です。", "target_word": "仕様", "complexity_tier": "T3", "furigana": "このサイトの仕様[しよう]で、登録[とうろく]には必[かなら]ずメールアドレスが必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "「その動きは仕様です」と担当者は説明した。", "target_word": "仕様", "complexity_tier": "T3", "furigana": "「その動[うご]きは仕様[しよう]です」と担当者[たんとうしゃ]は説明[せつめい]した。", "sentence_source": "generated"}, {"text": "機械の組み立て方は、仕様の通りにしなければなりません。", "target_word": "仕様", "complexity_tier": "T3", "furigana": "機械[きかい]の組[く]み立[た]て方[かた]は、仕様[しよう]の通[とお]りにしなければなりません。", "sentence_source": "generated"}, {"text": "作業の仕様をもう一度確認してから、取りかかりましょう。", "target_word": "仕様", "complexity_tier": "T3", "furigana": "作業[さぎょう]の仕様[しよう]をもう一度[いちど]確認[かくにん]してから、取[と]りかかりましょう。", "sentence_source": "generated"}, {"text": "仕様がはっきりしているので、初めての人でも迷わず作業できる。", "target_word": "仕様", "complexity_tier": "T3", "furigana": "仕様[しよう]がはっきりしているので、初[はじ]めての人[ひと]でも迷[まよ]わず作業[さぎょう]できる。", "sentence_source": "generated"}, {"text": "会社ごとに仕様が違うため、同じ手順では動かないことがある。", "target_word": "仕様", "complexity_tier": "T3", "furigana": "会社[かいしゃ]ごとに仕様[しよう]が違[ちが]うため、同[おな]じ手順[てじゅん]では動[うご]かないことがある。", "sentence_source": "generated"}, {"text": "新しい受付システムの仕様を、市役所の人が説明した。", "target_word": "仕様", "complexity_tier": "T3", "furigana": "新[あたら]しい受付[うけつけ]システムの仕様[しよう]を、市役所[しやくしょ]の人[ひと]が説明[せつめい]した。", "sentence_source": "generated"}, {"text": "作り方の仕様を守らなかったので、製品は検査で不合格になった。", "target_word": "仕様", "complexity_tier": "T3", "furigana": "作[つく]り方[かた]の仕様[しよう]を守[まも]らなかったので、製品[せいひん]は検査[けんさ]で不合格[ふごうかく]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "仕様", "label": "基本形"}], "register": "ややかたい", "sense_fingerprint": "作業や手続きを行うときに決められている決まりと方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: 取りかかり (Zipf 2.33)']::text[], '1150120c-165e-4f2c-8c6f-3d4fb6877a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37117, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仕様", "is_correct": true, "explanation": "「書いた」の対象になり、「に従って」で従う決まりや方法を示す。職人が従うのは工事の決まりなので意味も通る。"}, {"text": "天気", "is_correct": false, "explanation": "「書いた天気」は成り立たず、「天気に従って」も決まりを示す言い方にならない。"}, {"text": "人形", "is_correct": false, "explanation": "「書いた人形」は不自然で、「人形に従って」という言い方も文脈に合わない。"}, {"text": "掃除", "is_correct": false, "explanation": "「書いた掃除」は成り立たず、「掃除に従って」では壁の工事の手順を表せない。"}], "explanations": {"仕様": "「書いた」の対象になり、「に従って」で従う決まりや方法を示す。職人が従うのは工事の決まりなので意味も通る。", "天気": "「書いた天気」は成り立たず、「天気に従って」も決まりを示す言い方にならない。", "人形": "「書いた人形」は不自然で、「人形に従って」という言い方も文脈に合わない。", "掃除": "「書いた掃除」は成り立たず、「掃除に従って」では壁の工事の手順を表せない。"}, "sentence_index": 0, "correct_answer": "仕様"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来月の旅行の仕様を家族と相談して決めた。", "explanation": "ここは〈計画〉の意味。旅行の予定は計画が合い、仕様は機械や作業の決まりや方法を指すので合わない。"}, {"text": "本人の仕様を確認してから、進路を決めた。", "explanation": "ここは〈意向〉の意味。本人が望んでいることは意向が合い、仕様は物事を行う決まりや方法を指すので合わない。"}, {"text": "毎朝、仕様を始める前にメールを確認している。", "explanation": "ここは〈仕事〉の意味。始めたり続けたりするのは仕事で、仕様は物事を行うときの決まりや方法なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37117, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仕様", "is_correct": true, "explanation": "「がはっきりしている」と合い、ここでは作業の決まりが明確なので迷わず作業できるという意味になる。"}, {"text": "朝食", "is_correct": false, "explanation": "朝食は食事の名前で、「朝食がはっきりしている」とは言えず、作業の文脈とも合わない。"}, {"text": "空腹", "is_correct": false, "explanation": "空腹は体の状態で、「空腹がはっきりしている」とは言えず、作業の決まりを述べる文に入らない。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は行動の名前で、「散歩がはっきりしている」は成り立たず、作業の説明にもならない。"}], "explanations": {"仕様": "「がはっきりしている」と合い、ここでは作業の決まりが明確なので迷わず作業できるという意味になる。", "朝食": "朝食は食事の名前で、「朝食がはっきりしている」とは言えず、作業の文脈とも合わない。", "空腹": "空腹は体の状態で、「空腹がはっきりしている」とは言えず、作業の決まりを述べる文に入らない。", "散歩": "散歩は行動の名前で、「散歩がはっきりしている」は成り立たず、作業の説明にもならない。"}, "sentence_index": 6, "correct_answer": "仕様"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "映画を見たあと、仕様を友達と語り合った。", "explanation": "ここは〈感想〉の意味。見た作品への思いは感想が合い、仕様は物事を行うときの決まりや方法を指すので合わない。"}, {"text": "町の仕様が一気に広まった。", "explanation": "ここは〈噂〉の意味。町で広まるのは噂で、仕様は物事を行うときの決まりや方法を指すので合わない。"}, {"text": "彼女は仕様が明るくて、みんなに好かれている。", "explanation": "ここは〈性格〉の意味。人の人柄は性格が合い、仕様は物事を行うときの決まりや方法を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37117, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しいアプリの仕様が変えたので、ユーザーは前より画面を使いやすく感じた。", "corrected_sentence": "新しいアプリの仕様を変えたので、ユーザーは前より画面を使いやすく感じた。", "error_description": "「変える」は他動詞で、変える対象は「を」で示す。「仕様が変えた」は誤りで、正しくは「仕様を変えた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37117, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工場では、仕様を決まった上で、機械を組み立てた。", "corrected_sentence": "工場では、仕様を決めた上で、機械を組み立てた。", "error_description": "「仕様を」と結びつくのは他動詞の「決める」。自動詞の「決まる」は目的語を取れないので、正しくは「決めた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37118, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「〜に一時間かかる」の「に」。時間がかかる対象を示す。"}, {"text": "を", "is_correct": false, "explanation": "「通勤を一時間かかる」は、「かかる」が「〜を」を取らないので不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「通勤へ一時間かかる」は方向の「へ」が時間の「かかる」と結びつかず、不自然。"}, {"text": "の", "is_correct": false, "explanation": "「通勤の一時間かかる」は名詞を修飾する形で、文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「〜に一時間かかる」の「に」。時間がかかる対象を示す。", "を": "「通勤を一時間かかる」は、「かかる」が「〜を」を取らないので不自然。", "へ": "「通勤へ一時間かかる」は方向の「へ」が時間の「かかる」と結びつかず、不自然。", "の": "「通勤の一時間かかる」は名詞を修飾する形で、文として成り立たない。"}, "error_tags": {"を": "対象", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37118, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「通勤の時間」の「の」。「通勤」と「時間」を結びつける。"}, {"text": "を", "is_correct": false, "explanation": "「通勤を時間が半分になった」は、文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「通勤に時間が半分になった」は、変化の結果を示す「に」が「時間が」と続かず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「通勤へ時間が半分になった」は方向の「へ」が変化の結果と結びつかず、不自然。"}], "correct_answer": "の", "explanations": {"の": "「通勤の時間」の「の」。「通勤」と「時間」を結びつける。", "を": "「通勤を時間が半分になった」は、文として成り立たない。", "に": "「通勤に時間が半分になった」は、変化の結果を示す「に」が「時間が」と続かず不自然。", "へ": "「通勤へ時間が半分になった」は方向の「へ」が変化の結果と結びつかず、不自然。"}, "error_tags": {"を": "対象", "に": "結果", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37118, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "家と仕事場の間を毎日行き来すること。", "primary_collocate": null, "pronunciation": "つうきん", "ipa": "tsɯːkiɴ", "syllable_count": 4, "sentences": [{"text": "私は毎日、電車で通勤している。", "target_word": "通勤", "complexity_tier": "T3", "furigana": "私[わたし]は毎日[まいにち]、電車[でんしゃ]で通勤[つうきん]している。", "sentence_source": "generated"}, {"text": "家が会社から遠いので、通勤に一時間かかる。", "target_word": "通勤", "complexity_tier": "T3", "furigana": "家[いえ]が会社[かいしゃ]から遠[とお]いので、通勤[つうきん]に一時間[いちじかん]かかる。", "sentence_source": "generated"}, {"text": "雨の日は通勤が大変だ。", "target_word": "通勤", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は通勤[つうきん]が大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "運動のために、自転車で通勤することにした。", "target_word": "通勤", "complexity_tier": "T3", "furigana": "運動[うんどう]のために、自転車[じてんしゃ]で通勤[つうきん]することにした。", "sentence_source": "generated"}, {"text": "彼は車で通勤しているが、駐車場代が高い。", "target_word": "通勤", "complexity_tier": "T3", "furigana": "彼[かれ]は車[くるま]で通勤[つうきん]しているが、駐車場代[ちゅうしゃじょうだい]が高[たか]い。", "sentence_source": "generated"}, {"text": "新しい家は駅に近くて、通勤がとても楽になった。", "target_word": "通勤", "complexity_tier": "T3", "furigana": "新[あたら]しい家[いえ]は駅[えき]に近[ちか]くて、通勤[つうきん]がとても楽[らく]になった。", "sentence_source": "generated"}, {"text": "通勤の途中で、いつもコーヒーを買います。", "target_word": "通勤", "complexity_tier": "T3", "furigana": "通勤[つうきん]の途中[とちゅう]で、いつもコーヒーを買[か]います。", "sentence_source": "generated"}, {"text": "引っ越してから、通勤の時間が半分になった。", "target_word": "通勤", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]してから、通勤[つうきん]の時間[じかん]が半分[はんぶん]になった。", "sentence_source": "generated"}, {"text": "会社まで歩いて通勤できるので、交通費はかからない。", "target_word": "通勤", "complexity_tier": "T3", "furigana": "会社[かいしゃ]まで歩[ある]いて通勤[つうきん]できるので、交通費[こうつうひ]はかからない。", "sentence_source": "generated"}, {"text": "在宅勤務になって、通勤しなくてもよくなった。", "target_word": "通勤", "complexity_tier": "T3", "furigana": "在宅勤務[ざいたくきんむ]になって、通勤[つうきん]しなくてもよくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "通勤する", "label": "辞書形"}, {"form": "通勤している", "label": "進行・継続"}, {"form": "通勤した", "label": "過去形"}, {"form": "通勤しない", "label": "否定形"}, {"form": "通勤して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "家と職場を毎日往復する日常の移動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T2: contains vocabulary far above tier T2: 場代 (Zipf 2.27)']::text[], '79dd0ac8-530d-4cac-b7a0-2b6a258737ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37118, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "通勤", "is_correct": true, "explanation": "「電車で通勤している」は、家と職場を毎日往復するという意味で文脈に合う。"}, {"text": "出版", "is_correct": false, "explanation": "「出版」は本や雑誌を作って発行することで、電車で毎日している行為としては成り立たない。"}, {"text": "解剖", "is_correct": false, "explanation": "「解剖」は医学的に体を切り開く処置で、電車に乗って毎日行う行為として文が通らない。"}, {"text": "融資", "is_correct": false, "explanation": "「融資」はお金を貸すことで、電車で毎日行う行為と結びつかない。"}], "explanations": {"通勤": "「電車で通勤している」は、家と職場を毎日往復するという意味で文脈に合う。", "出版": "「出版」は本や雑誌を作って発行することで、電車で毎日している行為としては成り立たない。", "解剖": "「解剖」は医学的に体を切り開く処置で、電車に乗って毎日行う行為として文が通らない。", "融資": "「融資」はお金を貸すことで、電車で毎日行う行為と結びつかない。"}, "sentence_index": 0, "correct_answer": "通勤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "旅行の途中で、電車で通勤することにした。", "explanation": "ここは〈移動〉の意味。「通勤」は家と職場の往復を指すので、旅行の途中の移動には合わない。"}, {"text": "毎週土曜日、恋人の家に通勤している。", "explanation": "ここは〈通う〉の意味。「通勤」は職場への往復に限られるので、恋人の家へ足を運ぶ場合は「通う」を使い、「通勤」は合わない。"}, {"text": "来月は三日間、大阪へ通勤する予定だ。", "explanation": "ここは〈出張〉の意味。「通勤」は毎日の家と職場の往復なので、数日間の出張には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37118, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通勤", "is_correct": true, "explanation": "「通勤の途中で」は、家と職場を往復する途中という意味で文脈に合う。"}, {"text": "感電", "is_correct": false, "explanation": "「感電の途中で」は意味が通らない。感電は体に電流が流れることで、買い物の文と合わない。"}, {"text": "漂白", "is_correct": false, "explanation": "「漂白」は布や紙の色を抜く作業で、途中でコーヒーを買う文脈と結びつかない。"}, {"text": "座礁", "is_correct": false, "explanation": "「座礁」は船が浅瀬に乗り上げることで、通勤の途中という場面には当てはまらない。"}], "explanations": {"通勤": "「通勤の途中で」は、家と職場を往復する途中という意味で文脈に合う。", "感電": "「感電の途中で」は意味が通らない。感電は体に電流が流れることで、買い物の文と合わない。", "漂白": "「漂白」は布や紙の色を抜く作業で、途中でコーヒーを買う文脈と結びつかない。", "座礁": "「座礁」は船が浅瀬に乗り上げることで、通勤の途中という場面には当てはまらない。"}, "sentence_index": 6, "correct_answer": "通勤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎日、入院中の友人の病院へ通勤する。", "explanation": "ここは〈見舞い〉の意味。入院中の友人を見舞うのは〈見舞い〉で、「通勤」は仕事のための往復に限られるので合わない。"}, {"text": "大学生の弟は、毎日バスで大学へ通勤している。", "explanation": "ここは〈通学〉の意味。学生が学校へ通う場合は〈通学〉を使い、「通勤」は職場への往復に限られる。"}, {"text": "先月、友人の結婚式に一度だけ通勤した。", "explanation": "ここは〈出席〉の意味。一度きりの式に出席するのは〈出席〉で、「通勤」は毎日のように繰り返す職場への往復を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37118, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家が遠いので、通勤を一時間かかる。", "corrected_sentence": "家が遠いので、通勤に一時間かかる。", "error_description": "「〜に（時間が）かかる」の形で、「通勤」の後には「に」が続く。「通勤を」は誤りで、正しくは「通勤に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
