INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37119, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "自宅と職場との間を定期的に移動すること。", "primary_collocate": null, "pronunciation": "つうきん", "ipa": "tsɯːkiɴ", "syllable_count": 4, "sentences": [{"text": "姉は郊外の家から都心の病院まで通勤している。", "target_word": "通勤", "complexity_tier": "T3", "furigana": "姉[あね]は郊外[こうがい]の家[いえ]から都心[としん]の病院[びょういん]まで通勤[つうきん]している。", "sentence_source": "generated"}, {"text": "父は三十年間、同じ道を通勤してきた。", "target_word": "通勤", "complexity_tier": "T3", "furigana": "父[ちち]は三十年間[さんじゅうねんかん]、同[おな]じ道[みち]を通勤[つうきん]してきた。", "sentence_source": "generated"}, {"text": "通勤には定期券を買ったほうが安い。", "target_word": "通勤", "complexity_tier": "T3", "furigana": "通勤[つうきん]には定期券[ていきけん]を買[か]ったほうが安[やす]い。", "sentence_source": "generated"}, {"text": "彼女は毎朝六時の電車で通勤する。", "target_word": "通勤", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は毎朝[まいあさ]六時[ろくじ]の電車[でんしゃ]で通勤[つうきん]する。", "sentence_source": "generated"}, {"text": "会社は通勤の費用を出してくれる。", "target_word": "通勤", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は通勤[つうきん]の費用[ひよう]を出[だ]してくれる。", "sentence_source": "generated"}, {"text": "雪のせいで、今日は通勤に使うバスが遅れた。", "target_word": "通勤", "complexity_tier": "T3", "furigana": "雪[ゆき]のせいで、今日[きょう]は通勤[つうきん]に使[つか]うバスが遅[おく]れた。", "sentence_source": "generated"}, {"text": "新しい職場に通勤しやすい場所で、部屋を探している。", "target_word": "通勤", "complexity_tier": "T3", "furigana": "新[あたら]しい職場[しょくば]に通勤[つうきん]しやすい場所[ばしょ]で、部屋[へや]を探[さが]している。", "sentence_source": "generated"}, {"text": "私の通勤は片道四十分で、本を読む時間になっている。", "target_word": "通勤", "complexity_tier": "T3", "furigana": "私[わたし]の通勤[つうきん]は片道[かたみち]四十分[よんじっぷん]で、本[ほん]を読[よ]む時間[じかん]になっている。", "sentence_source": "generated"}, {"text": "彼は健康のため、一駅分歩いて通勤している。", "target_word": "通勤", "complexity_tier": "T3", "furigana": "彼[かれ]は健康[けんこう]のため、一駅分[ひとえきぶん]歩[ある]いて通勤[つうきん]している。", "sentence_source": "generated"}, {"text": "田舎では、車で通勤する人が多い。", "target_word": "通勤", "complexity_tier": "T3", "furigana": "田舎[いなか]では、車[くるま]で通勤[つうきん]する人[ひと]が多[おお]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "通勤する", "label": "辞書形"}, {"form": "通勤している", "label": "進行・継続"}, {"form": "通勤した", "label": "過去形"}, {"form": "通勤しない", "label": "否定形"}, {"form": "通勤して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "自宅と職場の間を決まった手段で定期的に移動すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79dd0ac8-530d-4cac-b7a0-2b6a258737ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37119, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "通勤", "is_correct": true, "explanation": "「通勤している」は、郊外の家から病院まで毎日往復するという意味で文脈に合う。"}, {"text": "解剖", "is_correct": false, "explanation": "「解剖」は医学の処置で、家から病院まで移動する文脈に合わない。"}, {"text": "溶接", "is_correct": false, "explanation": "「溶接」は金属を接合する作業で、家から病院への移動とは結びつかない。"}, {"text": "脱税", "is_correct": false, "explanation": "「脱税」は税金を逃れることで、移動の文とは関係がない。"}], "explanations": {"通勤": "「通勤している」は、郊外の家から病院まで毎日往復するという意味で文脈に合う。", "解剖": "「解剖」は医学の処置で、家から病院まで移動する文脈に合わない。", "溶接": "「溶接」は金属を接合する作業で、家から病院への移動とは結びつかない。", "脱税": "「脱税」は税金を逃れることで、移動の文とは関係がない。"}, "sentence_index": 0, "correct_answer": "通勤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来週、家族で北海道へ通勤する。", "explanation": "ここは〈旅行〉の意味。「通勤」は毎日の職場への往復を指すので、家族での旅行には使わない。"}, {"text": "中学生の妹は毎朝六時の電車で通勤する。", "explanation": "ここは〈通学〉の意味。学生が学校へ通う場合は〈通学〉を使い、「通勤」は職場への往復に使う。"}, {"text": "毎週、電車で入院中の友人の病室へ通勤する。", "explanation": "ここは〈見舞い〉の意味。入院中の友人を見舞うのは〈見舞い〉で、「通勤」は職場への定期的な往復なので友人の病室へは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37119, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通勤", "is_correct": true, "explanation": "「通勤しやすい」は職場への往復がしやすいという意味で、部屋探しの条件として合う。"}, {"text": "感電", "is_correct": false, "explanation": "「感電しやすい」は場所の条件として意味が通らない。"}, {"text": "漂白", "is_correct": false, "explanation": "「漂白しやすい」は部屋探しの条件として成り立たない。"}, {"text": "座礁", "is_correct": false, "explanation": "「座礁しやすい」は船の話で、部屋探しの条件には合わない。"}], "explanations": {"通勤": "「通勤しやすい」は職場への往復がしやすいという意味で、部屋探しの条件として合う。", "感電": "「感電しやすい」は場所の条件として意味が通らない。", "漂白": "「漂白しやすい」は部屋探しの条件として成り立たない。", "座礁": "「座礁しやすい」は船の話で、部屋探しの条件には合わない。"}, "sentence_index": 6, "correct_answer": "通勤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先月、田舎の祭りに一度だけ車で通勤した。", "explanation": "ここは〈参加〉の意味。祭りに一度加わるのは〈参加〉で、「通勤」は定期的に繰り返す職場への往復を指すので合わない。"}, {"text": "お盆には、田舎の実家へ通勤する。", "explanation": "ここは〈帰省〉の意味。実家へ帰るのは〈帰省〉で、「通勤」は職場への定期的な往復に限られるので使えない。"}, {"text": "田舎では、朝の散歩として車で通勤する人が多い。", "explanation": "ここは〈散歩〉の意味。「通勤」は仕事のための移動で、気分転換の外出には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37119, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨のせいで、明日は通勤を使う電車が遅れるかもしれない。", "corrected_sentence": "雨のせいで、明日は通勤に使う電車が遅れるかもしれない。", "error_description": "「通勤に使う」の「に」を「を」にした誤り。「〜に使う」は用途を示す「に」を取る。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37119, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "都会では、電車で通勤な人が多い。", "corrected_sentence": "都会では、電車で通勤する人が多い。", "error_description": "「通勤」は名詞で、動詞として使うには「する」が必要。「通勤な人」は誤りで、正しくは「通勤する人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
