INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37120, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "道にたくさんの車や人がいて、前に進めなくなることです。", "primary_collocate": null, "pronunciation": "じゅうたい", "ipa": "dʑɯːtai", "syllable_count": 4, "sentences": [{"text": "朝は道が混んで、渋滞になる。", "target_word": "渋滞", "complexity_tier": "T3", "furigana": "朝[あさ]は道[みち]が混[こ]んで、渋滞[じゅうたい]になる。", "sentence_source": "generated"}, {"text": "大きな事故があって、高速道路が渋滞している。", "target_word": "渋滞", "complexity_tier": "T3", "furigana": "大[おお]きな事故[じこ]があって、高速道路[こうそくどうろ]が渋滞[じゅうたい]している。", "sentence_source": "generated"}, {"text": "渋滞のせいで、約束の時間に遅れてしまった。", "target_word": "渋滞", "complexity_tier": "T3", "furigana": "渋滞[じゅうたい]のせいで、約束[やくそく]の時間[じかん]に遅[おく]れてしまった。", "sentence_source": "generated"}, {"text": "連休には、どの道も渋滞する。", "target_word": "渋滞", "complexity_tier": "T3", "furigana": "連休[れんきゅう]には、どの道[みち]も渋滞[じゅうたい]する。", "sentence_source": "generated"}, {"text": "渋滞を避けるために、朝早く出発しました。", "target_word": "渋滞", "complexity_tier": "T3", "furigana": "渋滞[じゅうたい]を避[さ]けるために、朝早[あさはや]く出発[しゅっぱつ]しました。", "sentence_source": "generated"}, {"text": "人が多すぎて、駅の前が渋滞していた。", "target_word": "渋滞", "complexity_tier": "T3", "furigana": "人[ひと]が多[おお]すぎて、駅[えき]の前[まえ]が渋滞[じゅうたい]していた。", "sentence_source": "generated"}, {"text": "バスが渋滞に入って、ぜんぜん動かない。", "target_word": "渋滞", "complexity_tier": "T3", "furigana": "バスが渋滞[じゅうたい]に入[はい]って、ぜんぜん動[うご]かない。", "sentence_source": "generated"}, {"text": "この道はいつも渋滞しているから、電車で行こう。", "target_word": "渋滞", "complexity_tier": "T3", "furigana": "この道[みち]はいつも渋滞[じゅうたい]しているから、電車[でんしゃ]で行[い]こう。", "sentence_source": "generated"}, {"text": "渋滞が長く続いて、子どもが車の中で寝てしまった。", "target_word": "渋滞", "complexity_tier": "T3", "furigana": "渋滞[じゅうたい]が長[なが]く続[つづ]いて、子[こ]どもが車[くるま]の中[なか]で寝[ね]てしまった。", "sentence_source": "generated"}, {"text": "工事のため、前の道は夕方になると渋滞する。", "target_word": "渋滞", "complexity_tier": "T3", "furigana": "工事[こうじ]のため、前[まえ]の道[みち]は夕方[ゆうがた]になると渋滞[じゅうたい]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "渋滞する", "label": "辞書形"}, {"form": "渋滞している", "label": "進行・継続"}, {"form": "渋滞した", "label": "過去形"}, {"form": "渋滞しない", "label": "否定形"}, {"form": "渋滞して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "車や人が多すぎて道で前に進めない状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79dd0ac8-530d-4cac-b7a0-2b6a258737ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37120, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "渋滞", "is_correct": true, "explanation": "「渋滞になる」は、道が混んで車が進まなくなるという意味で文脈に合う。"}, {"text": "出版", "is_correct": false, "explanation": "「出版」は本などを作って発行することで、道が混む文脈には合わない。"}, {"text": "溶接", "is_correct": false, "explanation": "「溶接」は金属を接合する作業で、道路の混雑とは結びつかない。"}, {"text": "融資", "is_correct": false, "explanation": "「融資」はお金を貸すことで、道が混むという内容とは関係がない。"}], "explanations": {"渋滞": "「渋滞になる」は、道が混んで車が進まなくなるという意味で文脈に合う。", "出版": "「出版」は本などを作って発行することで、道が混む文脈には合わない。", "溶接": "「溶接」は金属を接合する作業で、道路の混雑とは結びつかない。", "融資": "「融資」はお金を貸すことで、道が混むという内容とは関係がない。"}, "sentence_index": 0, "correct_answer": "渋滞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "景気が渋滞していて、給料が上がらない。", "explanation": "ここは〈停滞〉の意味。景気が止まって動かない状態は〈停滞〉で、〈渋滞〉は道路の車や人の流れに使う。"}, {"text": "言葉が渋滞して、うまく話せなかった。", "explanation": "ここは〈つかえ〉の意味。言葉が詰まって出ない状態は〈つかえ〉で、〈渋滞〉は道や人の流れに使う。"}, {"text": "家賃が渋滞していて、大家さんに注意された。", "explanation": "ここは〈滞納〉の意味。支払いが遅れている状態は〈滞納〉で、〈渋滞〉は交通の流れに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37120, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "渋滞", "is_correct": true, "explanation": "「渋滞に入って」は、車が流れに入って進まなくなるという意味で文脈に合う。"}, {"text": "感電", "is_correct": false, "explanation": "「感電」は体に電流が流れることで、バスの動きには当てはまらない。"}, {"text": "漂白", "is_correct": false, "explanation": "「漂白」は色を抜く作業で、バスが動かない場面とは結びつかない。"}, {"text": "座礁", "is_correct": false, "explanation": "「座礁」は船が浅瀬に乗り上げることで、バスの話には使わない。"}], "explanations": {"渋滞": "「渋滞に入って」は、車が流れに入って進まなくなるという意味で文脈に合う。", "感電": "「感電」は体に電流が流れることで、バスの動きには当てはまらない。", "漂白": "「漂白」は色を抜く作業で、バスが動かない場面とは結びつかない。", "座礁": "「座礁」は船が浅瀬に乗り上げることで、バスの話には使わない。"}, "sentence_index": 6, "correct_answer": "渋滞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電車が渋滞したので、会議に十分遅れた。", "explanation": "ここは〈遅延〉の意味。電車の運行が遅れることは〈遅延〉で、〈渋滞〉は道や人の流れに使う。"}, {"text": "連日の仕事で、疲れが渋滞してきた。", "explanation": "ここは〈蓄積〉の意味。疲れや負担が重なって溜まることは〈蓄積〉で、〈渋滞〉は車や人が前に進めない状態を指す。"}, {"text": "古い時計が渋滞して、とうとう動かなくなった。", "explanation": "ここは〈停止〉の意味。機械が止まる場合は〈停止〉で、〈渋滞〉は道路などで車が進まない状態を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37120, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の日は道が混んで、渋滞をなる。", "corrected_sentence": "雨の日は道が混んで、渋滞になる。", "error_description": "「渋滞になる」の「に」を「を」にした誤り。「〜になる」は変化の結果を示す「に」を取る。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37120, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工事のため、前の道は夕方になると渋滞を起こる。", "corrected_sentence": "工事のため、前の道は夕方になると渋滞が起こる。", "error_description": "「起こる」は自動詞で、主語を「が」で示す。「渋滞を起こる」の「を」は誤りで、正しくは「渋滞が起こる」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37121, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「渋滞の先頭」の「の」。渋滞の前の部分を表す。"}, {"text": "が", "is_correct": false, "explanation": "「渋滞が先頭では」は主語として成り立たず、「先頭」と結びつかない。"}, {"text": "を", "is_correct": false, "explanation": "「渋滞を先頭では」は「先頭」を目的語にできず、意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「渋滞に先頭では」は場所の「に」が「先頭」と結びつかず、不自然。"}], "correct_answer": "の", "explanations": {"の": "「渋滞の先頭」の「の」。渋滞の前の部分を表す。", "が": "「渋滞が先頭では」は主語として成り立たず、「先頭」と結びつかない。", "を": "「渋滞を先頭では」は「先頭」を目的語にできず、意味が通らない。", "に": "「渋滞に先頭では」は場所の「に」が「先頭」と結びつかず、不自然。"}, "error_tags": {"が": "主語", "を": "対象", "に": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37121, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「渋滞にはまる」の「に」。はまる先を示す。"}, {"text": "を", "is_correct": false, "explanation": "「渋滞をはまってしまい」は「はまる」が「〜を」を取らず、不自然。"}, {"text": "が", "is_correct": false, "explanation": "「渋滞がはまってしまい」は主語として成り立たず、意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「渋滞のはまってしまい」は名詞修飾の「の」で、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「渋滞にはまる」の「に」。はまる先を示す。", "を": "「渋滞をはまってしまい」は「はまる」が「〜を」を取らず、不自然。", "が": "「渋滞がはまってしまい」は主語として成り立たず、意味が通らない。", "の": "「渋滞のはまってしまい」は名詞修飾の「の」で、文が成り立たない。"}, "error_tags": {"を": "対象", "が": "主語", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37121, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "道路が車などでいっぱいになり、動きが悪くなること。", "primary_collocate": null, "pronunciation": "じゅうたい", "ipa": "dʑɯːtai", "syllable_count": 4, "sentences": [{"text": "雨が降ると、この道路は渋滞しやすい。", "target_word": "渋滞", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ると、この道路[どうろ]は渋滞[じゅうたい]しやすい。", "sentence_source": "generated"}, {"text": "渋滞の先頭では、事故の処理が行われていた。", "target_word": "渋滞", "complexity_tier": "T3", "furigana": "渋滞[じゅうたい]の先頭[せんとう]では、事故[じこ]の処理[しょり]が行[おこな]われていた。", "sentence_source": "generated"}, {"text": "ラジオが高速道路の渋滞について伝えている。", "target_word": "渋滞", "complexity_tier": "T3", "furigana": "ラジオが高速道路[こうそくどうろ]の渋滞[じゅうたい]について伝[つた]えている。", "sentence_source": "generated"}, {"text": "渋滞がひどくて、空港まで二時間もかかった。", "target_word": "渋滞", "complexity_tier": "T3", "furigana": "渋滞[じゅうたい]がひどくて、空港[くうこう]まで二時間[にじかん]もかかった。", "sentence_source": "generated"}, {"text": "大雪で、国道に二十キロの渋滞が発生した。", "target_word": "渋滞", "complexity_tier": "T3", "furigana": "大雪[おおゆき]で、国道[こくどう]に二十[にじゅう]キロの渋滞[じゅうたい]が発生[はっせい]した。", "sentence_source": "generated"}, {"text": "渋滞を知らせる標識が道の上に出ている。", "target_word": "渋滞", "complexity_tier": "T3", "furigana": "渋滞[じゅうたい]を知[し]らせる標識[ひょうしき]が道[みち]の上[うえ]に出[で]ている。", "sentence_source": "generated"}, {"text": "夏休みの最初の日曜日は、海へ向かう道が渋滞する。", "target_word": "渋滞", "complexity_tier": "T3", "furigana": "夏休[なつやす]みの最初[さいしょ]の日曜日[にちようび]は、海[うみ]へ向[む]かう道[みち]が渋滞[じゅうたい]する。", "sentence_source": "generated"}, {"text": "渋滞にはまってしまい、会議に間に合わなかった。", "target_word": "渋滞", "complexity_tier": "T3", "furigana": "渋滞[じゅうたい]にはまってしまい、会議[かいぎ]に間[ま]に合[あ]わなかった。", "sentence_source": "generated"}, {"text": "信号が故障したので、交差点を中心に渋滞が広がった。", "target_word": "渋滞", "complexity_tier": "T3", "furigana": "信号[しんごう]が故障[こしょう]したので、交差点[こうさてん]を中心[ちゅうしん]に渋滞[じゅうたい]が広[ひろ]がった。", "sentence_source": "generated"}, {"text": "新しいバイパスができて、町の渋滞が少なくなった。", "target_word": "渋滞", "complexity_tier": "T3", "furigana": "新[あたら]しいバイパスができて、町[まち]の渋滞[じゅうたい]が少[すく]なくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "渋滞する", "label": "辞書形"}, {"form": "渋滞している", "label": "進行・継続"}, {"form": "渋滞した", "label": "過去形"}, {"form": "渋滞しない", "label": "否定形"}, {"form": "渋滞して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "道路が車でふさがり流れが悪くなる交通の状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79dd0ac8-530d-4cac-b7a0-2b6a258737ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37121, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "渋滞", "is_correct": true, "explanation": "「渋滞しやすい」は、車が詰まりやすいという道路の状態を表し、文脈に合う。"}, {"text": "出版", "is_correct": false, "explanation": "「出版しやすい」は本や雑誌の話で、道路の状態には当てはまらない。"}, {"text": "溶接", "is_correct": false, "explanation": "「溶接しやすい」は金属作業の話で、道路の状態とは結びつかない。"}, {"text": "解剖", "is_correct": false, "explanation": "「解剖しやすい」は医学の処置の話で、道路の状態には合わない。"}], "explanations": {"渋滞": "「渋滞しやすい」は、車が詰まりやすいという道路の状態を表し、文脈に合う。", "出版": "「出版しやすい」は本や雑誌の話で、道路の状態には当てはまらない。", "溶接": "「溶接しやすい」は金属作業の話で、道路の状態とは結びつかない。", "解剖": "「解剖しやすい」は医学の処置の話で、道路の状態には合わない。"}, "sentence_index": 0, "correct_answer": "渋滞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "景気の渋滞が続いて、給料が上がらない。", "explanation": "ここは〈停滞〉の意味。景気が動かなくなる状態は〈停滞〉で、〈渋滞〉は道路の車の流れに使う。"}, {"text": "週末は温泉地に三日間渋滞した。", "explanation": "ここは〈滞在〉の意味。ある場所に泊まって過ごすことは〈滞在〉で、〈渋滞〉は車や人の流れが詰まる状態を指す。"}, {"text": "電気代が渋滞していて、支払いを催促された。", "explanation": "ここは〈滞納〉の意味。支払いが遅れている状態は〈滞納〉で、〈渋滞〉は交通の流れに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37121, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "渋滞", "is_correct": true, "explanation": "「渋滞する」は道路に車が詰まる意味で、海へ向かう道の状況に合う。"}, {"text": "感電", "is_correct": false, "explanation": "「感電」は体に電流が流れることで、道の状態を表す文には合わない。"}, {"text": "漂白", "is_correct": false, "explanation": "「漂白」は色を抜く作業で、道路の話とは結びつかない。"}, {"text": "座礁", "is_correct": false, "explanation": "「座礁」は船が乗り上げることで、道路の話には使わない。"}], "explanations": {"渋滞": "「渋滞する」は道路に車が詰まる意味で、海へ向かう道の状況に合う。", "感電": "「感電」は体に電流が流れることで、道の状態を表す文には合わない。", "漂白": "「漂白」は色を抜く作業で、道路の話とは結びつかない。", "座礁": "「座礁」は船が乗り上げることで、道路の話には使わない。"}, "sentence_index": 6, "correct_answer": "渋滞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古い冷蔵庫が渋滞して、とうとう冷えなくなった。", "explanation": "ここは〈故障〉の意味。機械が動かなくなるのは〈故障〉で、〈渋滞〉は道路の車の流れに使う。"}, {"text": "大雨の後、町のあちこちで水道管が渋滞している。", "explanation": "ここは〈断水〉の意味。水道が止まる状態は〈断水〉で、〈渋滞〉は車や人の流れが詰まる状態に使うので合わない。"}, {"text": "工事が渋滞して、完成が一か月も遅れた。", "explanation": "ここは〈遅れ〉の意味。工事の進みが遅れることは〈遅れ〉で、〈渋滞〉は道路で車が詰まる状態に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37121, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "事故のあと、渋滞に先頭で警察が交通整理をしていた。", "corrected_sentence": "事故のあと、渋滞の先頭で警察が交通整理をしていた。", "error_description": "「渋滞の先頭」の「の」を「に」にした誤り。「〜の先頭」は位置を示す「の」で結ぶ。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37121, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朝早く出たので、渋滞をはまらずに済んだ。", "corrected_sentence": "朝早く出たので、渋滞にはまらずに済んだ。", "error_description": "「はまる」は「〜に」を取る。「渋滞を」は誤りで、正しくは「渋滞に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37122, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37122, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「机の上が汚れていた」の主語を示す。"}, {"text": "と", "is_correct": false, "explanation": "「机の上と汚れていた」は並べる「と」で、主語を示せず文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "「机の上へ汚れていた」は方向の「へ」で、汚れる状態の主語にならない。"}, {"text": "より", "is_correct": false, "explanation": "「机の上より汚れていた」は比較の「より」で、比べる相手がなく文が成立しない。"}], "correct_answer": "が", "explanations": {"が": "「机の上が汚れていた」の主語を示す。", "と": "「机の上と汚れていた」は並べる「と」で、主語を示せず文が成立しない。", "へ": "「机の上へ汚れていた」は方向の「へ」で、汚れる状態の主語にならない。", "より": "「机の上より汚れていた」は比較の「より」で、比べる相手がなく文が成立しない。"}, "error_tags": {"と": "並列の誤り", "へ": "方向の誤り", "より": "比較の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37122, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものがきたなくなること。", "primary_collocate": null, "pronunciation": "よごれる", "ipa": "joɡoɾeɾɯ", "syllable_count": 4, "sentences": [{"text": "外で遊んで、服が泥で汚れた。", "target_word": "汚れた", "complexity_tier": "T3", "furigana": "外[そと]で遊[あそ]んで、服[ふく]が泥[どろ]で汚[よご]れた。", "sentence_source": "generated"}, {"text": "白いシャツはすぐ汚れるので、あまり着ません。", "target_word": "汚れる", "complexity_tier": "T3", "furigana": "白[しろ]いシャツはすぐ汚[よご]れるので、あまり着[き]ません。", "sentence_source": "generated"}, {"text": "手が汚れたから、先に洗ってください。", "target_word": "汚れた", "complexity_tier": "T3", "furigana": "手[て]が汚[よご]れたから、先[さき]に洗[あら]ってください。", "sentence_source": "generated"}, {"text": "靴が汚れないように、雨の日は長靴をはく。", "target_word": "汚れない", "complexity_tier": "T3", "furigana": "靴[くつ]が汚[よご]れないように、雨[あめ]の日[ひ]は長靴[ながぐつ]をはく。", "sentence_source": "generated"}, {"text": "部屋のカーペットがジュースで汚れてしまった。", "target_word": "汚れて", "complexity_tier": "T3", "furigana": "部屋[へや]のカーペットがジュースで汚[よご]れてしまった。", "sentence_source": "generated"}, {"text": "子どもの顔が、チョコレートで汚れている。", "target_word": "汚れている", "complexity_tier": "T3", "furigana": "子[こ]どもの顔[かお]が、チョコレートで汚[よご]れている。", "sentence_source": "generated"}, {"text": "ノートが汚れたので、新しいのを買った。", "target_word": "汚れた", "complexity_tier": "T3", "furigana": "ノートが汚[よご]れたので、新[あたら]しいのを買[か]った。", "sentence_source": "generated"}, {"text": "机の上が汚れていたので、ふきんでふいた。", "target_word": "汚れて", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]が汚[よご]れていたので、ふきんでふいた。", "sentence_source": "generated"}, {"text": "汚れた靴下は洗濯かごに入れてね。", "target_word": "汚れた", "complexity_tier": "T3", "furigana": "汚[よご]れた靴下[くつした]は洗濯[せんたく]かごに入[い]れてね。", "sentence_source": "generated"}, {"text": "エプロンをすれば、料理をしても服が汚れない。", "target_word": "汚れない", "complexity_tier": "T3", "furigana": "エプロンをすれば、料理[りょうり]をしても服[ふく]が汚[よご]れない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "汚れる", "label": "辞書形"}, {"form": "汚れて", "label": "て形"}, {"form": "汚れた", "label": "過去形"}, {"form": "汚れない", "label": "否定形"}, {"form": "汚れます", "label": "丁寧形"}, {"form": "汚れている", "label": "進行・継続"}], "register": "neutral", "sense_fingerprint": "服・手・持ち物などが泥や汁できたなくなる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79dd0ac8-530d-4cac-b7a0-2b6a258737ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37122, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汚れた", "is_correct": true, "explanation": "過去形で、泥によって服が汚れた結果を表す。"}, {"text": "汚す", "is_correct": false, "explanation": "他動詞なので「服を汚す」となり、服が主語の文には使えない。"}, {"text": "汚して", "is_correct": false, "explanation": "て形のままでは文を終えられず、「外で遊んで」の後に続かない。"}, {"text": "洗った", "is_correct": false, "explanation": "洗うは汚れを落とす動作で、泥で汚れた状態は表さない。"}], "explanations": {"汚れた": "過去形で、泥によって服が汚れた結果を表す。", "汚す": "他動詞なので「服を汚す」となり、服が主語の文には使えない。", "汚して": "て形のままでは文を終えられず、「外で遊んで」の後に続かない。", "洗った": "洗うは汚れを落とす動作で、泥で汚れた状態は表さない。"}, "sentence_index": 0, "correct_answer": "汚れた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "風邪をひいて、声が汚れてしまい、歌えなかった。", "explanation": "ここは〈かすれる〉（声が割れて聞き取りにくくなる）の意味。声の変化には「かすれる」を使い、汚れるは合わない。"}, {"text": "夏の日差しで、看板の赤色がだんだん汚れていった。", "explanation": "ここは〈色があせる〉の意味。色の変化には「褪せる」を使い、汚れるは合わない。"}, {"text": "トーストが汚れてしまったので、食べられなかった。", "explanation": "ここは〈焦げる〉の意味。焼きすぎて黒くなる場合は焦げるを使い、汚れるは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37122, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汚れた", "is_correct": true, "explanation": "過去形で、汚れたという原因を「ので」で示す。"}, {"text": "汚れて", "is_correct": false, "explanation": "て形は「ので」の前に続かない。"}, {"text": "汚し", "is_correct": false, "explanation": "連用形のままでは述語にならず、文が成立しない。"}, {"text": "書いて", "is_correct": false, "explanation": "書くは他動詞で「ノートを書く」になり、「ノートが」で続けられない。"}], "explanations": {"汚れた": "過去形で、汚れたという原因を「ので」で示す。", "汚れて": "て形は「ので」の前に続かない。", "汚し": "連用形のままでは述語にならず、文が成立しない。", "書いて": "書くは他動詞で「ノートを書く」になり、「ノートが」で続けられない。"}, "sentence_index": 6, "correct_answer": "汚れた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏の暑さで、冷蔵庫の牛乳が汚れてしまった。", "explanation": "ここは〈腐る〉（食品が傷んで悪くなる）の意味。食品の変質には腐るを使い、汚れるは合わない。"}, {"text": "海で一日遊んで、腕がこんがり汚れてしまった。", "explanation": "ここは〈日焼けする〉（日光で肌が褐色になる）の意味。日焼けには「焼ける」を使い、汚れるは合わない。"}, {"text": "寒い冷凍庫で、肉がかちかちに汚れてしまった。", "explanation": "ここは〈凍る〉の意味。水分が固まる変化には凍るを使い、汚れるは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37122, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の日は、靴をすぐに泥で汚れてしまう。", "corrected_sentence": "雨の日は、靴がすぐに泥で汚れてしまう。", "error_description": "誤りは「靴を」。「汚れる」は自動詞なので、主語には「が」を使う。正しくは「靴が」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "汚れる", "is_correct": true, "explanation": "辞書形で、「〜ので」の前に続く一般的な性質を表す。"}, {"text": "汚れ", "is_correct": false, "explanation": "語幹だけでは文が終わらず、「ので」にも続かない。"}, {"text": "汚れて", "is_correct": false, "explanation": "て形は「〜ので」の前に直接続けられない。"}, {"text": "汚れなく", "is_correct": false, "explanation": "連用形のままでは「ので」に続かず、文が成立しない。"}], "correct_form": "汚れる", "base_form": "汚れる", "form_label": "辞書形", "sentence_index": 1, "explanations": {"汚れる": "辞書形で、「〜ので」の前に続く一般的な性質を表す。", "汚れ": "語幹だけでは文が終わらず、「ので」にも続かない。", "汚れて": "て形は「〜ので」の前に直接続けられない。", "汚れなく": "連用形のままでは「ので」に続かず、文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37122, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "白いテーブルクロスが、ワインで汚れでしまった。", "corrected_sentence": "白いテーブルクロスが、ワインで汚れてしまった。", "error_description": "誤りは「汚れで」。て形の「て」を濁らせて「で」にしている。正しくは「汚れてしまった」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "汚れて", "is_correct": true, "explanation": "て形で、「汚れていた」の一部（て＋いた）を作る。"}, {"text": "汚れている", "is_correct": false, "explanation": "「ている」を既に含むため、「ていた」を続けると「汚れていていた」となり不自然で成立しない。"}, {"text": "汚れます", "is_correct": false, "explanation": "丁寧形で、「汚れますていた」は成立しない。"}, {"text": "汚れなかった", "is_correct": false, "explanation": "過去の否定形で、「汚れなかったていた」は成立せず、机が汚れていたという文脈とも逆になる。"}], "correct_form": "汚れて", "base_form": "汚れる", "form_label": "て形", "sentence_index": 7, "explanations": {"汚れて": "て形で、「汚れていた」の一部（て＋いた）を作る。", "汚れている": "「ている」を既に含むため、「ていた」を続けると「汚れていていた」となり不自然で成立しない。", "汚れます": "丁寧形で、「汚れますていた」は成立しない。", "汚れなかった": "過去の否定形で、「汚れなかったていた」は成立せず、机が汚れていたという文脈とも逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
