INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37123, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物の表面や空気などが、よごれてきれいではなくなること。", "primary_collocate": null, "pronunciation": "よごれる", "ipa": "joɡoɾeɾɯ", "syllable_count": 4, "sentences": [{"text": "工場の煙で、町の空気が汚れる。", "target_word": "汚れる", "complexity_tier": "T3", "furigana": "工場[こうじょう]の煙[けむり]で、町[まち]の空気[くうき]が汚[よご]れる。", "sentence_source": "generated"}, {"text": "川の水が汚れて、魚がいなくなった。", "target_word": "汚れて", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]が汚[よご]れて、魚[さかな]がいなくなった。", "sentence_source": "generated"}, {"text": "窓ガラスが排気ガスで汚れている。", "target_word": "汚れている", "complexity_tier": "T3", "furigana": "窓[まど]ガラスが排気[はいき]ガスで汚[よご]れている。", "sentence_source": "generated"}, {"text": "長い間そうじをしないと、床はすぐに汚れます。", "target_word": "汚れます", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]そうじをしないと、床[ゆか]はすぐに汚[よご]れます。", "sentence_source": "generated"}, {"text": "海岸の砂が油で汚れてしまった。", "target_word": "汚れて", "complexity_tier": "T3", "furigana": "海岸[かいがん]の砂[すな]が油[あぶら]で汚[よご]れてしまった。", "sentence_source": "generated"}, {"text": "車の白いボディーが、雨のあとに汚れた。", "target_word": "汚れた", "complexity_tier": "T3", "furigana": "車[くるま]の白[しろ]いボディーが、雨[あめ]のあとに汚[よご]れた。", "sentence_source": "generated"}, {"text": "空気が汚れると、のどが痛くなる人もいる。", "target_word": "汚れる", "complexity_tier": "T3", "furigana": "空気[くうき]が汚[よご]れると、のどが痛[いた]くなる人[ひと]もいる。", "sentence_source": "generated"}, {"text": "このかべは、手でさわっても汚れない。", "target_word": "汚れない", "complexity_tier": "T3", "furigana": "このかべは、手[て]でさわっても汚[よご]れない。", "sentence_source": "generated"}, {"text": "池の水が汚れたので、みんなで掃除をした。", "target_word": "汚れた", "complexity_tier": "T3", "furigana": "池[いけ]の水[みず]が汚[よご]れたので、みんなで掃除[そうじ]をした。", "sentence_source": "generated"}, {"text": "古い鏡の表面が汚れて、顔がよく見えない。", "target_word": "汚れて", "complexity_tier": "T3", "furigana": "古[ふる]い鏡[かがみ]の表面[ひょうめん]が汚[よご]れて、顔[かお]がよく見[み]えない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "汚れる", "label": "辞書形"}, {"form": "汚れて", "label": "て形"}, {"form": "汚れた", "label": "過去形"}, {"form": "汚れない", "label": "否定形"}, {"form": "汚れます", "label": "丁寧形"}, {"form": "汚れている", "label": "進行・継続"}], "register": "neutral", "sense_fingerprint": "物の表面・水・空気がよごれて清潔さを失う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79dd0ac8-530d-4cac-b7a0-2b6a258737ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37123, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汚れる", "is_correct": true, "explanation": "自動詞の基本形で、空気が汚れるという状態変化を言い切る。"}, {"text": "汚す", "is_correct": false, "explanation": "他動詞なので「空気を汚す」となり、空気が主語の文には合わない。"}, {"text": "汚して", "is_correct": false, "explanation": "て形では文を終えられず、「町の空気が」の後の述語にならない。"}, {"text": "汚し", "is_correct": false, "explanation": "連用形のままでは述語にならず、文が成立しない。"}], "explanations": {"汚れる": "自動詞の基本形で、空気が汚れるという状態変化を言い切る。", "汚す": "他動詞なので「空気を汚す」となり、空気が主語の文には合わない。", "汚して": "て形では文を終えられず、「町の空気が」の後の述語にならない。", "汚し": "連用形のままでは述語にならず、文が成立しない。"}, "sentence_index": 0, "correct_answer": "汚れる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この料理は時間が経って、味が汚れてしまった。", "explanation": "ここは〈まずくなる〉（味が落ちる）の意味。味の変化には「まずくなる」を使い、汚れるは合わない。"}, {"text": "トーストが汚れてしまったので、食べられなかった。", "explanation": "ここは〈焦げる〉の意味。焼きすぎて黒くなる場合は焦げるを使い、汚れるは合わない。"}, {"text": "夏の日差しで、看板の赤色がだんだん汚れていった。", "explanation": "ここは〈色があせる〉の意味。色の変化には褪せるを使い、汚れるは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37123, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汚れる", "is_correct": true, "explanation": "辞書形で、空気が汚れるという条件を「と」で示す。"}, {"text": "澄んで", "is_correct": false, "explanation": "て形は「と」の前に続かず、文が成立しない。"}, {"text": "冷やし", "is_correct": false, "explanation": "連用形のままでは「空気が」の述語にならない。"}, {"text": "濁って", "is_correct": false, "explanation": "て形は「と」の前に直接続けられず、条件の文にならない。"}], "explanations": {"汚れる": "辞書形で、空気が汚れるという条件を「と」で示す。", "澄んで": "て形は「と」の前に続かず、文が成立しない。", "冷やし": "連用形のままでは「空気が」の述語にならない。", "濁って": "て形は「と」の前に直接続けられず、条件の文にならない。"}, "sentence_index": 6, "correct_answer": "汚れる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏の暑さで、冷蔵庫の牛乳が汚れてしまった。", "explanation": "ここは〈腐る〉（食品が傷んで悪くなる）の意味。食品の変質には腐るを使い、汚れるは合わない。"}, {"text": "寒い冷凍庫で、肉がかちかちに汚れてしまった。", "explanation": "ここは〈凍る〉の意味。水分が固まる変化には凍るを使い、汚れるは合わない。"}, {"text": "転んでぶつけた足首が汚れて、ひどく腫れてしまった。", "explanation": "ここは〈腫れる〉（けがで皮膚が膨らむ）の意味。けがによる腫れには「腫れる」を使い、汚れるは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37123, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大雨のあと、川の水を泥で汚れてしまう。", "corrected_sentence": "大雨のあと、川の水が泥で汚れてしまう。", "error_description": "誤りは「水を」。「汚れる」は自動詞なので、主語「川の水」には「が」を使う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "汚れて", "is_correct": true, "explanation": "て形で、後ろの文へつないで原因と結果を示す。"}, {"text": "汚れ", "is_correct": false, "explanation": "語幹だけでは文が終わらず、「の」にも続かない。"}, {"text": "汚れよう", "is_correct": false, "explanation": "意志形のため「汚れよう、魚が…」と原因を続けられない。"}, {"text": "汚れます", "is_correct": false, "explanation": "丁寧形で、「汚れますて」は成立しない。"}], "correct_form": "汚れて", "base_form": "汚れる", "form_label": "て形", "sentence_index": 1, "explanations": {"汚れて": "て形で、後ろの文へつないで原因と結果を示す。", "汚れ": "語幹だけでは文が終わらず、「の」にも続かない。", "汚れよう": "意志形のため「汚れよう、魚が…」と原因を続けられない。", "汚れます": "丁寧形で、「汚れますて」は成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37123, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "港の岸壁が、油に汚れてしまった。", "corrected_sentence": "港の岸壁が、油で汚れてしまった。", "error_description": "誤りは「油に」。原因を表す「で」を「に」にしている。正しくは「油で汚れてしまった」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "汚れない", "is_correct": true, "explanation": "否定形で、手で触っても汚れにくいという意味を表す。"}, {"text": "汚れ", "is_correct": false, "explanation": "語幹だけでは文が終わらず、述語にならない。"}, {"text": "汚れなく", "is_correct": false, "explanation": "連用形のままでは文が終わらず、述語にならない。"}, {"text": "汚れて", "is_correct": false, "explanation": "て形では文が途中で切れ、述語にならない。"}], "correct_form": "汚れない", "base_form": "汚れる", "form_label": "否定形", "sentence_index": 7, "explanations": {"汚れない": "否定形で、手で触っても汚れにくいという意味を表す。", "汚れ": "語幹だけでは文が終わらず、述語にならない。", "汚れなく": "連用形のままでは文が終わらず、述語にならない。", "汚れて": "て形では文が途中で切れ、述語にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37124, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「公共の道」の「の」で、公共に属する道を示し、この文に合う。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」は、道にごみを捨てる文の「公共」には入らない。"}, {"text": "を", "is_correct": false, "explanation": "「公共を道」と目的語にはならず、文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、道を修飾できない。"}], "correct_answer": "の", "explanations": {"の": "「公共の道」の「の」で、公共に属する道を示し、この文に合う。", "が": "主語の「が」は、道にごみを捨てる文の「公共」には入らない。", "を": "「公共を道」と目的語にはならず、文として成り立たない。", "へ": "方向を表す「へ」は、道を修飾できない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37124, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「公共の道路」の「の」で、公共に属する道路を示し、この文に合う。"}, {"text": "に", "is_correct": false, "explanation": "「公共に道路は」は、相手や存在を表せず不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は、この文の主語を作れない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は、道路を修飾できない。"}], "correct_answer": "の", "explanations": {"の": "「公共の道路」の「の」で、公共に属する道路を示し、この文に合う。", "に": "「公共に道路は」は、相手や存在を表せず不自然。", "より": "比較の「より」は、この文の主語を作れない。", "から": "起点の「から」は、道路を修飾できない。"}, "error_tags": {"に": "存在・相手", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37124, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "みんなが使う乗り物や道のことです。", "primary_collocate": null, "pronunciation": "こうきょう", "ipa": "koːkjoː", "syllable_count": 4, "sentences": [{"text": "バスや電車などの公共の乗り物は、環境にやさしい。", "target_word": "公共", "complexity_tier": "T3", "furigana": "バスや電車[でんしゃ]などの公共[こうきょう]の乗[の]り物[もの]は、環境[かんきょう]にやさしい。", "sentence_source": "generated"}, {"text": "公共の道にごみを捨ててはいけない。", "target_word": "公共", "complexity_tier": "T3", "furigana": "公共[こうきょう]の道[みち]にごみを捨[す]ててはいけない。", "sentence_source": "generated"}, {"text": "車がなくても、公共の交通で通勤できる。", "target_word": "公共", "complexity_tier": "T3", "furigana": "車[くるま]がなくても、公共[こうきょう]の交通[こうつう]で通勤[つうきん]できる。", "sentence_source": "generated"}, {"text": "朝の公共の乗り物は混むので、早めに家を出る。", "target_word": "公共", "complexity_tier": "T3", "furigana": "朝[あさ]の公共[こうきょう]の乗[の]り物[もの]は混[こ]むので、早[はや]めに家[いえ]を出[で]る。", "sentence_source": "generated"}, {"text": "公共の道を工事するときは、前もって知らせる。", "target_word": "公共", "complexity_tier": "T3", "furigana": "公共[こうきょう]の道[みち]を工事[こうじ]するときは、前[まえ]もって知[し]らせる。", "sentence_source": "generated"}, {"text": "公共の乗り物の中では、携帯電話の音を消すのがマナーだ。", "target_word": "公共", "complexity_tier": "T3", "furigana": "公共[こうきょう]の乗[の]り物[もの]の中[なか]では、携帯電話[けいたいでんわ]の音[おと]を消[け]すのがマナーだ。", "sentence_source": "generated"}, {"text": "雪の日は、公共の交通が止まることがある。", "target_word": "公共", "complexity_tier": "T3", "furigana": "雪[ゆき]の日[ひ]は、公共[こうきょう]の交通[こうつう]が止[と]まることがある。", "sentence_source": "generated"}, {"text": "公共の道路は、みんなが使うので勝手にふさいではいけない。", "target_word": "公共", "complexity_tier": "T3", "furigana": "公共[こうきょう]の道路[どうろ]は、みんなが使[つか]うので勝手[かって]にふさいではいけない。", "sentence_source": "generated"}, {"text": "子どもに、公共の乗り物での座り方を教えた。", "target_word": "公共", "complexity_tier": "T3", "furigana": "子[こ]どもに、公共[こうきょう]の乗[の]り物[もの]での座[すわ]り方[かた]を教[おし]えた。", "sentence_source": "generated"}, {"text": "田舎では公共の乗り物が少なく、車がないと不便だ。", "target_word": "公共", "complexity_tier": "T3", "furigana": "田舎[いなか]では公共[こうきょう]の乗[の]り物[もの]が少[すく]なく、車[くるま]がないと不便[ふべん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "公共", "label": "基本形"}, {"form": "公共の", "label": "連体形"}, {"form": "公共的", "label": "形状詞形"}], "register": "標準的な普通体", "sense_fingerprint": "みんなが使う乗り物や道に関すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc4c99e5-c08d-4486-b1ed-5a1851877780') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37124, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公共", "is_correct": true, "explanation": "みんなが使う乗り物を指す「公共の乗り物」として、この文に合う。"}, {"text": "食べ物", "is_correct": false, "explanation": "「食べ物の乗り物」は意味が通らず、文に合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "「教科書の乗り物」は不自然で、乗り物を修飾できない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気の乗り物」は意味が通らず、文に合わない。"}], "explanations": {"公共": "みんなが使う乗り物を指す「公共の乗り物」として、この文に合う。", "食べ物": "「食べ物の乗り物」は意味が通らず、文に合わない。", "教科書": "「教科書の乗り物」は不自然で、乗り物を修飾できない。", "天気": "「天気の乗り物」は意味が通らず、文に合わない。"}, "sentence_index": 0, "correct_answer": "公共"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寮の住人だけが使う公共の部屋を、みんなで掃除した。", "explanation": "ここは〈共用〉の意味。特定の人たちだけで使う部屋は、公共ではなく共用と言う。"}, {"text": "彼女は公共の性格で、すぐに新しい友だちができる。", "explanation": "ここは〈社交的〉の意味。公共は社会全体に関わる物事を指すので、人の性格には使えない。"}, {"text": "先生は公共の態度で、どの生徒も平等に扱う。", "explanation": "ここは〈公平〉の意味。偏らない態度を言うので、公共とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37124, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公共", "is_correct": true, "explanation": "「雪の日は、公共の交通が止まる」の公共で、みんなが使う交通を指すので合う。"}, {"text": "寒さ", "is_correct": false, "explanation": "「寒さの交通」は意味が通らず、文に合わない。"}, {"text": "郵便", "is_correct": false, "explanation": "「郵便の交通」は不自然で、交通を修飾できない。"}, {"text": "洗剤", "is_correct": false, "explanation": "「洗剤の交通」は意味が通らず、文に合わない。"}], "explanations": {"公共": "「雪の日は、公共の交通が止まる」の公共で、みんなが使う交通を指すので合う。", "寒さ": "「寒さの交通」は意味が通らず、文に合わない。", "郵便": "「郵便の交通」は不自然で、交通を修飾できない。", "洗剤": "「洗剤の交通」は意味が通らず、文に合わない。"}, "sentence_index": 6, "correct_answer": "公共"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "役所の公共の車で、出張に行った。", "explanation": "ここは〈公用〉の意味。役所の車は公用車と言い、公共とは言わない。"}, {"text": "この日記は、人に見せたくないので公共にはしない。", "explanation": "ここは〈公開〉の意味。日記を人に見せることは公開と言い、公共とは言わない。"}, {"text": "家族の公共の財布から、お金を出した。", "explanation": "ここは〈共通〉の意味。家族だけの財布は、公共ではなく共通のものと言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37124, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "休みの日は、公共な交通でお出かけしよう。", "corrected_sentence": "休みの日は、公共の交通でお出かけしよう。", "error_description": "「公共」は名詞なので、続けるには「の」が必要。「公共な」は誤り（「公共的な」とは言える）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37124, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ふだんの通勤は、公共の乗り手を使う。", "corrected_sentence": "ふだんの通勤は、公共の乗り物を使う。", "error_description": "「公共の」に続けるのは「乗り物」が自然。「乗り手」は乗る人を指すので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37125, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37125, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「公共の施設」の「の」で、社会全体のための施設を示し、この文に合う。"}, {"text": "へ", "is_correct": false, "explanation": "「公共へ施設を使ったあと」は方向として不自然。"}, {"text": "より", "is_correct": false, "explanation": "「公共より施設を使った」は比較として意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は「公共から施設を使う」とは言えない。"}], "correct_answer": "の", "explanations": {"の": "「公共の施設」の「の」で、社会全体のための施設を示し、この文に合う。", "へ": "「公共へ施設を使ったあと」は方向として不自然。", "より": "「公共より施設を使った」は比較として意味が通らない。", "から": "起点の「から」は「公共から施設を使う」とは言えない。"}, "error_tags": {"へ": "方向", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37125, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "社会全体のためのもので、多くの人が利用できる施設やサービス。", "primary_collocate": null, "pronunciation": "こうきょう", "ipa": "koːkjoː", "syllable_count": 4, "sentences": [{"text": "公共のサービスは、税金によって支えられている。", "target_word": "公共", "complexity_tier": "T3", "furigana": "公共[こうきょう]のサービスは、税金[ぜいきん]によって支[ささ]えられている。", "sentence_source": "generated"}, {"text": "図書館のような公共の施設は、だれでも利用できる。", "target_word": "公共", "complexity_tier": "T3", "furigana": "図書館[としょかん]のような公共[こうきょう]の施設[しせつ]は、だれでも利用[りよう]できる。", "sentence_source": "generated"}, {"text": "水道やごみ収集は、生活に欠かせない公共のサービスだ。", "target_word": "公共", "complexity_tier": "T3", "furigana": "水道[すいどう]やごみ収集[しゅうしゅう]は、生活[せいかつ]に欠[か]かせない公共[こうきょう]のサービスだ。", "sentence_source": "generated"}, {"text": "公共の窓口で、住民票の手続きをした。", "target_word": "公共", "complexity_tier": "T3", "furigana": "公共[こうきょう]の窓口[まどぐち]で、住民票[じゅうみんひょう]の手続[てつづ]きをした。", "sentence_source": "generated"}, {"text": "公共の病院は、救急の患者を断らずに受け入れている。", "target_word": "公共", "complexity_tier": "T3", "furigana": "公共[こうきょう]の病院[びょういん]は、救急[きゅうきゅう]の患者[かんじゃ]を断[ことわ]らずに受[う]け入[い]れている。", "sentence_source": "generated"}, {"text": "公共の図書館ができて、子どもたちが放課後に集まるようになった。", "target_word": "公共", "complexity_tier": "T3", "furigana": "公共[こうきょう]の図書館[としょかん]ができて、子[こ]どもたちが放課後[ほうかご]に集[あつ]まるようになった。", "sentence_source": "generated"}, {"text": "民間のバスと違い、公共のバスは利益だけを目的にしない。", "target_word": "公共", "complexity_tier": "T3", "furigana": "民間[みんかん]のバスと違[ちが]い、公共[こうきょう]のバスは利益[りえき]だけを目的[もくてき]にしない。", "sentence_source": "generated"}, {"text": "公共の施設を使ったあとは、きれいに片づけよう。", "target_word": "公共", "complexity_tier": "T3", "furigana": "公共[こうきょう]の施設[しせつ]を使[つか]ったあとは、きれいに片[かた]づけよう。", "sentence_source": "generated"}, {"text": "公共の放送は、災害のときに大切な情報を伝える。", "target_word": "公共", "complexity_tier": "T3", "furigana": "公共[こうきょう]の放送[ほうそう]は、災害[さいがい]のときに大切[たいせつ]な情報[じょうほう]を伝[つた]える。", "sentence_source": "generated"}, {"text": "大雪で公共のサービスが止まり、町の人は困った。", "target_word": "公共", "complexity_tier": "T3", "furigana": "大雪[おおゆき]で公共[こうきょう]のサービスが止[と]まり、町[まち]の人[ひと]は困[こま]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "公共", "label": "基本形"}, {"form": "公共の", "label": "連体形"}, {"form": "公共的", "label": "形状詞形"}], "register": "標準的な普通体", "sense_fingerprint": "社会全体のための、多くの人が使える施設やサービス", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc4c99e5-c08d-4486-b1ed-5a1851877780') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37125, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公共", "is_correct": true, "explanation": "社会全体のための施設やサービスを指し、税金で支えられるサービスに合う。"}, {"text": "天気", "is_correct": false, "explanation": "「天気のサービス」は意味が通らず、税金で支えられる文に合わない。"}, {"text": "洗剤", "is_correct": false, "explanation": "「洗剤のサービス」は税金で支えられるという文脈に合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "「教科書のサービス」は不自然で、文の意味が成り立たない。"}], "explanations": {"公共": "社会全体のための施設やサービスを指し、税金で支えられるサービスに合う。", "天気": "「天気のサービス」は意味が通らず、税金で支えられる文に合わない。", "洗剤": "「洗剤のサービス」は税金で支えられるという文脈に合わない。", "教科書": "「教科書のサービス」は不自然で、文の意味が成り立たない。"}, "sentence_index": 0, "correct_answer": "公共"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "アパートの住人が、公共の洗濯機を交代で使っている。", "explanation": "ここは〈共同〉の意味。住人だけで使う洗濯機は共同利用で、公共とは言わない。"}, {"text": "審判は公共の判断で、どちらにも偏らず判定した。", "explanation": "ここは〈公平〉の意味。偏らずに判定することを言い、公共とは言わない。"}, {"text": "役所の公共の車を、休みの日に私用で使った。", "explanation": "ここは〈公用〉の意味。役所の車は公用車と言い、私用の場面に公共は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37125, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公共", "is_correct": true, "explanation": "「民間のバスと違い」と対比される、社会全体のためのバスを指すので合う。"}, {"text": "寒さ", "is_correct": false, "explanation": "「寒さのバス」は意味が通らず、対比の文に合わない。"}, {"text": "食べ物", "is_correct": false, "explanation": "「食べ物のバス」は不自然で、対比の文に合わない。"}, {"text": "雑誌", "is_correct": false, "explanation": "「雑誌のバス」は意味が通らず、文に合わない。"}], "explanations": {"公共": "「民間のバスと違い」と対比される、社会全体のためのバスを指すので合う。", "寒さ": "「寒さのバス」は意味が通らず、対比の文に合わない。", "食べ物": "「食べ物のバス」は不自然で、対比の文に合わない。", "雑誌": "「雑誌のバス」は意味が通らず、文に合わない。"}, "sentence_index": 6, "correct_answer": "公共"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私たちの公共の目標は、毎日同じだ。", "explanation": "ここは〈共通〉の意味。同じ目標を持つことは共通と言い、公共とは言わない。"}, {"text": "彼は公共の性格で、初対面の人ともすぐに話せる。", "explanation": "ここは〈社交的〉の意味。初対面でも話せる性格は社交的と言い、公共は使えない。"}, {"text": "社員だけで使う公共の寮があり、部屋を交代で使う。", "explanation": "ここは〈共用〉の意味。社員だけで使う寮は共用と言い、公共とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37125, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "税金は、公共をサービスを支えている。", "corrected_sentence": "税金は、公共のサービスを支えている。", "error_description": "「公共」は後ろの名詞を修飾するので「の」が必要。「公共を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37125, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公共のサービスは、市が維持するしている。", "corrected_sentence": "公共のサービスは、市が維持している。", "error_description": "「維持する」の後に「している」が続き、動詞の形が重なって誤り。「維持している」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308eae51-0ad5-4a22-937a-e44ff500172c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37126, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「交通が乱れる」の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「乱れる」は自動詞なので目的語の「を」を取らない。"}, {"text": "に", "is_correct": false, "explanation": "「交通に乱れています」は成立せず、主語を示す役割を果たさない。"}, {"text": "の", "is_correct": false, "explanation": "「交通の乱れています」は名詞を続けないと文にならない。"}], "correct_answer": "が", "explanations": {"が": "「交通が乱れる」の主語を示す。", "を": "「乱れる」は自動詞なので目的語の「を」を取らない。", "に": "「交通に乱れています」は成立せず、主語を示す役割を果たさない。", "の": "「交通の乱れています」は名詞を続けないと文にならない。"}, "error_tags": {"を": "目的語の誤り", "に": "格の誤り", "の": "連体修飾の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37126, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「交通が規制される」の主語を示す。"}, {"text": "と", "is_correct": false, "explanation": "「交通と規制される」は並べる「と」で、受け身の主語を示せず文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "「交通へ規制される」は方向の「へ」で、受け身の主語にならない。"}, {"text": "より", "is_correct": false, "explanation": "「交通より規制される」は比較の「より」で、比べる相手がなく文が成立しない。"}], "correct_answer": "が", "explanations": {"が": "「交通が規制される」の主語を示す。", "と": "「交通と規制される」は並べる「と」で、受け身の主語を示せず文が成立しない。", "へ": "「交通へ規制される」は方向の「へ」で、受け身の主語にならない。", "より": "「交通より規制される」は比較の「より」で、比べる相手がなく文が成立しない。"}, "error_tags": {"と": "並列の誤り", "へ": "方向の誤り", "より": "比較の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37126, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "のりものやみちをつかって、ひとやものがいどうすること。", "primary_collocate": null, "pronunciation": "こうつう", "ipa": "koːtsɯː", "syllable_count": 4, "sentences": [{"text": "この町は交通が便利です。", "target_word": "交通", "complexity_tier": "T3", "furigana": "この町[まち]は交通[こうつう]が便利[べんり]です。", "sentence_source": "generated"}, {"text": "雪のため、朝から交通が乱れています。", "target_word": "交通", "complexity_tier": "T3", "furigana": "雪[ゆき]のため、朝[あさ]から交通[こうつう]が乱[みだ]れています。", "sentence_source": "generated"}, {"text": "駅の近くは交通の便がいいので、人気があります。", "target_word": "交通", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くは交通[こうつう]の便[べん]がいいので、人気[にんき]があります。", "sentence_source": "generated"}, {"text": "この島は交通が不便なので、車がないと困ります。", "target_word": "交通", "complexity_tier": "T3", "furigana": "この島[しま]は交通[こうつう]が不便[ふべん]なので、車[くるま]がないと困[こま]ります。", "sentence_source": "generated"}, {"text": "道をわたるときは、交通に気をつけましょう。", "target_word": "交通", "complexity_tier": "T3", "furigana": "道[みち]をわたるときは、交通[こうつう]に気[き]をつけましょう。", "sentence_source": "generated"}, {"text": "大雨で、町の交通がすべて止まった。", "target_word": "交通", "complexity_tier": "T3", "furigana": "大雨[おおあめ]で、町[まち]の交通[こうつう]がすべて止[と]まった。", "sentence_source": "generated"}, {"text": "昔は交通が不便で、隣の町へ行くのに一日かかった。", "target_word": "交通", "complexity_tier": "T3", "furigana": "昔[むかし]は交通[こうつう]が不便[ふべん]で、隣[となり]の町[まち]へ行[い]くのに一日[いちにち]かかった。", "sentence_source": "generated"}, {"text": "祭りの日は、駅の前の交通が規制される。", "target_word": "交通", "complexity_tier": "T3", "furigana": "祭[まつ]りの日[ひ]は、駅[えき]の前[まえ]の交通[こうつう]が規制[きせい]される。", "sentence_source": "generated"}, {"text": "バスや電車が増えて、町の交通は前より楽になった。", "target_word": "交通", "complexity_tier": "T3", "furigana": "バスや電車[でんしゃ]が増[ふ]えて、町[まち]の交通[こうつう]は前[まえ]より楽[らく]になった。", "sentence_source": "generated"}, {"text": "交通のルールを守って、安全に歩きましょう。", "target_word": "交通", "complexity_tier": "T3", "furigana": "交通[こうつう]のルールを守[まも]って、安全[あんぜん]に歩[ある]きましょう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "交通", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "乗り物や道を使って人や物が行き来すること（道路・鉄道などの人や車の動き）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79dd0ac8-530d-4cac-b7a0-2b6a258737ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37126, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交通", "is_correct": true, "explanation": "「交通が便利」で、道路や鉄道で行き来しやすいことを表す。"}, {"text": "治安", "is_correct": false, "explanation": "「治安が便利」は意味が通らない。治安は安全の程度を表す。"}, {"text": "物価", "is_correct": false, "explanation": "「物価が便利」は意味が通らない。物価は値段の水準を表す。"}, {"text": "騒音", "is_correct": false, "explanation": "「騒音が便利」は意味が通らない。騒音は不快な音を表す。"}], "explanations": {"交通": "「交通が便利」で、道路や鉄道で行き来しやすいことを表す。", "治安": "「治安が便利」は意味が通らない。治安は安全の程度を表す。", "物価": "「物価が便利」は意味が通らない。物価は値段の水準を表す。", "騒音": "「騒音が便利」は意味が通らない。騒音は不快な音を表す。"}, "sentence_index": 0, "correct_answer": "交通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は労働組合と賃金の交通を続けた。", "explanation": "ここは〈交渉〉（条件を話し合うこと）の意味。話し合いには「交渉」を使い、交通は道や乗り物の往来に限るので合わない。"}, {"text": "二つの国の軍隊が三日間、交通を続けた。", "explanation": "ここは〈交戦〉（武力で争うこと）の意味。戦いには「交戦」を使い、交通は合わない。"}, {"text": "毎朝、母が子どもを学校まで交通している。", "explanation": "ここは〈送迎〉の意味。人を送り迎えする場合は送迎を使い、交通は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37126, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交通", "is_correct": true, "explanation": "「交通が不便」で、移動の便が悪いことを表す。"}, {"text": "砂糖", "is_correct": false, "explanation": "「砂糖が不便」は意味が通らない。"}, {"text": "地震", "is_correct": false, "explanation": "「地震が不便」は意味が通らない。"}, {"text": "湿気", "is_correct": false, "explanation": "「湿気が不便」は、一日かかる移動の説明にならない。"}], "explanations": {"交通": "「交通が不便」で、移動の便が悪いことを表す。", "砂糖": "「砂糖が不便」は意味が通らない。", "地震": "「地震が不便」は意味が通らない。", "湿気": "「湿気が不便」は、一日かかる移動の説明にならない。"}, "sentence_index": 6, "correct_answer": "交通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "渡り鳥は毎年秋、暖かい南への交通をする。", "explanation": "ここは〈移動〉の意味。鳥や人が場所を変える動きには移動を使い、交通は乗り物や道の往来に限るので合わない。"}, {"text": "重い荷物を、台車で交通している。", "explanation": "ここは〈運搬〉の意味。物を運ぶ動作には運搬を使い、交通は合わない。"}, {"text": "この店は、外国から果物を交通している。", "explanation": "ここは〈輸入〉の意味。外国から品物を取り寄せる場合は輸入を使い、交通は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37126, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "台風の影響で、駅前の交通にしばらく止まった。", "corrected_sentence": "台風の影響で、駅前の交通がしばらく止まった。", "error_description": "誤りは「交通に」。「止まる」は主語に「が」を使う。正しくは「交通が止まった」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37126, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この地域は交通を混雑していて、事故が多い。", "corrected_sentence": "この地域は交通が混雑していて、事故が多い。", "error_description": "誤りは「交通を」。「混雑する」は自動詞なので、主語「交通」には「が」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37127, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「交通が不便」の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「交通を不便で」は成立せず、「不便」の主語にならない。"}, {"text": "と", "is_correct": false, "explanation": "「交通と不便で」は並列の「と」で、「不便」の主語を示せず文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、「不便だ」の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「交通が不便」の主語を示す。", "を": "「交通を不便で」は成立せず、「不便」の主語にならない。", "と": "「交通と不便で」は並列の「と」で、「不便」の主語を示せず文が成立しない。", "へ": "方向を表す「へ」は、「不便だ」の主語にはならない。"}, "error_tags": {"を": "目的語の誤り", "へ": "方向の誤り", "と": "並列の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37127, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「交通を便利にする」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「交通が便利にする」は主語と動作が合わず、文が成立しない。"}, {"text": "に", "is_correct": false, "explanation": "「交通に便利にする」は不自然で、目的語を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「便利にする」の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「交通を便利にする」の目的語を示す。", "が": "「交通が便利にする」は主語と動作が合わず、文が成立しない。", "に": "「交通に便利にする」は不自然で、目的語を示せない。", "へ": "方向を表す「へ」は「便利にする」の目的語にならない。"}, "error_tags": {"が": "主語の誤り", "に": "格の誤り", "へ": "方向の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37127, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人や物が、ある場所から別の場所へ移動すること。また、そのための手段や仕組み。", "primary_collocate": null, "pronunciation": "こうつう", "ipa": "koːtsɯː", "syllable_count": 4, "sentences": [{"text": "この国は鉄道が発達していて、交通が整っている。", "target_word": "交通", "complexity_tier": "T3", "furigana": "この国[くに]は鉄道[てつどう]が発達[はったつ]していて、交通[こうつう]が整[ととの]っている。", "sentence_source": "generated"}, {"text": "山の中の村は、交通が不便で人が少ない。", "target_word": "交通", "complexity_tier": "T3", "furigana": "山[やま]の中[なか]の村[むら]は、交通[こうつう]が不便[ふべん]で人[ひと]が少[すく]ない。", "sentence_source": "generated"}, {"text": "新しい道路ができて、町と町の交通がよくなった。", "target_word": "交通", "complexity_tier": "T3", "furigana": "新[あたら]しい道路[どうろ]ができて、町[まち]と町[まち]の交通[こうつう]がよくなった。", "sentence_source": "generated"}, {"text": "川に橋がかかり、島との交通が始まった。", "target_word": "交通", "complexity_tier": "T3", "furigana": "川[かわ]に橋[はし]がかかり、島[しま]との交通[こうつう]が始[はじ]まった。", "sentence_source": "generated"}, {"text": "都市では、地下鉄が交通を支えている。", "target_word": "交通", "complexity_tier": "T3", "furigana": "都市[とし]では、地下鉄[ちかてつ]が交通[こうつう]を支[ささ]えている。", "sentence_source": "generated"}, {"text": "地震で道が壊れ、村との交通が切れてしまった。", "target_word": "交通", "complexity_tier": "T3", "furigana": "地震[じしん]で道[みち]が壊[こわ]れ、村[むら]との交通[こうつう]が切[き]れてしまった。", "sentence_source": "generated"}, {"text": "空の交通は、天気に大きく影響される。", "target_word": "交通", "complexity_tier": "T3", "furigana": "空[そら]の交通[こうつう]は、天気[てんき]に大[おお]きく影響[えいきょう]される。", "sentence_source": "generated"}, {"text": "市は、お年寄りのために交通を便利にする計画を立てた。", "target_word": "交通", "complexity_tier": "T3", "furigana": "市[し]は、お年寄[としよ]りのために交通[こうつう]を便利[べんり]にする計画[けいかく]を立[た]てた。", "sentence_source": "generated"}, {"text": "港ができてから、外国との交通がさかんになった。", "target_word": "交通", "complexity_tier": "T3", "furigana": "港[みなと]ができてから、外国[がいこく]との交通[こうつう]がさかんになった。", "sentence_source": "generated"}, {"text": "雪が多い地方では、冬でも交通を確保する工夫が必要だ。", "target_word": "交通", "complexity_tier": "T3", "furigana": "雪[ゆき]が多[おお]い地方[ちほう]では、冬[ふゆ]でも交通[こうつう]を確保[かくほ]する工夫[くふう]が必要[ひつよう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "交通", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "場所と場所を結ぶ移動の手段や仕組み（鉄道・道路・航路などの交通網）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79dd0ac8-530d-4cac-b7a0-2b6a258737ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37127, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交通", "is_correct": true, "explanation": "「交通が整う」で、場所と場所を結ぶ移動の仕組みが整備されることを表す。"}, {"text": "砂糖", "is_correct": false, "explanation": "「砂糖が整う」は意味が通らない。"}, {"text": "地震", "is_correct": false, "explanation": "「地震が整う」は意味が通らない。"}, {"text": "湿気", "is_correct": false, "explanation": "「湿気が整う」は意味が通らない。"}], "explanations": {"交通": "「交通が整う」で、場所と場所を結ぶ移動の仕組みが整備されることを表す。", "砂糖": "「砂糖が整う」は意味が通らない。", "地震": "「地震が整う」は意味が通らない。", "湿気": "「湿気が整う」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "交通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は持っていた本を、古い辞書と交通した。", "explanation": "ここは〈交換〉（物を取り替える）の意味。物の取り替えには「交換」を使い、交通は合わない。"}, {"text": "二人は夜の見張りを交通して、交互に休んだ。", "explanation": "ここは〈交代〉（役目を交互に替える）の意味。役目の入れ替えには「交代」を使い、交通は合わない。"}, {"text": "会議の資料を、遠くの支店へ交通した。", "explanation": "ここは〈送付〉の意味。書類を送る行為には送付を使い、交通は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37127, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交通", "is_correct": true, "explanation": "「空の交通」は航空路などの移動の仕組みを指し、天気の影響を受ける文として成立する。"}, {"text": "寿命", "is_correct": false, "explanation": "「空の寿命」は意味が通らない。"}, {"text": "食費", "is_correct": false, "explanation": "「空の食費」は意味が通らない。"}, {"text": "給料", "is_correct": false, "explanation": "「空の給料」は意味が通らない。"}], "explanations": {"交通": "「空の交通」は航空路などの移動の仕組みを指し、天気の影響を受ける文として成立する。", "寿命": "「空の寿命」は意味が通らない。", "食費": "「空の食費」は意味が通らない。", "給料": "「空の給料」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "交通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二つの国が国境で、三日間にわたって交通を続けた。", "explanation": "ここは〈交戦〉（武力で争うこと）の意味。戦いには「交戦」を使い、交通は合わない。"}, {"text": "重い機械を、クレーンで交通している。", "explanation": "ここは〈運搬〉の意味。物を運ぶ動作には運搬を使い、交通は合わない。"}, {"text": "この店は、外国から果物を交通している。", "explanation": "ここは〈輸入〉の意味。外国から品物を取り寄せる場合は輸入を使い、交通は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37127, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大橋ができて、島との交通を便利になった。", "corrected_sentence": "大橋ができて、島との交通が便利になった。", "error_description": "誤りは「交通を」。「便利になる」は主語に「が」を使う。正しくは「交通が便利になった」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37127, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大雪で鉄道が止まり、山の村との交通をとだえた。", "corrected_sentence": "大雪で鉄道が止まり、山の村との交通がとだえた。", "error_description": "誤りは「交通を」。「とだえる」は自動詞なので、主語「交通」には「が」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37128, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「電車での移動中」の「の」。で句を「移動」につなぐ連体修飾で正しい。"}, {"text": "が", "is_correct": false, "explanation": "「電車での＿移動中」では主語として成り立たず、不自然。"}, {"text": "を", "is_correct": false, "explanation": "「移動」は目的語を取らない用法なので、「電車でを移動」は誤り。"}, {"text": "へ", "is_correct": false, "explanation": "「電車でへ移動」は方向と手段が重なり、不自然。"}], "correct_answer": "の", "explanations": {"の": "「電車での移動中」の「の」。で句を「移動」につなぐ連体修飾で正しい。", "が": "「電車での＿移動中」では主語として成り立たず、不自然。", "を": "「移動」は目的語を取らない用法なので、「電車でを移動」は誤り。", "へ": "「電車でへ移動」は方向と手段が重なり、不自然。"}, "error_tags": {"の": "連体修飾", "が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37128, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「移動に時間がかかる」で、移動にかかる所要時間を示す。正しい。"}, {"text": "から", "is_correct": false, "explanation": "「移動から時間がかかる」は起点を示すが、所要時間の文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「移動と時間がかかる」は並列や相手を示すが、不自然。"}, {"text": "を", "is_correct": false, "explanation": "「移動を時間がかかる」は目的語を取れず、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「移動に時間がかかる」で、移動にかかる所要時間を示す。正しい。", "から": "「移動から時間がかかる」は起点を示すが、所要時間の文として成り立たない。", "と": "「移動と時間がかかる」は並列や相手を示すが、不自然。", "を": "「移動を時間がかかる」は目的語を取れず、文が成り立たない。"}, "error_tags": {"に": "所要", "から": "起点", "と": "並列", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37128, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人が別の場所に行くこと。", "primary_collocate": null, "pronunciation": "いどう", "ipa": "idoː", "syllable_count": 3, "sentences": [{"text": "次の会議室へ移動しますので、ついてきてください。", "target_word": "移動", "complexity_tier": "T3", "furigana": "次[つぎ]の会議室[かいぎしつ]へ移動[いどう]しますので、ついてきてください。", "sentence_source": "generated"}, {"text": "電車での移動中に、本を読んでいる。", "target_word": "移動", "complexity_tier": "T3", "furigana": "電車[でんしゃ]での移動中[いどうちゅう]に、本[ほん]を読[よ]んでいる。", "sentence_source": "generated"}, {"text": "出張が多く、一日の大半が移動で終わる日もある。", "target_word": "移動", "complexity_tier": "T3", "furigana": "出張[しゅっちょう]が多[おお]く、一日[いちにち]の大半[たいはん]が移動[いどう]で終[お]わる日[ひ]もある。", "sentence_source": "generated"}, {"text": "私たちは、バスで山のふもとまで移動した。", "target_word": "移動", "complexity_tier": "T3", "furigana": "私[わたし]たちは、バスで山[やま]のふもとまで移動[いどう]した。", "sentence_source": "generated"}, {"text": "駅から会場までの移動は、歩いて十五分だ。", "target_word": "移動", "complexity_tier": "T3", "furigana": "駅[えき]から会場[かいじょう]までの移動[いどう]は、歩[ある]いて十五分[じゅうごふん]だ。", "sentence_source": "generated"}, {"text": "雨が降ってきたので、みんなで屋根の下に移動した。", "target_word": "移動", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ってきたので、みんなで屋根[やね]の下[した]に移動[いどう]した。", "sentence_source": "generated"}, {"text": "社長は車で移動するため、道の混雑を気にしている。", "target_word": "移動", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は車[くるま]で移動[いどう]するため、道[みち]の混雑[こんざつ]を気[き]にしている。", "sentence_source": "generated"}, {"text": "移動に時間がかかるので、朝早く家を出た。", "target_word": "移動", "complexity_tier": "T3", "furigana": "移動[いどう]に時間[じかん]がかかるので、朝早[あさはや]く家[いえ]を出[で]た。", "sentence_source": "generated"}, {"text": "昼食のあと、全員で隣の部屋へ移動した。", "target_word": "移動", "complexity_tier": "T3", "furigana": "昼食[ちゅうしょく]のあと、全員[ぜんいん]で隣[となり]の部屋[へや]へ移動[いどう]した。", "sentence_source": "generated"}, {"text": "新幹線は、遠くへ移動するのに便利な乗り物だ。", "target_word": "移動", "complexity_tier": "T3", "furigana": "新幹線[しんかんせん]は、遠[とお]くへ移動[いどう]するのに便利[べんり]な乗[の]り物[もの]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "移動", "label": "基本形"}, {"form": "移動する", "label": "終止形"}, {"form": "移動した", "label": "過去形"}, {"form": "移動して", "label": "て形"}, {"form": "移動しない", "label": "ない形"}], "register": "標準（中立）", "sense_fingerprint": "人が目的の場所へ行く・出かけること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e4f16ac-015e-4e13-806a-656d45ceaf69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37128, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "移動", "is_correct": true, "explanation": "「次の会議室へ移動します」で、人が場所を移る意味として自然。"}, {"text": "撮影", "is_correct": false, "explanation": "写真や映像を撮る行為で、人が場所を移る意味ではない。"}, {"text": "購読", "is_correct": false, "explanation": "新聞などを継続して受け取ることで、場所の移動とは関係がない。"}, {"text": "採点", "is_correct": false, "explanation": "答案などに点数をつける行為で、会議室への移動とは合わない。"}], "explanations": {"移動": "「次の会議室へ移動します」で、人が場所を移る意味として自然。", "撮影": "写真や映像を撮る行為で、人が場所を移る意味ではない。", "購読": "新聞などを継続して受け取ることで、場所の移動とは関係がない。", "採点": "答案などに点数をつける行為で、会議室への移動とは合わない。"}, "sentence_index": 0, "correct_answer": "移動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校は来年から、新しい教育方式へ移動する。", "explanation": "ここは〈移行〉（新しい状態や仕組みに移ること）の意味。移動は場所を変えることなので、教育方式には使わない。"}, {"text": "物価が大きく移動した。", "explanation": "ここは〈変動〉（数値が上下すること）の意味。移動は位置の変化なので、物価には使わない。"}, {"text": "彼女の気持ちが、急に新しい恋人へ移動した。", "explanation": "ここは〈移る〉（気持ちが別のものに向く）の意味。移動は場所の変化なので、気持ちには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37128, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "移動", "is_correct": true, "explanation": "社長が車で移動する文脈で、場所を移る意味として自然。"}, {"text": "解散", "is_correct": false, "explanation": "集まりを終わらせる行為で、車での移動とは関係がない。"}, {"text": "清算", "is_correct": false, "explanation": "お金の支払いを終える意味で、移動の手段とは結びつかない。"}, {"text": "翻訳", "is_correct": false, "explanation": "言葉を置き換える作業で、車を使う文脈には合わない。"}], "explanations": {"移動": "社長が車で移動する文脈で、場所を移る意味として自然。", "解散": "集まりを終わらせる行為で、車での移動とは関係がない。", "清算": "お金の支払いを終える意味で、移動の手段とは結びつかない。", "翻訳": "言葉を置き換える作業で、車を使う文脈には合わない。"}, "sentence_index": 6, "correct_answer": "移動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は失敗の責任を部下に移動して、その場を逃れた。", "explanation": "ここは〈転嫁〉（責任を他人に押しつける）の意味。移動は場所を変えることなので、責任には使わない。"}, {"text": "この国は長い年月を経て、時代が大きく移動した。", "explanation": "ここは〈変遷〉（移り変わり）の意味。移動は位置の変化なので、時代の推移には使わない。"}, {"text": "町は観光から農業へ、経済の柱を大きく移動した。", "explanation": "ここは〈転換〉（方向を大きく切り替えること）の意味。移動は位置の変化なので、経済の柱には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37128, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私たちは、バスで山の駅を移動した。", "corrected_sentence": "私たちは、バスで山の駅まで移動した。", "error_description": "移動の到着点は「まで」で示す。「を」は目的語の形で、移動の行き先を表せないので誤り。正しくは「まで」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37128, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新人は、電車で本社に移動すため、朝早く出る。", "corrected_sentence": "新人は、電車で本社に移動するため、朝早く出る。", "error_description": "動詞の終止形「移動する」の「る」が抜けている。「移動すため」は活用が誤り。正しくは「移動するため」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37129, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "「安全な場所へ移動した」で、移動の行き先（方向）を示す。"}, {"text": "が", "is_correct": false, "explanation": "「場所が移動した」は場所自体が動く文になり、住民の移動として不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は後ろに名詞を続ける必要があり、「場所の移動した」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は一緒に行く相手を示すが、場所と一緒に動くという意味になり不自然。"}], "correct_answer": "へ", "explanations": {"へ": "「安全な場所へ移動した」で、移動の行き先（方向）を示す。", "が": "「場所が移動した」は場所自体が動く文になり、住民の移動として不自然。", "の": "連体修飾の「の」は後ろに名詞を続ける必要があり、「場所の移動した」は文として成り立たない。", "と": "「と」は一緒に行く相手を示すが、場所と一緒に動くという意味になり不自然。"}, "error_tags": {"へ": "方向", "が": "主語", "の": "連体修飾", "と": "共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37129, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「体育館への移動」の「の」。へ句を「移動」にかける連体修飾で正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「体育館へ＿移動」の位置では文が成立しない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、「体育館へで移動」は文として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」が重なると「体育館へへ」となり不自然。"}], "correct_answer": "の", "explanations": {"の": "「体育館への移動」の「の」。へ句を「移動」にかける連体修飾で正しい。", "が": "主語を示すが、「体育館へ＿移動」の位置では文が成立しない。", "で": "手段や場所を示すが、「体育館へで移動」は文として不自然。", "へ": "方向の「へ」が重なると「体育館へへ」となり不自然。"}, "error_tags": {"の": "連体修飾", "が": "主語", "で": "場所・手段", "へ": "重複"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37129, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある場所から別の場所へ位置を変えること。", "primary_collocate": null, "pronunciation": "いどう", "ipa": "idoː", "syllable_count": 3, "sentences": [{"text": "彼女の人生におけるこの学校の初日は、単なる物理的な場所の移動を意味するものではない。", "target_word": "移動", "complexity_tier": "T4", "furigana": "彼女[かのじょ]の人生[じんせい]におけるこの学校[がっこう]の初日[しょにち]は、単[たん]なる物理的[ぶつりてき]な場所[ばしょ]の移動[いどう]を意味[いみ]するものではない。", "sentence_source": "mined"}, {"text": "地震のあと、住民は安全な場所へ移動した。", "target_word": "移動", "complexity_tier": "T3", "furigana": "地震[じしん]のあと、住民[じゅうみん]は安全[あんぜん]な場所[ばしょ]へ移動[いどう]した。", "sentence_source": "generated"}, {"text": "机を窓の近くに移動してください。", "target_word": "移動", "complexity_tier": "T3", "furigana": "机[つくえ]を窓[まど]の近[ちか]くに移動[いどう]してください。", "sentence_source": "generated"}, {"text": "台風が近づくにつれ、雲がゆっくり北へ移動している。", "target_word": "移動", "complexity_tier": "T3", "furigana": "台風[たいふう]が近[ちか]づくにつれ、雲[くも]がゆっくり北[きた]へ移動[いどう]している。", "sentence_source": "generated"}, {"text": "このソフトでは、ファイルを別のフォルダに移動できる。", "target_word": "移動", "complexity_tier": "T3", "furigana": "このソフトでは、ファイルを別[べつ]のフォルダに移動[いどう]できる。", "sentence_source": "generated"}, {"text": "渡り鳥は、季節ごとに長い距離を移動する。", "target_word": "移動", "complexity_tier": "T3", "furigana": "渡[わた]り鳥[どり]は、季節[きせつ]ごとに長[なが]い距離[きょり]を移動[いどう]する。", "sentence_source": "generated"}, {"text": "引っ越しのたびに、荷物の移動が大変になる。", "target_word": "移動", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しのたびに、荷物[にもつ]の移動[いどう]が大変[たいへん]になる。", "sentence_source": "generated"}, {"text": "校舎から体育館への移動に、十分ほどかかる。", "target_word": "移動", "complexity_tier": "T3", "furigana": "校舎[こうしゃ]から体育館[たいいくかん]への移動[いどう]に、十分[じっぷん]ほどかかる。", "sentence_source": "generated"}, {"text": "店が駅の反対側に移動したため、地図が古くなった。", "target_word": "移動", "complexity_tier": "T3", "furigana": "店[みせ]が駅[えき]の反対側[はんたいがわ]に移動[いどう]したため、地図[ちず]が古[ふる]くなった。", "sentence_source": "generated"}, {"text": "動物園では、動物が広い場所を自由に移動できる。", "target_word": "移動", "complexity_tier": "T3", "furigana": "動物園[どうぶつえん]では、動物[どうぶつ]が広[ひろ]い場所[ばしょ]を自由[じゆう]に移動[いどう]できる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "移動", "label": "基本形"}, {"form": "移動する", "label": "終止形"}, {"form": "移動した", "label": "過去形"}, {"form": "移動して", "label": "て形"}, {"form": "移動しない", "label": "ない形"}], "register": "標準（中立）", "sense_fingerprint": "人・物・動物などがある場所から別の場所へ位置を変える", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e4f16ac-015e-4e13-806a-656d45ceaf69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37129, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "移動", "is_correct": true, "explanation": "「物理的な場所の移動」を指し、「意味する」ともつながる。"}, {"text": "点検", "is_correct": false, "explanation": "調べて確かめる行為を指し、場所が変わる意味ではないので合わない。"}, {"text": "修繕", "is_correct": false, "explanation": "壊れたものを直す意味で、場所の変化とは関係がない。"}, {"text": "購入", "is_correct": false, "explanation": "物を買う行為で、場所の変化を表す文脈には入らない。"}], "explanations": {"移動": "「物理的な場所の移動」を指し、「意味する」ともつながる。", "点検": "調べて確かめる行為を指し、場所が変わる意味ではないので合わない。", "修繕": "壊れたものを直す意味で、場所の変化とは関係がない。", "購入": "物を買う行為で、場所の変化を表す文脈には入らない。"}, "sentence_index": 0, "correct_answer": "移動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の関心が、仕事から趣味へ急に移動した。", "explanation": "ここは〈移る〉（関心や気持ちが別のものに向く）の意味。移動は場所の変化なので、関心には使わない。"}, {"text": "会社は、この春から新しい制度へ移動した。", "explanation": "ここは〈移行〉（新しい状態や仕組みに移ること）の意味。移動は場所を変えることなので、制度には使わない。"}, {"text": "物価が大きく移動した。", "explanation": "ここは〈変動〉（数値が上下すること）の意味。移動は位置の変化なので、物価には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37129, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "移動", "is_correct": true, "explanation": "「荷物の移動」は運ぶ作業を指し、「大変になる」と自然につながる。"}, {"text": "解約", "is_correct": false, "explanation": "契約を終わらせる行為で、荷物の作業を表す語ではない。"}, {"text": "延期", "is_correct": false, "explanation": "予定を後ろにずらす意味で、「荷物の」に続けると不自然。"}, {"text": "翻訳", "is_correct": false, "explanation": "言葉を別の言語に置き換える作業で、荷物には使わない。"}], "explanations": {"移動": "「荷物の移動」は運ぶ作業を指し、「大変になる」と自然につながる。", "解約": "契約を終わらせる行為で、荷物の作業を表す語ではない。", "延期": "予定を後ろにずらす意味で、「荷物の」に続けると不自然。", "翻訳": "言葉を別の言語に置き換える作業で、荷物には使わない。"}, "sentence_index": 6, "correct_answer": "移動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "失敗の責任を同僚に移動して、その場を逃れた。", "explanation": "ここは〈転嫁〉（責任を他人に押しつける）の意味。移動は場所を変えることなので、責任には使わない。"}, {"text": "この国は、長い年月を経て時代が大きく移動した。", "explanation": "ここは〈変遷〉（移り変わり）の意味。移動は位置の変化なので、時代の推移には使わない。"}, {"text": "会社は来年から、事業の方針を大きく移動した。", "explanation": "ここは〈転換〉（方向を大きく切り替えること）の意味。移動は位置の変化なので、方針には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37129, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "写真がほかのフォルダに移動させた。", "corrected_sentence": "写真をほかのフォルダに移動させた。", "error_description": "「移動させる」は「〜を〜に移動させる」と目的語に「を」を取る。「写真が」は誤りで、正しくは「写真を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37129, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は昨日、車で駅まで移動して。", "corrected_sentence": "父は昨日、車で駅まで移動した。", "error_description": "過去の出来事を表すには「移動した」が正しい。「移動して」で文を終えると述語が完結しないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a059b9ac-9698-4493-b8a7-d83e0c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37130, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「町全体」が「おおわれた」の主語。受け身の文では、覆われる側が「が」で示される。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。受け身「おおわれた」の主語には「を」を使えず、文の構造が崩れる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、受け身「おおわれた」の主語にはならず不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示すので、「町全体より雪におおわれた」は文の意味をなさない。"}], "correct_answer": "が", "explanations": {"が": "「町全体」が「おおわれた」の主語。受け身の文では、覆われる側が「が」で示される。", "を": "「を」は目的語を示す。受け身「おおわれた」の主語には「を」を使えず、文の構造が崩れる。", "へ": "「へ」は方向を示すが、受け身「おおわれた」の主語にはならず不自然。", "より": "「より」は比較の基準を示すので、「町全体より雪におおわれた」は文の意味をなさない。"}, "error_tags": {"を": "目的語（受け身では不可）", "へ": "方向（不適）", "より": "比較"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "一部", "is_correct": true, "explanation": "「全体」の対義語。「全体の半分以上」の文で、全体を分けた部分を表す。"}, {"text": "時刻", "is_correct": false, "explanation": "時刻は時の一点を表す語で、「全体」の対義語ではない。"}, {"text": "中心", "is_correct": false, "explanation": "物事の核となる部分を指す語で、「全体」の対義語とはされない。"}, {"text": "表面", "is_correct": false, "explanation": "外側の面を表す語で、「全体」の対義語ではない。"}], "correct_answer": "一部", "explanations": {"一部": "「全体」の対義語。「全体の半分以上」の文で、全体を分けた部分を表す。", "時刻": "時刻は時の一点を表す語で、「全体」の対義語ではない。", "中心": "物事の核となる部分を指す語で、「全体」の対義語とはされない。", "表面": "外側の面を表す語で、「全体」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37130, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「全体の」は「こと」を修飾する所属の「の」で、「全体のことを考えて」と続く。"}, {"text": "が", "is_correct": false, "explanation": "「全体が」は主語を示すが、「ことを考えて」とは続かない。"}, {"text": "に", "is_correct": false, "explanation": "「全体に」は相手や方向を示すが、「ことを考えて」とは続かない。"}, {"text": "で", "is_correct": false, "explanation": "「全体で」は範囲や手段を示すが、「ことを考えて」の対象にならない。"}], "correct_answer": "の", "explanations": {"の": "「全体の」は「こと」を修飾する所属の「の」で、「全体のことを考えて」と続く。", "が": "「全体が」は主語を示すが、「ことを考えて」とは続かない。", "に": "「全体に」は相手や方向を示すが、「ことを考えて」とは続かない。", "で": "「全体で」は範囲や手段を示すが、「ことを考えて」の対象にならない。"}, "error_tags": {"が": "主語（不適）", "に": "対象・方向", "で": "範囲・手段"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "部分", "is_correct": true, "explanation": "「全体」の対義語。機械全体を構成する一部分で、ここでは部品にあたる。"}, {"text": "天候", "is_correct": false, "explanation": "空模様を表す語で、「全体」の対義語ではない。"}, {"text": "始まり", "is_correct": false, "explanation": "物事の初めを表し、「全体」の対義語ではない。"}, {"text": "中核", "is_correct": false, "explanation": "中心となる重要な部分を表し、「全体」の対義語とはされない。"}], "correct_answer": "部分", "explanations": {"部分": "「全体」の対義語。機械全体を構成する一部分で、ここでは部品にあたる。", "天候": "空模様を表す語で、「全体」の対義語ではない。", "始まり": "物事の初めを表し、「全体」の対義語ではない。", "中核": "中心となる重要な部分を表し、「全体」の対義語とはされない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37130, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "みんなをひとまとめにしたもののこと。", "primary_collocate": null, "pronunciation": "ぜんたい", "ipa": "dzentai", "syllable_count": 4, "sentences": [{"text": "クラス全体で、合唱の練習をしました。", "target_word": "全体", "complexity_tier": "T3", "furigana": "クラス全体[ぜんたい]で、合唱[がっしょう]の練習[れんしゅう]をしました。", "sentence_source": "generated"}, {"text": "町全体が雪におおわれた。", "target_word": "全体", "complexity_tier": "T3", "furigana": "町[まち]全体[ぜんたい]が雪[ゆき]におおわれた。", "sentence_source": "generated"}, {"text": "まず全体を見てから、細かいところを直します。", "target_word": "全体", "complexity_tier": "T3", "furigana": "まず全体[ぜんたい]を見[み]てから、細[こま]かいところを直[なお]します。", "sentence_source": "generated"}, {"text": "全体の半分以上が、女性の客だった。", "target_word": "全体", "complexity_tier": "T3", "furigana": "全体[ぜんたい]の半分以上[はんぶんいじょう]が、女性[じょせい]の客[きゃく]だった。", "sentence_source": "generated"}, {"text": "先生は、全体に向かって大きな声で話した。", "target_word": "全体", "complexity_tier": "T3", "furigana": "先生[せんせい]は、全体[ぜんたい]に向[む]かって大[おお]きな声[こえ]で話[はな]した。", "sentence_source": "generated"}, {"text": "チーム全体の力が上がって、試合に勝てた。", "target_word": "全体", "complexity_tier": "T3", "furigana": "チーム全体[ぜんたい]の力[ちから]が上[あ]がって、試合[しあい]に勝[か]てた。", "sentence_source": "generated"}, {"text": "学校全体で、毎月一回そうじをします。", "target_word": "全体", "complexity_tier": "T3", "furigana": "学校[がっこう]全体[ぜんたい]で、毎月[まいつき]一回[いっかい]そうじをします。", "sentence_source": "generated"}, {"text": "全体のことを考えて、自分の意見をゆずった。", "target_word": "全体", "complexity_tier": "T3", "furigana": "全体[ぜんたい]のことを考[かんが]えて、自分[じぶん]の意見[いけん]をゆずった。", "sentence_source": "generated"}, {"text": "この会社は、全体で百人ほどの人が働いている。", "target_word": "全体", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、全体[ぜんたい]で百人[ひゃくにん]ほどの人[ひと]が働[はたら]いている。", "sentence_source": "generated"}, {"text": "部品が一つ悪いと、機械全体が動かなくなる。", "target_word": "全体", "complexity_tier": "T3", "furigana": "部品[ぶひん]が一[ひと]つ悪[わる]いと、機械[きかい]全体[ぜんたい]が動[うご]かなくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "全体", "label": "基本形"}], "register": "標準（中立）", "sense_fingerprint": "部分に分けず、ひとまとまりとして見た全部（一部の対）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: contains vocabulary far above tier T1: おおわれ (Zipf 1.5)','sentence 7 above tier T1: contains vocabulary far above tier T1: ゆずっ (Zipf 2.48)']::text[], '79dd0ac8-530d-4cac-b7a0-2b6a258737ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37130, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全体", "is_correct": true, "explanation": "「クラス全体」はクラス全員を指し、そのクラス全員で合唱の練習をしたという文に合う。"}, {"text": "個人", "is_correct": false, "explanation": "「個人」は一人ひとりを指すので、「クラス個人で」とは続かず、クラス全員での練習と合わない。"}, {"text": "見学", "is_correct": false, "explanation": "「見学」は練習に参加せず見ることなので、練習をした主体として「クラス見学で」は成り立たない。"}, {"text": "欠席", "is_correct": false, "explanation": "「欠席」は休むことなので、「合唱の練習をしました」と矛盾する。"}], "explanations": {"全体": "「クラス全体」はクラス全員を指し、そのクラス全員で合唱の練習をしたという文に合う。", "個人": "「個人」は一人ひとりを指すので、「クラス個人で」とは続かず、クラス全員での練習と合わない。", "見学": "「見学」は練習に参加せず見ることなので、練習をした主体として「クラス見学で」は成り立たない。", "欠席": "「欠席」は休むことなので、「合唱の練習をしました」と矛盾する。"}, "sentence_index": 0, "correct_answer": "全体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "借金を全体で返した。", "explanation": "ここは〈全額〉（金額のすべて）の意味。全体は金額を表さないので「全額」と言う。"}, {"text": "寒さで全体がふるえて、なかなか止まらなかった。", "explanation": "ここは〈全身〉（体のすべて）の意味。全体だけでは体全体を指せず、体がふるえる文には「全身」を使う。"}, {"text": "試合の最後に、全体を出し切った。", "explanation": "ここは〈全力〉（持っている力のすべて）の意味。全体は力の量を表さないので、「全力を出し切る」と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37130, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全体", "is_correct": true, "explanation": "「学校全体」は学校の全員を指し、毎月全員でそうじをするという文に合う。"}, {"text": "卒業", "is_correct": false, "explanation": "「卒業」は学校を終えることで、「学校卒業で」とそうじの文はつながらない。"}, {"text": "入学", "is_correct": false, "explanation": "「入学」は学校に入ることで、そうじの範囲や主体を示す語にならない。"}, {"text": "給食", "is_correct": false, "explanation": "「給食」は食事の提供で、「学校給食で」ではそうじの主体が示せない。"}], "explanations": {"全体": "「学校全体」は学校の全員を指し、毎月全員でそうじをするという文に合う。", "卒業": "「卒業」は学校を終えることで、「学校卒業で」とそうじの文はつながらない。", "入学": "「入学」は学校に入ることで、そうじの範囲や主体を示す語にならない。", "給食": "「給食」は食事の提供で、「学校給食で」ではそうじの主体が示せない。"}, "sentence_index": 6, "correct_answer": "全体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は練習で全体を出し切って、一位になった。", "explanation": "ここは〈全力〉（持っている力のすべて）の意味。全体は力の量を表さないので、「全力を出し切る」と言う。"}, {"text": "転んで、全体をすりむいた。", "explanation": "ここは〈全身〉（体のすべて）の意味。全体は体の部位を指さないので、「全身をすりむいた」と言う。"}, {"text": "窓を全体にあけて、風を入れた。", "explanation": "ここは〈全開〉（いっぱいに開くこと）の意味。全体は開け方を表せないので「全開にする」で使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37130, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "チーム全体を疲れて、休憩した。", "corrected_sentence": "チーム全体が疲れて、休憩した。", "error_description": "「チーム全体」は「疲れる」の主語なので「が」が正しい。「を」は他動詞の目的語を示す助詞で、自動詞「疲れる」には使わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37130, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校全体の話し合った。", "corrected_sentence": "学校全体で話し合った。", "error_description": "「話し合う」は、動作をする集団を「で」で示す。「の」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd8e2576-dcc7-4ff4-be6f-c279820f2ef3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37132, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「回数を減らす」と、減らす対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "他動詞「減らす」の対象に「が」は使えない。"}, {"text": "と", "is_correct": false, "explanation": "「回数と減らした」は文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「回数の減らした」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「回数を減らす」と、減らす対象を表す。", "が": "他動詞「減らす」の対象に「が」は使えない。", "と": "「回数と減らした」は文として成り立たない。", "の": "「回数の減らした」は文として成り立たない。"}, "error_tags": {"が": "subject_vs_object", "と": "companion_vs_object", "の": "possessive_vs_object"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "増やす", "is_correct": true, "explanation": "数を多くする意味で、「減らす」の反対。"}, {"text": "数える", "is_correct": false, "explanation": "「数える」は数を調べる意味で、反対ではない。"}, {"text": "捨てる", "is_correct": false, "explanation": "「捨てる」は不要なものを手放す意味で、反対ではない。"}, {"text": "分ける", "is_correct": false, "explanation": "「分ける」は分割する意味で、反対ではない。"}], "correct_answer": "増やす", "explanations": {"増やす": "数を多くする意味で、「減らす」の反対。", "数える": "「数える」は数を調べる意味で、反対ではない。", "捨てる": "「捨てる」は不要なものを手放す意味で、反対ではない。", "分ける": "「分ける」は分割する意味で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37132, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「数を減らす」と、減らす対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "他動詞「減らす」の対象に「が」は使えない。"}, {"text": "と", "is_correct": false, "explanation": "「数と減らします」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「数を減らす」と、減らす対象を表す。", "が": "他動詞「減らす」の対象に「が」は使えない。", "と": "「数と減らします」は文として成り立たない。", "へ": "「へ」は方向を表し、対象を表せない。"}, "error_tags": {"が": "subject_vs_object", "と": "companion_vs_object", "へ": "direction_vs_object"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "増やす", "is_correct": true, "explanation": "数を多くする意味で、「減らす」の反対。"}, {"text": "省く", "is_correct": false, "explanation": "「省く」は取り除く意味で、反対ではない。"}, {"text": "絞る", "is_correct": false, "explanation": "「絞る」は範囲を狭くする意味で、反対ではない。"}, {"text": "削る", "is_correct": false, "explanation": "「削る」は減らすに近い意味で、反対ではない。"}], "correct_answer": "増やす", "explanations": {"増やす": "数を多くする意味で、「減らす」の反対。", "省く": "「省く」は取り除く意味で、反対ではない。", "絞る": "「絞る」は範囲を狭くする意味で、反対ではない。", "削る": "「削る」は減らすに近い意味で、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37132, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かの数を少なくする。", "primary_collocate": null, "pronunciation": "へらす", "ipa": "heɾasɯ", "syllable_count": 3, "sentences": [{"text": "社員の数を減らします。", "target_word": "減らし", "complexity_tier": "T2", "furigana": "社員[しゃいん]の数[かず]を減[へ]らします。", "sentence_source": "generated"}, {"text": "食事の回数を減らした。", "target_word": "減らした", "complexity_tier": "T2", "furigana": "食事[しょくじ]の回数[かいすう]を減[へ]らした。", "sentence_source": "generated"}, {"text": "部屋の荷物を減らして、広く使う。", "target_word": "減らして", "complexity_tier": "T3", "furigana": "部屋[へや]の荷物[にもつ]を減[へ]らして、広[ひろ]く使[つか]う。", "sentence_source": "generated"}, {"text": "会議の数を減らすつもりです。", "target_word": "減らす", "complexity_tier": "T2", "furigana": "会議[かいぎ]の数[かず]を減[へ]らすつもりです。", "sentence_source": "generated"}, {"text": "車の台数を減らせば、費用も下がる。", "target_word": "減らせ", "complexity_tier": "T4", "furigana": "車[くるま]の台数[だいすう]を減[へ]らせば、費用[ひよう]も下[さ]がる。", "sentence_source": "generated"}, {"text": "無駄なアプリを減らしたい。", "target_word": "減らし", "complexity_tier": "T3", "furigana": "無駄[むだ]なアプリを減[へ]らしたい。", "sentence_source": "generated"}, {"text": "人数を減らされて、仕事が回らない。", "target_word": "減らされて", "complexity_tier": "T4", "furigana": "人数[にんずう]を減[へ]らされて、仕事[しごと]が回[まわ]らない。", "sentence_source": "generated"}, {"text": "ごみを減らしましょう。", "target_word": "減らし", "complexity_tier": "T2", "furigana": "ごみを減[へ]らしましょう。", "sentence_source": "generated"}, {"text": "本の数を減らさずに引っ越した。", "target_word": "減らさ", "complexity_tier": "T3", "furigana": "本[ほん]の数[かず]を減[へ]らさずに引[ひ]っ越[こ]した。", "sentence_source": "generated"}, {"text": "宿題の数を減らしてもらった。", "target_word": "減らして", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]の数[かず]を減[へ]らしてもらった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "減らし", "label": "活用"}, {"form": "減らした", "label": "活用"}, {"form": "減らせる", "label": "活用"}, {"form": "減らさない", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | ものの数を少なくする行為", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be06c00-e07b-4845-a5a1-5b9d6c46fb56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
